      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it modifies the named
      !>     EK file by adding data to the specified column.  This routine
      !>     writes the entire contents of the specified column in one shot.
      !>     This routine creates columns much more efficiently than can be
      !>     done by sequential calls to EKACEC, but has the drawback that
      !>     the caller must use more memory for the routine's inputs.  This
      !>     routine cannot be used to add data to a partially completed
      !>     column.
      !>
      !>## Examples
      !>
      !>     See EKACLC.
      !>
      !>## Restrictions
      !>
      !>     1)  This routine assumes the EK scratch area has been set up
      !>         properly for a fast load operation.  This routine writes
      !>         to the EK scratch area as well.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    Beta Version 1.0.0, 26-SEP-1995 (NJB)
      module subroutine zzekac03 ( ctx, handle, segdsc, coldsc, cvals, nlflgs, rcptrs, wkindx )
      use pepper_kinds, only: ip
      use pepper_strings, only: rtrim
      use pepper_inc_ekbool
      use pepper_inc_ekcnamsz
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekpage
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to new EK file.
      integer(ip), intent(in) :: segdsc ( * )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( * )  !! Column descriptor.
      character(*), intent(in) :: cvals  ( * )  !! Character values to add to column.
      logical, intent(in) :: nlflgs ( * )  !! Array of null flags for column entries.
      integer(ip), intent(in) :: rcptrs ( * )  !! Array of record pointers for segment.
      integer(ip), intent(inout) :: wkindx ( * )  !! Work space for column index.
!
!     Local parameters
!
      integer(ip), parameter :: bufsiz = cpsize

      character(cnamsz) :: column
      character(pgsizc) :: page

      integer(ip) :: adrbuf ( bufsiz )
      integer(ip) :: bufptr
      integer(ip) :: class
      integer(ip) :: colidx
      integer(ip) :: colwid
      integer(ip) :: dscbas
      integer(ip) :: from
      integer(ip) :: i
      integer(ip) :: idxtyp
      integer(ip) :: p
      integer(ip) :: p2
      integer(ip) :: pbase
      integer(ip) :: pos
      integer(ip) :: mbase
      integer(ip) :: n
      integer(ip) :: nchars
      integer(ip) :: ndata
      integer(ip) :: nlinks
      integer(ip) :: nnull
      integer(ip) :: nrows
      integer(ip) :: nulptr
      integer(ip) :: nwrite
      integer(ip) :: remain
      integer(ip) :: room
      integer(ip) :: strlen
      integer(ip) :: to
      integer(ip) :: tree

      logical :: fixlen
      logical :: indexd
      logical :: nullok

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Grab the column's attributes.  Initialize the maximum non-blank
!     width of the column.
!
      class  =  coldsc ( clsidx )
      idxtyp =  coldsc ( ixtidx )
      nulptr =  coldsc ( nflidx )
      colidx =  coldsc ( ordidx )
      colwid =  coldsc ( lenidx )

      nullok =  nulptr /= ifalse
      indexd =  idxtyp /= ifalse
      fixlen =  colwid /= ifalse

!
!     This column had better be class 3.
!
      if ( class /= 3 ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Column class code # found in descriptor for ' // &
                       'column #.  Class should be 3.'                 )
         call ctx%errint ( '#', class                                      )
         call ctx%errch  ( '#', column                                     )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

!
!     If the column is indexed, the index type should be 1; we don't
!     know how to create any other type of index.
!
      if  (  indexd  .and.  ( idxtyp /= 1 )  ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Index type code # found in descriptor for '   // &
                       'column #.  Code should be 1.'                  )
         call ctx%errint ( '#', idxtyp                                     )
         call ctx%errch  ( '#', column                                     )
         call ctx%sigerr ( 'SPICE(UNRECOGNIZEDTYPE)'                       )
         return

      end if

!
!     Push the column's ordinal index on the stack.  This allows us
!     to identify the column the addresses belong to.
!
      call zzekspsh ( ctx, 1, [ colidx ] )

!
!     Find the number of rows in the segment.
!
      nrows   =  segdsc ( nridx )

!
!     Count the number of strings to write.
!
      if ( nullok ) then
!
!        Count the non-null column entries; these are the
!        ones that will take up space.
!
         nnull  =  0
         ndata  =  0

         do i = 1, nrows

            if ( nlflgs(i) ) then
               nnull  =  nnull + 1
            end if

         end do

         ndata  =   nrows  -  nnull

      else

         ndata  =   nrows

      end if

      if ( ndata > 0 ) then
!
!        There's some data to write, so allocate a page.  Also
!        prepare a data buffer to be written out as a page.
!
         call zzekaps ( ctx, handle, segdsc, chr, .false., p, pbase )
         page  =  ' '

!
!        The link count starts out at zero.
!
         call prtenc ( ctx, 0,  page(clcidx:clcidx+encsiz-1) )

      end if

!
!     Write the input data out to the target file a page at a time.
!     Null values don't get written.
!
!     While we're at it, we'll push onto the EK stack the addresses
!     of the column entries.  We use the constant NULL rather than an
!     address to represent null entries.
!
!     We'll use FROM to indicate the element of CVALS we're
!     considering, TO to indicate the first character of PAGE to write
!     to, and BUFPTR to indicate the element of ADRBUF to write
!     addresses to.  The variable N indicates the number of characters
!     written to the current page.  NCHARS indicates the number of
!     characters left to write from the current input element.  NWRITE
!     will be used to count the column entries written so far.
!

      remain  =  nrows
      from    =  0
      to      =  1
      bufptr  =  1
      nwrite  =  0
      n       =  0

      do while ( remain > 0 )
!
!        Examine a column entry.  Write it out if it's non-null.
!
         from  =  from   + 1

         if (  nullok  .and.  ( nlflgs(from) )  ) then

            adrbuf(bufptr) =  null

         else
!
!           Write out the current column entry.  The entry
!           might span multiple pages.  However, we're guaranteed
!           enough room to write out to the current page the encoded
!           character count and at least one character of data.
!
!           Update the non-blank width for the column each time we
!           determine the length of an input string.
!
            if ( fixlen ) then
               strlen  =  min (  rtrim( cvals(from) ),  colwid  )
            else
               strlen  =  rtrim( cvals(from) )
            end if

            adrbuf(bufptr) =  to  +  pbase
            pos            =  1

!
!           Start out with the string length.
!
            call prtenc ( ctx,  strlen,  page(to : to+encsiz-1)  )

            n       =   n  +  encsiz
            to      =   n  +  1
            nchars  =   strlen

            do while ( nchars > 0 )

               room  =  cpsize - n

               if ( nchars <= room ) then
!
!                 The remaining portion of the string will fit on the
!                 current page.
!
                  page(to:to+nchars-1) =  cvals(from) (pos:pos+nchars-1)
                  n                    =  n   +  nchars
                  to                   =  n   +  1
                  nchars               =  0

!
!                 Add a link to the current page.
!

                  call prtdec ( ctx, page(clcidx:clcidx+encsiz-1),   nlinks )

                  call prtenc ( ctx, nlinks+1, page(clcidx:clcidx+encsiz-1) )

               else
!
!                 The string will have to be continued on another page.
!                 Write out the first ROOM characters to the current
!                 page first.
!
                  page(to:cpsize)  =  cvals(from) (pos:pos+room-1)
                  pos              =  pos    + room
                  nchars           =  nchars - room

!
!                 Add a link to the current page.
!
                  call prtdec ( ctx, page(clcidx:clcidx+encsiz-1),   nlinks )

                  call prtenc ( ctx, nlinks+1, page(clcidx:clcidx+encsiz-1) )

!
!                 Allocate another page.  Fill in the forward pointer
!                 in the previous page.
!
                  call zzekaps ( ctx,  handle,  segdsc,  chr, &
                                 .false.,  p2,      pbase )

                  call prtenc   ( ctx, p2,  page(cfpidx:cfpidx+encsiz-1) )

!
!                 Write out the full data page.  Get ready to write
!                 to the new page.
!
                  call zzekpgwc ( ctx, handle, p, page  )

                  p    =  p2
                  page = ' '
                  call prtenc ( ctx, 0,  page(clcidx:clcidx+encsiz-1) )

                  n    =  0
                  to   =  1

               end if

            end do
!
!           We've written out a column entry.
!
            nwrite  =  nwrite + 1

         end if
!
!        We're done with the current column entry, null or not.
!

         if ( nwrite < ndata ) then
!
!           There is at least one more column entry to write.
!           If there's not enough room on the current page to begin
!           writing another column entry, write out the page and
!           allocate another.
!
            room  =  cpsize - n

            if ( room  <  ( 1 + encsiz )  ) then

               call zzekpgwc ( ctx, handle, p,      page  )
               call zzekaps  ( ctx, handle, segdsc, chr, .false., p, pbase )

               page  =  ' '
               call prtenc ( ctx, 0,  page(clcidx:clcidx+encsiz-1) )

               n     =  0
               to    =  1

            end if

         else if ( n > 0 ) then
!
!           We've written the last of the non-null data to the current
!           page.  Write out this page.
!
            call zzekpgwc ( ctx, handle,  p,  page  )
            n  =  0

         end if

         remain  =  remain - 1

         if (  ( bufptr == bufsiz ) .or. ( remain == 0 )  ) then
!
!           The address buffer is full or we're out of input values
!           to look at, so push the buffer contents on the stack.
!
            call zzekspsh ( ctx, bufptr, adrbuf )
            bufptr  =  1

         else

            bufptr  =  bufptr + 1

         end if

      end do

!
!     If the column is supposed to have an index, now is the time to
!     build that index.  We'll find the order vector for the input
!     values, overwrite the elements of the order vector with the
!     corresponding elements of the input array of record pointers, then
!     load this sorted copy of the record pointer array into a tree in
!     one shot.
!
      if ( indexd ) then

         call zzekordc ( ctx, cvals,  nullok, nlflgs, nrows, wkindx )

         do i = 1, nrows
            wkindx(i) =  rcptrs( wkindx(i) )
         end do

         call zzektrit ( ctx, handle, tree                )
         call zzektr1s ( ctx, handle, tree, nrows, wkindx )

!
!        Update the segment's metadata to point to the index.  The
!        pointer indicates the root page of the tree.
!
         mbase   =  segdsc ( imdidx )
         dscbas  =  mbase  +  sdscsz  +  (colidx-1)*cdscsz

         call dasudi ( ctx, handle, dscbas+ixpidx, dscbas+ixpidx, [ tree ] )

      end if

      return
      end subroutine zzekac03

      !> Add an entire class 4 column to an EK segment.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         the handle of an EK file that is open for writing.
      !>                    A `begin segment for fast load' operation must
      !>                    have already been performed for the designated
      !>                    segment.
      !>
      !>     SEGDSC         is a descriptor for the segment to which data is
      !>                    to be added.  The segment descriptor is not
      !>                    updated by this routine, but some fields in the
      !>                    descriptor will become invalid after this routine
      !>                    returns.
      !>
      !>     COLDSC         is a descriptor for the column to be added.  The
      !>                    column attributes must be filled in, but any
      !>                    pointers may be uninitialized.
      !>
      !>     ENTSZS         is an array containing sizes of column entries.
      !>                    The Ith element of ENTSZS gives the size of the
      !>                    Ith column entry.  ENTSZS is used only for columns
      !>                    having variable-size entries.  For such columns,
      !>                    the dimension of ENTSZS must be at least NROWS.
      !>                    The size of null entries should be set to zero.
      !>
      !>                    For columns having fixed-size entries, the
      !>                    dimension of this array may be any positive value.
      !>
      !>     IVALS          is an array containing the entire set of column
      !>                    entries for the specified column.  The entries
      !>                    are listed in row-order:  the column entry for the
      !>                    first row of the segment is first, followed by the
      !>                    column entry for the second row, and so on.  The
      !>                    number of column entries must match the declared
      !>                    number of rows in the segment.  For columns having
      !>                    fixed-size entries, a null entry must be allocated
      !>                    the same amount of space occupied by a non-null
      !>                    entry in the array IVALS.  For columns having
      !>                    variable-size entries, null entries do not require
      !>                    any space in the IVALS array, but in any case must
      !>                    have their allocated space described correctly by
      !>                    the corresponding element of the ENTSZS array
      !>                    (described below).
      !>
      !>     ENTSZS         is an array containing sizes of column entries.
      !>                    The Ith element of ENTSZS gives the size of the
      !>                    Ith column entry.  ENTSZS is used only for columns
      !>                    having variable-size entries.  For such columns,
      !>                    the dimension of ENTSZS must be at least NROWS.
      !>                    The size of null entries should be set to zero.
      !>
      !>                    For columns having fixed-size entries, the
      !>                    dimension of this array may be any positive value.
      !>
      !>     NLFLGS         is an array of logical flags indicating whether
      !>                    the corresponding entries are null.  If the Ith
      !>                    element of NLFLGS is .FALSE., the Ith column entry
      !>                    defined by IVALS is added to the specified segment
      !>                    in the specified kernel file.
      !>
      !>                    If the Ith element of NLFGLS is .TRUE., the
      !>                    contents of the Ith column entry are undefined.
      !>
      !>                    NLFLGS is used only for columns that allow null
      !>                    values; it's ignored for other columns.
      !>
      !>## Detailed Output
      !>
      !>     None.  See $Particulars for a description of the effect of this
      !>     routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it modifies the named
      !>     EK file by adding data to the specified column.  This routine
      !>     writes the entire contents of the specified column in one shot.
      !>     This routine creates columns much more efficiently than can be
      !>     done by sequential calls to EKACEI, but has the drawback that
      !>     the caller must use more memory for the routine's inputs.  This
      !>     routine cannot be used to add data to a partially completed
      !>     column.
      !>
      !>## Examples
      !>
      !>     See EKACLI.
      !>
      !>## Restrictions
      !>
      !>     1)  This routine assumes the EK scratch area has been set up
      !>         properly for a fast load operation.  This routine writes
      !>         to the EK scratch area as well.
      !>
      !>     2)  Only one segment can be created at a time using the fast
      !>         load routines.
      !>
      !>     3)  No other EK operation may interrupt a fast load.  For
      !>         example, it is not valid to issue a query while a fast load
      !>         is in progress.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 22-JUL-1996 (NJB)
      !>
      !>        Bug fix:  case of 100% null data values is now handled
      !>        correctly.  Previous version line was changed from "Beta"
      !>        to "SPICELIB."
      !>
      !>-    SPICELIB Version 1.0.0, 26-SEP-1995 (NJB)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.1.0, 22-JUL-1996 (NJB)
      !>
      !>        Bug fix:  case of 100% null data values is now handled
      !>        correctly.  The test to determine when to write a page
      !>        was fixed to handle this case.
      !>
      !>        Previous version line was changed from "Beta"
      !>        to "SPICELIB."
      module subroutine zzekac04 ( ctx, handle, segdsc, coldsc, ivals, entszs, nlflgs )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekcnamsz
      use pepper_inc_ekdatpag
      use pepper_inc_ekpage
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to new EK file.
      integer(ip), intent(in) :: segdsc ( * )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( * )  !! Column descriptor.
      integer(ip), intent(in) :: ivals  ( * )  !! Integer values to add to column.
      integer(ip), intent(in) :: entszs ( * )  !! Array of sizes of column entries.
      logical, intent(in) :: nlflgs ( * )  !! Array of null flags for column entries.
!
!     Local parameters
!
      integer(ip), parameter :: bufsiz = ipsize

      character(cnamsz) :: column

      integer(ip) :: adrbuf ( bufsiz )
      integer(ip) :: bufptr
      integer(ip) :: class
      integer(ip) :: colidx
      integer(ip) :: cursiz
      integer(ip) :: from
      integer(ip) :: i
      integer(ip) :: n
      integer(ip) :: ndata
      integer(ip) :: nelt
      integer(ip) :: nlink
      integer(ip) :: nrows
      integer(ip) :: nulptr
      integer(ip) :: p
      integer(ip) :: p2
      integer(ip) :: page   ( pgsizi )
      integer(ip) :: pbase
      integer(ip) :: remain
      integer(ip) :: row
      integer(ip) :: size
      integer(ip) :: to

      logical :: cntinu
      logical :: fixsiz
      logical :: newreq
      logical :: nullok

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Grab the column's attributes.
!
      class  =  coldsc( clsidx )
      nulptr =  coldsc( nflidx )
      colidx =  coldsc( ordidx )
      size   =  coldsc( sizidx )

      nullok =  nulptr /= ifalse
      fixsiz =  size   /= ifalse

!
!     This column had better be class 4.
!
      if ( class /= 4 ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Column class code # found in descriptor for ' // &
                       'column #.  Class should be 4.'                 )
         call ctx%errint ( '#', class                                      )
         call ctx%errch  ( '#', column                                     )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

!
!     Push the column's ordinal index on the stack.  This allows us
!     to identify the column the addresses belong to.
!
      call zzekspsh ( ctx, 1, [ colidx ] )

!
!     Find the number of rows in the segment.
!
      nrows   =  segdsc ( nridx )

!
!     Record the number of data values to write.
!
      if ( nullok ) then
!
!        Sum the sizes of the non-null column entries; these are the
!        ones that will take up space.
!
         ndata  =  0

         do i = 1, nrows

            if ( .not. nlflgs(i) ) then

               if ( fixsiz ) then
                  ndata  =  ndata + size
               else
                  ndata  =  ndata + entszs(i)
               end if

            end if

         end do

      else

         if ( fixsiz ) then

            ndata  =  nrows * size

         else

            ndata  =  0

            do i = 1, nrows
               ndata  =  ndata + entszs(i)
            end do

         end if

      end if

      if ( ndata > 0 ) then
!
!        There's some data to write, so allocate a page.  Also
!        prepare a data buffer to be written out as a page.
!
         call zzekaps  ( ctx, handle, segdsc, int, .false., p, pbase )
         page = 0

      end if

!
!     Write the input data out to the target file a page at a time.
!     Null values don't get written.
!
!     While we're at it, we'll push onto the EK stack the addresses
!     of the column entries.  We use the constant NULL rather than an
!     address to represent null entries.
!
!     We'll use FROM to indicate the element of IVALS we're
!     considering, TO to indicate the element of PAGE to write
!     to, and BUFPTR to indicate the element of ADRBUF to write
!     addresses to.  The variable NELT is the count of the column entry
!     elements written for the current entry.  The variable N indicates
!     the number of integers written to the current page.
!

      remain  =  ndata
      from    =  1
      to      =  1
      bufptr  =  1
      row     =  1
      nelt    =  1
      n       =  0
      nlink   =  0

      do while ( row <= nrows )

!
!        NEWREQ is set to TRUE if we discover that the next column
!        entry must start on a new page.
!
         newreq  =  .false.

         if (  nullok  .and.  ( nlflgs(row) )  ) then

            if ( fixsiz ) then
               cursiz  =  size
            else
               cursiz  =  entszs(row)
            end if

            from           =  from   +  cursiz
            adrbuf(bufptr) =  null
            bufptr         =  bufptr +  1
            row            =  row    +  1
            nelt           =  1
            cntinu         =  .false.

         else

            if ( nelt == 1 ) then
!
!              We're about to write out a new column entry.  We must
!              insert the element count into the page before writing the
!              data.  The link count for the current page must be
!              incremented to account for this new entry.
!
!              At this point, we're guaranteed at least two free
!              spaces in the current page.
!
               if ( fixsiz ) then
                  cursiz  =  size
               else
                  cursiz  =  entszs(row)
               end if

               adrbuf(bufptr) =  to     +  pbase
               bufptr         =  bufptr + 1
               page(to)       =  cursiz
               to             =  to     + 1
               n              =  n      + 1
               nlink          =  nlink  + 1

            end if

!
!           At this point, there's at least one free space in the
!           current page.
!
            page(to)  =  ivals(from)
            to        =  to      +  1
            n         =  n       +  1
            from      =  from    +  1
            remain    =  remain  -  1

!
!           Decide whether we must continue the current entry on another
!           data page.
!
            cntinu  =  ( nelt < cursiz ) .and. ( n == ipsize )

            if ( nelt == cursiz ) then
!
!              The current element is the last of the current column
!              entry.
!
!              Determine whether we must start the next column entry on
!              a new page.  To start a column entry on the current page,
!              we must have enough room for the element count and at
!              least the first entry element.
!
               if ( remain > 0 ) then
                  newreq   =   n  > ( ipsize - 2 )
               end if

               nelt  =  1
               row   =  row   +  1

            else

               nelt  =  nelt  +  1

            end if

         end if

         if (  ( bufptr > bufsiz ) .or. ( row > nrows )  ) then
!
!           The address buffer is full or we're out of input values
!           to look at, so push the buffer contents on the stack.
!
            call zzekspsh ( ctx, bufptr-1, adrbuf )
            bufptr  =  1

         end if

         if (         cntinu &
             .or.     newreq &
             .or. ( ( row > nrows ) .and. ( ndata > 0 ) )  ) then

!
!           It's time to write out the current page.  First set the link
!           count.
!
            page ( ilcidx ) =  nlink

!
!           Write out the data page.
!
            call zzekpgwi ( ctx, handle, p, page  )

!
!           If there's more data to write, allocate another page.
!
            if ( remain > 0 ) then

               call zzekaps ( ctx, handle, segdsc, int, .false., p2, pbase )
               page = 0

               n      =  0
               nlink  =  0
               to     =  1

!
!              If we're continuing an element from the previous page,
!              link the previous page to the current one.
!
               if ( cntinu ) then
                  call zzeksfwd ( ctx, handle, int, p, p2 )
               end if

               p   =  p2

            end if
!
!           We've allocated a new data page if we needed one.
!

         end if
!
!        We've written out the last completed data page.
!

      end do
!
!     We've processed all entries of the input array.
!

      return
      end subroutine zzekac04

      !> Add an entire class 5 column to an EK segment.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         the handle of an EK file that is open for writing.
      !>                    A `begin segment for fast load' operation must
      !>                    have already been performed for the designated
      !>                    segment.
      !>
      !>     SEGDSC         is a descriptor for the segment to which data is
      !>                    to be added.  The segment descriptor is not
      !>                    updated by this routine, but some fields in the
      !>                    descriptor will become invalid after this routine
      !>                    returns.
      !>
      !>     COLDSC         is a descriptor for the column to be added.  The
      !>                    column attributes must be filled in, but any
      !>                    pointers may be uninitialized.
      !>
      !>     ENTSZS         is an array containing sizes of column entries.
      !>                    The Ith element of ENTSZS gives the size of the
      !>                    Ith column entry.  ENTSZS is used only for columns
      !>                    having variable-size entries.  For such columns,
      !>                    the dimension of ENTSZS must be at least NROWS.
      !>                    The size of null entries should be set to zero.
      !>
      !>                    For columns having fixed-size entries, the
      !>                    dimension of this array may be any positive value.
      !>
      !>     DVALS          is an array containing the entire set of column
      !>                    entries for the specified column.  The entries
      !>                    are listed in row-order:  the column entry for the
      !>                    first row of the segment is first, followed by the
      !>                    column entry for the second row, and so on.  The
      !>                    number of column entries must match the declared
      !>                    number of rows in the segment.  For columns having
      !>                    fixed-size entries, a null entry must be allocated
      !>                    the same amount of space occupied by a non-null
      !>                    entry in the array DVALS.  For columns having
      !>                    variable-size entries, null entries do not require
      !>                    any space in the DVALS array, but in any case must
      !>                    have their allocated space described correctly by
      !>                    the corresponding element of the ENTSZS array
      !>                    (described below).
      !>
      !>     ENTSZS         is an array containing sizes of column entries.
      !>                    The Ith element of ENTSZS gives the size of the
      !>                    Ith column entry.  ENTSZS is used only for columns
      !>                    having variable-size entries.  For such columns,
      !>                    the dimension of ENTSZS must be at least NROWS.
      !>                    The size of null entries should be set to zero.
      !>
      !>                    For columns having fixed-size entries, the
      !>                    dimension of this array may be any positive value.
      !>
      !>     NLFLGS         is an array of logical flags indicating whether
      !>                    the corresponding entries are null.  If the Ith
      !>                    element of NLFLGS is .FALSE., the Ith column entry
      !>                    defined by DVALS is added to the specified segment
      !>                    in the specified kernel file.
      !>
      !>                    If the Ith element of NLFGLS is .TRUE., the
      !>                    contents of the Ith column entry are undefined.
      !>
      !>                    NLFLGS is used only for columns that allow null
      !>                    values; it's ignored for other columns.
      !>
      !>## Detailed Output
      !>
      !>     None.  See $Particulars for a description of the effect of this
      !>     routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it modifies the named
      !>     EK file by adding data to the specified column.  This routine
      !>     writes the entire contents of the specified column in one shot.
      !>     This routine creates columns much more efficiently than can be
      !>     done by sequential calls to EKACED, but has the drawback that
      !>     the caller must use more memory for the routine's inputs.  This
      !>     routine cannot be used to add data to a partially completed
      !>     column.
      !>
      !>## Examples
      !>
      !>     See EKACLD.
      !>
      !>## Restrictions
      !>
      !>     1)  This routine assumes the EK scratch area has been set up
      !>         properly for a fast load operation.  This routine writes
      !>         to the EK scratch area as well.
      !>
      !>     2)  Only one segment can be created at a time using the fast
      !>         load routines.
      !>
      !>     3)  No other EK operation may interrupt a fast load.  For
      !>         example, it is not valid to issue a query while a fast load
      !>         is in progress.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 22-JUL-1996 (NJB)
      !>
      !>        Bug fix:  case of 100% null data values is now handled
      !>        correctly.  Previous version line was changed from "Beta"
      !>        to "SPICELIB."
      !>
      !>-    SPICELIB Version 1.0.0, 23-SEP-1995 (NJB)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.1.0, 22-JUL-1996 (NJB)
      !>
      !>        Bug fix:  case of 100% null data values is now handled
      !>        correctly.  The test to determine when to write a page
      !>        was fixed to handle this case.
      !>
      !>        Previous version line was changed from "Beta"
      !>        to "SPICELIB."
      module subroutine zzekac05 ( ctx, handle, segdsc, coldsc, dvals, entszs, nlflgs )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekcnamsz
      use pepper_inc_ekdatpag
      use pepper_inc_ekpage
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to new EK file.
      integer(ip), intent(in) :: segdsc ( * )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( * )  !! Column descriptor.
      real(wp), intent(in) :: dvals  ( * )  !! D.p. values to add to column.
      integer(ip), intent(in) :: entszs ( * )  !! Array of sizes of column entries.
      logical, intent(in) :: nlflgs ( * )  !! Array of null flags for column entries.
!
!     Local parameters
!
      integer(ip), parameter :: bufsiz = dpsize

      character(cnamsz) :: column

      real(wp) :: page   ( pgsizd )

      integer(ip) :: adrbuf ( bufsiz )
      integer(ip) :: bufptr
      integer(ip) :: class
      integer(ip) :: colidx
      integer(ip) :: cursiz
      integer(ip) :: from
      integer(ip) :: i
      integer(ip) :: n
      integer(ip) :: ndata
      integer(ip) :: nelt
      integer(ip) :: nlink
      integer(ip) :: nrows
      integer(ip) :: nulptr
      integer(ip) :: p
      integer(ip) :: p2
      integer(ip) :: pbase
      integer(ip) :: remain
      integer(ip) :: row
      integer(ip) :: size
      integer(ip) :: to

      logical :: cntinu
      logical :: fixsiz
      logical :: newreq
      logical :: nullok

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Grab the column's attributes.
!
      class  =  coldsc( clsidx )
      nulptr =  coldsc( nflidx )
      colidx =  coldsc( ordidx )
      size   =  coldsc( sizidx )

      nullok =  nulptr /= ifalse
      fixsiz =  size   /= ifalse

!
!     This column had better be class 5.
!
      if ( class /= 5 ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Column class code # found in descriptor for ' // &
                       'column #.  Class should be 5.'                 )
         call ctx%errint ( '#', class                                      )
         call ctx%errch  ( '#', column                                     )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

!
!     Push the column's ordinal index on the stack.  This allows us
!     to identify the column the addresses belong to.
!
      call zzekspsh ( ctx, 1, [ colidx ] )

!
!     Find the number of rows in the segment.
!
      nrows  =  segdsc ( nridx )

!
!     Record the number of data values to write.
!
      if ( nullok ) then
!
!        Sum the sizes of the non-null column entries; these are the
!        ones that will take up space.
!
         ndata  =  0

         do i = 1, nrows

            if ( .not. nlflgs(i) ) then

               if ( fixsiz ) then
                  ndata  =  ndata + size
               else
                  ndata  =  ndata + entszs(i)
               end if

            end if

         end do

      else

         if ( fixsiz ) then

            ndata  =  nrows * size

         else

            ndata  =  0

            do i = 1, nrows
               ndata  =  ndata + entszs(i)
            end do

         end if

      end if

      if ( ndata > 0 ) then
!
!        There's some data to write, so allocate a page.  Also
!        prepare a data buffer to be written out as a page.
!
         call zzekaps  ( ctx, handle, segdsc, dp, .false., p, pbase )
         page = 0.0_wp

      end if

!
!     Write the input data out to the target file a page at a time.
!     Null values don't get written.
!
!     While we're at it, we'll push onto the EK stack the addresses
!     of the column entries.  We use the constant NULL rather than an
!     address to represent null entries.
!
!     We'll use FROM to indicate the element of DVALS we're
!     considering, TO to indicate the element of PAGE to write
!     to, and BUFPTR to indicate the element of ADRBUF to write
!     addresses to.  The variable NELT is the count of the column entry
!     elements written for the current entry.  The variable N indicates
!     the number of d.p. numbers written to the current page.
!

      remain  =  ndata
      from    =  1
      to      =  1
      bufptr  =  1
      row     =  1
      nelt    =  1
      n       =  0
      nlink   =  0

      do while ( row <= nrows )

!
!        NEWREQ is set to TRUE if we discover that the next column
!        entry must start on a new page.
!
         newreq  =  .false.

         if (  nullok  .and.  ( nlflgs(row) )  ) then

            if ( fixsiz ) then
               cursiz  =  size
            else
               cursiz  =  entszs(row)
            end if

            from           =  from   +  cursiz
            adrbuf(bufptr) =  null
            bufptr         =  bufptr +  1
            row            =  row    +  1
            nelt           =  1
            cntinu         =  .false.

         else

            if ( nelt == 1 ) then
!
!              We're about to write out a new column entry.  We must
!              insert the element count into the page before writing the
!              data.  The link count for the current page must be
!              incremented to account for this new entry.
!
!              At this point, we're guaranteed at least two free
!              spaces in the current page.
!
               if ( fixsiz ) then
                  cursiz  =  size
               else
                  cursiz  =  entszs(row)
               end if

               adrbuf(bufptr) =  to     +  pbase
               bufptr         =  bufptr + 1
               page(to)       =  cursiz
               to             =  to     + 1
               n              =  n      + 1
               nlink          =  nlink  + 1

            end if

!
!           At this point, there's at least one free space in the
!           current page.
!
            page(to)  =  dvals(from)
            to        =  to      +  1
            n         =  n       +  1
            from      =  from    +  1
            remain    =  remain  -  1

!
!           Decide whether we must continue the current entry on another
!           data page.
!
            cntinu  =  ( nelt < cursiz ) .and. ( n == dpsize )

            if ( nelt == cursiz ) then
!
!              The current element is the last of the current column
!              entry.
!
!              Determine whether we must start the next column entry on
!              a new page.  To start a column entry on the current page,
!              we must have enough room for the element count and at
!              least the first entry element.
!
               if ( remain > 0 ) then
                  newreq   =   n  > ( dpsize - 2 )
               end if

               nelt  =  1
               row   =  row   +  1

            else

               nelt  =  nelt  +  1

            end if

         end if

         if (  ( bufptr > bufsiz ) .or. ( row > nrows )  ) then
!
!           The address buffer is full or we're out of input values
!           to look at, so push the buffer contents on the stack.
!
            call zzekspsh ( ctx, bufptr-1, adrbuf )
            bufptr  =  1

         end if

         if (         cntinu &
             .or.     newreq &
             .or. ( ( row > nrows ) .and. ( ndata > 0 ) )  ) then
!
!           It's time to write out the current page.  First set the link
!           count.
!
            page ( dlcidx ) =  nlink

!
!           Write out the data page.
!
            call zzekpgwd ( ctx, handle, p, page  )

!
!           If there's more data to write, allocate another page.
!
            if ( remain > 0 ) then

               call zzekaps ( ctx, handle, segdsc, dp, .false., p2, pbase )
               page = 0.0_wp

               n      =  0
               nlink  =  0
               to     =  1

!
!              If we're continuing an element from the previous page,
!              link the previous page to the current one.
!
               if ( cntinu ) then
                  call zzeksfwd ( ctx, handle, dp, p, p2 )
               end if

               p   =  p2

            end if
!
!           We've allocated a new data page if we needed one.
!

         end if
!
!        We've written out the last completed data page.
!

      end do
!
!     We've processed all entries of the input array.
!

      return
      end subroutine zzekac05

      !> Add an entire class 6 column to an EK segment.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         the handle of an EK file that is open for writing.
      !>                    A `begin segment for fast load' operation must
      !>                    have already been performed for the designated
      !>                    segment.
      !>
      !>     SEGDSC         is a descriptor for the segment to which data is
      !>                    to be added.  The segment descriptor is not
      !>                    updated by this routine, but some fields in the
      !>                    descriptor will become invalid after this routine
      !>                    returns.
      !>
      !>     COLDSC         is a descriptor for the column to be added.  The
      !>                    column attributes must be filled in, but any
      !>                    pointers may be uninitialized.
      !>
      !>     ENTSZS         is an array containing sizes of column entries.
      !>                    The Ith element of ENTSZS gives the size of the
      !>                    Ith column entry.  ENTSZS is used only for columns
      !>                    having variable-size entries.  For such columns,
      !>                    the dimension of ENTSZS must be at least NROWS.
      !>                    The size of null entries should be set to zero.
      !>
      !>                    For columns having fixed-size entries, the
      !>                    dimension of this array may be any positive value.
      !>
      !>     CVALS          is an array containing the entire set of column
      !>                    entries for the specified column.  The entries
      !>                    are listed in row-order:  the column entry for the
      !>                    first row of the segment is first, followed by the
      !>                    column entry for the second row, and so on.  The
      !>                    number of column entries must match the declared
      !>                    number of rows in the segment.  For columns having
      !>                    fixed-size entries, a null entry must be allocated
      !>                    the same amount of space occupied by a non-null
      !>                    entry in the array CVALS.  For columns having
      !>                    variable-size entries, null entries do not require
      !>                    any space in the CVALS array, but in any case must
      !>                    have their allocated space described correctly by
      !>                    the corresponding element of the ENTSZS array
      !>                    (described below).
      !>
      !>     ENTSZS         is an array containing sizes of column entries.
      !>                    The Ith element of ENTSZS gives the size of the
      !>                    Ith column entry.  ENTSZS is used only for columns
      !>                    having variable-size entries.  For such columns,
      !>                    the dimension of ENTSZS must be at least NROWS.
      !>                    The size of null entries should be set to zero.
      !>
      !>                    For columns having fixed-size entries, the
      !>                    dimension of this array may be any positive value.
      !>
      !>     NLFLGS         is an array of logical flags indicating whether
      !>                    the corresponding entries are null.  If the Ith
      !>                    element of NLFLGS is .FALSE., the Ith column entry
      !>                    defined by CVALS is added to the specified segment
      !>                    in the specified kernel file.
      !>
      !>                    If the Ith element of NLFGLS is .TRUE., the
      !>                    contents of the Ith column entry are undefined.
      !>
      !>                    NLFLGS is used only for columns that allow null
      !>                    values; it's ignored for other columns.
      !>
      !>## Detailed Output
      !>
      !>     None.  See $Particulars for a description of the effect of this
      !>     routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it modifies the named
      !>     EK file by adding data to the specified column.  This routine
      !>     writes the entire contents of the specified column in one shot.
      !>     This routine creates columns much more efficiently than can be
      !>     done by sequential calls to EKACEI, but has the drawback that
      !>     the caller must use more memory for the routine's inputs.  This
      !>     routine cannot be used to add data to a partially completed
      !>     column.
      !>
      !>## Examples
      !>
      !>     See EKACLC.
      !>
      !>## Restrictions
      !>
      !>     1)  This routine assumes the EK scratch area has been set up
      !>         properly for a fast load operation.  This routine writes
      !>         to the EK scratch area as well.
      !>
      !>     2)  Currently, the EK system can handle only one fast load
      !>         at at time---one segment created by a fast load must be
      !>         be completed by a call to EKFFLD before another segment
      !>         can be created by a fast load, even if the two segments
      !>         reside in different files.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 22-JUL-1996 (NJB)
      !>
      !>        Bug fix:  case of 100% null data values is now handled
      !>        correctly.  Previous version line was changed from "Beta"
      !>        to "SPICELIB."
      !>
      !>-    SPICELIB Version 1.0.0, 26-SEP-1995 (NJB)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.1.0, 22-JUL-1996 (NJB)
      !>
      !>        Bug fix:  case of 100% null data values is now handled
      !>        correctly.  The test to determine when to write a page
      !>        was fixed to handle this case.
      !>
      !>        Previous version line was changed from "Beta"
      !>        to "SPICELIB."
      module subroutine zzekac06 ( ctx, handle, segdsc, coldsc, cvals, entszs, nlflgs )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekcnamsz
      use pepper_inc_ekdatpag
      use pepper_inc_ekpage
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to new EK file.
      integer(ip), intent(in) :: segdsc ( * )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( * )  !! Column descriptor.
      character(*), intent(in) :: cvals  ( * )  !! Character values to add to column.
      integer(ip), intent(in) :: entszs ( * )  !! Array of sizes of column entries.
      logical, intent(in) :: nlflgs ( * )  !! Array of null flags for column entries.
!
!     Local parameters
!
      integer(ip), parameter :: bufsiz = cpsize

      character(cnamsz) :: column
      character(pgsizc) :: page

      integer(ip) :: adrbuf ( bufsiz )
      integer(ip) :: bufptr
      integer(ip) :: class
      integer(ip) :: colidx
      integer(ip) :: cp
      integer(ip) :: curchr
      integer(ip) :: cursiz
      integer(ip) :: cvlen
      integer(ip) :: from
      integer(ip) :: i
      integer(ip) :: l
      integer(ip) :: n
      integer(ip) :: nchars
      integer(ip) :: ndata
      integer(ip) :: nlink
      integer(ip) :: nrows
      integer(ip) :: nulptr
      integer(ip) :: nw
      integer(ip) :: nwrite
      integer(ip) :: p
      integer(ip) :: p2
      integer(ip) :: padlen
      integer(ip) :: pbase
      integer(ip) :: remain
      integer(ip) :: room
      integer(ip) :: row
      integer(ip) :: size
      integer(ip) :: strlen
      integer(ip) :: to

      logical :: cntinu
      logical :: fixsiz
      logical :: newent
      logical :: newreq
      logical :: nullok
      logical :: pad

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Grab the column's attributes.
!
      class  =  coldsc( clsidx )
      nulptr =  coldsc( nflidx )
      colidx =  coldsc( ordidx )
      size   =  coldsc( sizidx )
      strlen =  coldsc( lenidx )

      nullok =  nulptr /= ifalse
      fixsiz =  size   /= ifalse

!
!     This column had better be class 6.
!
      if ( class /= 6 ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Column class code # found in descriptor for ' // &
                       'column #.  Class should be 6.'                 )
         call ctx%errint ( '#', class                                      )
         call ctx%errch  ( '#', column                                     )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

!
!     Push the column's ordinal index on the stack.  This allows us
!     to identify the column the addresses belong to.
!
      call zzekspsh ( ctx, 1, [ colidx ] )

!
!     Find the number of rows in the segment.
!
      nrows   =  segdsc ( nridx )

!
!     Record the number of data values to write.
!
      if ( nullok ) then
!
!        Sum the sizes of the non-null column entries; these are the
!        ones that will take up space.
!
         ndata  =  0

         do i = 1, nrows

            if ( .not. nlflgs(i) ) then

               if ( fixsiz ) then
                  ndata  =  ndata   +  strlen * size
               else
                  ndata  =  ndata   +  strlen * entszs(i)
               end if

            end if

         end do

      else

         if ( fixsiz ) then

            ndata  =  nrows * strlen * size

         else

            ndata  =  0

            do i = 1, nrows
               ndata  =  ndata   +  strlen * entszs(i)
            end do

         end if

      end if

      if ( ndata > 0 ) then
!
!        There's some data to write, so allocate a page.  Also
!        prepare a data buffer to be written out as a page.
!
         call zzekaps  ( ctx, handle, segdsc, chr, .false., p, pbase )
         page  =  ' '

!
!        Decide now whether we will need to pad the input entry
!        elements with trailing blanks, and if so how much padding
!        we'll need.
!
         cvlen   =  min (  len( cvals(1) ),  strlen  )
         pad     =  cvlen  <  strlen

         if ( pad ) then
            padlen  =  strlen - cvlen
         end if

      end if

!
!     Write the input data out to the target file a page at a time.
!     Null values don't get written.
!
!     While we're at it, we'll push onto the EK stack the addresses
!     of the column entries.  We use the constant NULL rather than an
!     address to represent null entries.
!
!     We'll use FROM to indicate the element of CVALS we're
!     considering, TO to indicate the element of PAGE to write
!     to, and BUFPTR to indicate the element of ADRBUF to write
!     addresses to.   The variable N indicates the number of characters
!     written to the current page.  NCHARS is the number of characters
!     written in the current column entry. CP is the position in the
!     current input string of the character which we'll read next.
!

      remain  =  ndata
      from    =  1
      to      =  1
      bufptr  =  1
      row     =  1
      cp      =  1
      n       =  0
      nchars  =  0
      nlink   =  0
      newent  =  .true.

      do while ( row <= nrows )
!
!        NEWREQ is set to TRUE if we discover that the next column
!        entry must start on a new page.
!
         newreq  =  .false.

!
!        FROM and TO are expected to be properly set at this point.
!

         if (  nullok  .and.  ( nlflgs(row) )  ) then

            if ( fixsiz ) then
               cursiz  =  size
            else
               cursiz  =  entszs(row)
            end if

            from           =  from   +  cursiz
            adrbuf(bufptr) =  null
            bufptr         =  bufptr +  1
            row            =  row    +  1
            cntinu         =  .false.
            newent         =  .true.

         else

            if ( newent ) then
!
!              We're about to write out a new column entry.  We must
!              insert the element count into the page before writing the
!              data.  The link count for the current page must be
!              incremented to account for this new entry.
!
!              At this point, we're guaranteed at least ENCSIZ+1 free
!              spaces in the current page.
!
               if ( fixsiz ) then
                  cursiz  =  size
               else
                  cursiz  =  entszs(row)
               end if

               curchr         =  cursiz *  strlen
               nchars         =  0
               cp             =  1

               adrbuf(bufptr) =  to     +  pbase
               bufptr         =  bufptr + 1

               call prtenc ( ctx,  cursiz,  page( to : to+encsiz-1 )  )

               to             =  to     + encsiz
               n              =  n      + encsiz
               nlink          =  nlink  + 1
               newent         =  .false.

            end if

!
!           At this point, there's at least one free space in the
!           current page.  There's also at least one character to
!           write.  Transfer as much as possible of the current
!           column entry to the current page.
!
            room     =  cpsize - n
            nwrite   =  min ( curchr-nchars, room )
            nw       =  nwrite

            do while ( nw > 0 )
!
!              At this point, we're guaranteed that
!
!                 CP      <=  STRLEN
!                 TO      <   CPSIZE
!                 FROM is set correctly.
!
               if ( pad ) then
!
!                 The input strings must be padded with blanks up to
!                 a length of STRLEN characters.  The number of blanks
!                 used to pad the input is PADLEN.
!
                  if ( cp < cvlen ) then
!
!                    Compute the number of `actual' characters of data
!                    left in the current input string.
!
!                    Transfer the characters we have room for from the
!                    current input string to the current page.
!
                     l                    =  cvlen - cp + 1
                     l                    =  min ( l, nw  )

                     page( to : to+l-1 )  =  cvals(from)( cp : cp+l-1 )
                     cp                   =  cp  + l
                     nw                   =  nw  - l
                     to                   =  to  + l

                  else
!
!                    The input character pointer is in the `pad' zone.
!                    Let L be the length of padding that is required
!                    and can fit in the page.
!
                     l                    =  strlen - cp + 1
                     l                    =  min ( l, nw )

                     page( to : to+l-1 )  =  ' '
                     cp                   =  cp  + l
                     nw                   =  nw  - l
                     to                   =  to  + l

                  end if

               else
!
!                 The input data doesn't require padding.
!
!                 Compute the number of `actual' characters of data
!                 left in the current input string.
!
!                 Transfer the characters we have room for from the
!                 current input string to the current page.
!
                  l                    =  strlen - cp + 1
                  l                    =  min ( l, nw )

                  page( to : to+l-1 )  =  cvals(from)( cp : cp+l-1 )
                  cp                   =  cp + l
                  nw                   =  nw - l
                  to                   =  to + l

               end if

!
!              If the input pointer is beyond the end of the declared
!              length of the target column's strings STRLEN, it's time
!              to look at the next input string.
!
               if ( cp > strlen ) then
                  from  =  from + 1
                  cp    =  1
               end if

            end do

!
!           We've written NWRITE characters to the current page.  FROM,
!           TO, and CP are set.
!
            n         =  n       +  nwrite
            remain    =  remain  -  nwrite
            nchars    =  nchars  +  nwrite

!
!           Decide whether we must continue the current entry on another
!           data page.
!
            cntinu  =  ( nchars < curchr ) .and. ( n == cpsize )

!
!           If we've finished writing out a column entry, get ready
!           to write the next one.
!
            if ( nchars == curchr ) then
!
!              The current character is the last of the current column
!              entry.
!
!              Determine whether we must start the next column entry on
!              a new page.  To start a column entry on the current page,
!              we must have enough room for the element count and at
!              least one character of data.
!
               if ( remain > 0 ) then
                  newreq   =   n  > ( cpsize - encsiz - 1 )
               end if

               row     =   row   +  1
               newent  =  .true.

            end if

         end if

!
!        At this point, CNTINU indicates whether we need to continue
!        the current entry on another page.  If we finished writing out
!        the entry, CNTINU is .FALSE.
!

         if (  ( bufptr > bufsiz ) .or. ( row > nrows )  ) then
!
!           The address buffer is full or we're out of input values
!           to look at, so push the buffer contents on the stack.
!
            call zzekspsh ( ctx, bufptr-1, adrbuf )
            bufptr  =  1

         end if

         if (         cntinu &
             .or.     newreq &
             .or. ( ( row > nrows ) .and. ( ndata > 0 ) )  ) then
!
!           It's time to write out the current page.  First set the link
!           count.
!
            call prtenc ( ctx,  nlink,  page ( clcidx : clcidx+encsiz-1 )  )

!
!           Write out the data page.
!
            call zzekpgwc ( ctx, handle, p, page  )

!
!           If there's more data to write, allocate another page.
!
            if ( remain > 0 ) then

               call zzekaps ( ctx, handle, segdsc, chr, .false., p2, pbase )
               page   = ' '

               n      =  0
               nlink  =  0
               to     =  1

!
!              If we're continuing an element from the previous page,
!              link the previous page to the current one.
!
               if ( cntinu ) then
                  call zzeksfwd ( ctx, handle, chr, p, p2 )
               end if

               p   =  p2

            end if
!
!           We've allocated a new data page if we needed one.
!

         end if
!
!        We've written out the last completed data page.
!

      end do
!
!     We've processed all entries of the input array.
!

      return
      end subroutine zzekac06

      !> Add a column entry to a specified record in a class 4 column.
      !> The entries of class 4 columns are arrays of integer values.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is a file handle of an EK open for write access.
      !>
      !>     SEGDSC         is the descriptor of the segment in which
      !>                    the specified column entry is to be written.
      !>
      !>     COLDSC         is the descriptor of the column in which
      !>                    the specified column entry is to be written.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry to be written.
      !>
      !>     NVALS,
      !>     IVALS          are, respectively, the number of values to add to
      !>                    the specified column and the set of values
      !>                    themselves.  The data values are written into the
      !>                    specified column and record.
      !>
      !>                    If the column has fixed-size entries, then NVALS
      !>                    must equal the entry size for the specified column.
      !>
      !>                    Only one value can be added to a virtual column.
      !>
      !>     ISNULL         is a logical flag indicating whether the entry is
      !>                    null.  If ISNULL is .FALSE., the column entry
      !>                    defined by NVALS and IVALS is added to the
      !>                    specified kernel file.
      !>
      !>                    If ISNULL is .TRUE., NVALS and IVALS are ignored.
      !>                    The contents of the column entry are undefined.
      !>                    If the column has fixed-length, variable-size
      !>                    entries, the number of entries is considered to
      !>                    be 1.
      !>
      !>## Detailed Output
      !>
      !>     None.  See the $Particulars section for a description of the
      !>     effect of this routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.  The file is not modified.
      !>
      !>     2)  If the ordinal position of the column specified by COLDSC
      !>         is out of range, the error SPICE(INVALIDINDEX) is signaled.
      !>         The file is not modified.
      !>
      !>     3)  If the input flag ISNULL is .TRUE. but the target column
      !>         does not allow nulls, the error SPICE(BADATTRIBUTE) is
      !>         signaled.  The file is not modified.
      !>
      !>     4)  If RECPTR is invalid, a DAS addressing error may occur.  The
      !>         error in *not* trapped in advance.  This routine assumes that
      !>         a valid value of RECPTR has been supplied by the caller.
      !>
      !>     3)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.  The file may be corrupted.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it sets the value of a
      !>     column entry in an EK segment.  If the column is indexed, the
      !>     index is updated to reflect the presence of the new entry.  This
      !>     routine is intended to set values of uninitialized column entries
      !>     only.  To update existing entries, use the ZZEKUExx routines, or
      !>     at the user level, the EKUCEx routines.
      !>
      !>     This routine does not participate in shadowing functions.  If the
      !>     target EK is shadowed, the caller is responsible for performing
      !>     necessary backup operations.  If the target EK is not shadowed,
      !>     the target record's status is not modified.
      !>
      !>     The changes made by this routine to the target EK file become
      !>     permanent when the file is closed.  Failure to close the file
      !>     properly will leave it in an indeterminate state.
      !>
      !>## Examples
      !>
      !>     See EKACEI.
      !>
      !>## Restrictions
      !>
      !>     1) This routine cannot be used to update existing column entries.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 03-OCT-2021 (NJB)
      !>
      !>        Corrected typos in comments.
      !>
      !>-    Beta Version 1.0.0, 26-SEP-1995 (NJB)
      module subroutine zzekad04 ( ctx, handle, segdsc, coldsc, recptr, nvals, ivals, isnull )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(inout) :: segdsc ( * )  !! Segment descriptor. (PEPPER: changed by the routine, an input in SPICELIB's table)
      integer(ip), intent(in) :: coldsc ( * )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      integer(ip), intent(in) :: nvals  !! Number of values to add to column.
      integer(ip), intent(in) :: ivals  ( * )  !! Integer values to add to column.
      logical, intent(in) :: isnull  !! Flag indicating whether column entry is null.
!
!     Local variables
!
      integer(ip) :: colidx
      integer(ip) :: datptr
      integer(ip) :: lastw
      integer(ip) :: mbase
      integer(ip) :: ncols
      integer(ip) :: nlinks
      integer(ip) :: nrec
      integer(ip) :: nwrite
      integer(ip) :: p
      integer(ip) :: p2
      integer(ip) :: pbase
      integer(ip) :: ptrloc
      integer(ip) :: recno
      integer(ip) :: remain
      integer(ip) :: room
      integer(ip) :: start

      logical :: fstpag

      nrec    =  segdsc ( nridx  )
      colidx  =  coldsc ( ordidx )

!
!     Make sure the column exists.
!
      ncols  =  segdsc ( ncidx )

      if (  ( colidx < 1 ) .or. ( colidx > ncols )  ) then

         call ctx%setmsg ( 'Column index = #; valid range is 1:#.' )
         call ctx%errint ( '#',  colidx                            )
         call ctx%errint ( '#',  nrec                              )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                   )
         return

      end if

!
!     If the value is null, make sure that nulls are permitted
!     in this column.
!
      if (  isnull  .and.  ( coldsc(nflidx) /= itrue )  ) then

         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Column having index # in segment # does '  // &
                       'not allow nulls, but a null value was '    // &
                       'supplied for the element in record #.'     )
         call ctx%errint ( '#',  colidx                                )
         call ctx%errint ( '#',  segdsc(snoidx)                        )
         call ctx%errint ( '#',  recno                                 )
         call ctx%sigerr ( 'SPICE(BADATTRIBUTE)'                       )
         return

      end if

!
!     Check NVALS.  If the column has fixed-size entries, NVALS must
!     match the declared entry size.  In all cases, NVALS must be
!     positive.
!
      if ( nvals < 1 ) then

         call ctx%setmsg ( 'COLIDX = #;  segment = #; NVALS = #;  '  // &
                       'NVALS must be positive '                   )
         call ctx%errint ( '#',  colidx                                )
         call ctx%errint ( '#',  segdsc(snoidx)                        )
         call ctx%errint ( '#',  nvals                                 )
         call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                       )
         return

      end if

      if ( coldsc(sizidx) /= ifalse ) then

         if ( nvals /= coldsc(sizidx) ) then

            call ctx%setmsg ( 'COLIDX = #;  segment = #; NVALS = #; '     // &
                          'declared entry size = #.  Sizes must match.')
            call ctx%errint ( '#',  colidx                                 )
            call ctx%errint ( '#',  segdsc(snoidx)                         )
            call ctx%errint ( '#',  nvals                                  )
            call ctx%errint ( '#',  coldsc(sizidx)                         )
            call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                        )
            return

         end if

      end if

!
!     Compute the data pointer location.
!
      ptrloc  =  recptr + dptbas + colidx

      if ( isnull ) then
!
!        All we need do is set the data pointer.  The segment's
!        metadata are not affected.
!
         call dasudi ( ctx, handle, ptrloc, ptrloc, [ null ] )

      else

         lastw   =  segdsc ( liwidx )
         room    =  ipsize - lastw
         remain  =  nvals
         start   =  1
         fstpag  =  .true.

         do while ( remain > 0 )
!
!           Decide where to write the data values.  In order to write
!           to the current page, we require enough room for the count
!           and at least one column entry element.
!
            if ( room >= 2 ) then
!
!              There's room in the current page.  If this is the first
!              page this entry is written on, set the data pointer
!              and count.  Write as much of the value as possible to
!              the current page.
!
               p       =   segdsc(lipidx)

               call zzekpgbs ( ctx, int,  p,  pbase )

               datptr  =  pbase + lastw + 1

               if ( fstpag ) then

                  call dasudi ( ctx, handle, ptrloc, ptrloc, [ datptr ] )
                  call dasudi ( ctx, handle, datptr, datptr, [ nvals ] )

                  room    =  room   - 1
                  datptr  =  datptr + 1

               end if

               nwrite  =  min ( remain, room )

               call dasudi ( ctx, handle, &
                             datptr, &
                             datptr+nwrite-1, &
                             ivals ( start )  )

               remain  =  remain - nwrite
               room    =  room   - nwrite
               start   =  start  + nwrite

!
!              The page containing the data item gains a link.
!
               call zzekglnk ( ctx, handle, int, p, nlinks   )
               call zzekslnk ( ctx, handle, int, p, nlinks+1 )

!
!              The last integer word in use must be updated.  Account
!              for the count, if this is the first page on which the
!              current entry is written.
!
               if ( fstpag ) then
                  segdsc ( liwidx )  =  lastw + 1 + nwrite
                  fstpag             =  .false.
               else
                  segdsc ( liwidx )  =  lastw + nwrite
               end if

            else
!
!              Allocate a data page.  If this is not the first data
!              page written to, link the previous page to the current
!              one.
!
               call zzekaps ( ctx, handle, segdsc, int, .false., p2, pbase )

               if ( .not. fstpag ) then
                  call zzeksfwd ( ctx, handle, int, p, p2 )
               end if

!
!              The last integer page and word in use must be updated.
!
               p                  =  p2
               lastw              =  0
               segdsc ( lipidx )  =  p
               segdsc ( liwidx )  =  lastw
               room               =  ipsize

!
!              Make sure the link count is zeroed out.
!
               call zzekslnk ( ctx, handle, int, p, 0 )

            end if

         end do

      end if

!
!     Write out the updated segment descriptor.
!
      mbase  =  segdsc(imdidx)

      call dasudi ( ctx, handle, mbase+1, mbase+sdscsz, segdsc )

!
!     Class 4 columns are not indexed, so we need not update any
!     index to account for the new element.
!

      return
      end subroutine zzekad04

      !> Add a column entry to a specified record in a class 5 column.
      !> The entries of class 5 columns are arrays of d.p. values.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is a file handle of an EK open for write access.
      !>
      !>     SEGNO          is the index of the segment to which data is to
      !>                    be added.
      !>
      !>     RECNO          is the index of the record to which data is to be
      !>                    added.  This record number is relative to the start
      !>                    of the segment indicated by SEGNO; the first
      !>                    record in the segment has index 1.
      !>
      !>     COLUMN         is the name of the column to which data is to be
      !>                    added.
      !>
      !>     NVALS,
      !>     DVALS          are, respectively, the number of values to add to
      !>                    the specified column and the set of values
      !>                    themselves.  The data values are written into the
      !>                    specified column and record.
      !>
      !>                    If the  column has fixed-size entries, then NVALS
      !>                    must equal the entry size for the specified column.
      !>
      !>                    Only one value can be added to a virtual column.
      !>
      !>     ISNULL         is a logical flag indicating whether the entry is
      !>                    null.  If ISNULL is .FALSE., the column entry
      !>                    defined by NVALS and DVALS is added to the
      !>                    specified kernel file.
      !>
      !>                    If ISNULL is .TRUE., NVALS and DVALS are ignored.
      !>                    The contents of the column entry are undefined.
      !>                    If the column has fixed-length, variable-size
      !>                    entries, the number of entries is considered to
      !>                    be 1.
      !>
      !>## Detailed Output
      !>
      !>     None.  See the $Particulars section for a description of the
      !>     effect of this routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.  The file is not modified.
      !>
      !>     2)  If the ordinal position of the column specified by COLDSC
      !>         is out of range, the error SPICE(INVALIDINDEX) is signaled.
      !>         The file is not modified.
      !>
      !>     3)  If the input flag ISNULL is .TRUE. but the target column
      !>         does not allow nulls, the error SPICE(BADATTRIBUTE) is
      !>         signaled.  The file is not modified.
      !>
      !>     4)  If RECPTR is invalid, a DAS addressing error may occur.  The
      !>         error in *not* trapped in advance.  This routine assumes that
      !>         a valid value of RECPTR has been supplied by the caller.
      !>
      !>     3)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.  The file may be corrupted.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it sets the value of a
      !>     column entry in an EK segment.  If the column is indexed, the
      !>     index is updated to reflect the presence of the new entry.  This
      !>     routine is intended to set values of uninitialized column entries
      !>     only.  To update existing entries, use the ZZEKUExx routines, or
      !>     at the user level, the EKUCEx routines.
      !>
      !>     This routine does not participate in shadowing functions.  If the
      !>     target EK is shadowed, the caller is responsible for performing
      !>     necessary backup operations.  If the target EK is not shadowed,
      !>     the target record's status is not modified.
      !>
      !>     The changes made by this routine to the target EK file become
      !>     permanent when the file is closed.  Failure to close the file
      !>     properly will leave it in an indeterminate state.
      !>
      !>## Examples
      !>
      !>     See EKACED.
      !>
      !>## Restrictions
      !>
      !>     1) This routine cannot be used to update existing column entries.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 03-OCT-2021 (NJB)
      !>
      !>        Corrected typos in comments.
      !>
      !>-    Beta Version 1.0.0, 27-SEP-1995 (NJB)
      module subroutine zzekad05 ( ctx, handle, segdsc, coldsc, recptr, nvals, dvals, isnull )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to new EK file.
      integer(ip), intent(inout) :: segdsc ( * )  !! Segment descriptor. (PEPPER: changed by the routine, an input in SPICELIB's table)
      integer(ip), intent(in) :: coldsc ( * )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Pointer to the record to which data is to be added.
      integer(ip), intent(in) :: nvals  !! Number of values to add to column.
      real(wp), intent(in) :: dvals  ( * )  !! Double precision values to add to column.
      logical, intent(in) :: isnull  !! Flag indicating whether column entry is null.
!
!     Local variables
!
      integer(ip) :: colidx
      integer(ip) :: datptr
      integer(ip) :: lastw
      integer(ip) :: mbase
      integer(ip) :: ncols
      integer(ip) :: nlinks
      integer(ip) :: nrec
      integer(ip) :: nwrite
      integer(ip) :: p
      integer(ip) :: p2
      integer(ip) :: pbase
      integer(ip) :: prvbas
      integer(ip) :: ptrloc
      integer(ip) :: recno
      integer(ip) :: remain
      integer(ip) :: room
      integer(ip) :: start

      logical :: fstpag

      nrec    =  segdsc ( nridx  )
      colidx  =  coldsc ( ordidx )

!
!     Make sure the column exists.
!
      ncols  =  segdsc ( ncidx )

      if (  ( colidx < 1 ) .or. ( colidx > ncols )  ) then

         call ctx%setmsg ( 'Column index = #; valid range is 1:#.' )
         call ctx%errint ( '#',  colidx                            )
         call ctx%errint ( '#',  nrec                              )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                   )
         return

      end if

!
!     If the value is null, make sure that nulls are permitted
!     in this column.
!
      if (  isnull  .and.  ( coldsc(nflidx) /= itrue )  ) then

         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Column having index # in segment # does '  // &
                       'not allow nulls, but a null value was '    // &
                       'supplied for the element in record #.'     )
         call ctx%errint ( '#',  colidx                                )
         call ctx%errint ( '#',  segdsc(snoidx)                        )
         call ctx%errint ( '#',  recno                                 )
         call ctx%sigerr ( 'SPICE(BADATTRIBUTE)'                       )
         return

      end if

!
!     Check NVALS.  If the column has fixed-size entries, NVALS must
!     match the declared entry size.  In all cases, NVALS must be
!     positive.
!
      if ( nvals < 1 ) then

         call ctx%setmsg ( 'COLIDX = #;  segment = #; NVALS = #;  '  // &
                       'NVALS must be positive '                   )
         call ctx%errint ( '#',  colidx                                )
         call ctx%errint ( '#',  segdsc(snoidx)                        )
         call ctx%errint ( '#',  nvals                                 )
         call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                       )
         return

      end if

      if ( coldsc(sizidx) /= ifalse ) then

         if ( nvals /= coldsc(sizidx) ) then

            call ctx%setmsg ( 'COLIDX = #;  segment = #; NVALS = #; '     // &
                          'declared entry size = #.  Sizes must match.')
            call ctx%errint ( '#',  colidx                                 )
            call ctx%errint ( '#',  segdsc(snoidx)                         )
            call ctx%errint ( '#',  nvals                                  )
            call ctx%errint ( '#',  coldsc(sizidx)                         )
            call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                        )
            return

         end if

      end if

!
!     Compute the data pointer location.
!
      ptrloc  =  recptr + dptbas + colidx

      if ( isnull ) then
!
!        All we need do is set the data pointer.  The segment's
!        metadata are not affected.
!
         call dasudi ( ctx, handle, ptrloc, ptrloc, [ null ] )

      else

         lastw   =  segdsc ( ldwidx )
         room    =  dpsize - lastw
         remain  =  nvals
         start   =  1
         fstpag  =  .true.

         do while ( remain > 0 )
!
!           Decide where to write the data values.  In order to write
!           to the current page, we require enough room for the count
!           and at least one column entry element.
!
            if ( room >= 2 ) then
!
!              There's room in the current page.  If this is the first
!              page this entry is written on, set the data pointer
!              and count.  Write as much of the value as possible to
!              the current page.
!
               p       =   segdsc(ldpidx)

               call zzekpgbs ( ctx, dp,  p,  pbase )

               prvbas  =  pbase
               datptr  =  pbase + lastw + 1

               if ( fstpag ) then

                  call dasudi ( ctx, handle, ptrloc, ptrloc, [ datptr ] )
                  call dasudd ( ctx, handle, datptr, datptr, [ real(nvals, wp) ] )

                  room    =  room   - 1
                  datptr  =  datptr + 1

               end if

               nwrite  =  min ( remain, room )

               call dasudd ( ctx, handle, &
                             datptr, &
                             datptr+nwrite-1, &
                             dvals ( start )  )

               remain  =  remain - nwrite
               room    =  room   - nwrite
               start   =  start  + nwrite

!
!              The page containing the data item gains a link.
!
               call zzekglnk ( ctx, handle, dp, p, nlinks   )
               call zzekslnk ( ctx, handle, dp, p, nlinks+1 )

!
!              The last d.p. word in use must be updated.  Account
!              for the count, if this is the first page on which the
!              current entry is written.
!
               if ( fstpag ) then
                  segdsc ( ldwidx )  =  lastw + 1 + nwrite
                  fstpag             =  .false.
               else
                  segdsc ( ldwidx )  =  lastw + nwrite
               end if

            else
!
!              Allocate a d.p. data page.  If this is not the first data
!              page written to, link the previous page to the current
!              one.
!
               call zzekaps ( ctx, handle, segdsc, dp, .false., p2, pbase )

               if ( .not. fstpag ) then
                  call zzeksfwd ( ctx, handle, dp, p, p2 )
               end if

!
!              The last d.p. page and word in use must be updated.
!
               p                  =  p2
               lastw              =  0
               segdsc ( ldpidx )  =  p
               segdsc ( ldwidx )  =  lastw
               room               =  dpsize
!
!              Make sure the link count is zeroed out.
!
               call zzekslnk ( ctx, handle, dp, p, 0 )

            end if

         end do

      end if

!
!     Write out the updated segment descriptor.
!
      mbase  =  segdsc(imdidx)

      call dasudi ( ctx, handle, mbase+1, mbase+sdscsz, segdsc )

!
!     Class 5 columns are not indexed, so we need not update any
!     index to account for the new element.
!

      return
      end subroutine zzekad05

      !> Add a column entry to a specified record in a class 6 column.
      !> The entries of class 6 columns are arrays of character string
      !> values.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is the handle of an EK file that is open for write
      !>                    access.
      !>
      !>     SEGNO          is the index of the segment to which data is to
      !>                    be added.
      !>
      !>     RECNO          is the index of the record to which data is to be
      !>                    added.  This record number is relative to the start
      !>                    of the segment indicated by SEGNO; the first
      !>                    record in the segment has index 1.
      !>
      !>     COLUMN         is the name of the column to which data is to be
      !>                    added.
      !>
      !>     NVALS,
      !>     CVALS          are, respectively, the number of values to add to
      !>                    the specified column and the set of values
      !>                    themselves.  The data values are written into the
      !>                    specified column and record.
      !>
      !>                    If the  column has fixed-size entries, then NVALS
      !>                    must equal the entry size for the specified column.
      !>
      !>                    Only one value can be added to a virtual column.
      !>
      !>     ISNULL         is a logical flag indicating whether the entry is
      !>                    null.  If ISNULL is .FALSE., the column entry
      !>                    defined by NVALS and CVALS is added to the
      !>                    specified kernel file.
      !>
      !>                    If ISNULL is .TRUE., NVALS and CVALS are ignored.
      !>                    The contents of the column entry are undefined.
      !>                    If the column has fixed-length, variable-size
      !>                    entries, the number of entries is considered to
      !>                    be 1.
      !>
      !>## Detailed Output
      !>
      !>     None.  See the $Particulars section for a description of the
      !>     effect of this routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.  The file is not modified.
      !>
      !>     2)  If the ordinal position of the column specified by COLDSC
      !>         is out of range, the error SPICE(INVALIDINDEX) is signaled.
      !>         The file is not modified.
      !>
      !>     3)  If the input flag ISNULL is .TRUE. but the target column
      !>         does not allow nulls, the error SPICE(BADATTRIBUTE) is
      !>         signaled.  The file is not modified.
      !>
      !>     4)  If RECPTR is invalid, a DAS addressing error may occur.  The
      !>         error in *not* trapped in advance.  This routine assumes that
      !>         a valid value of RECPTR has been supplied by the caller.
      !>
      !>     3)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.  The file may be corrupted.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it sets the value of a
      !>     column entry in an EK segment.  If the column is indexed, the
      !>     index is updated to reflect the presence of the new entry.  This
      !>     routine is intended to set values of uninitialized column entries
      !>     only.  To update existing entries, use the ZZEKUExx routines, or
      !>     at the user level, the EKUCEx routines.
      !>
      !>     This routine does not participate in shadowing functions.  If the
      !>     target EK is shadowed, the caller is responsible for performing
      !>     necessary backup operations.  If the target EK is not shadowed,
      !>     the target record's status is not modified.
      !>
      !>     The changes made by this routine to the target EK file become
      !>     permanent when the file is closed.  Failure to close the file
      !>     properly will leave it in an indeterminate state.
      !>
      !>## Examples
      !>
      !>     See EKACEC.
      !>
      !>## Restrictions
      !>
      !>     1) This routine cannot be used to update existing column entries.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 03-OCT-2021 (NJB)
      !>
      !>        Corrected typos in comments.
      !>
      !>-    Beta Version 1.0.0, 23-OCT-1995 (NJB)
      module subroutine zzekad06 ( ctx, handle, segdsc, coldsc, recptr, nvals, cvals, isnull )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! EK file handle.
      integer(ip), intent(inout) :: segdsc ( * )  !! Segment descriptor. (PEPPER: changed by the routine, an input in SPICELIB's table)
      integer(ip), intent(in) :: coldsc ( * )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Pointer to the record to which data is to be added.
      integer(ip), intent(in) :: nvals  !! Number of values to add to column.
      character(*), intent(in) :: cvals  ( * )  !! Character values to add to column.
      logical, intent(in) :: isnull  !! Flag indicating whether column entry is null.
!
!     Local parameters
!
      integer(ip), parameter :: maxpad = 100
!
!     Local variables
!
      integer(ip) :: mbase
      integer(ip) :: nwrite
      integer(ip) :: cvlen
      integer(ip) :: pos
      integer(ip) :: p2
      integer(ip) :: room
      integer(ip) :: np
      integer(ip) :: lastw
      integer(ip) :: mnroom
      integer(ip) :: pbase
      integer(ip) :: ncols
      integer(ip) :: strlen
      integer(ip) :: n
      integer(ip) :: remain
      integer(ip) :: colidx
      integer(ip) :: nchrs
      logical :: pad
      integer(ip) :: recno
      integer(ip) :: eltidx
      logical :: fstpag
      integer(ip) :: nrec
      integer(ip) :: wpad
      integer(ip) :: npad
      integer(ip) :: nlinks
      integer(ip) :: ptrloc
      if ( .not. allocated ( ctx%zzekad06_state ) ) allocate ( ctx%zzekad06_state )
      associate ( padbuf => ctx%zzekad06_state%padbuf, &
                  datptr => ctx%zzekad06_state%datptr, &
                  p => ctx%zzekad06_state%p, &
                  padlen => ctx%zzekad06_state%padlen, &
                  first => ctx%zzekad06_state%first )
      if ( first ) then
         padbuf = ' '
         first  = .false.
      end if

!
!     Make sure the record exists.
!
      nrec    =  segdsc ( nridx  )
      colidx  =  coldsc ( ordidx )

!
!     Make sure the column exists.
!
      ncols  =  segdsc ( ncidx )

      if (  ( colidx < 1 ) .or. ( colidx > ncols )  ) then

         call ctx%setmsg ( 'Column index = #; valid range is 1:#.' )
         call ctx%errint ( '#',  colidx                            )
         call ctx%errint ( '#',  nrec                              )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                   )
         return

      end if

!
!     If the value is null, make sure that nulls are permitted
!     in this column.
!
      if (  isnull  .and.  ( coldsc(nflidx) /= itrue )  ) then

         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Column having index # in segment # does '  // &
                       'not allow nulls, but a null value was '    // &
                       'supplied for the element in record #.'     )
         call ctx%errint ( '#',  colidx                                )
         call ctx%errint ( '#',  segdsc(snoidx)                        )
         call ctx%errint ( '#',  recno                                 )
         call ctx%sigerr ( 'SPICE(BADATTRIBUTE)'                       )
         return

      end if

!
!     Check NVALS.  If the column has fixed-size entries, NVALS must
!     match the declared entry size.  In all cases, NVALS must be
!     positive.
!
      if ( nvals < 1 ) then

         call ctx%setmsg ( 'COLIDX = #;  segment = #; NVALS = #;  '  // &
                       'NVALS must be positive '                   )
         call ctx%errint ( '#',  colidx                                )
         call ctx%errint ( '#',  segdsc(snoidx)                        )
         call ctx%errint ( '#',  nvals                                 )
         call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                       )
         return

      end if

      if ( coldsc(sizidx) /= ifalse ) then

         if ( nvals /= coldsc(sizidx) ) then

            call ctx%setmsg ( 'COLIDX = #;  segment = #; NVALS = #; '     // &
                          'declared entry size = #.  Sizes must match.')
            call ctx%errint ( '#',  colidx                                 )
            call ctx%errint ( '#',  segdsc(snoidx)                         )
            call ctx%errint ( '#',  nvals                                  )
            call ctx%errint ( '#',  coldsc(sizidx)                         )
            call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                        )
            return

         end if

      end if

!
!     Compute the data pointer location.
!
      ptrloc  =  recptr + dptbas + colidx

      if ( isnull ) then
!
!        All we need do is set the data pointer.  The segment's
!        metadata are not affected.
!
         call dasudi ( ctx, handle, ptrloc, ptrloc, [ null ] )

      else
!
!        Decide now whether we will need to pad the input entry
!        elements with trailing blanks, and if so how much padding
!        we'll need.
!
         strlen  =  coldsc ( lenidx   )
         cvlen   =  len    ( cvals(1) )
         pad     =  cvlen  <  strlen

         if ( pad ) then
            padlen  =  strlen - cvlen
         end if

         lastw   =  segdsc ( lcwidx )
         room    =  cpsize - lastw
         fstpag  =  .true.

!
!        Initialize the page base and target data pointer, if possible.
!        If the current page is full, these functions will be performed
!        below in the code section in which a new page is allocated.
!
         if ( lastw < cpsize ) then

            p       =  segdsc(lcpidx)

            call zzekpgbs ( ctx, chr,  p,  pbase )

            datptr  =  pbase + lastw + 1

         end if

         eltidx  =  1

         do while (  ( eltidx <= nvals ) .and. ( .not. ctx%failed() )  )
!
!           Write out the element having index ELTIDX.
!
            pos     =  0
            remain  =  strlen

            do while ( remain > 0 )
!
!              Decide where to write the data values.  In order to write
!              a new entry, we require enough room for the count
!              and at least one character of data.
!
               if ( fstpag ) then
                  mnroom  =  1 + encsiz
               else
                  mnroom  =  1
               end if

               if ( room  >=  mnroom ) then
!
!                 There's room in the current page.  If this is the
!                 first page this entry is written on, set the data
!                 pointer and count.  Write as much of the value as
!                 possible to the current page.
!
                  if ( fstpag ) then

                     call dasudi ( ctx, handle, ptrloc, ptrloc, [ datptr ] )
                     call zzeksei ( ctx, handle, datptr, nvals          )

                     room    =  room   - encsiz
                     datptr  =  datptr + encsiz

!
!                    The first page containing some or all of the data
!                    item gains a link.
!
                     call zzekglnk ( ctx, handle, chr, p, nlinks   )
                     call zzekslnk ( ctx, handle, chr, p, nlinks+1 )

                  end if

!
!                 Write the characters we can fit onto the current page.
!
                  nwrite  =  min ( remain, room )
                  n       =  nwrite

                  do while ( n > 0 )

                     if ( pos < cvlen )   then
!
!                       Take data from the input string CVALS(ELTIDX).
!
                        nchrs  =  min ( n, cvlen - pos )

                        call dasudc ( ctx, handle, &
                                      datptr, &
                                      datptr + nchrs - 1, &
                                      pos    + 1, &
                                      pos    + nchrs, &
                                      cvals( eltidx )     )

                        n      =  n      - nchrs
                        pos    =  pos    + nchrs
                        datptr =  datptr + nchrs

                     else if ( pad ) then
!
!                       We must add trailing blanks to the column
!                       entry at this point.
!
                        npad  =  min ( n, padlen )
                        np    =  npad

                        do while ( np > 0 )

                           wpad  =  min ( np, maxpad )

                           call dasudc ( ctx, handle, &
                                         datptr, &
                                         datptr + wpad - 1, &
                                         1, &
                                         wpad, &
                                         padbuf          )

                           np      =  np     - wpad
                           datptr  =  datptr + wpad

                        end do

                        n   =   n   - npad
                        pos =   pos + npad

                     end if

                  end do
!
!                 We've written all we can to the current page.
!
                  remain  =  remain - nwrite
                  room    =  room   - nwrite

!
!                 The last character word in use must be updated.
!                 Account for the count, if this is the first page on
!                 which the current entry is written.
!
                  if ( fstpag ) then

                     lastw              =  lastw + encsiz + nwrite
                     segdsc ( lcwidx )  =  lastw
                     fstpag             =  .false.

                  else

                     lastw              =  lastw + nwrite
                     segdsc ( lcwidx )  =  lastw

                  end if

               else
!
!                 Allocate a character data page.  If this is not the
!                 first data page written to, link the previous page to
!                 the current one.
!
                  call zzekaps ( ctx, handle,   segdsc,  chr, &
                                 .false.,  p2,      pbase  )

                  if ( .not. fstpag ) then
                     call zzeksfwd ( ctx, handle, chr, p, p2 )
                  end if

                  p                  =  p2
                  lastw              =  0
                  segdsc ( lcpidx )  =  p
                  segdsc ( lcwidx )  =  lastw

                  room               =  cpsize
                  datptr             =  pbase  +  1

!
!                 Set the link count.  If this is the first page
!                 onto which the input column entry is written,
!                 just zero out the count; the count will be set above.
!                 Additional pages get one link.
!
                  if ( fstpag ) then
                     nlinks  =  0
                  else
                     nlinks  =  1
                  end if

                  call zzekslnk ( ctx, handle, chr, p, nlinks )

               end if

            end do
!
!           We've written out the current element.
!

            eltidx  =  eltidx + 1

         end do

      end if

!
!     Write out the updated segment descriptor.
!
      mbase  =  segdsc(imdidx)

      call dasudi ( ctx, handle, mbase+1, mbase+sdscsz, segdsc )

!
!     Class 6 columns are not indexed, so we need not update any
!     index to account for the new element.
!

      return
      end associate
      end subroutine zzekad06

      !> Delete a specified class 5 column entry from an EK record.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is a file handle of an EK open for write access.
      !>
      !>     SEGDSC         is the descriptor of the segment from which to
      !>                    delete the specified column entry.
      !>
      !>     COLDSC         is the descriptor of the column from which to
      !>                    delete the specified column entry.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry to delete.
      !>
      !>## Detailed Output
      !>
      !>     None.  See the $Particulars section for a description of the
      !>     effect of this routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.  The file will not be modified.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.  The file may be corrupted.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it deletes a column entry
      !>     from an EK segment.  The status of the record containing the entry
      !>     is set to `updated'.  The deleted entry is marked as
      !>     `uninitialized'.
      !>
      !>     The link counts for the pages containing the deleted column entry
      !>     are decremented.  If the count for a page becomes zero, that page
      !>     is freed.  If the entry to be deleted is already uninitialized
      !>     upon entry to this routine, no link counts are modified.  The
      !>     record containing the entry is still marked `updated' in this
      !>     case.
      !>
      !>     The changes made by this routine to the target EK file become
      !>     permanent when the file is closed.  Failure to close the file
      !>     properly will leave it in an indeterminate state.
      !>
      !>## Examples
      !>
      !>     See EKDELR.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 07-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error message.
      !>
      !>        Deleted unneeded declarations and code.
      !>
      !>-    Beta Version 1.0.0, 28-SEP-1995 (NJB)
      module subroutine zzekde05 ( ctx, handle, segdsc, coldsc, recptr )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(inout) :: segdsc ( sdscsz )  !! Segment descriptor. (PEPPER: changed by the routine, an input in SPICELIB's table)
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      real(wp) :: dpnelt_1(1)  !! one-element copy of dpnelt (array argument)
      integer(ip) :: datptr_1(1)  !! one-element copy of datptr (array argument)
!
!     Local variables
!
      real(wp) :: dpnelt

      integer(ip) :: base
      integer(ip) :: datptr
      integer(ip) :: nelts
      integer(ip) :: next
      integer(ip) :: nlinks
      integer(ip) :: nseen
      integer(ip) :: p
      integer(ip) :: ptrloc
      integer(ip) :: recno

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Before trying to actually modify the file, do every error
!     check we can.
!
!     Is this file handle valid--is the file open for paged write
!     access?  Signal an error if not.
!
      call zzekpgch ( ctx, handle, 'WRITE' )

      if ( ctx%failed() ) return

!
!     Compute the data pointer location.  If the data pointer is
!     already set to `uninitialized', there's nothing to do.  If
!     the element is null, just set it to `uninitialized'.  The
!     presence of actual data obligates us to clean up, however.
!
      ptrloc  =  recptr + dptbas + coldsc(ordidx)

      call dasrdi ( ctx, handle, ptrloc, ptrloc, datptr_1 )
      datptr = datptr_1(1)

      if ( datptr > 0 ) then
!
!        Get the element count for the entry.
!
         call dasrdd ( ctx, handle, datptr, datptr, dpnelt_1 )
         dpnelt = dpnelt_1(1)

         nelts  =  nint ( dpnelt )

!
!        Set the data pointer to indicate the item is uninitialized.
!
         call dasudi ( ctx, handle, ptrloc, ptrloc, [ uninit ] )

!
!        Find the number of the page containing the column entry.
!
         call zzekpgpg ( ctx, dp, datptr, p, base )

!
!        Look up the forward pointer.  This pointer will be valid
!        if the column entry is continued on another page.
!
         call zzekgfwd ( ctx, handle, dp, p, next )

!
!        Get the link count for the current page.  If we have more
!        than one link to the page, decrement the link count.  If
!        we're down to one link, this deletion will finish off the
!        page:  we'll deallocate it.
!
         call zzekglnk ( ctx, handle, dp, p, nlinks )

         if ( nlinks > 1 ) then

            call zzekslnk ( ctx, handle, dp, p, nlinks-1 )

         else
!
!           If we removed the last item from the page, we can delete
!           the page.  ZZEKDPS adjusts the segment's metadata
!           to reflect the deallocation.
!
            call zzekdps  ( ctx, handle, segdsc, dp, p )

         end if

         nseen = min (  nelts,  (base+dpsize-datptr)  )

         do while (  ( nseen < nelts ) .and. ( .not. ctx%failed() )  )
!
!           The column entry is continued on the page indicated by
!           NEXT.
!
!           Get the link count for the current page.  If we have more
!           than one link to the page, decrement the link count.  If
!           we're down to one link, this deletion will finish off the
!           page:  we'll deallocate it.
!
            p  =  next

            call zzekgfwd ( ctx, handle, dp, p, next   )
            call zzekglnk ( ctx, handle, dp, p, nlinks )

            if ( nlinks > 1 ) then

               call zzekslnk ( ctx, handle, dp, p, nlinks-1 )

            else
!
!              If we removed the last item from the page, we can delete
!              the page.  ZZEKDPS adjusts the segment's metadata
!              to reflect the deallocation.
!
               call zzekdps ( ctx, handle, segdsc, dp, p )

            end if

            nseen  =  min (  nelts,  ( dpsize + nseen )  )

         end do

      else if ( datptr == null ) then
!
!        Mark the entry as `uninitialized'.
!
         call dasudi ( ctx, handle, ptrloc, ptrloc, [ uninit ] )

      else if ( datptr /= uninit ) then
!
!        UNINIT was the last valid possibility.  The data pointer is
!        corrupted.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Data pointer is corrupted. SEGNO = #; '  // &
                       'COLIDX =  #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  segdsc(snoidx)                      )
         call ctx%errint ( '#',  coldsc(ordidx)                      )
         call ctx%errint ( '#',  recno                               )
         call ctx%errhan ( '#',  handle                              )
         call ctx%sigerr ( 'SPICE(BUG)'                              )
         return

      end if

!
!     Set the record's status to indicate that this record is updated.
!
      call dasudi ( ctx, handle, recptr+staidx, recptr+staidx, [ update ] )

      return
      end subroutine zzekde05

      !> Delete a specified class 6 column entry from an EK record.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is a file handle of an EK open for write access.
      !>
      !>     SEGDSC         is the descriptor of the segment from which to
      !>                    delete the specified column entry.
      !>
      !>     COLDSC         is the descriptor of the column from which to
      !>                    delete the specified column entry.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry to delete.
      !>
      !>## Detailed Output
      !>
      !>     None.  See the $Particulars section for a description of the
      !>     effect of this routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.  The file will not be modified.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.  The file may be corrupted.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it deletes a column entry
      !>     from an EK segment.  The status of the record containing the entry
      !>     is set to `updated'.  The deleted entry is marked as
      !>     `uninitialized'.
      !>
      !>     The link counts for the pages containing the deleted column entry
      !>     are decremented.  If the count for a page becomes zero, that page
      !>     is freed.  If the entry to be deleted is already uninitialized
      !>     upon entry to this routine, no link counts are modified.  The
      !>     record containing the entry is still marked `updated' in this
      !>     case.
      !>
      !>     The changes made by this routine to the target EK file become
      !>     permanent when the file is closed.  Failure to close the file
      !>     properly will leave it in an indeterminate state.
      !>
      !>## Examples
      !>
      !>     See EKDELR.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 07-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error message.
      !>
      !>        Deleted unneeded declarations and code.
      !>
      !>-    Beta Version 1.0.0, 28-SEP-1995 (NJB)
      module subroutine zzekde06 ( ctx, handle, segdsc, coldsc, recptr )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(inout) :: segdsc ( sdscsz )  !! Segment descriptor. (PEPPER: changed by the routine, an input in SPICELIB's table)
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      integer(ip) :: datptr_1(1)  !! one-element copy of datptr (array argument)

      integer(ip) :: base
      integer(ip) :: datptr
      integer(ip) :: nchars
      integer(ip) :: nelts
      integer(ip) :: next
      integer(ip) :: nlinks
      integer(ip) :: nseen
      integer(ip) :: p
      integer(ip) :: ptrloc
      integer(ip) :: recno

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Before trying to actually modify the file, do every error
!     check we can.
!
!     Is this file handle valid--is the file open for paged write
!     access?  Signal an error if not.
!
      call zzekpgch ( ctx, handle, 'WRITE' )

      if ( ctx%failed() ) return

!
!     Compute the data pointer location.  If the data pointer is
!     already set to `uninitialized', there's nothing to do.  If
!     the element is null, just set it to `uninitialized'.  The
!     presence of actual data obligates us to clean up, however.
!
      ptrloc  =  recptr + dptbas + coldsc(ordidx)

      call dasrdi ( ctx, handle, ptrloc, ptrloc, datptr_1 )
      datptr = datptr_1(1)

      if ( datptr > 0 ) then
!
!        Get the element count for the entry.  Compute the character
!        count for the entry.
!
         call zzekgei ( ctx, handle, datptr, nelts )

         nchars  =  coldsc(lenidx) * nelts

!
!        Set the data pointer to indicate the item is uninitialized.
!
         call dasudi ( ctx, handle, ptrloc, ptrloc, [ uninit ] )

!
!        Find the number of the page containing the column entry.
!
         call zzekpgpg ( ctx, chr, datptr, p, base )

!
!        Look up the forward pointer.  This pointer will be valid
!        if the column entry is continued on another page.
!
         call zzekgfwd ( ctx, handle, chr, p, next )

!
!        Get the link count for the current page.  If we have more
!        than one link to the page, decrement the link count.  If
!        we're down to one link, this deletion will finish off the
!        page:  we'll deallocate it.
!
         call zzekglnk ( ctx, handle, chr, p, nlinks )

         if ( nlinks > 1 ) then

            call zzekslnk ( ctx, handle, chr, p, nlinks-1 )

         else
!
!           If we removed the last item from the page, we can delete
!           the page.  ZZEKDPS adjusts the segment's metadata
!           to reflect the deallocation.
!
            call zzekdps  ( ctx, handle, segdsc, chr, p )

         end if

         nseen = min (  nchars,  (base+cpsize-datptr)  )

         do while (  ( nseen < nchars ) .and. ( .not. ctx%failed() )  )
!
!           The column entry is continued on the page indicated by
!           NEXT.
!
!           Get the link count for the current page.  If we have more
!           than one link to the page, decrement the link count.  If
!           we're down to one link, this deletion will finish off the
!           page:  we'll deallocate it.
!
            p  =  next

            call zzekgfwd ( ctx, handle, chr, p, next   )
            call zzekglnk ( ctx, handle, chr, p, nlinks )

            if ( nlinks > 1 ) then

               call zzekslnk ( ctx, handle, chr, p, nlinks-1 )

            else
!
!              If we removed the last item from the page, we can delete
!              the page.  ZZEKDPS adjusts the segment's metadata
!              to reflect the deallocation.
!
               call zzekdps  ( ctx, handle, segdsc, chr, p )

            end if

            nseen  =  min (  nchars,  ( cpsize + nseen )  )

         end do

      else if ( datptr == null ) then
!
!        Mark the entry as `uninitialized'.
!
         call dasudi ( ctx, handle, ptrloc, ptrloc, [ uninit ] )

      else if ( datptr /= uninit ) then
!
!        UNINIT was the last valid possibility.  The data pointer is
!        corrupted.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Data pointer is corrupted. SEGNO = #; '  // &
                       'COLIDX =  #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  segdsc(snoidx)                      )
         call ctx%errint ( '#',  coldsc(ordidx)                      )
         call ctx%errint ( '#',  recno                               )
         call ctx%errhan ( '#',  handle                              )
         call ctx%sigerr ( 'SPICE(BUG)'                              )
         return

      end if

!
!     Set the record's status to indicate that this record is updated.
!
      call dasudi ( ctx, handle, recptr+staidx, recptr+staidx, [ update ] )

      return
      end subroutine zzekde06

      !> Return the size of a specified column entry.
      !>
      !> The function returns the number of elements in the specified
      !> column entry.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is an EK file handle.  The file may be open for
      !>                    reading or writing.
      !>
      !>     SEGDSC         is the segment descriptor of the segment
      !>                    containing the column specified by COLDSC.
      !>
      !>     COLDSC         is the column descriptor of the column containing
      !>                    the entry whose size is requested.
      !>
      !>     RECPTR         is a pointer to the EK record containing the
      !>                    column entry of interest.
      !>
      !>## Detailed Output
      !>
      !>     The function returns the number of elements in the specified
      !>     column entry.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading the indicated file,
      !>         the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This utility centralizes the commonly performed function of
      !>     determining the element count of a column entry.
      !>
      !>## Examples
      !>
      !>     See EKRCEI.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 07-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error message.
      !>
      !>-    Beta Version 1.0.0, 09-NOV-1995 (NJB)
      module integer(ip) function zzekesiz ( ctx, handle, segdsc, coldsc, recptr )
      use pepper_kinds, only: ip
      use pepper_inc_ekcoldsc
      use pepper_inc_ekcnamsz
      use pepper_inc_eksegdsc
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
!
!     Local variables
!
      character(cnamsz) :: column

      integer(ip) :: class
      integer(ip) :: recno
      integer(ip) :: segno

!
!     Initialize the function's return value.
!
      zzekesiz  =  0

!
!     Delegate the problem to the routine of the appropriate class.
!     The first three classes are scalars.
!
      class  =  coldsc ( clsidx )

      if ( class == 1 ) then

         zzekesiz  =  1

      else if ( class == 2 ) then

         zzekesiz  =  1

      else if ( class == 3 ) then

         zzekesiz  =  1

      else if ( class == 4 ) then

         zzekesiz  =  zzeksz04 ( ctx, handle, segdsc, coldsc, recptr )

      else if ( class == 5 ) then

         zzekesiz  =  zzeksz05 ( ctx, handle, segdsc, coldsc, recptr )

      else if ( class == 6 ) then

         zzekesiz  =  zzeksz06 ( ctx, handle, segdsc, coldsc, recptr )

      else if ( class == 7 ) then

         zzekesiz  =  1

      else if ( class == 8 ) then

         zzekesiz  =  1

      else if ( class == 9 ) then

         zzekesiz  =  1

      else

!
!        This is an unsupported column class.
!
         call zzekcnam ( ctx, handle, coldsc, column )

         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )
         segno  =  segdsc ( snoidx )

         call ctx%setmsg ( 'Class # from input column descriptor is not ' // &
                       'a supported integer class.  COLUMN = #; '     // &
                       'RECNO = #; SEGNO = #; EK = #.'                 )
         call ctx%errint ( '#',  class                                     )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

      return
      end function zzekesiz

      !> Return the data pointer for a specified EK column entry.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is a file handle of an EK open for read or write
      !>                    access.
      !>
      !>     SEGDSC         is the descriptor of the segment containing
      !>                    the specified column entry.
      !>
      !>     COLDSC         is the descriptor of the column containing
      !>                    the specified column entry.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry whose data pointer is desired.
      !>
      !>## Detailed Output
      !>
      !>     DATPTR         is the data pointer of the specified column entry.
      !>                    When DATPTR is positive, it represents a pointer
      !>                    to a data value.  The interpretation of the
      !>                    pointer depends on the class of the column entry.
      !>                    DATPTR may also take on the distinguished values
      !>
      !>                       UNINIT  (indicated uninitialized entry)
      !>                       NULL    (indicated null entry)
      !>                       NOBACK  (indicated uninitialized backup entry)
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading the indicated file, the
      !>         error will be diagnosed by routines called by this routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine hides details of column entry data pointer access.
      !>
      !>## Examples
      !>
      !>     See ZZEKRFIL.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 07-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>-    Beta Version 1.0.0, 17-OCT-1995 (NJB)
      module subroutine zzekgcdp ( ctx, handle, segdsc, coldsc, recptr, datptr )
      use pepper_kinds, only: ip
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ekrecptr
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      integer(ip), intent(out) :: datptr  !! Data pointer of column entry.
      integer(ip) :: datptr_1(1)  !! one-element copy of datptr (array argument)
!
!     Local variables
!
      integer(ip) :: colidx
      integer(ip) :: ncols
      integer(ip) :: ptrloc
      integer(ip) :: recno

!
!     Make sure the column exists.
!
      ncols  =  segdsc ( ncidx  )
      colidx =  coldsc ( ordidx )

      if (  ( colidx < 1 ) .or. ( colidx > ncols )  ) then

         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Column index = #; valid range is 1:#.' // &
                       'SEGNO = #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  colidx                            )
         call ctx%errint ( '#',  ncols                             )
         call ctx%errint ( '#',  segdsc(snoidx)                    )
         call ctx%errint ( '#',  recno                             )
         call ctx%errhan ( '#',  handle                            )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                   )
         return

      end if

!
!     Compute the data pointer location, and read the pointer.
!
      ptrloc  =  recptr + dptbas + colidx

      call dasrdi ( ctx, handle, ptrloc, ptrloc, datptr_1 )
      datptr = datptr_1(1)

      return
      end subroutine zzekgcdp

      !> Initialize a new type 1 EK segment to allow fast loading.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is the handle of an EK file open for write access.
      !>                    A new type 1 segment is to be created in this file
      !>                    via a fast load.  The segment's metadata has
      !>                    already been set up by EKBSEG.
      !>
      !>     SEGNO          is the number of the segment to prepare for a
      !>                    fast load.
      !>
      !>## Detailed Output
      !>
      !>     RCPTRS         is an array of record pointers for the input
      !>                    segment.  This array must not be modified by the
      !>                    caller.
      !>
      !>                    The array RCPTRS must be passed as an input to
      !>                    each column addition routine called while
      !>                    writing the specified segment.
      !>
      !>                    RCPTRS must be declared with dimension equal to
      !>                    the number of rows in the segment.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine carries out the type-1-specific preparation for
      !>     populating a type 1 EK segment with data via the fast column
      !>     loader routines.  This routine expects the segment's metadata to
      !>     already have been written by EKBSEG.
      !>
      !>## Examples
      !>
      !>     See EKIFLD.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 06-SEP-2006 (NJB)
      !>
      !>        Added Restrictions section to header.  Changed
      !>        previous version line's product from "Beta" to "SPICELIB."
      !>
      !>-    SPICELIB Version 1.0.0, 06-NOV-1995 (NJB)
      module subroutine zzekif01 ( ctx, handle, segno, rcptrs )
      use pepper_kinds, only: ip
      use pepper_inc_ekdatpag
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(in) :: segno  !! Segment number.
      integer(ip), intent(out) :: rcptrs ( * )  !! Array of record pointers.
!
!     Local variables
!
      integer(ip) :: base
      integer(ip) :: i
      integer(ip) :: j
      integer(ip) :: ncols
      integer(ip) :: npage
      integer(ip) :: nr
      integer(ip) :: nrows
      integer(ip) :: nrp
      integer(ip) :: p
      integer(ip) :: pbase
      integer(ip) :: recno
      integer(ip) :: remain
      integer(ip) :: rpsize
      integer(ip) :: segdsc ( sdscsz )
      integer(ip) :: top

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Read in the segment descriptor.
!
      call zzeksdsc ( ctx,  handle,  segno,  segdsc )

      ncols  =  segdsc(ncidx)
      nrows  =  segdsc(nridx)

!
!     Empty the EK scratch area stack.
!
      call zzekstop ( ctx, top )
      call zzeksdec ( ctx, top )

!
!     Push the handle and segment number onto the stack.
!
      call zzekspsh ( ctx, 1, [ handle ] )
      call zzekspsh ( ctx, 1, [ segno ] )

!
!     The segment will require a record pointer structure for each row
!     in the segment.  Right now, all we're going to do is allocate
!     integer pages to hold these structures and save the base
!     addresses of each structure.
!
!     We compute the number of record pointers that can fit on one page.
!     We also compute the number of pages we'll need to hold the
!     pointers.
!
      rpsize  =    dptbas + ncols
      nrp     =    ipsize / rpsize
      npage   =  ( nrows + nrp - 1 ) / nrp

!
!     We'll compute addresses of record pointers a pageful at a time.
!
      remain  =  nrows
      recno   =  0

      do i = 1, npage
!
!        Allocate a page to hold the record pointers.  A page from
!        the free list is acceptable, hence the argument .FALSE.
!        passed to ZZEKAPS.
!
         call zzekaps  ( ctx, handle, segdsc, int, .false., p, pbase )

!
!        NR is the number of record pointers we'll eventually write to
!        this page.
!
         nr  =  min ( nrp, remain )

         do j = 1, nr
!
!           Record the base address of the current record pointer
!           in the record pointer array.
!
            base                =  (j-1) * rpsize
            rcptrs ( recno+j )  =  pbase + base

         end do

         recno   =  recno   +  nr
         remain  =  remain  -  nr

      end do

      return
      end subroutine zzekif01

      !> Initialize a new type 2 EK segment to allow fast loading.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is the handle of an EK file open for write access.
      !>                    A new type 2 segment is to be created in this file
      !>                    via a fast load.  The segment's metadata has
      !>                    already been set up by EKBSEG.
      !>
      !>     SEGNO          is the number of the segment to prepare for a
      !>                    fast load.
      !>
      !>## Detailed Output
      !>
      !>     None.  See $Particulars for a description of the effect of this
      !>     routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine carries out the type-2-specific preparation for
      !>     populating a type 2 EK segment with data via the fast column
      !>     loader routines.  This routine expects the segment's metadata to
      !>     already have been written by EKBSEG.
      !>
      !>     This routine expects the segment to contain columns having class
      !>     7, 8, or 9.
      !>
      !>## Examples
      !>
      !>     See EKIFLD.
      !>
      !>## Restrictions
      !>
      !>     1)  Assumes total number of words required for column metadata
      !>         is no greater than IPSIZE.  Currently, with a maximum of 100
      !>         columns and a maximum metadata size of 2 words per column,
      !>         this condition is met.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    Beta Version 1.0.0, 09-NOV-1995 (NJB)
      module subroutine zzekif02 ( ctx, handle, segno )
      use pepper_kinds, only: ip
      use pepper_inc_ekclas07
      use pepper_inc_ekclas08
      use pepper_inc_ekclas09
      use pepper_inc_ekcoldsc
      use pepper_inc_ekpage
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(in) :: segno  !! Segment number.
      integer(ip) :: class_1(1)  !! one-element copy of class (array argument)
!
!     Local variables
!
      integer(ip) :: base
      integer(ip) :: class
      integer(ip) :: dscbas
      integer(ip) :: i
      integer(ip) :: mbase
      integer(ip) :: ncols
      integer(ip) :: nrows
      integer(ip) :: offset
      integer(ip) :: p
      integer(ip) :: page   ( pgsizi )
      integer(ip) :: segdsc ( sdscsz )

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Read in the segment descriptor.
!
      call zzekmloc ( ctx, handle, segno,   page(1),         mbase  )
      call dasrdi   ( ctx, handle, mbase+1, mbase+sdscsz, segdsc )

      ncols  =  segdsc(ncidx)
      nrows  =  segdsc(nridx)

!
!     Allocate space for column metadata.  We assume that one page
!     of IPSIZE integers is enough room.
!
      call zzekaps ( ctx, handle, segdsc, int, .false., p, base  )

      offset  =  base

      do i = 1, ncols
!
!        Read the class from the descriptor of the Ith column directly
!        from the file.  We'll need the descriptor's address in order to
!        update the descriptor in the file.
!
         dscbas  =  mbase + cdoff + (i-1)*cdscsz

         call dasrdi ( ctx, handle, dscbas+clsidx, dscbas+clsidx, class_1 )
         class = class_1(1)

!
!        Update the file.  Set the column descriptor's metadata pointer
!        to the base address of the metadata area.
!
         call dasudi ( ctx, handle, dscbas+metidx, dscbas+metidx, [ offset ] )

!
!        Increment the metadata offset by the size of the metadata
!        for the current column.  The classes of interest range from
!        7 to 9.
!
         if ( class == 7 ) then

            offset  =  offset + mdsz07

         else if ( class == 8 ) then

            offset  =  offset + mdsz08

         else if ( class == 9 ) then

            offset  =  offset + mdsz09

         else

            call ctx%setmsg ( 'Class # is not supported.' )
            call ctx%errint ( '#',  class                 )
            call ctx%sigerr ( 'SPICE(NOCLASS)'            )
            return

         end if

      end do

      return
      end subroutine zzekif02

      !> Read a column entry from a specified record in a class 1 column.
      !> Class 1 columns contain scalar integer values.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is an EK file handle.
      !>
      !>     SEGDSC         is the descriptor of the segment from which data is
      !>                    to be read.
      !>
      !>     COLDSC         is the descriptor of the column from which data is
      !>                    to be read.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry to be written.
      !>
      !>## Detailed Output
      !>
      !>     IVAL           is the value read from the specified column entry.
      !>
      !>     ISNULL         is a logical flag indicating whether the column
      !>                    entry is null.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If the specified column entry has not been initialized, the
      !>         error SPICE(UNINITIALIZEDVALUE) is signaled.
      !>
      !>     3)  If the ordinal position of the column specified by COLDSC
      !>         is out of range, the error SPICE(INVALIDINDEX) is signaled.
      !>
      !>     4)  If an I/O error occurs while reading the indicated file,
      !>         the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine is a utility for reading data from class 1 columns.
      !>
      !>## Examples
      !>
      !>     See EKRCEI.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 07-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>        Bug fix: changed max column index in long error
      !>        message from NREC to NCOLS.
      !>
      !>-    Beta Version 1.0.0, 18-OCT-1995 (NJB)
      module subroutine zzekrd01 ( ctx, handle, segdsc, coldsc, recptr, ival, isnull )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      integer(ip), intent(out) :: ival  !! Integer value in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.
      integer(ip) :: ival_1(1)  !! one-element copy of ival (array argument)
      integer(ip) :: datptr_1(1)  !! one-element copy of datptr (array argument)

      integer(ip) :: colidx
      integer(ip) :: datptr
      integer(ip) :: ncols
      integer(ip) :: recno
      integer(ip) :: ptrloc

!
!     Make sure the column exists.
!
      ncols  =  segdsc ( ncidx  )
      colidx =  coldsc ( ordidx )

      if (  ( colidx < 1 ) .or. ( colidx > ncols )  ) then

         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Column index = #; valid range is 1:#.' // &
                       'SEGNO = #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  colidx                            )
         call ctx%errint ( '#',  ncols                             )
         call ctx%errint ( '#',  segdsc(snoidx)                    )
         call ctx%errint ( '#',  recno                             )
         call ctx%errhan ( '#',  handle                            )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                   )
         return

      end if

!
!     Compute the data pointer location, and read the pointer.
!
      ptrloc  =  recptr + dptbas + colidx

      call dasrdi ( ctx, handle, ptrloc, ptrloc, datptr_1 )
      datptr = datptr_1(1)

      if ( datptr > 0 ) then
!
!        Just read the value.
!
         call dasrdi ( ctx, handle, datptr, datptr, ival_1 )
         ival = ival_1(1)
         isnull  =  .false.

      else if ( datptr == null ) then
!
!        The value is null.
!
         isnull =  .true.

      else if (       ( datptr == uninit ) &
                 .or. ( datptr == noback )  )  then
!
!        The data value is absent.  This is an error.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Attempted to read uninitialized column '    // &
                       'entry.  SEGNO = #; COLIDX = #; RECNO = #; ' // &
                       'EK = #'                                      )
         call ctx%errint ( '#',  segdsc(snoidx)                          )
         call ctx%errint ( '#',  colidx                                  )
         call ctx%errint ( '#',  recno                                   )
         call ctx%errhan ( '#',  handle                                  )
         call ctx%sigerr ( 'SPICE(UNINITIALIZEDVALUE)'                   )
         return

      else
!
!        The data pointer is corrupted.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Data pointer is corrupted. SEGNO = #; '  // &
                       'COLIDX =  #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  segdsc(snoidx)                      )
         call ctx%errint ( '#',  colidx                              )
         call ctx%errint ( '#',  recno                               )
         call ctx%errhan ( '#',  handle                              )
         call ctx%sigerr ( 'SPICE(BUG)'                              )
         return

      end if

      return
      end subroutine zzekrd01

      !> Read a column entry from a specified record in a class 2 column.
      !> Class 2 columns contain scalar double precision values.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is an EK file handle.
      !>
      !>     SEGDSC         is the descriptor of the segment from which data is
      !>                    to be read.
      !>
      !>     COLDSC         is the descriptor of the column from which data is
      !>                    to be read.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry to be written.
      !>
      !>## Detailed Output
      !>
      !>     DVAL           is the value read from the specified column entry.
      !>
      !>     ISNULL         is a logical flag indicating whether the entry is
      !>                    null.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If the specified column entry has not been initialized, the
      !>         error SPICE(UNINITIALIZEDVALUE) is signaled.
      !>
      !>     3)  If the ordinal position of the column specified by COLDSC
      !>         is out of range, the error SPICE(INVALIDINDEX) is signaled.
      !>
      !>     4)  If an I/O error occurs while reading the indicated file,
      !>         the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine is a utility for reading data from class 2 columns.
      !>
      !>## Examples
      !>
      !>     See EKRCED.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 07-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>        Bug fix: changed max column index in long error
      !>        message from NREC to NCOLS.
      !>
      !>-    Beta Version 1.0.0, 18-OCT-1995 (NJB)
      module subroutine zzekrd02 ( ctx, handle, segdsc, coldsc, recptr, dval, isnull )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      real(wp), intent(out) :: dval  !! Double precision value in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.
      real(wp) :: dval_1(1)  !! one-element copy of dval (array argument)
      integer(ip) :: datptr_1(1)  !! one-element copy of datptr (array argument)

      integer(ip) :: colidx
      integer(ip) :: datptr
      integer(ip) :: ncols
      integer(ip) :: ptrloc
      integer(ip) :: recno

!
!     Make sure the column exists.
!
      ncols   =  segdsc ( ncidx  )
      colidx  =  coldsc ( ordidx )

      if (  ( colidx < 1 ) .or. ( colidx > ncols )  ) then

         call ctx%setmsg ( 'Column index = #; valid range is 1:#.' )
         call ctx%errint ( '#',  colidx                            )
         call ctx%errint ( '#',  ncols                             )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                   )
         return

      end if

!
!     Compute the data pointer location, and read the pointer.
!
      ptrloc  =  recptr + dptbas + colidx

      call dasrdi ( ctx, handle, ptrloc, ptrloc, datptr_1 )
      datptr = datptr_1(1)

      if ( datptr > 0 ) then
!
!        Just read the value.
!
         call dasrdd ( ctx, handle, datptr, datptr, dval_1 )
         dval = dval_1(1)
         isnull  =  .false.

      else if ( datptr == null ) then
!
!        The value is null.
!
         isnull =  .true.

      else if (       ( datptr == uninit ) &
                 .or. ( datptr == noback )  )  then
!
!        The data value is absent.  This is an error.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Attempted to read uninitialized column '    // &
                       'entry.  SEGNO = #; COLIDX = #; RECNO = #; ' // &
                       'EK = #'                                      )
         call ctx%errint ( '#',  segdsc(snoidx)                          )
         call ctx%errint ( '#',  colidx                                  )
         call ctx%errint ( '#',  recno                                   )
         call ctx%errhan ( '#',  handle                                  )
         call ctx%sigerr ( 'SPICE(UNINITIALIZEDVALUE)'                   )
         return

      else
!
!        The data pointer is corrupted.
!
         call ctx%setmsg ( 'Data pointer is corrupted. SEGNO = #; '  // &
                       'COLIDX =  #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  segdsc(snoidx)                      )
         call ctx%errint ( '#',  colidx                              )
         call ctx%errint ( '#',  recno                               )
         call ctx%errhan ( '#',  handle                              )
         call ctx%sigerr ( 'SPICE(BUG)'                              )
         return

      end if

      return
      end subroutine zzekrd02

      !> Read a column entry from a specified record in a class 3 column.
      !> Class 3 columns contain scalar character values.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is an EK file handle.
      !>
      !>     SEGDSC         is the descriptor of the segment from which data is
      !>                    to be read.
      !>
      !>     COLDSC         is the descriptor of the column from which data is
      !>                    to be read.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry to be written.
      !>
      !>## Detailed Output
      !>
      !>     CVLEN          is the length of the returned string value.  This
      !>                    is the index of the last non-blank character of
      !>                    the string.  This definition applies to both fixed-
      !>                    and variable-length strings.
      !>
      !>                    CVLEN is set to 1 if the column entry is null.
      !>
      !>     CVAL           is the value read from the specified column entry.
      !>                    If CVAL has insufficient length to hold the
      !>                    returned string value, the output value is
      !>                    truncated on the right.  Entries that are shorter
      !>                    than the string length of CVAL are padded with
      !>                    trailing blanks.
      !>
      !>     ISNULL         is a logical flag indicating whether the entry is
      !>                    null.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If the specified column entry has not been initialized, the
      !>         error SPICE(UNINITIALIZED) is signaled.
      !>
      !>     3)  If the ordinal position of the column specified by COLDSC
      !>         is out of range, the error SPICE(INVALIDINDEX) is signaled.
      !>
      !>     4)  If the output string CVAL is too short to accommodate the
      !>         returned string value, the output value is truncated on the
      !>         right.  No error is signaled.
      !>
      !>     5)  If an I/O error occurs while reading the indicated file,
      !>         the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine is a utility for reading data from class 3 columns.
      !>
      !>## Examples
      !>
      !>     See EKRCEC.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.4.0, 07-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>        Bug fix: changed max column index in long error
      !>        message from NREC to NCOLS.
      !>
      !>-    SPICELIB Version 1.3.0, 31-MAY-2010 (NJB)
      !>
      !>        Bug fix: call to DASRDI was overwriting local memory. This
      !>        problem did not affect operation of the routine except on
      !>        the Mac/Intel/OSX/ifort/32-bit platform, on which it caused
      !>        a segmentation fault when this routine was compiled with
      !>        default optimization.
      !>
      !>-    SPICELIB Version 1.2.0, 23-JUL-1999 (NJB)
      !>
      !>        Error check for string truncation on output was removed.
      !>        This error check interfered with the use of this routine
      !>        (via a call to ZZEKRSC) within ZZEKJSRT, which relies on
      !>        being able to read into a buffer initial substrings of scalar
      !>        data.
      !>
      !>-    SPICELIB Version 1.1.0, 28-JUL-1997 (NJB)
      !>
      !>        Error check for string truncation on output was added.
      !>        SHORT error message SPICE(UNINITIALIZEDVALUE) was shortened
      !>        to SPICE(UNINITIALIZED).  Error messages were enhanced so
      !>        as to use column names rather than indices.  Miscellaneous
      !>        header fixes were made.
      !>
      !>-    SPICELIB Version 1.0.0, 18-OCT-1995 (NJB)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.2.0, 23-JUL-1999 (NJB)
      !>
      !>        Error check for string truncation on output was removed.
      !>        This error check interfered with the use of this routine
      !>        (via a call to ZZEKRSC) within ZZEKJSRT, which relies on
      !>        being able to read into a buffer initial substrings of scalar
      !>        data.
      !>
      !>-    SPICELIB Version 1.1.0, 25-JUL-1997 (NJB)
      !>
      !>        Error check for string truncation on output was added.
      !>        SHORT error message SPICE(UNINITIALIZEDVALUE) was shortened
      !>        to SPICE(UNINITIALIZED), since the previous string exceeded
      !>        the maximum allowed length for the short error message.
      !>
      !>        Error messages were enhanced so as to use column names rather
      !>        than indices.
      module subroutine zzekrd03 ( ctx, handle, segdsc, coldsc, recptr, cvlen, cval, isnull )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekcnamsz
      use pepper_inc_ekdatpag
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype

      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      integer(ip), intent(out) :: cvlen  !! Length of returned character value.
      character(*), intent(out) :: cval  !! Character value in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.
      integer(ip) :: datptr_1(1)  !! one-element copy of datptr (array argument)
!
!     Local variables
!
      character(cnamsz) :: column

      integer(ip) :: avail
      integer(ip) :: b
      integer(ip) :: bpos
      integer(ip) :: colidx
      integer(ip) :: datptr
      integer(ip) :: e
      integer(ip) :: epos
      integer(ip) :: l
      integer(ip) :: n
      integer(ip) :: ncols
      integer(ip) :: p
      integer(ip) :: pbase
      integer(ip) :: relptr
      integer(ip) :: ptrloc
      integer(ip) :: recno

!
!     Make sure the column exists.
!
      ncols   =  segdsc ( ncidx  )
      colidx  =  coldsc ( ordidx )

      if (  ( colidx < 1 ) .or. ( colidx > ncols )  ) then

         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Column index = #; valid range is 1:#.' // &
                       'SEGNO = #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  colidx                            )
         call ctx%errint ( '#',  ncols                             )
         call ctx%errint ( '#',  segdsc(snoidx)                    )
         call ctx%errint ( '#',  recno                             )
         call ctx%errhan ( '#',  handle                            )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                   )
         return

      end if

!
!     Compute the data pointer location, and read both the pointer
!     and the stored string size.
!
      ptrloc  =  recptr + dptbas + colidx

      call dasrdi ( ctx, handle, ptrloc, ptrloc, datptr_1 )
      datptr = datptr_1(1)

      if ( datptr > 0 ) then
!
!        Read the value.  This is slightly more complicated than
!        the numeric cases, because the value may be spread across
!        multiple pages.  Also, we must not write past the end of the
!        output string.
!
!        We'll need the number of the page at which the first character
!        of the string is stored.  This page contains at least one
!        character of the data value.
!
         call zzekgei ( ctx, handle, datptr, cvlen )

!
!        Set the data pointer to the start of the string data, skipping
!        over the encoded string length.
!
         datptr  =  datptr + encsiz

         n       =  min ( cvlen, len(cval) )

!
!        Read the available data from the page under consideration.
!
         call zzekpgpg ( ctx, chr, datptr, p, pbase )

         relptr =  datptr - pbase
         avail  =  min  ( n,  cpsize - relptr + 1 )
         b      =  datptr
         e      =  datptr + avail - 1
         bpos   =  1
         epos   =  avail
         l      =  epos - bpos + 1

         call dasrdc ( ctx, handle, b, e, bpos, epos, cval )

         n      =  n - l

         do while ( n > 0 )
!
!           Read the forward page pointer from the current page; find
!           the base address of the referenced page.
!
            call zzekgei  ( ctx, handle,  pbase+cfpidx,  p     )
            call zzekpgbs ( ctx, chr,     p,             pbase )

            avail  =  min  ( n, cpsize )
            b      =  pbase + 1
            e      =  pbase + avail
            bpos   =  epos  + 1
            epos   =  epos  + avail

            call dasrdc ( ctx, handle, b, e, bpos, epos, cval )

            n      =  n    - avail
            bpos   =  epos + 1

         end do

!
!        Blank-pad CVAL if required.
!
         if ( len(cval) > epos ) then
            cval( epos+1 : )  =  ' '
         end if

         isnull  =  .false.

      else if ( datptr == null ) then
!
!        The value is null.
!
         isnull =  .true.
         cvlen  =   1

      else if (       ( datptr == uninit ) &
                 .or. ( datptr == noback )  )  then
!
!        The data value is absent.  This is an error.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Attempted to read uninitialized column '    // &
                       'entry.  SEGNO = #; COLUMN = #; RECNO = #; ' // &
                       'EK = #'                                      )
         call ctx%errint ( '#',  segdsc(snoidx)                          )
         call ctx%errch  ( '#',  column                                  )
         call ctx%errint ( '#',  recno                                   )
         call ctx%errhan ( '#',  handle                                  )
         call ctx%sigerr ( 'SPICE(UNINITIALIZED)'                        )
         return

      else
!
!        The data pointer is corrupted.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call zzekcnam ( ctx, handle,   coldsc, column )

         call ctx%setmsg ( 'Data pointer is corrupted. SEGNO = #; '  // &
                       'COLUMN =  #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  segdsc(snoidx)                      )
         call ctx%errch  ( '#',  column                              )
         call ctx%errint ( '#',  recno                               )
         call ctx%errhan ( '#',  handle                              )
         call ctx%sigerr ( 'SPICE(BUG)'                              )
         return

      end if

      return
      end subroutine zzekrd03

      !> Read a specified element range from a column entry in a specified
      !> record in a class 4 column.  Class 4 columns have integer arrays
      !> as column entries.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is an EK file handle.
      !>
      !>     SEGDSC         is the descriptor of the segment from which data is
      !>                    to be read.
      !>
      !>     COLDSC         is the descriptor of the column from which data is
      !>                    to be read.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry to be written.
      !>
      !>     BEG,
      !>     END            are, respectively, the start and end indices of
      !>                    the contiguous range of elements to be read from
      !>                    the specified column entry.
      !>
      !>## Detailed Output
      !>
      !>     IVALS          are the values read from the specified column
      !>                    entry.  The mapping of elements of the column entry
      !>                    to elements of IVALS is as shown below:
      !>
      !>                       Column entry element       IVALS element
      !>                       --------------------       -------------
      !>                       BEG                        1
      !>                       BEG+1                      2
      !>                       .                          .
      !>                       .                          .
      !>                       .                          .
      !>                       END                        END-BEG+1
      !>
      !>                    IVALS is valid only if the output argument
      !>                    FOUND is returned .TRUE.
      !>
      !>     ISNULL         is a logical flag indicating whether the entry is
      !>                    null.  ISNULL is set on output whether or not
      !>                    the range of elements designated by BEG and END
      !>                    exists.
      !>
      !>     FOUND          is a logical flag indicating whether the range
      !>                    of elements designated by BEG and END exists.
      !>                    If the number of elements in the specified column
      !>                    entry is not at least END, FOUND will be returned
      !>                    .FALSE.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If the specified column entry has not been initialized, the
      !>         error SPICE(UNINITIALIZEDVALUE) is signaled.
      !>
      !>     3)  If the ordinal position of the column specified by COLDSC
      !>         is out of range, the error SPICE(INVALIDINDEX) is signaled.
      !>
      !>     4)  If an I/O error occurs while reading the indicated file,
      !>         the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine is a utility for reading data from class 4 columns.
      !>
      !>## Examples
      !>
      !>     See EKRCEI.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.2.0, 07-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>        Bug fix: changed max column index in long error
      !>        message from NREC to NCOLS.
      !>
      !>-    SPICELIB Version 1.1.0, 08-SEP-2005 (NJB)
      !>
      !>        Updated to remove non-standard use of duplicate arguments
      !>        in ZZEKGFWD call.
      !>
      !>-    SPICELIB Version 1.0.0, 18-OCT-1995 (NJB)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.1.0, 08-SEP-2005 (NJB)
      !>
      !>        Updated to remove non-standard use of duplicate arguments
      !>        in ZZEKGFWD call.
      module subroutine zzekrd04 ( ctx, handle, segdsc, coldsc, recptr, beg, end, ivals, isnull, found )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      integer(ip), intent(in) :: beg  !! Start element index.
      integer(ip), intent(in) :: end  !! End element index.
      integer(ip), intent(out) :: ivals  ( * )  !! Integer values in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.
      logical, intent(out) :: found  !! Flag indicating whether elements were found.
      integer(ip) :: p_1(1)  !! one-element copy of p (array argument)
      integer(ip) :: nelt_1(1)  !! one-element copy of nelt (array argument)
      integer(ip) :: datptr_1(1)  !! one-element copy of datptr (array argument)

      integer(ip) :: base
      integer(ip) :: colidx
      integer(ip) :: datptr
      integer(ip) :: maxidx
      integer(ip) :: minidx
      integer(ip) :: ncols
      integer(ip) :: nelt
      integer(ip) :: nread
      integer(ip) :: p
      integer(ip) :: ptemp
      integer(ip) :: ptrloc
      integer(ip) :: recno
      integer(ip) :: remain
      integer(ip) :: start

!
!     Make sure the column exists.
!
      ncols  =  segdsc ( ncidx  )
      colidx =  coldsc ( ordidx )

      if (  ( colidx < 1 ) .or. ( colidx > ncols )  ) then

         call ctx%setmsg ( 'Column index = #; valid range is 1:#.' )
         call ctx%errint ( '#',  colidx                            )
         call ctx%errint ( '#',  ncols                             )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                   )
         return

      end if

!
!     Compute the data pointer location, and read the pointer.
!
      ptrloc  =  recptr + dptbas + colidx

      call dasrdi ( ctx, handle, ptrloc, ptrloc, datptr_1 )
      datptr = datptr_1(1)

      if ( datptr > 0 ) then
!
!        The entry is non-null.
!
         isnull  =  .false.

!
!        Get the element count.  Check for range specifications that
!        can't be met.
!
         call dasrdi ( ctx, handle, datptr, datptr, nelt_1 )
         nelt = nelt_1(1)

         if (  ( beg < 1 ) .or. ( beg > nelt )  )  then

            found  =  .false.
            return

         else if (  ( end < 1 ) .or. ( end > nelt )  )  then

            found  =  .false.
            return

         else if ( end < beg ) then

            found  =  .false.
            return

         end if

!
!        The request is valid, so read the data.  The first step is to
!        locate the element at index BEG.
!
         call zzekpgpg ( ctx, int, datptr, p, base )

         minidx  =  1
         maxidx  =  base   + ipsize - datptr
         datptr  =  datptr + beg

         do while ( maxidx < beg )
!
!           Locate the page on which the element is continued.
!
            call dasrdi ( ctx, handle, base+ifpidx, base+ifpidx, p_1 )
            p = p_1(1)

!
!           Determine the highest-indexed element of the column entry
!           located on the current page.
!
            call zzekpgbs ( ctx, int, p, base )

            minidx  =  maxidx  +   1
            maxidx  =  min ( maxidx + ipsize, nelt )

!
!           The following assignment will set DATPTR to the correct
!           value on the last pass through this loop.
!
            datptr  =  base    +   1   +  ( beg - minidx )

         end do

!
!        At this point, P is the page on which the element having index
!        BEG is located.  BASE is the base address of this page.
!        MAXIDX is the highest index of any element on the current page.
!
         remain  =  end    -   beg   +   1
         start   =  1

!
!        Decide how many elements to read from the current page, and
!        read them.
!
         nread   =  min ( remain,  ( base + ipsize - datptr + 1 )  )

         call dasrdi ( ctx, handle, datptr, datptr+nread-1, ivals(start) )

         remain  =  remain  -  nread

         do while (  ( remain > 0 ) .and.  ( .not. ctx%failed() )  )
!
!           Locate the page on which the element is continued.
!
            call zzekgfwd ( ctx, handle, int, p, ptemp )
            p = ptemp

            call zzekpgbs ( ctx, int,         p, base  )

            datptr  =  base   +  1
            start   =  start  +  nread
            nread   =  min ( remain,  ipsize )

            call dasrdi ( ctx, handle, datptr, datptr+nread-1, ivals(start) )

            remain  =  remain  -  nread

         end do

         found =  .not. ctx%failed()

      else if ( datptr == null ) then
!
!        The value is null.
!
         isnull =  .true.
         found  =  .true.

      else if ( datptr == uninit ) then
!
!        The data value is absent.  This is an error.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Attempted to read uninitialized column '    // &
                       'entry.  SEGNO = #; COLIDX = #; RECNO = #; ' // &
                       'EK = #'                                      )
         call ctx%errint ( '#',  segdsc(snoidx)                          )
         call ctx%errint ( '#',  colidx                                  )
         call ctx%errint ( '#',  recno                                   )
         call ctx%errhan ( '#',  handle                                  )
         call ctx%sigerr ( 'SPICE(UNINITIALIZEDVALUE)'                   )
         return

      else
!
!        The data pointer is corrupted.
!
         call ctx%setmsg ( 'Data pointer is corrupted. SEGNO = #; '  // &
                       'COLIDX =  #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  segdsc(snoidx)                      )
         call ctx%errint ( '#',  colidx                              )
         call ctx%errint ( '#',  recno                               )
         call ctx%errhan ( '#',  handle                              )
         call ctx%sigerr ( 'SPICE(BUG)'                              )
         return

      end if

      return
      end subroutine zzekrd04

      !> Read a specified element range from a column entry in a specified
      !> record in a class 5 column.  Class 5 columns have d.p. arrays
      !> as column entries.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is an EK file handle.
      !>
      !>     SEGDSC         is the descriptor of the segment from which data is
      !>                    to be read.
      !>
      !>     COLDSC         is the descriptor of the column from which data is
      !>                    to be read.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry to be written.
      !>
      !>     BEG,
      !>     END            are, respectively, the start and end indices of
      !>                    the contiguous range of elements to be read from
      !>                    the specified column entry.
      !>
      !>## Detailed Output
      !>
      !>     DVALS          are the values read from the specified column
      !>                    entry.  The mapping of elements of the column entry
      !>                    to elements of DVALS is as shown below:
      !>
      !>                       Column entry element       DVALS element
      !>                       --------------------       -------------
      !>                       BEG                        1
      !>                       BEG+1                      2
      !>                       .                          .
      !>                       .                          .
      !>                       .                          .
      !>                       END                        END-BEG+1
      !>
      !>                    DVALS is valid only if the output argument
      !>                    FOUND is returned .TRUE.
      !>
      !>     ISNULL         is a logical flag indicating whether the entry is
      !>                    null.  ISNULL is set on output whether or not
      !>                    the range of elements designated by BEG and END
      !>                    exists.
      !>
      !>     FOUND          is a logical flag indicating whether the range
      !>                    of elements designated by BEG and END exists.
      !>                    If the number of elements in the specified column
      !>                    entry is not at least END, FOUND will be returned
      !>                    .FALSE.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If the specified column entry has not been initialized, the
      !>         error SPICE(UNINITIALIZEDVALUE) is signaled.
      !>
      !>     3)  If the ordinal position of the column specified by COLDSC
      !>         is out of range, the error SPICE(INVALIDINDEX) is signaled.
      !>
      !>     4)  If an I/O error occurs while reading the indicated file,
      !>         the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine is a utility for reading data from class 5 columns.
      !>
      !>## Examples
      !>
      !>     See EKRCED.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.2.0, 07-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>        Bug fix: changed max column index in long error
      !>        message from NREC to NCOLS.
      !>
      !>-    SPICELIB Version 1.1.0, 12-SEP-2005 (NJB)
      !>
      !>        Updated to remove non-standard use of duplicate arguments
      !>        in ZZEKGFWD calls.
      !>
      !>-    SPICELIB Version 1.0.0, 18-OCT-1995 (NJB)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.1.0, 12-SEP-2005 (NJB)
      !>
      !>        Updated to remove non-standard use of duplicate arguments
      !>        in ZZEKGFWD calls.
      module subroutine zzekrd05 ( ctx, handle, segdsc, coldsc, recptr, beg, end, dvals, isnull, found )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      integer(ip), intent(in) :: beg  !! Start element index.
      integer(ip), intent(in) :: end  !! End element index.
      real(wp), intent(out) :: dvals  ( * )  !! Double precision values in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.
      logical, intent(out) :: found  !! Flag indicating whether elements were found.
      real(wp) :: dpnelt_1(1)  !! one-element copy of dpnelt (array argument)
      integer(ip) :: datptr_1(1)  !! one-element copy of datptr (array argument)
!
!     Local variables
!
      real(wp) :: dpnelt

      integer(ip) :: base
      integer(ip) :: colidx
      integer(ip) :: datptr
      integer(ip) :: maxidx
      integer(ip) :: minidx
      integer(ip) :: ncols
      integer(ip) :: nelt
      integer(ip) :: nread
      integer(ip) :: p
      integer(ip) :: ptemp
      integer(ip) :: ptrloc
      integer(ip) :: recno
      integer(ip) :: remain
      integer(ip) :: start

!
!     Make sure the column exists.
!
      ncols  =  segdsc ( ncidx  )
      colidx =  coldsc ( ordidx )

      if (  ( colidx < 1 ) .or. ( colidx > ncols )  ) then

         call ctx%setmsg ( 'Column index = #; valid range is 1:#.' )
         call ctx%errint ( '#',  colidx                            )
         call ctx%errint ( '#',  ncols                             )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                   )
         return

      end if

!
!     Compute the data pointer location, and read the pointer.
!
      ptrloc  =  recptr + dptbas + colidx

      call dasrdi ( ctx, handle, ptrloc, ptrloc, datptr_1 )
      datptr = datptr_1(1)

      if ( datptr > 0 ) then
!
!        The entry is non-null.
!
         isnull  =  .false.

!
!        Get the element count.  Check for range specifications that
!        can't be met.
!
         call dasrdd ( ctx, handle, datptr, datptr, dpnelt_1 )
         dpnelt = dpnelt_1(1)

         nelt  =  nint ( dpnelt )

         if (  ( beg < 1 ) .or. ( beg > nelt )  )  then

            found  =  .false.
            return

         else if (  ( end < 1 ) .or. ( end > nelt )  )  then

            found  =  .false.
            return

         else if ( end < beg ) then

            found  =  .false.
            return

         end if

!
!        The request is valid, so read the data.  The first step is to
!        locate the element at index BEG.
!
         call zzekpgpg ( ctx, dp, datptr, p, base )

         minidx  =  1
         maxidx  =  base   + dpsize - datptr
         datptr  =  datptr + beg

         do while ( maxidx < beg )
!
!           Locate the page on which the element is continued.
!
            call zzekgfwd ( ctx, handle, dp, p, ptemp )
            p = ptemp

            call zzekpgbs ( ctx, dp,         p, base  )

!
!           Determine the highest-indexed element of the column entry
!           located on the current page.
!
            minidx  =  maxidx  +   1
            maxidx  =  min ( maxidx + dpsize, nelt )

!
!           The following assignment will set DATPTR to the correct
!           value on the last pass through this loop.
!
            datptr  =  base    +   1   +  ( beg - minidx )

         end do

!
!        At this point, P is the page on which the element having index
!        BEG is located.  BASE is the base address of this page.
!        MAXIDX is the highest index of any element on the current page.
!
         remain  =  end    -   beg   +   1
         start   =  1

!
!        Decide how many elements to read from the current page, and
!        read them.
!
         nread   =  min ( remain,  ( base + dpsize - datptr + 1 )  )

         call dasrdd ( ctx, handle, datptr, datptr+nread-1, dvals(start) )

         remain  =  remain  -  nread

         do while (  ( remain > 0 ) .and.  ( .not. ctx%failed() )  )
!
!           Locate the page on which the element is continued.
!
            call zzekgfwd ( ctx, handle, dp, p, ptemp )
            p = ptemp

            call zzekpgbs ( ctx, dp,         p, base  )

            datptr  =  base   +  1
            start   =  start  +  nread
            nread   =  min ( remain,  dpsize )

            call dasrdd ( ctx, handle, datptr, datptr+nread-1, dvals(start) )

            remain  =  remain  -  nread

         end do

         found =  .not. ctx%failed()

      else if ( datptr == null ) then
!
!        The value is null.
!
         isnull =  .true.
         found  =  .true.

      else if ( datptr == uninit ) then
!
!        The data value is absent.  This is an error.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Attempted to read uninitialized column '    // &
                       'entry.  SEGNO = #; COLIDX = #; RECNO = #; ' // &
                       'EK = #'                                      )
         call ctx%errint ( '#',  segdsc(snoidx)                          )
         call ctx%errint ( '#',  colidx                                  )
         call ctx%errint ( '#',  recno                                   )
         call ctx%errhan ( '#',  handle                                  )
         call ctx%sigerr ( 'SPICE(UNINITIALIZEDVALUE)'                   )
         return

      else
!
!        The data pointer is corrupted.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Data pointer is corrupted. SEGNO = #; '  // &
                       'COLIDX =  #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  segdsc(snoidx)                      )
         call ctx%errint ( '#',  colidx                              )
         call ctx%errint ( '#',  recno                               )
         call ctx%errhan ( '#',  handle                              )
         call ctx%sigerr ( 'SPICE(BUG)'                              )
         return

      end if

      return
      end subroutine zzekrd05

      !> Read a specified element range from a column entry in a specified
      !> record in a class 6 column.  Class 6 columns have character arrays
      !> as column entries.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is an EK file handle.
      !>
      !>     SEGDSC         is the descriptor of the segment from which data is
      !>                    to be read.
      !>
      !>     COLDSC         is the descriptor of the column from which data is
      !>                    to be read.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry to be written.
      !>
      !>     BEG,
      !>     END            are, respectively, the start and end indices of
      !>                    the contiguous range of elements to be read from
      !>                    the specified column entry.
      !>
      !>## Detailed Output
      !>
      !>     CVALS          are the values read from the specified column
      !>                    entry.  The mapping of elements of the column entry
      !>                    to elements of CVALS is as shown below:
      !>
      !>                       Column entry element       CVALS element
      !>                       --------------------       -------------
      !>                       BEG                        1
      !>                       BEG+1                      2
      !>                       .                          .
      !>                       .                          .
      !>                       .                          .
      !>                       END                        END-BEG+1
      !>
      !>                    CVALS must have sufficient string length to hold
      !>                    the longest returned string value.  Entries that
      !>                    are shorter than the string length of CVALS are
      !>                    padded with trailing blanks.
      !>
      !>                    CVALS is valid only if the output argument
      !>                    FOUND is returned .TRUE.
      !>
      !>     ISNULL         is a logical flag indicating whether the entry is
      !>                    null.  ISNULL is set on output whether or not
      !>                    the range of elements designated by BEG and END
      !>                    exists.
      !>
      !>     FOUND          is a logical flag indicating whether the range
      !>                    of elements designated by BEG and END exists.
      !>                    If the number of elements in the specified column
      !>                    entry is not at least END, FOUND will be returned
      !>                    .FALSE.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If the specified column entry has not been initialized, the
      !>         error SPICE(UNINITIALIZED) is signaled.
      !>
      !>     3)  If the ordinal position of the column specified by COLDSC
      !>         is out of range, the error SPICE(INVALIDINDEX) is signaled.
      !>
      !>     4)  If the string length of CVALS is shorter than the declared
      !>         string length of the specified column, the error
      !>         SPICE(STRINGTRUNCATED) is signaled.
      !>
      !>     5)  If an I/O error occurs while reading the indicated file,
      !>         the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine is a utility for reading data from class 6 columns.
      !>
      !>## Examples
      !>
      !>     See EKRCEC.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.2.0, 07-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>        Bug fix: changed max column index in long error
      !>        message from NREC to NCOLS.
      !>
      !>-    SPICELIB Version 1.1.0, 28-JUL-1997 (NJB)
      !>
      !>        Error check for string truncation on output was added.
      !>        SHORT error message SPICE(UNINITIALIZEDVALUE) was shortened
      !>        to SPICE(UNINITIALIZED).  Error messages were enhanced so
      !>        as to use column names rather than indices.
      !>
      !>-    SPICELIB Version 1.0.0, 18-OCT-1995 (NJB)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.1.0, 28-JUL-1997 (NJB)
      !>
      !>        Error check for string truncation on output was added.
      !>        SHORT error message SPICE(UNINITIALIZEDVALUE) was shortened
      !>        to SPICE(UNINITIALIZED).  Error messages were enhanced so
      !>        as to use column names rather than indices.
      module subroutine zzekrd06 ( ctx, handle, segdsc, coldsc, recptr, beg, end, cvals, isnull, found )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekcnamsz
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype

      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      integer(ip), intent(in) :: beg  !! Start element index.
      integer(ip), intent(in) :: end  !! End element index.
      character(*), intent(out) :: cvals  ( * )  !! Character values in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.
      logical, intent(out) :: found  !! Flag indicating whether elements were found.
      integer(ip) :: datptr_1(1)  !! one-element copy of datptr (array argument)
!
!     Local variables
!
      character(cnamsz) :: column

      integer(ip) :: avail
      integer(ip) :: base
      integer(ip) :: colidx
      integer(ip) :: cvlen
      integer(ip) :: d
      integer(ip) :: datptr
      integer(ip) :: delta
      integer(ip) :: eltidx
      integer(ip) :: eltoff
      integer(ip) :: maxelt
      integer(ip) :: ncols
      integer(ip) :: nelt
      integer(ip) :: nread
      integer(ip) :: nskip
      integer(ip) :: offset
      integer(ip) :: p
      integer(ip) :: pagnum
      integer(ip) :: pg
      integer(ip) :: ptrloc
      integer(ip) :: ptroff
      integer(ip) :: recno
      integer(ip) :: remain
      integer(ip) :: start
      integer(ip) :: strlen

!
!     Make sure the column exists.
!
      ncols  =  segdsc ( ncidx  )
      colidx =  coldsc ( ordidx )

      if (  ( colidx < 1 ) .or. ( colidx > ncols )  ) then

         call ctx%setmsg ( 'Column index = #; valid range is 1:#.' )
         call ctx%errint ( '#',  colidx                            )
         call ctx%errint ( '#',  ncols                             )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                   )
         return

      end if

!
!     Make sure the output buffer is wide enough to hold the returned
!     strings.
!
      cvlen   =  len    ( cvals(1) )
      strlen  =  coldsc ( lenidx   )

      if ( strlen > cvlen ) then
!
!        We have a string truncation error.  Look up the column
!        name, record number, and file name before signaling an
!        error.
!
         call zzekcnam ( ctx, handle, coldsc, column )

         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'String value has length #; output string '// &
                       'can hold only # characters.  COLUMN = #; '// &
                       'SEGNO = #; RECNO = #; EK = #'              )
         call ctx%errint ( '#',  strlen                                )
         call ctx%errint ( '#',  cvlen                                 )
         call ctx%errch  ( '#',  column                                )
         call ctx%errint ( '#',  segdsc(snoidx)                        )
         call ctx%errint ( '#',  recno                                 )
         call ctx%errhan ( '#',  handle                                )
         call ctx%sigerr ( 'SPICE(STRINGTRUNCATED)'                    )
         return

      end if

!
!     Compute the data pointer location, and read the pointer.
!
      ptrloc  =  recptr + dptbas + colidx

      call dasrdi ( ctx, handle, ptrloc, ptrloc, datptr_1 )
      datptr = datptr_1(1)

      if ( datptr > 0 ) then
!
!        The entry is non-null.
!
         isnull  =  .false.

!
!        Get the element count.  Check for range specifications that
!        can't be met.
!
         call zzekgei ( ctx, handle, datptr, nelt )

         if (  ( beg < 1 ) .or. ( beg > nelt )  )  then

            found  =  .false.
            return

         else if (  ( end < 1 ) .or. ( end > nelt )  )  then

            found  =  .false.
            return

         else if ( end < beg ) then

            found  =  .false.
            return

         end if

!
!        The request is valid, so read the data.  The first step is to
!        locate the element at index BEG.  We'll first decide on which
!        page the desired element starts.  The first page holds up to
!        CPSIZE - ENCSIZ characters; the rest hold CPSIZE characters.
!        While we're at it, we'll compute the offset ELTOFF of the
!        element from the base of the page on which the element starts.
!        We'll use the name OFFSET to represent the character offset
!        of the element from the base of the page on which the column
!        entry starts.
!
         call zzekpgpg ( ctx, chr, datptr, p, base )

         ptroff  =  datptr  -  base
         offset  =  ptroff  +  encsiz   +   strlen * ( beg - 1 )

         if ( offset <= cpsize ) then

            pagnum   =    1
            eltoff   =    offset

         else

            pagnum   =  ( offset  +  cpsize   -   1 ) / cpsize
            eltoff   =    offset  -    ( pagnum - 1 ) * cpsize

         end if

!
!        Get the absolute page number and base address of the page
!        on which the element starts.  If this is not the page on
!        which the column entry starts, we'll chain along using
!        the page's forward links until we arrive at the correct page.
!
         pg  =  1

         do while ( pg < pagnum )
!
!           Get the link to the next page, then look up the base
!           address of that page.
!
            call zzekgei  ( ctx, handle, base+cfpidx, p    )
            call zzekpgbs ( ctx, chr,    p,           base )

            pg  =  pg + 1

         end do

!
!        The desired element starts at address BASE + ELTOFF.
!
         datptr  =  base + eltoff

!
!        At this point, P is the page on which the element having index
!        BEG is located.  BASE is the base address of this page.
!
!        Read the strings one at a time.
!
         eltidx   =  1
         maxelt   =  end - beg + 1

         do while (  ( eltidx <= maxelt ) .and. ( .not. ctx%failed() )  )
!
!           Read the current string.  The string may be continued over
!           multiple pages.  Read only as many characters as will fit
!           in the output buffer element CVALS(ELTIDX).
!
            remain  =  min ( cvlen, strlen )
            start   =  1

            do while (  ( remain > 0 ) .and. ( .not. ctx%failed() )  )

               avail  =  base + cpsize - datptr + 1
               nread  =  min  ( remain,  avail )

               if ( nread > 0 ) then

                  call dasrdc ( ctx, handle, &
                                datptr, &
                                datptr + nread - 1, &
                                start, &
                                start + nread - 1, &
                                cvals ( eltidx )    )

                  start  =  start  + nread
                  remain =  remain - nread
                  datptr =  datptr + nread

               else
!
!                 Go to the next page for the continuation of the
!                 current string.
!
                  call zzekgei  ( ctx, handle, base+cfpidx, p    )
                  call zzekpgbs ( ctx, chr,    p,           base )

                  datptr  =  base   +  1

               end if

            end do

!
!           If we did not read all of the current array element,
!           we'll need to advance DATPTR past the end of the element.
!           If this advance moved DATPTR beyond the last character
!           of the current page, the logic above will set DATPTR to
!           indicate the first character of the next continuation page.
!
            delta  =  strlen - cvlen

            if ( delta > 0 ) then

               d  =  delta

               do while ( d > 0 )

                  avail  =  base + cpsize - datptr + 1
                  nskip  =  min  ( d,  avail )

                  if ( nskip > 0 ) then

                     d      =  d      - nskip
                     datptr =  datptr + nskip

                  else
!
!                    Go to the next page for the continuation of the
!                    current string.
!
                     call zzekgei  ( ctx, handle, base+cfpidx, p    )
                     call zzekpgbs ( ctx, chr,    p,           base )

                     datptr  =  base   +  1

                  end if

               end do

            end if

!
!           Blank-pad the output string if necessary.
!
            if ( cvlen > strlen ) then
               cvals ( eltidx ) ( strlen+1: ) = ' '
            end if

            eltidx  =  eltidx + 1

         end do

         found =  .not. ctx%failed()

      else if ( datptr == null ) then
!
!        The value is null.
!
         isnull =  .true.
         found  =  .true.

      else if ( datptr == uninit ) then
!
!        The data value is absent.  This is an error.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call zzekcnam ( ctx, handle,   coldsc, column )

         call ctx%setmsg ( 'Attempted to read uninitialized column '    // &
                       'entry.  SEGNO = #; COLUMN = #; RECNO = #; ' // &
                       'EK = #'                                      )
         call ctx%errint ( '#',  segdsc(snoidx)                          )
         call ctx%errch  ( '#',  column                                  )
         call ctx%errint ( '#',  recno                                   )
         call ctx%errhan ( '#',  handle                                  )
         call ctx%sigerr ( 'SPICE(UNINITIALIZED)'                        )
         return

      else
!
!        The data pointer is corrupted.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call zzekcnam ( ctx, handle,   coldsc, column )

         call ctx%setmsg ( 'Data pointer is corrupted. SEGNO = #; '  // &
                       'COLUMN =  #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  segdsc(snoidx)                      )
         call ctx%errch  ( '#',  column                              )
         call ctx%errint ( '#',  recno                               )
         call ctx%errhan ( '#',  handle                              )
         call ctx%sigerr ( 'SPICE(BUG)'                              )
         return

      end if

      return
      end subroutine zzekrd06

      !> Read a column entry from a specified record in a class 7 column.
      !> Class 7 columns contain fixed-count, scalar integer values.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is an EK file handle.
      !>
      !>     SEGDSC         is the descriptor of the segment from which data is
      !>                    to be read.
      !>
      !>     COLDSC         is the descriptor of the column from which data is
      !>                    to be read.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry to be written.  For class 7 columns, record
      !>                    pointers are identical to record numbers.
      !>
      !>## Detailed Output
      !>
      !>     IVAL           is the value read from the specified column entry.
      !>
      !>     ISNULL         is a logical flag indicating whether the column
      !>                    entry is null.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If the ordinal position of the column specified by COLDSC
      !>         is out of range, the error SPICE(INVALIDINDEX) is signaled.
      !>
      !>     3)  If an I/O error occurs while reading the indicated file,
      !>         the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine is a utility for reading data from class 7 columns.
      !>
      !>## Examples
      !>
      !>     See EKRCEI.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 07-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>        Bug fix: changed max column index in long error
      !>        message from NREC to NCOLS.
      !>
      !>-    Beta Version 1.0.0, 09-NOV-1995 (NJB)
      module subroutine zzekrd07 ( ctx, handle, segdsc, coldsc, recptr, ival, isnull )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekclas07
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekpage
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      integer(ip), intent(out) :: ival  !! Integer value in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.
      integer(ip) :: ival_1(1)  !! one-element copy of ival (array argument)
!
!     Local variables
!
      character(1) :: cflag

      integer(ip) :: addrss
      integer(ip) :: colidx
      integer(ip) :: datbas
      integer(ip) :: mdat   ( mdsz07 )
      integer(ip) :: metloc
      integer(ip) :: ncols
      integer(ip) :: nflbas
      integer(ip) :: offset
      integer(ip) :: q
      integer(ip) :: r
      integer(ip) :: recno

      logical :: nullok

!
!     Make sure the column exists.
!
      ncols   =  segdsc ( ncidx  )
      colidx  =  coldsc ( ordidx )
      metloc  =  coldsc ( metidx )
      nullok  =  coldsc ( nflidx ) == itrue

      if (  ( colidx < 1 ) .or. ( colidx > ncols )  ) then

         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Column index = #; valid range is 1:#.' // &
                       'SEGNO = #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  colidx                            )
         call ctx%errint ( '#',  ncols                             )
         call ctx%errint ( '#',  segdsc(snoidx)                    )
         call ctx%errint ( '#',  recno                             )
         call ctx%errhan ( '#',  handle                            )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                   )
         return

      end if

!
!     Read the metadata block.  There are two items in the block:
!
!        1) The base address of the first page of the data
!        2) The base address of the null flag array, if nulls are
!           permitted.
!
      call dasrdi ( ctx, handle, metloc+1, metloc+mdsz07, mdat )

      datbas = mdat ( dbix07 )
      nflbas = mdat ( nfix07 )

!
!     If null values are permitted, the first step is to get
!     the null flag for the value of interest.  Compute the
!     address of this flag.
!
!     There are CPSIZE null flags per page, and each page has size
!     PGSIZC.  The null flags start at the beginning of the page.
!
      if ( nullok ) then

         q       =  (recptr-1) / cpsize
         r       =  recptr - q * cpsize
         offset  =  r      + q * pgsizc
         addrss  =  nflbas + offset

         call dasrdc ( ctx, handle, addrss, addrss, 1, 1, cflag )

         isnull  =  cflag == ctrue

         if ( isnull ) return

      end if

!
!     If we're still here, we'll read the data value.
!
      isnull  =  .false.

!
!     The address calculation for the value is analogous to that
!     for the null flag.
!
      q       =  (recptr-1)  / ipsize
      r       =  recptr - q * ipsize
      offset  =  r      + q * pgsizi
      addrss  =  datbas + offset

      call dasrdi ( ctx, handle, addrss, addrss, ival_1 )
      ival = ival_1(1)

      return
      end subroutine zzekrd07

      !> Read a column entry from a specified record in a class 8 column.
      !> Class 8 columns contain fixed-count, scalar, double precision
      !> values.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is an EK file handle.
      !>
      !>     SEGDSC         is the descriptor of the segment from which data is
      !>                    to be read.
      !>
      !>     COLDSC         is the descriptor of the column from which data is
      !>                    to be read.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry to be written.  For class 8 columns, record
      !>                    pointers are identical to record numbers.
      !>
      !>## Detailed Output
      !>
      !>     DVAL           is the value read from the specified column entry.
      !>
      !>     ISNULL         is a logical flag indicating whether the entry is
      !>                    null.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If the ordinal position of the column specified by COLDSC
      !>         is out of range, the error SPICE(INVALIDINDEX) is signaled.
      !>
      !>     3)  If an I/O error occurs while reading the indicated file,
      !>         the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine is a utility for reading data from class 8 columns.
      !>
      !>## Examples
      !>
      !>     See EKRCED.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 07-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>        Bug fix: changed max column index in long error
      !>        message from NREC to NCOLS.
      !>
      !>-    Beta Version 1.0.0, 09-NOV-1995 (NJB)
      module subroutine zzekrd08 ( ctx, handle, segdsc, coldsc, recptr, dval, isnull )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekbool
      use pepper_inc_ekclas08
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekpage
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      real(wp), intent(out) :: dval  !! Double precision value in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.
      real(wp) :: dval_1(1)  !! one-element copy of dval (array argument)
!
!     Local variables
!
      character(1) :: cflag

      integer(ip) :: addrss
      integer(ip) :: colidx
      integer(ip) :: datbas
      integer(ip) :: mdat   ( mdsz08 )
      integer(ip) :: metloc
      integer(ip) :: ncols
      integer(ip) :: nflbas
      integer(ip) :: offset
      integer(ip) :: q
      integer(ip) :: r
      integer(ip) :: recno

      logical :: nullok

!
!     Make sure the column exists.
!
      ncols   =  segdsc ( ncidx  )
      colidx  =  coldsc ( ordidx )
      metloc  =  coldsc ( metidx )
      nullok  =  coldsc ( nflidx ) == itrue

      if (  ( colidx < 1 ) .or. ( colidx > ncols )  ) then

         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Column index = #; valid range is 1:#.' &
         //            'SEGNO = #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  colidx                            )
         call ctx%errint ( '#',  ncols                             )
         call ctx%errint ( '#',  segdsc(snoidx)                    )
         call ctx%errint ( '#',  recno                             )
         call ctx%errhan ( '#',  handle                            )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                   )
         return

      end if

!
!     Read the metadata block.  There are two items in the block:
!
!        1) The base address of the first page of the data
!        2) The base address of the null flag array, if nulls are
!           permitted.
!
      call dasrdi ( ctx, handle, metloc+1, metloc+mdsz08, mdat )

      datbas = mdat ( dbix08 )
      nflbas = mdat ( nfix08 )

!
!     If null values are permitted, the first step is to get
!     the null flag for the value of interest.  Compute the
!     address of this flag.
!
!     There are CPSIZE null flags per page, and each page has size
!     PGSIZC.  The null flags start at the beginning of the page.
!
      if ( nullok ) then

         q       =  (recptr-1) / cpsize
         r       =  recptr - q * cpsize
         offset  =  r      + q * pgsizc
         addrss  =  nflbas + offset

         call dasrdc ( ctx, handle, addrss, addrss, 1, 1, cflag )

         isnull  =  cflag == ctrue

         if ( isnull ) return

      end if

!
!     If we're still here, we'll read the data value.
!
      isnull  =  .false.

!
!     The address calculation for the value is analogous to that
!     for the null flag.
!
      q       =  (recptr-1)  / dpsize
      r       =  recptr - q * dpsize
      offset  =  r      + q * pgsizd
      addrss  =  datbas + offset

      call dasrdd ( ctx, handle, addrss, addrss, dval_1 )
      dval = dval_1(1)

      return
      end subroutine zzekrd08

      !> Set the data pointer for a specified EK column entry.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is a file handle of an EK open for write access.
      !>
      !>     SEGDSC         is the descriptor of the segment containing
      !>                    the specified column entry.
      !>
      !>     COLDSC         is the descriptor of the column containing
      !>                    the specified column entry.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry whose data pointer is to be set.
      !>
      !>     DATPTR         is the data pointer of the specified column entry.
      !>                    When DATPTR is positive, it represents a pointer
      !>                    to a data value.  The interpretation of the
      !>                    pointer depends on the class of the column entry.
      !>                    DATPTR may also take on the distinguished values
      !>
      !>                       UNINIT  (indicated uninitialized entry)
      !>                       NULL    (indicated null entry)
      !>                       NOBACK  (indicated uninitialized backup entry)
      !>
      !>## Detailed Output
      !>
      !>     None.  See $Particulars for a description of the action of this
      !>     routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine hides details of column entry data pointer access.
      !>     The inverse of this routine is ZZEKGCDP.
      !>
      !>## Examples
      !>
      !>     1)  Set a column's data pointer to indicate that a column entry
      !>         is uninitialized.  The parameter UNINIT is defined in
      !>         ekrecptr.inc
      !>
      !>           CALL ZZEKSCDP ( HANDLE, SEGDSC, COLDSC, RECPTR, UNINIT )
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 09-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>-    Beta Version 1.0.0, 17-OCT-1995 (NJB)
      module subroutine zzekscdp ( ctx, handle, segdsc, coldsc, recptr, datptr )
      use pepper_kinds, only: ip
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ekrecptr
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      integer(ip), intent(in) :: datptr  !! Data pointer of column entry.
!
!     Local variables
!
      integer(ip) :: colidx
      integer(ip) :: ncols
      integer(ip) :: ptrloc
      integer(ip) :: recno

!
!     Is this file handle valid--is the file open for paged write
!     access?  Signal an error if not.
!
      call zzekpgch ( ctx, handle, 'WRITE' )

      if ( ctx%failed() ) return

!
!     Make sure the column exists.
!
      ncols  =  segdsc ( ncidx  )
      colidx =  coldsc ( ordidx )

      if (  ( colidx < 1 ) .or. ( colidx > ncols )  ) then

         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Column index = #; valid range is 1:#.' // &
                       'SEGNO = #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  colidx                            )
         call ctx%errint ( '#',  ncols                             )
         call ctx%errint ( '#',  segdsc(snoidx)                    )
         call ctx%errint ( '#',  recno                             )
         call ctx%errhan ( '#',  handle                            )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                   )
         return

      end if

!
!     Compute the data pointer location, and set the pointer.
!
      ptrloc  =  recptr + dptbas + colidx

      call dasudi ( ctx, handle, ptrloc, ptrloc, [ datptr ] )

      return
      end subroutine zzekscdp

      !> Write a character array out to a contiguous set of EK pages.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         the handle of an EK file that is open for writing.
      !>
      !>     SEGDSC         is a descriptor for the segment to which data is
      !>                    to be added.  The segment descriptor is not
      !>                    updated by this routine, but some fields in the
      !>                    descriptor will become invalid after this routine
      !>                    returns.
      !>
      !>     NVALS          is the number of character values to write.
      !>
      !>     L              is the length of the input values.  The input
      !>                    strings are expected to be short compared to the
      !>                    size of a character page.
      !>
      !>     CVALS          is an array of character values.  The first L
      !>                    characters of each element of CVALS will be
      !>                    written.  The strings are not split across pages;
      !>                    instead, unused space is left at the end of each
      !>                    page if the string length does not divide the
      !>                    page size evenly.
      !>
      !>## Detailed Output
      !>
      !>     P              is the number of the first page to which the
      !>                    input values are written.  CVALS(1) is written to
      !>                    a range of DAS character words starting with the
      !>                    the first word of page P.  The values are written
      !>                    to a contiguous set of pages in increasing order.
      !>
      !>     BASE           is the base address of P.  BASE is the predecessor
      !>                    of the first DAS address belonging to page P.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>     3)  If L is negative or greater than the input string length,
      !>         the error SPICE(INVALIDSIZE) is signaled.
      !>
      !>     4)  If L is greater than the size of the data area of a
      !>         character page, the error SPICE(INVALIDSIZE) is signaled.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine writes an array of character values to a contiguous
      !>     set of new character pages.  The first element of the input array
      !>     is written to a range of values starting at the first DAS address
      !>     of the first page of the set.
      !>
      !>     Note that the values do not occupy a contiguous range of DAS
      !>     character words, since each page contains several addresses
      !>     reserved for bookkeeping information, and since there may be
      !>     unused space at the end of a data page.  However, since each page
      !>     contains exactly CPSIZE characters and has size PGSIZC, it's easy
      !>     to compute the DAS address of the Ith element in the array:
      !>
      !>        N          =   IPSIZE  / L
      !>        Q          =   I       / N
      !>        R          =   I  -  Q * N
      !>
      !>        ADDRSS(I)  =  BASE  +  Q * PGSIZC  +  (R-1) * L  +  1
      !>
      !>## Examples
      !>
      !>     See ZZEKAC07.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 03-OCT-2021 (NJB)
      !>
      !>        Corrected typos in comments.
      !>
      !>-    Beta Version 1.0.0, 07-NOV-1995 (NJB)
      module subroutine zzekwpac ( ctx, handle, segdsc, nvals, l, cvals, p, base )
      use pepper_kinds, only: ip
      use pepper_inc_ekdatpag
      use pepper_inc_ekpage
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( * )  !! Descriptor of segment that owns the array.
      integer(ip), intent(in) :: nvals  !! Number of values to write.
      integer(ip), intent(in) :: l  !! String length.
      character(*), intent(in) :: cvals  ( * )  !! Character values.
      integer(ip), intent(out) :: p  !! Number of first page containing array.
      integer(ip), intent(out) :: base  !! Base address of first page.
!
!     Local variables
!
      character(pgsizc) :: page

      integer(ip) :: from
      integer(ip) :: npage
      integer(ip) :: spp
      integer(ip) :: to

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Check the input string length.
!
      if (      ( l < 0             ) &
           .or. ( l > len(cvals(1)) ) &
           .or. ( l > cpsize        )  ) then

         call ctx%setmsg ( 'String length # is just plain wrong.' )
         call ctx%errint ( '#',  l                                )
         call ctx%sigerr ( 'SPICE(INVALIDSIZE)'                   )
         return

      end if

!
!     Compute the number of strings we can hold in one page.
!
      spp  =  cpsize / l

!
!     Decide how many pages are required to hold the array, and
!     allocate that many new, contiguous pages.
!
      npage  =  ( nvals + spp - 1 ) / spp

      call zzekacps ( ctx, handle, segdsc, chr, npage, p, base )

!
!     We'll use FROM to indicate the element of CVALS we're
!     considering and TO to indicate the element of PAGE to write
!     to.
!
      to   =  1
      page =  ' '

      do from = 1, nvals
!
!        The Assignment.
!
         page( to : to+l-1 ) =  cvals(from)
         to                  =  to + l

         if (      ( to   > cpsize-l+1 ) &
              .or. ( from == nvals      )  ) then
!
!           Either the current data page is full, or we've buffered
!           the last of the available data.  It's time to write out the
!           current page.
!
            call zzekpgwc ( ctx, handle, p, page  )

!
!           Set the link count.
!
            call zzekslnk ( ctx, handle, chr, p,  (to-l)/l  )

!
!           Next page.
!
            p   =  p + 1
            to  =  1

         end if

      end do

      return
      end subroutine zzekwpac

      !> Write an integer array out to a contiguous set of EK pages.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         the handle of an EK file that is open for writing.
      !>
      !>     SEGDSC         is a descriptor for the segment to which data is
      !>                    to be added.  The segment descriptor is not
      !>                    updated by this routine, but some fields in the
      !>                    descriptor will become invalid after this routine
      !>                    returns.
      !>
      !>     NVALS          is the number of integer values to write.
      !>
      !>     IVALS          is an array of integer values.
      !>
      !>## Detailed Output
      !>
      !>     P              is the number of the first page to which the
      !>                    input values are written.  IVALS(1) is written to
      !>                    the first word of page P.  The values are written
      !>                    to a contiguous set of pages in increasing order.
      !>
      !>     BASE           is the base address of P.  BASE is the predecessor
      !>                    of the first DAS address belonging to page P.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine writes an array of integer values to a contiguous
      !>     set of new integer pages.  The first element of the input array
      !>     is written to the first DAS address of the first page of the set.
      !>
      !>     Note that the values do not occupy a contiguous range of DAS
      !>     integer words, since each page contains several addresses
      !>     reserved for bookkeeping information.  However, since each page
      !>     contains exactly IPSIZE integers and has size PGSIZI, it's easy
      !>     to compute the DAS address of the Ith element in the array:
      !>
      !>        Q          =   (I-1)  /  IPSIZE
      !>        R          =   I  -  Q * IPSIZE
      !>
      !>        ADDRSS(I)  =  BASE +  Q * PGSIZI + R
      !>
      !>## Examples
      !>
      !>     See ZZEKAC07.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    Beta Version 1.0.0, 08-NOV-1995 (NJB)
      module subroutine zzekwpai ( ctx, handle, segdsc, nvals, ivals, p, base )
      use pepper_kinds, only: ip
      use pepper_inc_ekdatpag
      use pepper_inc_ekpage
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( * )  !! Descriptor of segment that owns the array.
      integer(ip), intent(in) :: nvals  !! Number of values to write.
      integer(ip), intent(in) :: ivals  ( * )  !! Integer values.
      integer(ip), intent(out) :: p  !! Number of first page containing array.
      integer(ip), intent(out) :: base  !! Base address of first page.
!
!     Local variables
!
      integer(ip) :: from
      integer(ip) :: npage
      integer(ip) :: page   ( pgsizi )
      integer(ip) :: to

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Decide how many pages are required to hold the array, and
!     allocate that many new, contiguous pages.
!
      npage  =  ( nvals + ipsize - 1 ) / ipsize

      call zzekacps ( ctx, handle, segdsc, int, npage, p, base )

!
!     We'll use FROM to indicate the element of IVALS we're
!     considering and TO to indicate the element of PAGE to write
!     to.
!
      to  =  1
      page = 0

      do from = 1, nvals
!
!        The Assignment.
!
         page(to) =  ivals(from)
         to       =  to + 1

         if (  ( to > ipsize ) .or. ( from == nvals )  ) then
!
!           Either the current data page is full, or we've buffered
!           the last of the available data.  It's time to write out the
!           current page.  First set the link count.
!
            page ( ilcidx ) =  to - 1

!
!           Write out the data page.
!
            call zzekpgwi ( ctx, handle, p, page  )

!
!           Next page.
!
            p   =  p + 1
            to  =  1

         end if

      end do

      return
      end subroutine zzekwpai

      !> Write a logical array out to a contiguous set of EK pages.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         the handle of an EK file that is open for writing.
      !>
      !>     SEGDSC         is a descriptor for the segment to which data is
      !>                    to be added.  The segment descriptor is not
      !>                    updated by this routine, but some fields in the
      !>                    descriptor will become invalid after this routine
      !>                    returns.
      !>
      !>     NVALS          is the number of logical values to write.
      !>
      !>     LVALS          is an array of logical values.  The values will
      !>                    be stored as characters, with one character used
      !>                    per element of LVALS.
      !>
      !>## Detailed Output
      !>
      !>     P              is the number of the first page to which the
      !>                    input values are written.  The character
      !>                    representing LVALS(1) is written to the first DAS
      !>                    character of page P.  The values are written
      !>                    to a contiguous set of pages in increasing order.
      !>
      !>     BASE           is the base address of P.  BASE is the predecessor
      !>                    of the first DAS address belonging to page P.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine writes an array of logical values to a contiguous
      !>     set of new character pages.  The first element of the input array
      !>     is written to a range of values starting at the first DAS address
      !>     of the first page of the set.
      !>
      !>     This routine supports creation of null flag arrays for fixed-count
      !>     column classes.
      !>
      !>     Note that the values do not occupy a contiguous range of DAS
      !>     character words, since each page contains several addresses
      !>     reserved for bookkeeping information, and since there may be
      !>     unused space at the end of a data page.
      !>
      !>## Examples
      !>
      !>     See ZZEKAC07.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    Beta Version 1.0.0, 08-NOV-1995 (NJB)
      module subroutine zzekwpal ( ctx, handle, segdsc, nvals, lvals, p, base )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekdatpag
      use pepper_inc_ekpage
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( * )  !! Descriptor of segment that owns the array.
      integer(ip), intent(in) :: nvals  !! Number of values to write.
      logical, intent(in) :: lvals  ( * )  !! Logical values.
      integer(ip), intent(out) :: p  !! Number of first page containing array.
      integer(ip), intent(out) :: base  !! Base address of first page.
!
!     Local variables
!
      character(pgsizc) :: page

      integer(ip) :: from
      integer(ip) :: npage
      integer(ip) :: to

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Decide how many pages are required to hold the array, and
!     allocate that many new, contiguous pages.
!
      npage  =  ( nvals + cpsize - 1 ) / cpsize

      call zzekacps ( ctx, handle, segdsc, chr, npage, p, base )

!
!     Write the input data out to the target file a page at a time.
!
!     We'll use FROM to indicate the element of LVALS we're
!     considering and TO to indicate the element of PAGE to write
!     to.
!
      to      =  1
      page    =  ' '

      do from = 1, nvals

!
!        The Assignment.
!
         if ( lvals(from) ) then
            page( to : to ) =  ctrue
         else
            page( to : to ) =  cfalse
         end if

         to  =  to + 1

         if (  ( to > cpsize ) .or. ( from == nvals )  ) then
!
!           Either the current data page is full, or we've buffered
!           the last of the available data.  It's time to write out the
!           current page.
!
!           Write out the data page.
!
            call zzekpgwc ( ctx, handle, p, page  )

!
!           Set the link count.
!
            call zzekslnk ( ctx, handle, chr, p, to-1 )

!
!           Next page.
!
            p   =  p + 1
            to  =  1

         end if

      end do

      return
      end subroutine zzekwpal

      !> Append a new, empty record at the end of a specified E-kernel
      !> segment.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is a file handle of an EK open for write access.
      !>
      !>     SEGNO    is the number of the segment to which the record
      !>              is to be added.
      !>
      !>## Detailed Output
      !>
      !>     RECNO    is the number of the record appended by this
      !>              routine. RECNO is used to identify the record
      !>              when writing column entries to it.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, an error is signaled by a routine in the
      !>         call tree of this routine. The file will not be modified.
      !>
      !>     2)  If SEGNO is out of range, the error SPICE(INVALIDINDEX)
      !>         is signaled. The file will not be modified.
      !>
      !>     3)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error is signaled by a routine in the call tree of
      !>         this routine. The file may be corrupted.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading ek.req for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects: It appends a new, empty
      !>     record structure to an EK segment. The ordinal position of the
      !>     new record is one greater than the previous number of records in
      !>     in the segment.
      !>
      !>     After a new record has been appended to a segment by this routine,
      !>     the record must be populated with data using the EKACEx
      !>     routines.  EKs are valid only when all of their column entries
      !>     are initialized.
      !>
      !>     To insert a record into a segment at a specified ordinal position,
      !>     use the routine EKAPPR.
      !>
      !>     This routine cannot be used with the "fast write" suite of
      !>     routines. See the EK Required Reading ek.req for a discussion of
      !>     the fast writers.
      !>
      !>     When a record is inserted into an EK file that is not shadowed,
      !>     the status of the record starts out set to OLD. The status
      !>     does not change when data is added to the record.
      !>
      !>     If the target EK is shadowed, the new record will be given the
      !>     status NEW. Updating column values in the record does not change
      !>     its status. When changes are committed, the status is set to OLD.
      !>     If a rollback is performed before changes are committed, the
      !>     record is deleted. Closing the target file without committing
      !>     changes implies a rollback.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Append a record to a specified segment.
      !>
      !>        Suppose we have an E-kernel which contains records of orders
      !>        for data products. The E-kernel has a table called DATAORDERS
      !>        that consists of the set of columns listed below:
      !>
      !>           DATAORDERS
      !>
      !>              Column Name     Data Type
      !>              -----------     ---------
      !>              ORDER_ID        INTEGER
      !>              CUSTOMER_ID     INTEGER
      !>              LAST_NAME       CHARACTER*(*)
      !>              FIRST_NAME      CHARACTER*(*)
      !>              ORDER_DATE      TIME
      !>              COST            DOUBLE PRECISION
      !>
      !>        The order database also has a table of items that have been
      !>        ordered. The columns of this table are shown below:
      !>
      !>           DATAITEMS
      !>
      !>              Column Name     Data Type
      !>              -----------     ---------
      !>              ITEM_ID         INTEGER
      !>              ORDER_ID        INTEGER
      !>              ITEM_NAME       CHARACTER*(*)
      !>              DESCRIPTION     CHARACTER*(*)
      !>              PRICE           DOUBLE PRECISION
      !>
      !>        We'll suppose that the EK file contains two segments, the
      !>        first containing the DATAORDERS table and the second
      !>        containing the DATAITEMS table.
      !>
      !>        This examples creates such EK, with no records in either
      !>        table, and after re-opening the file, inserts a new record
      !>        into the DATAITEMS table.
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM EKAPPR_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Include the EK Column Name Size (CNAMSZ)
      !>C
      !>      INCLUDE 'ekcnamsz.inc'
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      CHARACTER*(*)         EKNAME
      !>      PARAMETER           ( EKNAME  = 'ekappr_ex1.bdb' )
      !>
      !>      INTEGER               DECLEN
      !>      PARAMETER           ( DECLEN = 200 )
      !>
      !>      INTEGER               DESCLN
      !>      PARAMETER           ( DESCLN = 80  )
      !>
      !>      INTEGER               NAMLEN
      !>      PARAMETER           ( NAMLEN = 40  )
      !>
      !>      INTEGER               NCOLS
      !>      PARAMETER           ( NCOLS  = 6   )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(DECLEN)    CDECLS ( NCOLS )
      !>      CHARACTER*(CNAMSZ)    CNAMES ( NCOLS )
      !>      CHARACTER*(DESCLN)    DESCRP
      !>      CHARACTER*(NAMLEN)    IFNAME
      !>      CHARACTER*(NAMLEN)    ITEMNM
      !>
      !>      DOUBLE PRECISION      PRICE
      !>
      !>      INTEGER               ESIZE
      !>      INTEGER               HANDLE
      !>      INTEGER               ITEMID
      !>      INTEGER               NRESVC
      !>      INTEGER               ORDID
      !>      INTEGER               RECNO
      !>      INTEGER               SEGNO
      !>
      !>      LOGICAL               ISNULL
      !>
      !>C
      !>C     Open a new EK file.  For simplicity, we will not
      !>C     reserve any space for the comment area, so the
      !>C     number of reserved comment characters is zero.
      !>C     The variable IFNAME is the internal file name.
      !>C
      !>      NRESVC  =  0
      !>      IFNAME  =  'Test EK/Created 01-JUN-2019'
      !>
      !>      CALL EKOPN ( EKNAME, IFNAME, NRESVC, HANDLE )
      !>
      !>C
      !>C     Set up the table and column names and declarations
      !>C     for the DATAORDERS segment.  We'll index all of
      !>C     the columns.  All columns are scalar, so we omit
      !>C     the size declaration.  Only the COST column may take
      !>C     null values.
      !>C
      !>      CNAMES(1) =  'ORDER_ID'
      !>      CDECLS(1) =  'DATATYPE = INTEGER, INDEXED = TRUE'
      !>
      !>      CNAMES(2) =  'CUSTOMER_ID'
      !>      CDECLS(2) =  'DATATYPE = INTEGER, INDEXED = TRUE'
      !>
      !>      CNAMES(3) =  'LAST_NAME'
      !>      CDECLS(3) =  'DATATYPE = CHARACTER*(*), ' //
      !>     .             'INDEXED  = TRUE'
      !>
      !>      CNAMES(4) =  'FIRST_NAME'
      !>      CDECLS(4) =  'DATATYPE = CHARACTER*(*), ' //
      !>     .             'INDEXED  = TRUE'
      !>
      !>      CNAMES(5) =  'ORDER_DATE'
      !>      CDECLS(5) =  'DATATYPE = TIME, INDEXED  = TRUE'
      !>
      !>      CNAMES(6) =  'COST'
      !>      CDECLS(6) =  'DATATYPE = DOUBLE PRECISION,' //
      !>     .             'INDEXED  = TRUE,'             //
      !>     .             'NULLS_OK = TRUE'
      !>
      !>C
      !>C     Start the first segment. Since we have no data for this
      !>C     segment, start the segment by just defining the new
      !>C     segment's schema.
      !>C
      !>      CALL EKBSEG ( HANDLE, 'DATAORDERS', NCOLS,
      !>     .              CNAMES, CDECLS,       SEGNO )
      !>
      !>C
      !>C     At this point, the second segment could be
      !>C     created by an analogous process.  In fact, the
      !>C     second segment could be created at any time; it is
      !>C     not necessary to populate the first segment with
      !>C     data before starting the second segment.
      !>C
      !>C     Set up the table and column names and declarations
      !>C     for the DATAITEMS segment.  We'll index all of
      !>C     the columns.  All columns are scalar, so we omit
      !>C     the size declaration.
      !>C
      !>      CNAMES(1) =  'ITEM_ID'
      !>      CDECLS(1) =  'DATATYPE = INTEGER, INDEXED = TRUE'
      !>
      !>      CNAMES(2) =  'ORDER_ID'
      !>      CDECLS(2) =  'DATATYPE = INTEGER, INDEXED = TRUE'
      !>
      !>      CNAMES(3) =  'ITEM_NAME'
      !>      CDECLS(3) =  'DATATYPE = CHARACTER*(*),' //
      !>     .             'INDEXED  = TRUE'
      !>
      !>      CNAMES(4) =  'DESCRIPTION'
      !>      CDECLS(4) =  'DATATYPE = CHARACTER*(*),' //
      !>     .             'INDEXED  = TRUE'
      !>
      !>      CNAMES(5) =  'PRICE'
      !>      CDECLS(5) =  'DATATYPE = DOUBLE PRECISION,' //
      !>     .             'INDEXED  = TRUE'
      !>
      !>C
      !>C     Start the new segment. Since we have no data for this
      !>C     segment, start the segment by just defining the new
      !>C     segment's schema.
      !>C
      !>      CALL EKBSEG ( HANDLE, 'DATAITEMS', 5,
      !>     .              CNAMES, CDECLS,      SEGNO )
      !>
      !>C
      !>C     End the file by a call to EKCLS.
      !>C
      !>      CALL EKCLS ( HANDLE )
      !>
      !>C
      !>C     Now, we want to insert a new record into the DATAITEMS
      !>C     table.
      !>C
      !>C     Open the database for write access.  This call is
      !>C     made when the file already exists.
      !>C
      !>      CALL EKOPW ( EKNAME, HANDLE )
      !>
      !>C
      !>C     Append a new, empty record to the DATAITEMS
      !>C     table. Recall that the DATAITEMS table
      !>C     is in segment number 2.  The call will return
      !>C     the number of the new, empty record.
      !>C
      !>      SEGNO = 2
      !>      CALL EKAPPR ( HANDLE, SEGNO, RECNO )
      !>
      !>C
      !>C     At this point, the new record is empty.  A valid EK
      !>C     cannot contain empty records.  We fill in the data
      !>C     here.  Data items are filled in one column at a time.
      !>C     The order in which the columns are filled in is not
      !>C     important.  We use the EKACEx (add column entry)
      !>C     routines to fill in column entries.  We'll assume
      !>C     that no entries are null.  All entries are scalar,
      !>C     so the entry size is 1.
      !>C
      !>      ISNULL =  .FALSE.
      !>      ESIZE  =  1
      !>
      !>C
      !>C     The following variables will contain the data for
      !>C     the new record.
      !>C
      !>      ORDID  =   10011
      !>      ITEMID =   531
      !>      ITEMNM =  'Sample item'
      !>      DESCRP =  'This sample item is used only in tests.'
      !>      PRICE  =   1345.678D0
      !>
      !>C
      !>C     Note that the names of the routines called
      !>C     correspond to the data types of the columns:  the
      !>C     last letter of the routine name is C, I, or D,
      !>C     depending on the data type.
      !>C
      !>      CALL EKACEI ( HANDLE, SEGNO,  RECNO, 'ORDER_ID',
      !>     .              ESIZE,  ORDID,  ISNULL               )
      !>
      !>      CALL EKACEI ( HANDLE, SEGNO,  RECNO, 'ITEM_ID',
      !>     .              ESIZE,  ITEMID, ISNULL               )
      !>
      !>      CALL EKACEC ( HANDLE, SEGNO,  RECNO, 'ITEM_NAME',
      !>     .              ESIZE,  ITEMNM, ISNULL               )
      !>
      !>      CALL EKACEC ( HANDLE, SEGNO,  RECNO, 'DESCRIPTION',
      !>     .              ESIZE,  DESCRP, ISNULL               )
      !>
      !>      CALL EKACED ( HANDLE, SEGNO,  RECNO, 'PRICE',
      !>     .              ESIZE,  PRICE,  ISNULL               )
      !>
      !>C
      !>C     Close the file to make the update permanent.
      !>C
      !>      CALL EKCLS ( HANDLE )
      !>
      !>      END
      !>```
      !>
      !>        When this program is executed, no output is presented on
      !>        screen. After run completion, a new EK file exists in the
      !>        output directory.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 02-JUL-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>        Added complete code example.
      !>
      !>-    SPICELIB Version 1.0.1, 09-JAN-2002 (NJB)
      !>
      !>        Documentation change: instances of the phrase "fast load"
      !>        were replaced with "fast write."
      !>
      !>-    SPICELIB Version 1.0.0, 19-DEC-1995 (NJB)
      module subroutine ekappr ( ctx, handle, segno, recno )
      use pepper_kinds, only: ip
      use pepper_inc_ekdatpag
      use pepper_inc_ekpage
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(in) :: segno  !! Segment number.
      integer(ip), intent(out) :: recno  !! Number of appended record.

      integer(ip) :: mbase
      integer(ip) :: mp
      integer(ip) :: nrec
      integer(ip) :: segdsc ( sdscsz )

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Before trying to actually write anything, do every error
!     check we can.
!
!     Is this file handle valid--is the file open for paged write
!     access?  Signal an error if not.
!
      call zzekpgch ( ctx, handle, 'WRITE' )

      if ( ctx%failed() ) return

!
!     Look up the integer metadata page and page base for the segment.
!     Given the base address, we can read the pertinent metadata in
!     one shot.
!
      call zzekmloc ( ctx, handle,  segno,  mp,  mbase  )

      if ( ctx%failed() ) return

      call dasrdi ( ctx, handle,  mbase+1,  mbase+sdscsz,  segdsc )

!
!     Obtain the number of records already present.
!
      nrec   =  segdsc ( nridx )

!
!     Insert the new record at the end of the segment.
!
      recno  =  nrec + 1

      call ekinsr ( ctx, handle, segno, recno )

      return
      end subroutine ekappr

      !> Initialize a new E-kernel segment to allow fast writing.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is the handle of an EK file open for write access. A new
      !>              segment is to be created in this file.
      !>
      !>     TABNAM   is the name of the EK table to which the current segment
      !>              belongs. All segments in the EK file designated by HANDLE
      !>              must have identical column attributes. TABNAM must not
      !>              exceed TNAMSZ (64) characters in length. Case is not
      !>              significant. Table names must start with a letter and
      !>              contain only characters from the set {A-Z,a-z,0-9,$,_}.
      !>
      !>     NCOLS    is the number of columns in a new segment.
      !>
      !>     NROWS    is the number of rows in a new segment. Each column to be
      !>              added to the segment must contain the number of entries
      !>              indicated by NROWS.
      !>
      !>     CNAMES,
      !>     DECLS    are, respectively, an array of column names and their
      !>              corresponding declarations: the Ith element of CNAMES and
      !>              the Ith element of DECLS apply to the Ith column in the
      !>              segment.
      !>
      !>              Column names must not exceed CNAMSZ (32) characters in
      !>              length. Case is not significant. Column names must start
      !>              with a letter and contain only characters from the set
      !>              {A-Z,a-z,0-9,$,_}.
      !>
      !>              The declarations are strings that contain "keyword=value"
      !>              assignments that define the attributes of the columns to
      !>              which they apply. The column attributes that are defined
      !>              by a column declaration are:
      !>
      !>                 DATATYPE
      !>                 SIZE
      !>                 <is the column indexed?>
      !>                 <does the column allow null values?>
      !>
      !>              The form of a declaration is
      !>
      !>                 'DATATYPE  = <type>,
      !>                  SIZE      = <size>,
      !>                  INDEXED   = <boolean>,
      !>                  NULLS_OK  = <boolean>'
      !>
      !>              For example, an indexed, scalar, integer column that
      !>              allows null values would have the declaration
      !>
      !>                 'DATATYPE  = INTEGER,
      !>                  SIZE      = 1,
      !>                  INDEXED   = TRUE,
      !>                  NULLS_OK  = TRUE'
      !>
      !>              Commas are required to separate the assignments within
      !>              declarations; white space is optional; case is not
      !>              significant.
      !>
      !>              The order in which the attribute keywords are listed in
      !>              declaration is not significant.
      !>
      !>              Every column in a segment must be declared.
      !>
      !>              Each column entry is effectively an array, each element
      !>              of which has the declared data type. The SIZE keyword
      !>              indicates how many elements are in each entry of the
      !>              column in whose declaration the keyword appears. Note
      !>              that only scalar-valued columns (those for which SIZE =
      !>              1) may be referenced in query constraints. A size
      !>              assignment has the syntax
      !>
      !>                 'SIZE = <integer>'
      !>
      !>              or
      !>                 'SIZE = VARIABLE'
      !>
      !>              The size value defaults to 1 if omitted.
      !>
      !>              The DATATYPE keyword defines the data type of column
      !>              entries. The DATATYPE assignment syntax has any of the
      !>              forms
      !>
      !>                 'DATATYPE = CHARACTER*(<length>)'
      !>                 'DATATYPE = CHARACTER*(*)'
      !>                 'DATATYPE = DOUBLE PRECISION'
      !>                 'DATATYPE = INTEGER'
      !>                 'DATATYPE = TIME'
      !>
      !>              As the datatype declaration syntax suggests, character
      !>              strings may have fixed or variable length.
      !>              Variable-length strings are allowed only in columns of
      !>              size 1.
      !>
      !>              Optionally, scalar-valued columns may be indexed. To
      !>              create an index for a column, use the assignment
      !>
      !>                 'INDEXED = TRUE'
      !>
      !>              By default, columns are not indexed.
      !>
      !>              Optionally, any column can allow null values. To indicate
      !>              that a column may allow null values, use the assignment
      !>
      !>                 'NULLS_OK = TRUE'
      !>
      !>              in the column declaration. By default, null values are
      !>              not allowed in column entries.
      !>
      !>## Detailed Output
      !>
      !>     SEGNO    is the number of the segment created by this routine.
      !>              Segment numbers are used as unique identifiers by other
      !>              EK access routines.
      !>
      !>     RCPTRS   is an array of record pointers for the input segment.
      !>              This array must not be modified by the caller.
      !>
      !>              The array RCPTRS must be passed as an input to each
      !>              column addition routine called while writing the
      !>              specified segment.
      !>
      !>              RCPTRS must be declared with dimension NROWS.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     2)  If TABNAM is more than TNAMSZ characters long, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>     3)  If TABNAM contains any nonprintable characters, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>     4)  If NCOLS is non-positive or greater than the maximum allowed
      !>         number MXCLSG, an error is signaled by a routine in the call
      !>         tree of this routine.
      !>
      !>     5)  If NROWS is non-positive, the error SPICE(INVALIDCOUNT)
      !>         is signaled.
      !>
      !>     6)  If any column name exceeds CNAMSZ characters in length, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     7)  If any column name contains non-printable characters, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>     8)  If a declaration cannot be understood by this routine, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     9)  If an non-positive string length or element size is specified,
      !>         an error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     10) If an I/O error occurs while reading or writing the indicated
      !>         file, the error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading ek.req for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine prepares an EK for the creation of a new segment via
      !>     the fast column writer routines. After this routine is called,
      !>     the columns of the segment are filled in by calls to the fast
      !>     column writer routines of the appropriate data types. The fast
      !>     column writer routines are:
      !>
      !>        EKACLC {EK, add column, character}
      !>        EKACLD {EK, add column, double precision}
      !>        EKACLI {EK, add column, integer}
      !>
      !>     When all of the columns have been added, the write operation is
      !>     completed by a call to EKFFLD {EK, finish fast write}.
      !>
      !>     The segment is not valid until EKFFLD has been called.
      !>
      !>     The EK system supports only one fast write at a time. It is
      !>     not possible use the fast write routines to simultaneously write
      !>     multiple segments, either in the same EK file or in different
      !>     files.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Suppose we want to create an Sequence Component E-kernel
      !>        named 'ekifld_ex1.bes' which contains records of orders for
      !>        data products. The E-kernel has a table called DATAORDERS that
      !>        consists of the set of columns listed below:
      !>
      !>           DATAORDERS
      !>
      !>              Column Name     Data Type
      !>              -----------     ---------
      !>              ORDER_ID        INTEGER
      !>              CUSTOMER_ID     INTEGER
      !>              LAST_NAME       CHARACTER*(*)
      !>              FIRST_NAME      CHARACTER*(*)
      !>              ORDER_DATE      TIME
      !>              COST            DOUBLE PRECISION
      !>
      !>        The order database also has a table of items that have been
      !>        ordered. The columns of this table are shown below:
      !>
      !>           DATAITEMS
      !>
      !>              Column Name     Data Type
      !>              -----------     ---------
      !>              ITEM_ID         INTEGER
      !>              ORDER_ID        INTEGER
      !>              ITEM_NAME       CHARACTER*(*)
      !>              DESCRIPTION     CHARACTER*(*)
      !>              PRICE           DOUBLE PRECISION
      !>
      !>        The file "ekifld_ex1.bdb" will contain two segments, the first
      !>        containing the DATAORDERS table and the second containing the
      !>        DATAITEMS table.
      !>
      !>        This example demonstrates how to open a new EK file and create
      !>        the first of the segments described above.
      !>
      !>        Use the LSK kernel below to load the leap seconds and time
      !>        constants required for the conversions.
      !>
      !>           naif0012.tls
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM EKIFLD_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Include the EK Column Name Size (CNAMSZ)
      !>C
      !>      INCLUDE 'ekcnamsz.inc'
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      CHARACTER*(*)         LSK
      !>      PARAMETER           ( LSK    = 'naif0012.tls' )
      !>
      !>      CHARACTER*(*)         TABLE
      !>      PARAMETER           ( TABLE  = 'DATAORDERS'   )
      !>
      !>      INTEGER               DECLEN
      !>      PARAMETER           ( DECLEN = 200 )
      !>
      !>      INTEGER               FNMLEN
      !>      PARAMETER           ( FNMLEN = 50  )
      !>
      !>      INTEGER               LNMLEN
      !>      PARAMETER           ( LNMLEN = 50  )
      !>
      !>      INTEGER               NAMLEN
      !>      PARAMETER           ( NAMLEN = 40  )
      !>
      !>      INTEGER               NCOLS
      !>      PARAMETER           ( NCOLS  = 6   )
      !>
      !>      INTEGER               NROWS
      !>      PARAMETER           ( NROWS  = 9   )
      !>
      !>      INTEGER               UTCLEN
      !>      PARAMETER           ( UTCLEN = 30  )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(DECLEN)    CDECLS ( NCOLS )
      !>      CHARACTER*(32)        CNAMES ( NCOLS )
      !>      CHARACTER*(FNMLEN)    FNAMES ( NROWS )
      !>      CHARACTER*(LNMLEN)    LNAMES ( NROWS )
      !>      CHARACTER*(NAMLEN)    IFNAME
      !>      CHARACTER*(UTCLEN)    ODATE
      !>
      !>      DOUBLE PRECISION      COSTS  ( NROWS )
      !>      DOUBLE PRECISION      ETS    ( NROWS )
      !>
      !>      INTEGER               CSTIDS ( NROWS )
      !>      INTEGER               HANDLE
      !>      INTEGER               I
      !>      INTEGER               NRESVC
      !>      INTEGER               ORDIDS ( NROWS )
      !>      INTEGER               RCPTRS ( NROWS )
      !>      INTEGER               SEGNO
      !>      INTEGER               SIZES  ( NROWS )
      !>      INTEGER               WKINDX ( NROWS )
      !>
      !>      LOGICAL               NLFLGS ( NROWS )
      !>
      !>C
      !>C     Load a leapseconds kernel for UTC/ET conversion.
      !>C
      !>      CALL FURNSH ( 'naif0012.tls' )
      !>
      !>C
      !>C     Open a new EK file.  For simplicity, we will not
      !>C     reserve any space for the comment area, so the
      !>C     number of reserved comment characters is zero.
      !>C     The variable IFNAME is the internal file name.
      !>C
      !>      NRESVC  =  0
      !>      IFNAME  =  'Test EK/Created 20-SEP-1995'
      !>
      !>      CALL EKOPN ( 'ekifld_ex1.bes', IFNAME, NRESVC, HANDLE )
      !>
      !>C
      !>C     Set up the table and column names and declarations
      !>C     for the DATAORDERS segment.  We'll index all of
      !>C     the columns.  All columns are scalar, so we omit
      !>C     the size declaration.  Only the COST column may take
      !>C     null values.
      !>C
      !>      CNAMES(1) =  'ORDER_ID'
      !>      CDECLS(1) =  'DATATYPE = INTEGER, INDEXED = TRUE'
      !>
      !>      CNAMES(2) =  'CUSTOMER_ID'
      !>      CDECLS(2) =  'DATATYPE = INTEGER, INDEXED = TRUE'
      !>
      !>      CNAMES(3) =  'LAST_NAME'
      !>      CDECLS(3) =  'DATATYPE = CHARACTER*(*),' //
      !>     .             'INDEXED  = TRUE'
      !>
      !>      CNAMES(4) =  'FIRST_NAME'
      !>      CDECLS(4) =  'DATATYPE = CHARACTER*(*),' //
      !>     .             'INDEXED  = TRUE'
      !>
      !>      CNAMES(5) =  'ORDER_DATE'
      !>      CDECLS(5) =  'DATATYPE = TIME, INDEXED  = TRUE'
      !>
      !>      CNAMES(6) =  'COST'
      !>      CDECLS(6) =  'DATATYPE = DOUBLE PRECISION,' //
      !>     .             'INDEXED  = TRUE,'             //
      !>     .             'NULLS_OK = TRUE'
      !>
      !>C
      !>C     Start the segment.  We presume the number of  rows
      !>C     of data is known in advance.
      !>C
      !>      CALL EKIFLD ( HANDLE,  TABLE,  NCOLS, NROWS,
      !>     .              CNAMES,  CDECLS, SEGNO, RCPTRS )
      !>
      !>C
      !>C     At this point, arrays containing data for the
      !>C     segment's columns may be filled in.  The names
      !>C     of the data arrays are shown below.
      !>C
      !>C        Column           Data array
      !>C
      !>C        'ORDER_ID'       ORDIDS
      !>C        'CUSTOMER_ID'    CSTIDS
      !>C        'LAST_NAME'      LNAMES
      !>C        'FIRST_NAME'     FNAMES
      !>C        'ORDER_DATE'     ETS
      !>C        'COST'           COSTS
      !>C
      !>      DO I = 1, NROWS
      !>
      !>         ORDIDS(I) = I
      !>         CSTIDS(I) = I * 100
      !>         COSTS(I)  = I * 100.D0
      !>
      !>         CALL REPMI ( 'Order # Customer first name',
      !>     .                '#', I, FNAMES(I)             )
      !>         CALL REPMI ( 'Order # Customer last name',
      !>     .                '#', I, LNAMES(I)             )
      !>         CALL REPMI ( '1998 Mar #', '#', I, ODATE   )
      !>
      !>         CALL UTC2ET ( ODATE,  ETS(I) )
      !>
      !>         NLFLGS(I) = .FALSE.
      !>
      !>      END DO
      !>
      !>      NLFLGS(2) = .TRUE.
      !>
      !>C
      !>C     The SIZES array shown below is ignored for scalar
      !>C     and fixed-size array columns, so we need not
      !>C     initialize it.  For variable-size arrays, the
      !>C     Ith element of the SIZES array must contain the size
      !>C     of the Ith column entry in the column being written.
      !>C     Normally, the SIZES array would be reset for each
      !>C     variable-size column.
      !>C
      !>C     The NLFLGS array indicates which entries are null.
      !>C     It is ignored for columns that don't allow null
      !>C     values.  In this case, only the COST column allows
      !>C     nulls.
      !>C
      !>C     Add the columns of data to the segment.  All of the
      !>C     data for each column is written in one shot.
      !>C
      !>      CALL EKACLI ( HANDLE, SEGNO,  'ORDER_ID',
      !>     .              ORDIDS, SIZES,  NLFLGS,  RCPTRS, WKINDX )
      !>
      !>      CALL EKACLI ( HANDLE, SEGNO,  'CUSTOMER_ID',
      !>     .              CSTIDS, SIZES,  NLFLGS,  RCPTRS, WKINDX )
      !>
      !>      CALL EKACLC ( HANDLE, SEGNO,  'LAST_NAME',
      !>     .              LNAMES, SIZES,  NLFLGS,  RCPTRS, WKINDX )
      !>
      !>      CALL EKACLC ( HANDLE, SEGNO,  'FIRST_NAME',
      !>     .              FNAMES, SIZES,  NLFLGS,  RCPTRS, WKINDX )
      !>
      !>      CALL EKACLD ( HANDLE, SEGNO,  'ORDER_DATE',
      !>     .              ETS,    SIZES,  NLFLGS,  RCPTRS, WKINDX )
      !>
      !>      CALL EKACLD ( HANDLE, SEGNO,  'COST',
      !>     .              COSTS,  SIZES,  NLFLGS,  RCPTRS, WKINDX )
      !>
      !>C
      !>C     Complete the segment.  The RCPTRS array is that
      !>C     returned by EKIFLD.
      !>C
      !>      CALL EKFFLD ( HANDLE, SEGNO, RCPTRS )
      !>
      !>C
      !>C     At this point, the second segment could be
      !>C     created by an analogous process.  In fact, the
      !>C     second segment could be created at any time; it is
      !>C     not necessary to populate the first segment with
      !>C     data before starting the second segment.
      !>C
      !>C     The file must be closed by a call to EKCLS.
      !>C
      !>      CALL EKCLS ( HANDLE )
      !>
      !>      END
      !>```
      !>
      !>        When this program is executed, no output is presented on
      !>        screen. After run completion, a new EK file exists in the
      !>        output directory.
      !>
      !>## Restrictions
      !>
      !>     1)  Only one segment can be created at a time using the fast
      !>         write routines.
      !>
      !>     2)  No other EK operation may interrupt a fast write. For
      !>         example, it is not valid to issue a query while a fast write
      !>         is in progress.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.2.0, 17-JUN-2021 (JDR) (BVS)
      !>
      !>        Added missing IMPLICIT NONE.
      !>
      !>        Edited the header to comply with NAIF standard. and
      !>        created complete code example from existing fragment.
      !>
      !>        Corrected entry #4 in $Exceptions: the same error is signaled
      !>        in the requested number of columns exceeds the maximum allowed
      !>        per segment.
      !>
      !>-    SPICELIB Version 1.1.1, 10-JAN-2002 (NJB)
      !>
      !>        Documentation change: instances of the phrase "fast load"
      !>        were replaced with "fast write." Corrected value of table
      !>        name size in header comment.
      !>
      !>-    SPICELIB Version 1.1.0, 18-JUN-1999 (WLT)
      !>
      !>        Balanced CHKIN/CHKOUT calls.
      !>
      !>-    SPICELIB Version 1.0.0, 25-OCT-1995 (NJB)
      module subroutine ekifld ( ctx, handle, tabnam, ncols, nrows, cnames, decls, segno, rcptrs )
      use pepper_kinds, only: ip
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      character(*), intent(in) :: tabnam  !! Table name.
      integer(ip), intent(in) :: ncols  !! Number of columns in the segment.
      integer(ip), intent(in) :: nrows  !! Number of rows in the segment.
      character(*), intent(in) :: cnames ( * )  !! Names of columns.
      character(*), intent(in) :: decls  ( * )  !! Declarations of columns.
      integer(ip), intent(out) :: segno  !! Segment number.
      integer(ip), intent(out) :: rcptrs ( * )  !! Array of record pointers.

      integer(ip) :: mbase
      integer(ip) :: p
      integer(ip) :: segdsc ( sdscsz )
      integer(ip) :: stype

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Check out NROWS.
!
      if ( nrows < 1 ) then

         call ctx%setmsg ( 'Number of rows must be > 0, was #. ' )
         call ctx%errint ( '#',  nrows                           )
         call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                 )
         return

      end if

!
!     Create the segment's metadata.
!
      call ekbseg ( ctx, handle, tabnam, ncols, cnames, decls, segno )

      if ( ctx%failed() ) return

!
!     Fill the number of rows into the (file's) segment descriptor.
!
      call zzekmloc ( ctx,  handle,  segno,        p,            mbase  )
      call dasudi ( ctx, handle, mbase+nridx, mbase+nridx, [ nrows ] )

!
!     Read in the segment descriptor, and get the segment's type.
!
      call zzeksdsc ( ctx,  handle,  segno,  segdsc )

      stype  =  segdsc(ektidx)

!
!     Complete the fast write preparations appropriate to the segment's
!     type.
!
      if ( stype == 1 ) then

         call zzekif01 ( ctx, handle, segno, rcptrs )

      else if ( stype == 2 ) then

         call zzekif02 ( ctx, handle, segno )

      else

         call ctx%setmsg ( 'Segment type # is not currently supported.' )
         call ctx%errint ( '#', stype                                   )
         call ctx%sigerr ( 'SPICE(BUG)'                                 )
         return

      end if

      return
      end subroutine ekifld

      !> Read data from a character column in a specified EK record.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is an EK file handle. The file may be open for read or
      !>              write access.
      !>
      !>     SEGNO    is the index of the segment from which data is to be
      !>              read.
      !>
      !>     RECNO    is the index of the record from which data is to be read.
      !>              This record number is relative to the start of the
      !>              segment indicated by SEGNO; the first record in the
      !>              segment has index 1.
      !>
      !>     COLUMN   is the name of the column from which data is to be read.
      !>
      !>## Detailed Output
      !>
      !>     NVALS,
      !>     CVALS    are, respectively, the number of values found in the
      !>              specified column entry and the set of values themselves.
      !>              The array CVALS must have sufficient string length to
      !>              accommodate the longest string in the returned column
      !>              entry.
      !>
      !>              For columns having fixed-size entries, when a column
      !>              entry is null, NVALS is still set to the column entry
      !>              size. For columns having variable- size entries, NVALS is
      !>              set to 1 for null entries.
      !>
      !>     ISNULL   is a logical flag indicating whether the returned column
      !>              entry is null.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     2)  If SEGNO is out of range, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     3)  If RECNO is out of range, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     4)  If COLUMN is not the name of a declared column, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>     5)  If COLUMN specifies a column of whose data type is not
      !>         character, the error SPICE(WRONGDATATYPE) is signaled.
      !>
      !>     6)  If COLUMN specifies a column of whose class is not
      !>         a character class known to this routine, the error
      !>         SPICE(NOCLASS) is signaled.
      !>
      !>     7)  If an attempt is made to read an uninitialized column entry,
      !>         an error is signaled by a routine in the call tree of this
      !>         routine. A null entry is considered to be initialized, but
      !>         entries do not contain null values by default.
      !>
      !>     8)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>     9)  If any element of the column entry would be truncated when
      !>         assigned to an element of CVALS, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading ek.req for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine is a utility that allows an EK file to be read
      !>     directly without using the high-level query interface.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) The following program demonstrates how to create a new EK and
      !>        add data to a character column in a given record within the
      !>        file, and how to read the data from it.
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM EKRCEC_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Include the EK Column Name Size (CNAMSZ)
      !>C
      !>      INCLUDE 'ekcnamsz.inc'
      !>
      !>C
      !>C     Local constants.
      !>C
      !>      CHARACTER*(*)         EKNAME
      !>      PARAMETER           ( EKNAME = 'ekrcec_ex1.bdb' )
      !>
      !>      CHARACTER*(*)         IFNAME
      !>      PARAMETER           ( IFNAME = 'Test EK'  )
      !>
      !>      CHARACTER*(*)         TABLE
      !>      PARAMETER           ( TABLE  = 'CHR_DATA' )
      !>
      !>      INTEGER               CVLEN
      !>      PARAMETER           ( CVLEN  = 9  )
      !>
      !>      INTEGER               DECLEN
      !>      PARAMETER           ( DECLEN = 200 )
      !>
      !>      INTEGER               MAXVAL
      !>      PARAMETER           ( MAXVAL = 4  )
      !>
      !>      INTEGER               NCOLS
      !>      PARAMETER           ( NCOLS  = 2  )
      !>
      !>      INTEGER               NROWS
      !>      PARAMETER           ( NROWS  = 6  )
      !>
      !>      INTEGER               NRESVC
      !>      PARAMETER           ( NRESVC = 0  )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(DECLEN)    CDECLS ( NCOLS  )
      !>      CHARACTER*(CNAMSZ)    CNAMES ( NCOLS  )
      !>      CHARACTER*(CVLEN)     CVALS  ( MAXVAL )
      !>
      !>      INTEGER               HANDLE
      !>      INTEGER               I
      !>      INTEGER               J
      !>      INTEGER               NVALS
      !>      INTEGER               RECNO
      !>      INTEGER               SEGNO
      !>
      !>      LOGICAL               ISNULL
      !>
      !>C
      !>C     Open a new EK file.  For simplicity, we won't
      !>C     reserve space for the comment area, so the
      !>C     number of reserved comment characters is zero.
      !>C     The constant IFNAME is the internal file name.
      !>C
      !>      CALL EKOPN ( EKNAME, IFNAME, NRESVC, HANDLE )
      !>
      !>C
      !>C     Set up the table and column names and declarations
      !>C     for the CHR_DATA segment.  We'll index all of
      !>C     the columns.
      !>C
      !>      CNAMES(1) =  'CHR_COL_1'
      !>      CDECLS(1) =  'DATATYPE = CHARACTER*(*), '
      !>     .       //    'INDEXED = TRUE, NULLS_OK = TRUE'
      !>
      !>      CNAMES(2) =  'CHR_COL_2'
      !>      CDECLS(2) =  'DATATYPE = CHARACTER*(9), '
      !>     .       //    'SIZE = VARIABLE, NULLS_OK = TRUE'
      !>
      !>C
      !>C     Start the segment.
      !>C
      !>      CALL EKBSEG ( HANDLE, TABLE,  NCOLS,
      !>     .              CNAMES, CDECLS, SEGNO )
      !>
      !>      DO I = 0, NROWS-1
      !>
      !>         CALL EKAPPR ( HANDLE, SEGNO, RECNO )
      !>
      !>         ISNULL = ( I .EQ. 1 )
      !>
      !>         CALL INTSTR ( I, CVALS(1) )
      !>         CALL EKACEC ( HANDLE, SEGNO, RECNO, CNAMES(1),
      !>     .                 1,      CVALS, ISNULL           )
      !>
      !>C
      !>C        Array-valued columns follow.
      !>C
      !>         CALL INTSTR ( 10*I,     CVALS(1) )
      !>         CALL INTSTR ( 10*I + 1, CVALS(2) )
      !>         CALL INTSTR ( 10*I + 2, CVALS(3) )
      !>         CALL INTSTR ( 10*I + 3, CVALS(4) )
      !>         CALL EKACEC ( HANDLE, SEGNO, RECNO, CNAMES(2),
      !>     .                 4,      CVALS, ISNULL           )
      !>
      !>      END DO
      !>
      !>C
      !>C     End the file.
      !>C
      !>      CALL EKCLS ( HANDLE )
      !>
      !>C
      !>C     Open the created file. Show the values added.
      !>C
      !>      CALL EKOPR ( EKNAME, HANDLE )
      !>
      !>      DO I = 1, NROWS
      !>
      !>         CALL EKRCEC ( HANDLE, SEGNO, I,     CNAMES(1),
      !>     .                 NVALS,  CVALS, ISNULL           )
      !>
      !>         IF ( .NOT. ISNULL ) THEN
      !>
      !>            WRITE(*,*) 'Data from column: ', CNAMES(1)
      !>            WRITE(*,*) '   record number: ', I
      !>            WRITE(*,*) '   values       : ',
      !>     .                                ( CVALS(J), J=1,NVALS )
      !>            WRITE(*,*) ' '
      !>
      !>         ELSE
      !>
      !>            WRITE(*,*) 'Record ', I, 'flag is NULL.'
      !>            WRITE(*,*) ' '
      !>
      !>         END IF
      !>
      !>C
      !>C        Array-valued columns follow.
      !>C
      !>         CALL EKRCEC ( HANDLE, SEGNO, I,     CNAMES(2),
      !>     .                 NVALS,  CVALS, ISNULL           )
      !>
      !>         IF ( .NOT. ISNULL ) THEN
      !>
      !>            WRITE(*,*) 'Data from column: ', CNAMES(2)
      !>            WRITE(*,*) '   record number: ', I
      !>            WRITE(*,*) '   values       : ',
      !>     .                                ( CVALS(J), J=1,NVALS )
      !>            WRITE(*,*) ' '
      !>
      !>         END IF
      !>
      !>      END DO
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Data from column: CHR_COL_1
      !>            record number:            1
      !>            values       : 0
      !>
      !>         Data from column: CHR_COL_2
      !>            record number:            1
      !>            values       : 0        1        2        3
      !>
      !>         Record            2 flag is NULL.
      !>
      !>         Data from column: CHR_COL_1
      !>            record number:            3
      !>            values       : 2
      !>
      !>         Data from column: CHR_COL_2
      !>            record number:            3
      !>            values       : 20       21       22       23
      !>
      !>         Data from column: CHR_COL_1
      !>            record number:            4
      !>            values       : 3
      !>
      !>         Data from column: CHR_COL_2
      !>            record number:            4
      !>            values       : 30       31       32       33
      !>
      !>         Data from column: CHR_COL_1
      !>            record number:            5
      !>            values       : 4
      !>
      !>         Data from column: CHR_COL_2
      !>            record number:            5
      !>            values       : 40       41       42       43
      !>
      !>         Data from column: CHR_COL_1
      !>            record number:            6
      !>            values       : 5
      !>
      !>         Data from column: CHR_COL_2
      !>            record number:            6
      !>            values       : 50       51       52       53
      !>
      !>        Note that the second record does not appear due to setting the
      !>        ISNULL flag to true for that record.
      !>
      !>        After run completion, a new EK exists in the output directory.
      !>
      !>## Restrictions
      !>
      !>     1)  EK files open for write access are not necessarily readable.
      !>         In particular, a column entry can be read only if it has been
      !>         initialized. The caller is responsible for determining
      !>         when it is safe to read from files open for write access.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.4.0, 06-JUL-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>        Added complete code example.
      !>
      !>-    SPICELIB Version 1.3.0, 06-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>-    SPICELIB Version 1.2.0, 20-JUN-1999 (WLT)
      !>
      !>        Removed unbalanced call to CHKOUT.
      !>
      !>-    SPICELIB Version 1.1.0, 28-JUL-1997 (NJB)
      !>
      !>        Bug fix: Record number, not record pointer, is now supplied
      !>        to look up data in the class 9 case. Miscellaneous header
      !>        changes were made as well. Check for string truncation on
      !>        output has been added.
      !>
      !>-    SPICELIB Version 1.0.0, 26-SEP-1995 (NJB)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.1.0, 28-JUL-1997 (NJB)
      !>
      !>        Bug fix: Record number, not record pointer, is now supplied
      !>        to look up data in the class 9 case. For class 9 columns,
      !>        column entry locations are calculated directly from record
      !>        numbers, no indirection is used.
      !>
      !>        Miscellaneous header changes were made as well.
      !>
      !>        The routines
      !>
      !>           ZZEKRD03
      !>           ZZEKRD06
      !>           ZZEKRD09
      !>
      !>        now check for string truncation on output and signal errors
      !>        if truncation occurs.
      module subroutine ekrcec ( ctx, handle, segno, recno, column, nvals, cvals, isnull )
      use pepper_kinds, only: ip
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(inout) :: segno  !! Index of segment containing record. (PEPPER: changed by the routine, an input in SPICELIB's table)
      integer(ip), intent(in) :: recno  !! Record from which data is to be read.
      character(*), intent(in) :: column  !! Column name.
      integer(ip), intent(out) :: nvals  !! Number of values in column entry.
      character(*), intent(out) :: cvals  ( * )  !! Character values in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.

      integer(ip) :: coldsc ( cdscsz )
      integer(ip) :: class
      integer(ip) :: cvlen
      integer(ip) :: dtype
      integer(ip) :: recptr
      integer(ip) :: segdsc ( sdscsz )

      logical :: found

!
!     First step:  find the descriptor for the named segment.  Using
!     this descriptor, get the column descriptor.
!
      call zzeksdsc ( ctx, handle, segno,  segdsc          )
      call zzekcdsc ( ctx, handle, segdsc, column, coldsc  )

      if ( ctx%failed() ) return

!
!     This column had better be of character type.
!
      dtype  =  coldsc(typidx)

      if ( dtype /= chr ) then

         call ctx%setmsg ( 'Column # is of type #; EKRCEC only works '    // &
                       'with character columns.  RECNO = #; SEGNO = ' // &
                       '#; EK = #.'                                    )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  dtype                                     )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(WRONGDATATYPE)'                          )
         return

      end if

!
!     Now it's time to read data from the file.  Call the low-level
!     reader appropriate to the column's class.
!
      class  =  coldsc ( clsidx )

      if ( class == 3 ) then
!
!        Look up the record pointer for the target record.
!
         call zzektrdp ( ctx,  handle,  segdsc(rtidx),  recno, recptr )

         call zzekrd03 ( ctx,  handle,  segdsc, coldsc, &
                          recptr,  cvlen,  cvals(1),  isnull  )
         nvals  =  1

      else if ( class == 6 ) then

         call zzektrdp ( ctx, handle, segdsc(rtidx), recno, recptr )

         nvals  =  zzekesiz ( ctx, handle, segdsc, coldsc, recptr )

         call zzekrd06 ( ctx,  handle,  segdsc,  coldsc,  recptr, &
                          1,       nvals,   cvals,   isnull,  found  )

      else if ( class == 9 ) then
!
!        Records in class 9 columns are identified by a record number
!        rather than a pointer.
!
         call zzekrd09 ( ctx,  handle,  segdsc, coldsc, &
                          recno,   cvlen,  cvals(1),  isnull  )
         nvals  =  1

      else

!
!        This is an unsupported character column class.
!
         segno  =  segdsc ( snoidx )

         call ctx%setmsg ( 'Class # from input column descriptor is not ' // &
                       'a supported character class.  COLUMN = #; '   // &
                       'RECNO = #; SEGNO = #; EK = #.'                 )
         call ctx%errint ( '#',  class                                     )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

      return
      end subroutine ekrcec

      !> Read data from a double precision column in a specified EK
      !> record.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is an EK file handle. The file may be open for read or
      !>              write access.
      !>
      !>     SEGNO    is the index of the segment from which data is to be
      !>              read.
      !>
      !>     RECNO    is the index of the record from which data is to be read.
      !>              This record number is relative to the start of the
      !>              segment indicated by SEGNO; the first record in the
      !>              segment has index 1.
      !>
      !>     COLUMN   is the name of the column from which data is to be read.
      !>
      !>## Detailed Output
      !>
      !>     NVALS,
      !>     DVALS    are, respectively, the number of values found in the
      !>              specified column entry and the set of values themselves.
      !>
      !>              For columns having fixed-size entries, when column entry
      !>              is null, NVALS is still set to the column entry size. For
      !>              columns having variable- size entries, NVALS is set to 1
      !>              for null entries.
      !>
      !>     ISNULL   is a logical flag indicating whether the returned column
      !>              entry is null.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     2)  If SEGNO is out of range, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     3)  If RECNO is out of range, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     4)  If COLUMN is not the name of a declared column, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>     5)  If COLUMN specifies a column of whose data type is not
      !>         double precision, the error SPICE(WRONGDATATYPE) is signaled.
      !>
      !>     6)  If COLUMN specifies a column of whose class is not
      !>         a double precision class known to this routine, the error
      !>         SPICE(NOCLASS) is signaled.
      !>
      !>     7)  If an attempt is made to read an uninitialized column entry,
      !>         an error is signaled by a routine in the call tree of this
      !>         routine. A null entry is considered to be initialized, but
      !>         entries do not contain null values by default.
      !>
      !>     8)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading ek.req for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine is a utility that allows an EK file to be read
      !>     directly without using the high-level query interface.
      !>
      !>## Examples
      !>
      !>     1)  Read the value in the third record of the column DCOL in
      !>         the fifth segment of an EK file designated by HANDLE.
      !>
      !>            CALL EKRCED ( HANDLE, 5, 3, 'DCOL', N, DVAL, ISNULL )
      !>
      !>## Restrictions
      !>
      !>     1)  EK files open for write access are not necessarily readable.
      !>         In particular, a column entry can be read only if it has been
      !>         initialized. The caller is responsible for determining
      !>         when it is safe to read from files open for write access.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.3.1, 26-MAY-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.3.0, 06-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>-    SPICELIB Version 1.2.0, 20-JUN-1999 (WLT)
      !>
      !>        Removed unbalanced call to CHKOUT.
      !>
      !>-    SPICELIB Version 1.1.0, 28-JUL-1997 (NJB)
      !>
      !>        Bug fix: Record number, not record pointer, is now supplied
      !>        to look up data in the class 8 case. Miscellaneous header
      !>        changes were made as well.
      !>
      !>-    SPICELIB Version 1.0.0, 06-NOV-1995 (NJB)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.1.0, 28-JUL-1997 (NJB)
      !>
      !>        Bug fix: Record number, not record pointer, is now supplied
      !>        to look up data in the class 8 case. For class 8 columns,
      !>        column entry locations are calculated directly from record
      !>        numbers; no indirection is used.
      !>
      !>        Miscellaneous header changes were made as well.
      module subroutine ekrced ( ctx, handle, segno, recno, column, nvals, dvals, isnull )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(inout) :: segno  !! Index of segment containing record. (PEPPER: changed by the routine, an input in SPICELIB's table)
      integer(ip), intent(in) :: recno  !! Record from which data is to be read.
      character(*), intent(in) :: column  !! Column name.
      integer(ip), intent(out) :: nvals  !! Number of values in column entry.
      real(wp), intent(out) :: dvals  ( * )  !! D.p. values in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.

      integer(ip) :: coldsc ( cdscsz )
      integer(ip) :: class
      integer(ip) :: dtype
      integer(ip) :: recptr
      integer(ip) :: segdsc ( sdscsz )

      logical :: found

!
!     First step:  find the descriptor for the named segment.  Using
!     this descriptor, get the column descriptor.
!
      call zzeksdsc ( ctx, handle, segno,  segdsc          )
      call zzekcdsc ( ctx, handle, segdsc, column, coldsc  )

      if ( ctx%failed() ) return

!
!     This column had better be of d.p. or TIME type.
!
      dtype  =  coldsc(typidx)

      if ( ( dtype /= dp ) .and. ( dtype /= time )  ) then

         call ctx%setmsg ( 'Column # is of type #; EKRCED only works '    // &
                       'with d.p. or TIME columns.  RECNO = #; '      // &
                       'SEGNO =  #; EK = #.'                           )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  dtype                                     )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(WRONGDATATYPE)'                          )
         return

      end if

!
!     Now it's time to read data from the file.  Call the low-level
!     reader appropriate to the column's class.
!
      class  =  coldsc ( clsidx )

      if ( class == 2 ) then
!
!        Look up the record pointer for the target record.
!
         call zzektrdp ( ctx, handle, segdsc(rtidx),  recno,  recptr )

         call zzekrd02 ( ctx, handle, segdsc, coldsc, recptr, dvals(1), isnull )
         nvals  =  1

      else if ( class == 5 ) then

         call zzektrdp ( ctx, handle, segdsc(rtidx), recno, recptr )

         nvals  =  zzekesiz ( ctx, handle, segdsc, coldsc, recptr )

         call zzekrd05 ( ctx,  handle,  segdsc,  coldsc,  recptr, &
                          1,       nvals,   dvals,   isnull,  found  )

      else if ( class == 8 ) then
!
!        Records in class 8 columns are identified by a record number
!        rather than a pointer.
!
         call zzekrd08 ( ctx, handle, segdsc, coldsc, recno, dvals(1), isnull )
         nvals  =  1

      else

!
!        This is an unsupported d.p. column class.
!
         segno  =  segdsc ( snoidx )

         call ctx%setmsg ( 'Class # from input column descriptor is not ' // &
                       'a supported d.p. class.  COLUMN = #; '        // &
                       'RECNO = #; SEGNO = #; EK = #.'                 )
         call ctx%errint ( '#',  class                                     )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

      return
      end subroutine ekrced

      !> Read data from an integer column in a specified EK record.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is an EK file handle. The file may be open for read or
      !>              write access.
      !>
      !>     SEGNO    is the index of the segment from which data is to be
      !>              read.
      !>
      !>     RECNO    is the index of the record from which data is to be read.
      !>              This record number is relative to the start of the
      !>              segment indicated by SEGNO; the first record in the
      !>              segment has index 1.
      !>
      !>     COLUMN   is the name of the column from which data is to be read.
      !>
      !>## Detailed Output
      !>
      !>     NVALS,
      !>     IVALS    are, respectively, the number of values found in the
      !>              specified column entry and the set of values themselves.
      !>
      !>              For columns having fixed-size entries, when a a column
      !>              entry is null, NVALS is still set to the column entry
      !>              size. For columns having variable-size entries, NVALS is
      !>              set to 1 for null entries.
      !>
      !>     ISNULL   is a logical flag indicating whether the returned column
      !>              entry is null.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     2)  If SEGNO is out of range, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     3)  If RECNO is out of range, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     4)  If COLUMN is not the name of a declared column, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>     5)  If COLUMN specifies a column of whose data type is not
      !>         integer, the error SPICE(WRONGDATATYPE) is signaled.
      !>
      !>     6)  If COLUMN specifies a column of whose class is not
      !>         an integer class known to this routine, the error
      !>         SPICE(NOCLASS) is signaled.
      !>
      !>     7)  If an attempt is made to read an uninitialized column entry,
      !>         an error is signaled by a routine in the call tree of this
      !>         routine. A null entry is considered to be initialized, but
      !>         entries do not contain null values by default.
      !>
      !>     8)  If an I/O error occurs while reading the indicated file, the
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading ek.req for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine is a utility that allows an EK file to be read
      !>     directly without using the high-level query interface.
      !>
      !>## Examples
      !>
      !>     1)  Read the value in the third record of the column ICOL in
      !>         the fifth segment of an EK file designated by HANDLE.
      !>
      !>            CALL EKRCEI ( HANDLE, 5, 3, 'ICOL', N, IVAL, ISNULL )
      !>
      !>## Restrictions
      !>
      !>     1)  EK files open for write access are not necessarily readable.
      !>         In particular, a column entry can be read only if it has been
      !>         initialized. The caller is responsible for determining
      !>         when it is safe to read from files open for write access.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.3.1, 26-MAY-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.3.0, 06-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>-    SPICELIB Version 1.2.0, 20-JUN-1999 (WLT)
      !>
      !>        Removed unbalanced call to CHKOUT.
      !>
      !>-    SPICELIB Version 1.1.0, 28-JUL-1997 (NJB)
      !>
      !>        Bug fix: Record number, not record pointer, is now supplied
      !>        to look up data in the class 7 case. Miscellaneous header
      !>        changes were made as well.
      !>
      !>-    SPICELIB Version 1.0.0, 06-NOV-1995 (NJB)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.1.0, 28-JUL-1997 (NJB)
      !>
      !>        Bug fix: Record number, not record pointer, is now supplied
      !>        to look up data in the class 7 case. For class 7 columns,
      !>        column entry locations are calculated directly from record
      !>        numbers; no indirection is used.
      !>
      !>        Miscellaneous header changes were made as well.
      module subroutine ekrcei ( ctx, handle, segno, recno, column, nvals, ivals, isnull )
      use pepper_kinds, only: ip
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(inout) :: segno  !! Index of segment containing record. (PEPPER: changed by the routine, an input in SPICELIB's table)
      integer(ip), intent(in) :: recno  !! Record from which data is to be read.
      character(*), intent(in) :: column  !! Column name.
      integer(ip), intent(out) :: nvals  !! Number of values in column entry.
      integer(ip), intent(out) :: ivals  ( * )  !! Integer values in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.

      integer(ip) :: coldsc ( cdscsz )
      integer(ip) :: class
      integer(ip) :: dtype
      integer(ip) :: recptr
      integer(ip) :: segdsc ( sdscsz )

      logical :: found

!
!     First step:  find the descriptor for the named segment.  Using
!     this descriptor, get the column descriptor.
!
      call zzeksdsc ( ctx, handle, segno,  segdsc          )
      call zzekcdsc ( ctx, handle, segdsc, column, coldsc  )

      if ( ctx%failed() ) return

!
!     This column had better be of integer type.
!
      dtype  =  coldsc(typidx)

      if ( dtype /= int ) then

         call ctx%setmsg ( 'Column # is of type #; EKRCEI only works '    // &
                       'with integer columns.  RECNO = #; SEGNO = '   // &
                       '#; EK = #.'                                    )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  dtype                                     )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(WRONGDATATYPE)'                          )
         return

      end if

!
!     Now it's time to read data from the file.  Call the low-level
!     reader appropriate to the column's class.
!
      class  =  coldsc ( clsidx )

      if ( class == 1 ) then
!
!        Look up the record pointer for the target record.
!
         call zzektrdp ( ctx, handle, segdsc(rtidx),  recno,  recptr )

         call zzekrd01 ( ctx, handle, segdsc, coldsc, recptr, ivals(1), isnull )
         nvals  =  1

      else if ( class == 4 ) then

         call zzektrdp ( ctx, handle, segdsc(rtidx),  recno,  recptr )

         nvals  =  zzekesiz ( ctx, handle, segdsc, coldsc, recptr )

         call zzekrd04 ( ctx,  handle,  segdsc,  coldsc,  recptr, &
                          1,       nvals,   ivals,   isnull,  found  )

      else if ( class == 7 ) then
!
!        Records in class 7 columns are identified by a record number
!        rather than a pointer.
!
         call zzekrd07 ( ctx, handle, segdsc, coldsc, recno, ivals(1), isnull )
         nvals  =  1

      else

!
!        This is an unsupported integer column class.
!
         segno  =  segdsc ( snoidx )

         call ctx%setmsg ( 'Class # from input column descriptor is not ' // &
                       'a supported integer class.  COLUMN = #; '     // &
                       'RECNO = #; SEGNO = #; EK = #.'                 )
         call ctx%errint ( '#',  class                                     )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

      return
      end subroutine ekrcei

      !> All the values of a double precision or time column entry of an EK
      !> record (PEPPER; [[ekrced]] with the size of the entry). Bound as the
      !> generic `ek_values`.
      module subroutine ek_values_real ( ctx, handle, segno, recno, column, values, isnull )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! the handle of the EK file
      integer(ip), intent(in) :: segno  !! the segment number
      integer(ip), intent(in) :: recno  !! the record number
      character(*), intent(in) :: column  !! the column name
      real(wp), allocatable, intent(out) :: values(:)  !! the values (size 0 if null, or after an error)
      logical, intent(out) :: isnull  !! the entry is null
      integer(ip) :: n
      integer(ip) :: nvals
      integer(ip) :: seg
      isnull = .false.
      allocate ( values(0) )
      if ( ctx%failed() ) return
      call ek_entry_size ( ctx, handle, segno, recno, column, n )
      if ( ctx%failed() ) return
      deallocate ( values )
      allocate ( values(max(n,1)) )
      seg = segno
      call ekrced ( ctx, handle, seg, recno, column, nvals, values, isnull )
      if ( ctx%failed() .or. isnull ) then
         deallocate ( values )
         allocate ( values(0) )
      else
         values = values(1:nvals)
      end if
      end subroutine ek_values_real

      !> All the values of an integer column entry of an EK record (PEPPER;
      !> [[ekrcei]] with the size of the entry). Bound as the generic
      !> `ek_values`.
      module subroutine ek_values_int ( ctx, handle, segno, recno, column, values, isnull )
      use pepper_kinds, only: ip
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! the handle of the EK file
      integer(ip), intent(in) :: segno  !! the segment number
      integer(ip), intent(in) :: recno  !! the record number
      character(*), intent(in) :: column  !! the column name
      integer(ip), allocatable, intent(out) :: values(:)  !! the values (size 0 if null, or after an error)
      logical, intent(out) :: isnull  !! the entry is null
      integer(ip) :: n
      integer(ip) :: nvals
      integer(ip) :: seg
      isnull = .false.
      allocate ( values(0) )
      if ( ctx%failed() ) return
      call ek_entry_size ( ctx, handle, segno, recno, column, n )
      if ( ctx%failed() ) return
      deallocate ( values )
      allocate ( values(max(n,1)) )
      seg = segno
      call ekrcei ( ctx, handle, seg, recno, column, nvals, values, isnull )
      if ( ctx%failed() .or. isnull ) then
         deallocate ( values )
         allocate ( values(0) )
      else
         values = values(1:nvals)
      end if
      end subroutine ek_values_int

      !> All the values of a character column entry of an EK record, each of
      !> its full length (PEPPER; [[ekrcec]] with the size of the entry).
      !> Bound as the generic `ek_values`. Values of fixed-length columns
      !> are returned without their trailing blanks.
      module subroutine ek_values_str ( ctx, handle, segno, recno, column, values, isnull )
      use pepper_kinds, only: ip
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! the handle of the EK file
      integer(ip), intent(in) :: segno  !! the segment number
      integer(ip), intent(in) :: recno  !! the record number
      character(*), intent(in) :: column  !! the column name
      type(string), allocatable, intent(out) :: values(:)  !! the values (size 0 if null, or after an error)
      logical, intent(out) :: isnull  !! the entry is null
      integer(ip) :: coldsc ( cdscsz )
      integer(ip) :: segdsc ( sdscsz )
      integer(ip) :: class
      integer(ip) :: cvlen
      integer(ip) :: k
      integer(ip) :: n
      integer(ip) :: nvals
      integer(ip) :: recptr
      integer(ip) :: seg
      character(1) :: one(1)
      isnull = .false.
      allocate ( values(0) )
      if ( ctx%failed() ) return
      call zzeksdsc ( ctx, handle, segno,  segdsc          )
      call zzekcdsc ( ctx, handle, segdsc, column, coldsc  )
      if ( ctx%failed() ) return
      class = coldsc(clsidx)
      seg   = segno
      if ( coldsc(typidx) /= chr .or. .not. any ( class == [3, 6, 9] ) ) then
!
!        Not a character column: EKRCEC signals the error.
!
         call ekrcec ( ctx, handle, seg, recno, column, nvals, one, isnull )
         return
      end if
      if ( class == 3 ) then
!
!        A variable-length string: read its length first.
!
         call zzektrdp ( ctx, handle, segdsc(rtidx), recno, recptr )
         call zzekrd03 ( ctx, handle, segdsc, coldsc, recptr, cvlen, one(1), isnull )
         if ( ctx%failed() .or. isnull ) return
         block
            character(len=max(cvlen,1)) :: buf
            call zzekrd03 ( ctx, handle, segdsc, coldsc, recptr, cvlen, buf, isnull )
            if ( ctx%failed() ) return
            deallocate ( values )
            allocate ( values(1) )
            values(1)%s = buf(1:cvlen)
         end block
      else
!
!        Fixed-length strings: the column's length.
!
         call ek_entry_size ( ctx, handle, segno, recno, column, n )
         if ( ctx%failed() ) return
         block
            character(len=max(coldsc(lenidx),1)) :: buf(max(n,1))
            call ekrcec ( ctx, handle, seg, recno, column, nvals, buf, isnull )
            if ( ctx%failed() .or. isnull ) return
            deallocate ( values )
            allocate ( values(nvals) )
            do k = 1, nvals
               values(k)%s = trim ( buf(k) )
            end do
         end block
      end if
      end subroutine ek_values_str

      !> The number of values of a column entry of an EK record: 1 for the
      !> scalar column classes, the size of the entry for the array classes
      !> (PEPPER).
      subroutine ek_entry_size ( ctx, handle, segno, recno, column, n )
      use pepper_kinds, only: ip
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! the handle of the EK file
      integer(ip), intent(in) :: segno  !! the segment number
      integer(ip), intent(in) :: recno  !! the record number
      character(*), intent(in) :: column  !! the column name
      integer(ip), intent(out) :: n  !! the number of values of the entry
      integer(ip) :: coldsc ( cdscsz )
      integer(ip) :: segdsc ( sdscsz )
      integer(ip) :: recptr
      n = 1
      call zzeksdsc ( ctx, handle, segno,  segdsc          )
      call zzekcdsc ( ctx, handle, segdsc, column, coldsc  )
      if ( ctx%failed() ) return
      if ( any ( coldsc(clsidx) == [4, 5, 6] ) ) then
         call zzektrdp ( ctx, handle, segdsc(rtidx), recno, recptr )
         if ( ctx%failed() ) return
         n = zzekesiz ( ctx, handle, segdsc, coldsc, recptr )
      end if
      end subroutine ek_entry_size

      !> Add an entire class 7 column to an EK segment.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         the handle of an EK file that is open for writing.
      !>                    A `begin segment for fast load' operation must
      !>                    have already been performed for the designated
      !>                    segment.
      !>
      !>     SEGDSC         is a descriptor for the segment to which data is
      !>                    to be added.  The segment descriptor is not
      !>                    updated by this routine, but some fields in the
      !>                    descriptor will become invalid after this routine
      !>                    returns.
      !>
      !>     COLDSC         is a descriptor for the column to be added.  The
      !>                    column attributes must be filled in, but any
      !>                    pointers may be uninitialized.
      !>
      !>     IVALS          is an array containing the entire set of column
      !>                    entries for the specified column.  The entries
      !>                    are listed in row-order:  the column entry for the
      !>                    first row of the segment is first, followed by the
      !>                    column entry for the second row, and so on.  The
      !>                    number of column entries must match the declared
      !>                    number of rows in the segment.  Elements must be
      !>                    allocated for each column entry, including null
      !>                    entries.
      !>
      !>     NLFLGS         is an array of logical flags indicating whether
      !>                    the corresponding entries are null.  If the Ith
      !>                    element of NLFLGS is .FALSE., the Ith column entry
      !>                    defined by IVALS is added to the specified segment
      !>                    in the specified kernel file.
      !>
      !>                    If the Ith element of NLFGLS is .TRUE., the
      !>                    contents of the Ith column entry are undefined.
      !>
      !>                    NLFLGS is used only for columns that allow null
      !>                    values; it's ignored for other columns.
      !>
      !>     WKINDX         is a work space array used for building a column
      !>                    index.  If the column is indexed, the dimension of
      !>                    WKINDX must be at NROWS, where NROWS is the number
      !>                    of rows in the column.  If the column is not
      !>                    indexed, this work space is not used, so the
      !>                    dimension may be any positive value.
      !>
      !>## Detailed Output
      !>
      !>     None.  See $Particulars for a description of the effect of this
      !>     routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it modifies the named
      !>     EK file by adding data to the specified column.  This routine
      !>     writes the entire contents of the specified column in one shot.
      !>     This routine creates columns much more efficiently than can be
      !>     done by sequential calls to EKACEI, but has the drawback that
      !>     the caller must use more memory for the routine's inputs.  This
      !>     routine cannot be used to add data to a partially completed
      !>     column.
      !>
      !>     Class 7 columns have fixed record counts and contain scalar,
      !>     integer data.
      !>
      !>## Examples
      !>
      !>     See EKACLI.
      !>
      !>## Restrictions
      !>
      !>     1)  This routine assumes the EK file has been set up
      !>         properly for a fast load operation.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    Beta Version 1.0.0, 13-NOV-1995 (NJB)
      module subroutine zzekac07 ( ctx, handle, segdsc, coldsc, ivals, nlflgs, wkindx )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekclas07
      use pepper_inc_ekcoldsc
      use pepper_inc_ekcnamsz
      use pepper_inc_ekdatpag
      use pepper_inc_ekpage
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to new EK file.
      integer(ip), intent(in) :: segdsc ( * )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( * )  !! Column descriptor.
      integer(ip), intent(in) :: ivals  ( * )  !! Integer values to add to column.
      logical, intent(in) :: nlflgs ( * )  !! Array of null flags for column entries.
      integer(ip), intent(inout) :: wkindx ( * )  !! Work space for column index.
!
!     Local variables
!
      character(cnamsz) :: column

      integer(ip) :: class
      integer(ip) :: cmbase
      integer(ip) :: colidx
      integer(ip) :: datbas
      integer(ip) :: dscbas
      integer(ip) :: from
      integer(ip) :: idxbas
      integer(ip) :: idxpag
      integer(ip) :: idxtyp
      integer(ip) :: p
      integer(ip) :: page   ( pgsizi )
      integer(ip) :: mbase
      integer(ip) :: nflbas
      integer(ip) :: nflpag
      integer(ip) :: npage
      integer(ip) :: nrows
      integer(ip) :: nulptr
      integer(ip) :: to

      logical :: indexd
      logical :: nullok

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Grab the column's attributes.
!
      class  =  coldsc( clsidx )
      idxtyp =  coldsc( ixtidx )
      nulptr =  coldsc( nflidx )
      colidx =  coldsc( ordidx )

      nullok =  nulptr /= ifalse
      indexd =  idxtyp /= ifalse

!
!     This column had better be class 7.
!
      if ( class /= 7 ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Column class code # found in descriptor for ' // &
                       'column #.  Class should be 7.'                 )
         call ctx%errint ( '#', class                                      )
         call ctx%errch  ( '#', column                                     )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

!
!     Find the number of rows in the segment.
!
      nrows = segdsc ( nridx )

!
!     Decide how many pages are required to hold the array, and
!     allocate that many new, contiguous pages.
!
      npage  =  ( nrows + ipsize - 1 ) / ipsize

      call zzekacps ( ctx, handle, segdsc, int, npage, p, datbas )

!
!     We'll use FROM to indicate the element of IVALS we're
!     considering and TO to indicate the element of PAGE to write
!     to.
!
      to  =  1
      page = 0

      do from = 1, nrows

!
!        The Assignment.
!
         if (  ( .not. nullok ) .or. ( .not. nlflgs(from) )  ) then
!
!           The current item is non-null.
!
            page(to)  =  ivals(from)

         end if

         to =  to + 1

         if (  ( to > ipsize ) .or. ( from == nrows )  ) then
!
!           Either the current data page is full, or we've buffered
!           the last of the available data.  It's time to write out the
!           current page.  First set the link count.
!
            page ( ilcidx ) =  to - 1

!
!           Write out the data page.
!
            call zzekpgwi ( ctx, handle, p, page  )

!
!           Next page.
!
            p   =  p + 1
            to  =  1

         end if

      end do

!
!     Update the column's metadata area to point to the data array.
!
      cmbase = coldsc(metidx)

      call dasudi ( ctx, handle, cmbase+dbix07, cmbase+dbix07, [ datbas ] )

!
!     If the column is supposed to have an index, now is the time to
!     build that index.  Type 2 indexes are just order vectors.
!
      if ( indexd ) then
!
!        Compute the order vector.
!
         call zzekordi ( ctx, ivals,  nullok, nlflgs, nrows, wkindx )

!
!        Write out the index.
!
         call zzekwpai ( ctx, handle, segdsc, nrows, wkindx, idxpag, idxbas )

!
!        Update the column's metadata to point to the index.  The
!        pointer indicates base address of the index.  Also set the
!        index type in the column descriptor.
!
         mbase   =  segdsc ( imdidx )
         dscbas  =  mbase  +  sdscsz  +  (colidx-1)*cdscsz

         call dasudi ( ctx, handle, dscbas+ixpidx, dscbas+ixpidx, [ idxbas ] )
         call dasudi ( ctx, handle, dscbas+ixtidx, dscbas+ixtidx, [ 2 ] )

      end if

      if ( nullok ) then
!
!        Nulls are allowed.  Write out the null flag array.
!
         call zzekwpal ( ctx, handle, segdsc, nrows, nlflgs, nflpag, nflbas )

!
!        Update the column's metadata area to point to the null flag
!        array.
!
         call dasudi ( ctx, handle, cmbase+nfix07, cmbase+nfix07, [ nflbas ] )

      end if

      return
      end subroutine zzekac07

      !> Add an entire class 8 column to an EK segment.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         the handle of an EK file that is open for writing.
      !>                    A `begin segment for fast load' operation must
      !>                    have already been performed for the designated
      !>                    segment.
      !>
      !>     SEGDSC         is a descriptor for the segment to which data is
      !>                    to be added.  The segment descriptor is not
      !>                    updated by this routine, but some fields in the
      !>                    descriptor will become invalid after this routine
      !>                    returns.
      !>
      !>     COLDSC         is a descriptor for the column to be added.  The
      !>                    column attributes must be filled in, but any
      !>                    pointers may be uninitialized.
      !>
      !>     DVALS          is an array containing the entire set of column
      !>                    entries for the specified column.  The entries
      !>                    are listed in row-order:  the column entry for the
      !>                    first row of the segment is first, followed by the
      !>                    column entry for the second row, and so on.  The
      !>                    number of column entries must match the declared
      !>                    number of rows in the segment.  Elements must be
      !>                    allocated for each column entry, including null
      !>                    entries.
      !>
      !>     NLFLGS         is an array of logical flags indicating whether
      !>                    the corresponding entries are null.  If the Ith
      !>                    element of NLFLGS is .FALSE., the Ith column entry
      !>                    defined by DVALS is added to the specified segment
      !>                    in the specified kernel file.
      !>
      !>                    If the Ith element of NLFGLS is .TRUE., the
      !>                    contents of the Ith column entry are undefined.
      !>
      !>                    NLFLGS is used only for columns that allow null
      !>                    values; it's ignored for other columns.
      !>
      !>     WKINDX         is a work space array used for building a column
      !>                    index.  If the column is indexed, the dimension of
      !>                    WKINDX must be at NROWS, where NROWS is the number
      !>                    of rows in the column.  If the column is not
      !>                    indexed, this work space is not used, so the
      !>                    dimension may be any positive value.
      !>
      !>## Detailed Output
      !>
      !>     None.  See $Particulars for a description of the effect of this
      !>     routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it modifies the named
      !>     EK file by adding data to the specified column.  This routine
      !>     writes the entire contents of the specified column in one shot.
      !>     This routine creates columns much more efficiently than can be
      !>     done by sequential calls to EKACED, but has the drawback that
      !>     the caller must use more memory for the routine's inputs.  This
      !>     routine cannot be used to add data to a partially completed
      !>     column.
      !>
      !>     Class 8 columns have fixed record counts and contain scalar,
      !>     double precision data.
      !>
      !>## Examples
      !>
      !>     See EKACLD.
      !>
      !>## Restrictions
      !>
      !>     1)  This routine assumes the EK file has been set up
      !>         properly for a fast load operation.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    Beta Version 1.0.0, 13-NOV-1995 (NJB)
      module subroutine zzekac08 ( ctx, handle, segdsc, coldsc, dvals, nlflgs, wkindx )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekbool
      use pepper_inc_ekclas08
      use pepper_inc_ekcnamsz
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekpage
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to new EK file.
      integer(ip), intent(in) :: segdsc ( * )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( * )  !! Column descriptor.
      real(wp), intent(in) :: dvals  ( * )  !! D.p. values to add to column.
      logical, intent(in) :: nlflgs ( * )  !! Array of null flags for column entries.
      integer(ip), intent(inout) :: wkindx ( * )  !! Work space for column index.
!
!     Local variables
!
      character(cnamsz) :: column

      real(wp) :: page   ( pgsizd )

      integer(ip) :: class
      integer(ip) :: cmbase
      integer(ip) :: colidx
      integer(ip) :: datbas
      integer(ip) :: dscbas
      integer(ip) :: from
      integer(ip) :: idxbas
      integer(ip) :: idxpag
      integer(ip) :: idxtyp
      integer(ip) :: p
      integer(ip) :: mbase
      integer(ip) :: nflbas
      integer(ip) :: nflpag
      integer(ip) :: npage
      integer(ip) :: nrows
      integer(ip) :: nulptr
      integer(ip) :: to

      logical :: indexd
      logical :: nullok

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Grab the column's attributes.
!
      class  =  coldsc( clsidx )
      idxtyp =  coldsc( ixtidx )
      nulptr =  coldsc( nflidx )
      colidx =  coldsc( ordidx )

      nullok =  nulptr /= ifalse
      indexd =  idxtyp /= ifalse

!
!     This column had better be class 8.
!
      if ( class /= 8 ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Column class code # found in descriptor for ' // &
                       'column #.  Class should be 8.'                 )
         call ctx%errint ( '#', class                                      )
         call ctx%errch  ( '#', column                                     )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

!
!     Find the number of rows in the segment.
!
      nrows = segdsc ( nridx )

!
!     Decide how many pages are required to hold the array, and
!     allocate that many new, contiguous pages.
!
      npage  =  ( nrows + dpsize - 1 ) / dpsize

      call zzekacps ( ctx, handle, segdsc, dp, npage, p, datbas )

!
!     We'll use FROM to indicate the element of DVALS we're
!     considering and TO to indicate the element of PAGE to write
!     to.
!
      to  =  1
      page = 0.0_wp

      do from = 1, nrows

!
!        The Assignment.
!
         if (  ( .not. nullok ) .or. ( .not. nlflgs(from) )  ) then
!
!           The current item is non-null.
!
            page(to)  =  dvals(from)

         end if

         to =  to + 1

         if (  ( to > dpsize ) .or. ( from == nrows )  ) then
!
!           Either the current data page is full, or we've buffered
!           the last of the available data.  It's time to write out the
!           current page.  First set the link count.
!
            page ( dlcidx ) =  to - 1

!
!           Write out the data page.
!
            call zzekpgwd ( ctx, handle, p, page  )

!
!           Next page.
!
            p   =  p + 1
            to  =  1

         end if

      end do

!
!     Update the column's metadata area to point to the data array.
!
      cmbase = coldsc(metidx)

      call dasudi ( ctx, handle, cmbase+dbix08, cmbase+dbix08, [ datbas ] )

!
!     If the column is supposed to have an index, now is the time to
!     build that index.  Type 2 indexes are just order vectors.
!
      if ( indexd ) then
!
!        Compute the order vector.
!
         call zzekordd ( ctx, dvals,  nullok, nlflgs, nrows, wkindx )

!
!        Write out the index.
!
         call zzekwpai ( ctx, handle, segdsc, nrows, wkindx, idxpag, idxbas )

!
!        Update the column's metadata to point to the index.  The
!        pointer indicates base address of the index.  Also set the
!        index type in the column descriptor.
!
         mbase   =  segdsc ( imdidx )
         dscbas  =  mbase  +  sdscsz  +  (colidx-1)*cdscsz

         call dasudi ( ctx, handle, dscbas+ixpidx, dscbas+ixpidx, [ idxbas ] )
         call dasudi ( ctx, handle, dscbas+ixtidx, dscbas+ixtidx, [ 2 ] )

      end if

      if ( nullok ) then
!
!        Nulls are allowed.  Write out the null flag array.
!
         call zzekwpal ( ctx, handle, segdsc, nrows, nlflgs, nflpag, nflbas )

!
!        Update the column's metadata area to point to the null flag
!        array.
!
         call dasudi ( ctx, handle, cmbase+nfix08, cmbase+nfix08, [ nflbas ] )

      end if

      return
      end subroutine zzekac08

      !> Add an entire class 9 column to an EK segment.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         the handle of an EK file that is open for writing.
      !>                    A `begin segment for fast load' operation must
      !>                    have already been performed for the designated
      !>                    segment.
      !>
      !>     SEGDSC         is a descriptor for the segment to which data is
      !>                    to be added.  The segment descriptor is not
      !>                    updated by this routine, but some fields in the
      !>                    descriptor will become invalid after this routine
      !>                    returns.
      !>
      !>     COLDSC         is a descriptor for the column to be added.  The
      !>                    column attributes must be filled in, but any
      !>                    pointers may be uninitialized.
      !>
      !>     CVALS          is an array containing the entire set of column
      !>                    entries for the specified column.  The entries
      !>                    are listed in row-order:  the column entry for the
      !>                    first row of the segment is first, followed by the
      !>                    column entry for the second row, and so on.  The
      !>                    number of column entries must match the declared
      !>                    number of rows in the segment.  Elements must be
      !>                    allocated for each column entry, including null
      !>                    entries.
      !>
      !>     NLFLGS         is an array of logical flags indicating whether
      !>                    the corresponding entries are null.  If the Ith
      !>                    element of NLFLGS is .FALSE., the Ith column entry
      !>                    defined by CVALS is added to the specified segment
      !>                    in the specified kernel file.
      !>
      !>                    If the Ith element of NLFGLS is .TRUE., the
      !>                    contents of the Ith column entry are undefined.
      !>
      !>                    NLFLGS is used only for columns that allow null
      !>                    values; it's ignored for other columns.
      !>
      !>     WKINDX         is a work space array used for building a column
      !>                    index.  If the column is indexed, the dimension of
      !>                    WKINDX must be at NROWS, where NROWS is the number
      !>                    of rows in the column.  If the column is not
      !>                    indexed, this work space is not used, so the
      !>                    dimension may be any positive value.
      !>
      !>## Detailed Output
      !>
      !>     None.  See $Particulars for a description of the effect of this
      !>     routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it modifies the named
      !>     EK file by adding data to the specified column.  This routine
      !>     writes the entire contents of the specified column in one shot.
      !>     This routine creates columns much more efficiently than can be
      !>     done by sequential calls to EKACEC, but has the drawback that
      !>     the caller must use more memory for the routine's inputs.  This
      !>     routine cannot be used to add data to a partially completed
      !>     column.
      !>
      !>     Class 9 columns have fixed record counts, and contain
      !>     fixed-length strings.
      !>
      !>## Examples
      !>
      !>     See EKACLC.
      !>
      !>## Restrictions
      !>
      !>     1)  This routine assumes the EK file has been set up
      !>         properly for a fast load operation.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    Beta Version 1.0.0, 09-NOV-1995 (NJB)
      module subroutine zzekac09 ( ctx, handle, segdsc, coldsc, cvals, nlflgs, wkindx )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekclas09
      use pepper_inc_ekcnamsz
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekpage
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to new EK file.
      integer(ip), intent(in) :: segdsc ( * )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( * )  !! Column descriptor.
      character(*), intent(in) :: cvals  ( * )  !! Character values to add to column.
      logical, intent(in) :: nlflgs ( * )  !! Array of null flags for column entries.
      integer(ip), intent(inout) :: wkindx ( * )  !! Work space for column index.
!
!     Local variables
!
      character(cnamsz) :: column
      character(pgsizc) :: page

      integer(ip) :: class
      integer(ip) :: cmbase
      integer(ip) :: colidx
      integer(ip) :: datbas
      integer(ip) :: dscbas
      integer(ip) :: from
      integer(ip) :: idxbas
      integer(ip) :: idxpag
      integer(ip) :: idxtyp
      integer(ip) :: p
      integer(ip) :: l
      integer(ip) :: mbase
      integer(ip) :: nflbas
      integer(ip) :: nflpag
      integer(ip) :: npage
      integer(ip) :: nrows
      integer(ip) :: nulptr
      integer(ip) :: spp
      integer(ip) :: to

      logical :: fixlen
      logical :: indexd
      logical :: nullok

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Grab the column's attributes.  Initialize the maximum non-blank
!     width of the column.
!
      class  =  coldsc ( clsidx )
      idxtyp =  coldsc ( ixtidx )
      nulptr =  coldsc ( nflidx )
      colidx =  coldsc ( ordidx )
      l      =  coldsc ( lenidx )

      nullok =  nulptr /= ifalse
      indexd =  idxtyp /= ifalse
      fixlen =  l      /= ifalse

!
!     This column had better be class 9.
!
      if ( class /= 9 ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Column class code # found in descriptor for ' // &
                       'column #.  Class should be 9.'                 )
         call ctx%errint ( '#', class                                      )
         call ctx%errch  ( '#', column                                     )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

!
!     Make sure the column has fixed-length strings.
!
      if  ( .not. fixlen ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Column # has variable string length; class '  // &
                       '9 supports fixed-length strings only.'         )
         call ctx%errch  ( '#', column                                     )
         call ctx%sigerr ( 'SPICE(BUG)'                                    )
         return

      end if

!
!     Check the input string length.
!
      if (      ( l < 0             ) &
           .or. ( l > len(cvals(1)) ) &
           .or. ( l > cpsize        )  ) then

         call ctx%setmsg ( 'String length # is just plain wrong.' )
         call ctx%errint ( '#',  l                                )
         call ctx%sigerr ( 'SPICE(INVALIDSIZE)'                   )
         return

      end if

!
!     Compute the number of strings we can hold in one page.
!
      spp  =  cpsize / l

!
!     Find the number of rows in the segment.
!
      nrows = segdsc ( nridx )

!
!     Decide how many pages are required to hold the array, and
!     allocate that many new, contiguous pages.
!
      npage  =  ( nrows + spp - 1 ) / spp

      call zzekacps ( ctx, handle, segdsc, chr, npage, p, datbas )

!
!     We'll use FROM to indicate the element of CVALS we're
!     considering and TO to indicate the element of PAGE to write
!     to.
!
      to   =  1
      page =  ' '

      do from = 1, nrows
!
!        The Assignment.
!
         if (  ( .not. nullok ) .or. ( .not. nlflgs(from) )  ) then

            page( to : to+l-1 ) =  cvals(from)

         end if

         to  =  to + l

         if (      ( to   > cpsize-l+1 ) &
              .or. ( from == nrows      )  ) then
!
!           Either the current data page is full, or we've buffered
!           the last of the available data.  It's time to write out the
!           current page.
!
            call zzekpgwc ( ctx, handle, p, page  )

!
!           Set the link count.
!
            call zzekslnk ( ctx, handle, chr, p,  (to-l)/l  )

!
!           Next page.
!
            p   =  p + 1
            to  =  1

         end if

      end do

!
!     Update the column's metadata area to point to the data array.
!
      cmbase = coldsc(metidx)

      call dasudi ( ctx, handle, cmbase+dbix09, cmbase+dbix09, [ datbas ] )

!
!     If the column is supposed to have an index, now is the time to
!     build that index.  Type 2 indexes are just order vectors.
!
      if ( indexd ) then
!
!        Compute the order vector.
!
         call zzekordc ( ctx, cvals,  nullok, nlflgs, nrows, wkindx )

!
!        Write out the index.
!
         call zzekwpai ( ctx, handle, segdsc, nrows, wkindx, idxpag, idxbas )

!
!        Update the column's metadata to point to the index.  The
!        pointer indicates base address of the index.  Also set the
!        index type in the column descriptor.
!
         mbase   =  segdsc ( imdidx )
         dscbas  =  mbase  +  sdscsz  +  (colidx-1)*cdscsz

         call dasudi ( ctx, handle, dscbas+ixpidx, dscbas+ixpidx, [ idxbas ] )
         call dasudi ( ctx, handle, dscbas+ixtidx, dscbas+ixtidx, [ 2 ] )

      end if

      if ( nullok ) then
!
!        Nulls are allowed.  Write out the null flag array.
!
         call zzekwpal ( ctx, handle, segdsc, nrows, nlflgs, nflpag, nflbas )

!
!        Update the column's metadata area to point to the null flag
!        array.
!
         call dasudi ( ctx, handle, cmbase+nfix09, cmbase+nfix09, [ nflbas ] )

      end if

      return
      end subroutine zzekac09

      !> Read scalar data from a character column in a specified EK
      !> record.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is an EK file handle.
      !>
      !>     SEGDSC         is the descriptor of the segment from which data is
      !>                    to be read.
      !>
      !>     COLDSC         is the column descriptor corresponding to the
      !>                    column from which data is to be read.
      !>
      !>     RECPTR         is a pointer to the record from which data is to be
      !>                    read.
      !>
      !>     ELTIDX         is the index of the column entry element to read.
      !>                    If the column entry is scalar, this argument is
      !>                    ignored.
      !>
      !>## Detailed Output
      !>
      !>     CVLEN          is the length of the stored character string value.
      !>                    This is the actual number of characters stored;
      !>                    CVLEN may be less than the declared length of
      !>                    the column to which the value belongs, if the
      !>                    column is declared to contain fixed-length strings.
      !>                    CVLEN is valid only when FOUND is set to .TRUE.
      !>
      !>     CVAL           is the specified column entry.  CVAL is valid only
      !>                    when FOUND is set to .TRUE.
      !>
      !>     ISNULL         is a logical flag indicating whether the entry is
      !>                    null.  ISNULL is valid only when FOUND is set to
      !>                    .TRUE.
      !>
      !>     FOUND          is a logical flag indicating whether the specified
      !>                    column entry element was found.  For vector-valued
      !>                    columns, if ELTIDX refers to a non-existent
      !>                    column entry element, FOUND is set to .FALSE.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If COLDSC is not the name of a declared column, the error
      !>         will be diagnosed by routines called by this routine.
      !>
      !>     3)  If COLDSC specifies a column of whose data type is not
      !>         character, the error SPICE(WRONGDATATYPE) will be signaled.
      !>
      !>     4)  If COLDSC specifies a column of whose class is not
      !>         a character class known to this routine, the error
      !>         SPICE(NOCLASS) will be signaled.
      !>
      !>     5)  If the indicated column is array-valued, and if ELTIDX is
      !>         non-positive, the error will be diagnosed by routines called
      !>         by this routine.  However, if ELTIDX is greater than the
      !>         number of elements in the specified column entry, FOUND is
      !>         set to .FALSE. and no error is signaled.
      !>
      !>     6)  If an I/O error occurs while reading the indicated file,
      !>         the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     The ZZEKRSx routines are low-level readers that expect column
      !>     entries to be defined by descriptors.  Since these routines do not
      !>     look up descriptors, in cases where many successive accesses to
      !>     the same segment and column are required, these routines are
      !>     considerably more efficient than the high-level readers.
      !>
      !>     These routines do not participate in tracing.
      !>
      !>## Examples
      !>
      !>     See ZZEKECMP.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 06-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>-    Beta Version 1.0.0, 06-NOV-1995 (NJB)
      module subroutine zzekrsc ( ctx, handle, segdsc, coldsc, recptr, eltidx, cvlen, cval, isnull, found )
      use pepper_kinds, only: ip
      use pepper_inc_ekcnamsz
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Pointer to record from which data is to be read.
      integer(ip), intent(in) :: eltidx  !! Index of column entry element to be read.
      integer(ip), intent(out) :: cvlen  !! Length of stored string.
      character(*), intent(out) :: cval  !! Character value in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.
      logical, intent(out) :: found  !! Flag indicting whether entry element was found.
!
!     Local variables
!
      character(cnamsz) :: column

      integer(ip) :: class
      integer(ip) :: dtype
      integer(ip) :: recno
      integer(ip) :: segno

!
!     Nothing found to begin with.
!
      found  =  .false.

!
!     This column had better be of character type.
!
      dtype  =  coldsc(typidx)

      if ( dtype /= chr ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         segno  =  segdsc   ( snoidx )
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Column # is of type #; ZZEKRSC only works '   // &
                       'with integer columns.  RECNO = #; SEGNO = '   // &
                       '#; EK = #.'                                    )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  dtype                                     )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(WRONGDATATYPE)'                          )
         return

      end if

!
!     Now it's time to read data from the file.  Call the low-level
!     reader appropriate to the column's class.
!
      class  =  coldsc ( clsidx )

      if ( class == 3 ) then

         call zzekrd03 ( ctx,  handle,  segdsc,  coldsc, &
                          recptr,  cvlen,   cval,   isnull  )

         found  =  .true.

      else if ( class == 6 ) then
!
!        Class 6 columns contain character string array entries.
!
         call zzekrd06 ( ctx, handle,  segdsc,  coldsc,  recptr, &
                         eltidx,  eltidx,  cval,    isnull,  found )
!
!        PEPPER: the strings of a class 6 column have the column's
!        declared length. SPICELIB left CVLEN unset for this class.
!
         cvlen  =  coldsc ( lenidx )

      else if ( class == 9 ) then

         call zzekrd09 ( ctx,  handle,  segdsc,  coldsc, &
                          recptr,  cvlen,   cval,   isnull  )

         found  =  .true.

      else

!
!        This is an unsupported character column class.
!
         call zzekcnam ( ctx, handle, coldsc, column )

         segno  =  segdsc   ( snoidx )
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Class # from input column descriptor is not ' // &
                       'a supported character class.  COLUMN = #; '   // &
                       'RECNO = #; SEGNO = #; EK = #.'                 )
         call ctx%errint ( '#',  class                                     )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

      return
      end subroutine zzekrsc

      !> Read scalar data from a double precision column in a specified EK
      !> record.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is an EK file handle.
      !>
      !>     SEGDSC         is the descriptor of the segment from which data is
      !>                    to be read.
      !>
      !>     COLDSC         is the column descriptor corresponding to the
      !>                    column from which data is to be read.
      !>
      !>     RECPTR         is a pointer to the record from which data is to be
      !>                    read.
      !>
      !>     ELTIDX         is the index of the column entry element to read.
      !>                    If the column entry is scalar, this argument is
      !>                    ignored.
      !>
      !>## Detailed Output
      !>
      !>     DVAL           is the specified column entry.  DVAL is valid only
      !>                    when FOUND is set to .TRUE.
      !>
      !>     ISNULL         is a logical flag indicating whether the entry is
      !>                    null.  ISNULL is valid only when FOUND is set to
      !>                    .TRUE.
      !>
      !>     FOUND          is a logical flag indicating whether the specified
      !>                    column entry element was found.  For vector-valued
      !>                    columns, if ELTIDX refers to a non-existent
      !>                    column entry element, FOUND is set to .FALSE.
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If COLDSC is not the name of a declared column, the error
      !>         will be diagnosed by routines called by this routine.
      !>
      !>     3)  If COLDSC specifies a column of whose data type is not
      !>         double precision, the error SPICE(WRONGDATATYPE) will be
      !>         signaled.
      !>
      !>     4)  If COLDSC specifies a column of whose class is not
      !>         an double precision class known to this routine, the error
      !>         SPICE(NOCLASS) will be signaled.
      !>
      !>     5)  If the indicated column is array-valued, and if ELTIDX is
      !>         non-positive, the error will be diagnosed by routines called
      !>         by this routine.  However, if ELTIDX is greater than the
      !>         number of elements in the specified column entry, FOUND is
      !>         set to .FALSE. and no error is signaled.
      !>
      !>     6)  If an I/O error occurs while reading the indicated file,
      !>         the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     The ZZEKRSx routines are low-level readers that expect column
      !>     entries to be defined by descriptors.  Since these routines do not
      !>     look up descriptors, in cases where many successive accesses to
      !>     the same segment and column are required, these routines are
      !>     considerably more efficient than the high-level readers.
      !>
      !>     These routines do not participate in tracing.
      !>
      !>## Examples
      !>
      !>     See ZZEKECMP.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 06-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>-    Beta Version 1.0.0, 06-NOV-1995 (NJB)
      module subroutine zzekrsd ( ctx, handle, segdsc, coldsc, recptr, eltidx, dval, isnull, found )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekcnamsz
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Pointer to record from which data is to be read.
      integer(ip), intent(in) :: eltidx  !! Index of column entry element to be read.
      real(wp), intent(out) :: dval  !! D.p. value in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.
      logical, intent(out) :: found  !! Flag indicting whether entry element was found.
      real(wp) :: dval_1(1)  !! one-element copy of dval (array argument)

      character(cnamsz) :: column

      integer(ip) :: class
      integer(ip) :: dtype
      integer(ip) :: recno
      integer(ip) :: segno

!
!     Nothing found to begin with.
!
      found  =  .false.

!
!     This column had better be of d.p. or TIME type.
!
      dtype  =  coldsc(typidx)

      if ( ( dtype /= dp ) .and. ( dtype /= time )  ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         segno  =  segdsc   ( snoidx )
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Column # is of type #; ZZEKRSD only works '   // &
                       'with DP or TIME columns.  RECNO = #; SEGNO = '// &
                       '#; EK = #.'                                    )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  dtype                                     )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(WRONGDATATYPE)'                          )
         return

      end if

!
!     Now it's time to read data from the file.  Call the low-level
!     reader appropriate to the column's class.
!
      class  =  coldsc ( clsidx )

      if ( class == 2 ) then

         call zzekrd02 ( ctx, handle, segdsc, coldsc, recptr, dval, isnull  )

         found  =  .true.

      else if ( class == 5 ) then
!
!        Class 5 columns contain d.p. array entries.
!
         call zzekrd05 ( ctx, handle, segdsc, coldsc, recptr, eltidx, eltidx, dval_1, isnull, found )
         dval = dval_1(1)

      else if ( class == 8 ) then

         call zzekrd08 ( ctx, handle, segdsc, coldsc, recptr, dval, isnull  )

         found  =  .true.

      else

!
!        This is an unsupported d.p. column class.
!
         call zzekcnam ( ctx, handle, coldsc, column )

         segno  =  segdsc   ( snoidx )
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Class # from input column descriptor is not ' // &
                       'a supported d.p. class.  COLUMN = #; '        // &
                       'RECNO = #; SEGNO = #; EK = #.'                 )
         call ctx%errint ( '#',  class                                     )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

      return
      end subroutine zzekrsd

      !> Read scalar data from an integer column in a specified EK record.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is an EK file handle.
      !>
      !>     SEGDSC         is the descriptor of the segment from which data is
      !>                    to be read.
      !>
      !>     COLDSC         is the column descriptor corresponding to the
      !>                    column from which to read.
      !>
      !>     RECPTR         is a pointer to the record from which data is to be
      !>                    read.
      !>
      !>     ELTIDX         is the index of the column entry element to read.
      !>                    If the column entry is scalar, this argument is
      !>                    ignored.
      !>
      !>## Detailed Output
      !>
      !>     IVAL           is the specified column entry.  IVAL is valid only
      !>                    when FOUND is set to .TRUE.
      !>
      !>     ISNULL         is a logical flag indicating whether the entry is
      !>                    null.  ISNULL is valid only when FOUND is set to
      !>                    .TRUE.
      !>
      !>     FOUND          is a logical flag indicating whether the specified
      !>                    column entry element was found.  For vector-valued
      !>                    columns, if ELTIDX refers to a non-existent
      !>                    column entry element, FOUND is set to .FALSE.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If COLDSC is not the descriptor of a declared column, the
      !>         error will be diagnosed by routines called by this routine.
      !>
      !>     3)  If COLDSC specifies a column of whose data type is not
      !>         integer, the error SPICE(WRONGDATATYPE) will be signaled.
      !>
      !>     4)  If COLDSC specifies a column of whose class is not
      !>         an integer class known to this routine, the error
      !>         SPICE(NOCLASS) will be signaled.
      !>
      !>     5)  If the indicated column is array-valued, and if ELTIDX is
      !>         non-positive, the error will be diagnosed by routines called
      !>         by this routine.  However, if ELTIDX is greater than the
      !>         number of elements in the specified column entry, FOUND is
      !>         set to .FALSE. and no error is signaled.
      !>
      !>     6)  If an I/O error occurs while reading the indicated file,
      !>         the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     The ZZEKRSx routines are low-level readers that expect column
      !>     entries to be defined by descriptors.  Since these routines do not
      !>     look up descriptors, in cases where many successive accesses to
      !>     the same segment and column are required, these routines are
      !>     considerably more efficient than the high-level readers.
      !>
      !>     These routines do not participate in tracing.
      !>
      !>## Examples
      !>
      !>     See ZZEKECMP.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 06-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>-    Beta Version 1.0.0, 06-NOV-1995 (NJB)
      module subroutine zzekrsi ( ctx, handle, segdsc, coldsc, recptr, eltidx, ival, isnull, found )
      use pepper_kinds, only: ip
      use pepper_inc_ekcnamsz
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Pointer to record from which data is to be read.
      integer(ip), intent(in) :: eltidx  !! Index of column entry element to be read.
      integer(ip), intent(out) :: ival  !! Integer value in column entry.
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.
      logical, intent(out) :: found  !! Flag indicting whether entry element was found.
      integer(ip) :: ival_1(1)  !! one-element copy of ival (array argument)

      character(cnamsz) :: column

      integer(ip) :: class
      integer(ip) :: dtype
      integer(ip) :: recno
      integer(ip) :: segno

!
!     Nothing found to begin with.
!
      found  =  .false.

!
!     This column had better be of integer type.
!
      dtype  =  coldsc(typidx)

      if ( dtype /= int ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         segno  =  segdsc   ( snoidx )
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Column # is of type #; ZZEKRSI only works '   // &
                       'with integer columns.  RECNO = #; SEGNO = '   // &
                       '#; EK = #.'                                    )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  dtype                                     )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(WRONGDATATYPE)'                          )
         return

      end if

!
!     Now it's time to read data from the file.  Call the low-level
!     reader appropriate to the column's class.
!
      class  =  coldsc ( clsidx )

      if ( class == 1 ) then
!
!        Class 1 columns contain scalar, integer entries.
!
         call zzekrd01 ( ctx, handle, segdsc, coldsc, recptr, ival, isnull )

         found  =  .true.

      else if ( class == 4 ) then
!
!        Class 4 columns contain integer array entries.
!
         call zzekrd04 ( ctx, handle, segdsc, coldsc, recptr, eltidx, eltidx, ival_1, isnull, found )
         ival = ival_1(1)

      else if ( class == 7 ) then
!
!        Class 7 columns are fixed-count columns that contain scalar,
!        integer entries.
!
         call zzekrd07 ( ctx, handle, segdsc, coldsc, recptr, ival, isnull )

         found  =  .true.

      else

!
!        This is an unsupported integer column class.
!
         call zzekcnam ( ctx, handle, coldsc, column )

         segno  =  segdsc   ( snoidx )
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Class # from input column descriptor is not ' // &
                       'a supported integer class.  COLUMN = #; '     // &
                       'RECNO = #; SEGNO = #; EK = #.'                 )
         call ctx%errint ( '#',  class                                     )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

      return
      end subroutine zzekrsi

      !> Update a specified class 4 column entry in an EK record.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is a file handle of an EK open for write access.
      !>
      !>     SEGDSC         is the descriptor of the segment containing
      !>                    the specified column entry.
      !>
      !>     COLDSC         is the descriptor of the column containing
      !>                    the specified column entry.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry to update.
      !>
      !>     NVALS          is the number of values in the replacement
      !>                    column entry.
      !>
      !>     IVALS          is an array of integer values with which to update
      !>                    the specified column entry.
      !>
      !>     ISNULL         is a logical flag indicating whether the value
      !>                    of the specified column entry is to be set to NULL.
      !>                    If so, the input IVALS is ignored.
      !>
      !>## Detailed Output
      !>
      !>     None.  See the $Particulars section for a description of the
      !>     effect of this routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.  The file will not be modified.
      !>
      !>     2)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.  The file may be corrupted.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it updates a column entry
      !>     in an EK segment.  The status of the record containing the entry
      !>     is set to `updated'.  If the column containing the entry is
      !>     indexed, the corresponding index is updated.
      !>
      !>     The changes made by this routine to the target EK file become
      !>     permanent when the file is closed.  Failure to close the file
      !>     properly will leave it in an indeterminate state.
      !>
      !>## Examples
      !>
      !>     See EKUCEI.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    Beta Version 1.0.0, 27-SEP-1995 (NJB)
      module subroutine zzekue04 ( ctx, handle, segdsc, coldsc, recptr, nvals, ivals, isnull )
      use pepper_kinds, only: ip
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(inout) :: segdsc ( sdscsz )  !! Segment descriptor. (PEPPER: changed by the routine, an input in SPICELIB's table)
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      integer(ip), intent(in) :: nvals  !! Number of values.
      integer(ip), intent(in) :: ivals ( * )  !! Integer values.
      logical, intent(in) :: isnull  !! Null flag.
!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Get rid of the old column entry first.
!
      call zzekde04 ( ctx, handle, segdsc, coldsc, recptr )

      if ( ctx%failed() ) return

!
!     We've reduced the problem to a solved one:  that of adding
!     a column entry.
!
      call zzekad04 ( ctx, handle, segdsc, coldsc, recptr, nvals, ivals, isnull )

      return
      end subroutine zzekue04

      !> Update a specified class 5 column entry in an EK record.
