      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.1, 03-OCT-2021 (NJB)
      !>
      !>        Corrected typos in comments.
      !>
      !>-    Beta Version 1.1.0, 18-JUN-1999 (WLT)
      !>
      !>        Removed an unbalanced call to CHKOUT
      !>
      !>-    Beta Version 1.0.0, 19-OCT-1995 (NJB)
      module subroutine zzekleri ( ctx, handle, segdsc, coldsc, ikey, recptr, null, prvidx, prvptr )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekcnamsz
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: ikey  !! Integer key.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      logical, intent(in) :: null  !! Null flag.
      integer(ip), intent(out) :: prvidx  !! Ordinal position of predecessor of IKEY.
      integer(ip), intent(out) :: prvptr  !! Pointer to record containing predecessor of IKEY.
!
!     Local variables
!
      character(cnamsz) :: column

      integer(ip) :: dtype
      integer(ip) :: itype

      logical :: indexd

      if ( ctx%failed() ) return

!
!     If the column's not indexed, we have no business being here.
!
      indexd  =  coldsc(ixtidx) /= ifalse

      if ( .not. indexd ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Column # is not indexed.' )
         call ctx%errch  ( '#',  column               )
         call ctx%sigerr ( 'SPICE(NOTINDEXED)'        )
         return

      end if

!
!     Check the column's data type.
!
      dtype  =  coldsc(typidx)

      if ( dtype /= int ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Column # should be INT but has type #.' )
         call ctx%errch  ( '#',  column                             )
         call ctx%errint ( '#',  dtype                              )
         call ctx%sigerr ( 'SPICE(INVALIDTYPE)'                     )
         return

      end if

!
!     Hand the problem off to the subroutine that understands this
!     column's index type.
!
      itype  =  coldsc(ixtidx)

      if ( itype == 1 ) then

         call zzekeri1 ( ctx,  handle,  segdsc,  coldsc,  ikey, &
                          recptr,  null,    prvidx,  prvptr  )

      else

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Column # has index type #.' )
         call ctx%errch  ( '#',  column                 )
         call ctx%errint ( '#',  itype                  )
         call ctx%sigerr ( 'SPICE(INVALIDTYPE)'         )
         return

      end if

      return
      end subroutine zzekleri

      !> Find the ordinal position of a specified record in a specified,
      !> indexed EK column.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is an EK file handle.  The file may be open for
      !>                    reading or writing.
      !>
      !>     SEGDSC         is the segment descriptor of the segment
      !>                    containing the column to be searched.
      !>
      !>     COLDSC         is the column descriptor of the column to be
      !>                    searched.
      !>
      !>     RECPTR         is a pointer to the record whose ordinal position
      !>                    is to be found.
      !>
      !>## Detailed Output
      !>
      !>     POS            is the ordinal position in the specified column
      !>                    of the input record, where the order relation is
      !>                    specified by the column's index.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If an I/O error occurs while reading the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     Various EK write operations require the capability of locating
      !>     the index key that maps to a given record number.  An example is
      !>     updating a column's index to reflect deletion of a specified
      !>     record:  the key that maps to the record must be deleted.
      !>     Locating this key is the inverse of the problem that the index
      !>     is meant to solve.
      !>
      !>## Examples
      !>
      !>     See ZZEKIXDL.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 2.1.0, 07-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error message.
      !>
      !>-    SPICELIB Version 2.0.0, 31-MAY-2010 (NJB)
      !>
      !>        Bug fix: substring bound out-of-range violation
      !>        in reference to local variable CVAL has been
      !>        corrected. This error could occur if the a
      !>        class 3 column entry had length exceeding MAXSTR.
      !>
      !>-    Beta Version 1.0.0, 10-OCT-1995 (NJB)
      module subroutine zzekfrx ( ctx, handle, segdsc, coldsc, recptr, pos )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Pointer to record to locate.
      integer(ip), intent(out) :: pos  !! Ordinal position of record.
!
!     Local variables
!
      character(:), allocatable :: cval  !! the column entry (PEPPER: SPICELIB's CHARACTER*(MAXSTR))

      real(wp) :: dval

      integer(ip) :: cmplen
      integer(ip) :: cvlen
      integer(ip) :: dtype
      integer(ip) :: ival
      integer(ip) :: prvptr
      integer(ip) :: recno

      logical :: found
      logical :: isnull

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Determine the data type of the column, and look up the value
!     associated with RECPTR.
!
      dtype  =  coldsc ( typidx )

      if ( dtype == chr ) then

!
!        PEPPER: read the whole string. SPICELIB looked up at most its
!        first MAXSTR characters in the column's index.
!
         call zzekrsc_whole ( ctx,  handle,  segdsc,  coldsc,  recptr, &
                              1,       cvlen,   cval,    isnull,  found  )

         if (  found  .and. ( .not. isnull )  ) then

            cmplen = cvlen
         else
            cmplen = 0
         end if

      else if (  ( dtype == dp ) .or. ( dtype == time )  ) then

         call zzekrsd ( ctx,  handle,  segdsc,  coldsc,  recptr, &
                         1,       dval,    isnull,  found  )

      else if ( dtype == int ) then

         call zzekrsi ( ctx,  handle,  segdsc,  coldsc,  recptr, &
                         1,       ival,    isnull,  found  )

      else

         call ctx%setmsg ( 'File = #; COLIDX = #. Unrecognized data ' // &
                       'type code # found in descriptor.'           )
         call ctx%errhan ( '#',     handle                              )
         call ctx%errint ( '#',     coldsc(ordidx)                      )
         call ctx%errint ( '#',     dtype                               )
         call ctx%sigerr ( 'SPICE(ITEMNOTFOUND)'                        )
         return

      end if

      if ( .not. found ) then
!
!        We have a most heinous situation.  We should always be able
!        to find the value associated with a record.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'File = #; RECNO = #; COLIDX = #. Column '     // &
                       'entry was not found.  This probably indicates'// &
                       ' a corrupted file or a bug in the EK code.'    )
         call ctx%errhan ( '#',     handle                                 )
         call ctx%errint ( '#',     recno                                  )
         call ctx%errint ( '#',     coldsc(ordidx)                         )
         call ctx%sigerr ( 'SPICE(ITEMNOTFOUND)'                           )
         return

      end if

!
!     Find the last column entry less than or equal to the one
!     associated with the input record, where the order relation is
!     dictionary ordering on (<column value>, <record number>) pairs.
!     These ordered pairs are distinct, even if the column entries
!     are not.  Therefore, the ordinal position POS will actually be
!     the ordinal position of our record.
!
      if ( dtype == chr ) then

         call zzeklerc ( ctx, handle,  segdsc,  coldsc,  cval(:cmplen), &
                         recptr,  isnull,  pos,     prvptr         )

      else if (  ( dtype == dp ) .or. ( dtype == time )  ) then

         call zzeklerd ( ctx, handle,  segdsc,  coldsc,  dval, &
                         recptr,  isnull,  pos,     prvptr  )

      else
!
!        The data type is INT.  (We've already checked for invalid
!        types.)
!

         call zzekleri ( ctx, handle,  segdsc,  coldsc,  ival, &
                         recptr,  isnull,  pos,     prvptr  )

      end if

      if ( prvptr /= recptr ) then
!
!        Big problem.  This should never happen.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'File = #; RECNO = #; COLIDX = #.  Record ' // &
                       'that was last less than or equal to RECNO '// &
                       'was not equal to RECNO.  This probably '   // &
                       'indicates  a corrupted file or a bug in '  // &
                       'the EK code.'                               )
         call ctx%errhan ( '#',     handle                              )
         call ctx%errint ( '#',     recno                               )
         call ctx%errint ( '#',     coldsc(ordidx)                      )
         call ctx%sigerr ( 'SPICE(ITEMNOTFOUND)'                        )
         return

      end if

      return
      end subroutine zzekfrx

      !> Insert into a type 1 EK index a record pointer associated with a
      !> character key.  The key and record pointer determine the insertion
      !> point via dictionary ordering on (value, record pointer) pairs.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is a file handle of an EK open for write access.
      !>
      !>     SEGDSC         is the segment descriptor of the segment
      !>                    containing the column specified by COLDSC.
      !>
      !>     COLDSC         is the column descriptor of the column to
      !>                    which the index corresponds.
      !>
      !>     CKEY           is a character string key.
      !>
      !>     RECPTR         is a record pointer associated with the input key.
      !>
      !>     NULL           is a logical flag indicating whether the input
      !>                    value is null.
      !>
      !>## Detailed Output
      !>
      !>     None.  This routine operates by side effects.  See $Particulars
      !>     for a description of the effect of this routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.
      !>
      !>     2)  If the data type of the input column is not character,
      !>         the error SPICE(INVALIDTYPE) is signaled.
      !>
      !>     3)  If the input column is not indexed, the error
      !>         SPICE(NOTINDEXED) is signaled.
      !>
      !>     4)  If the index type of the input column is not recognized,
      !>         the error SPICE(INVALIDTYPE) is signaled.
      !>
      !>     5)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine updates the index of an EK segment to reflect the
      !>     addition of a record to the segment.  The index must be
      !>     associated with a character, scalar column.  The type of the
      !>     index must be 1.
      !>
      !>     The ordinal position of the new item is determined by the key
      !>     CKEY.  The new item will follow the last item already present
      !>     in the column having a value less than or equal to CKEY.
      !>
      !>     In order to support the capability of creating an index for a
      !>     column that has already been populated with data, this routine
      !>     does not require that number of elements referenced by the
      !>     input column's index match the number of elements in the column;
      !>     the index is allowed to reference fewer elements.  However,
      !>     every record referenced by the index must be populated with data.
      !>
      !>## Examples
      !>
      !>     See ZZEKAD03.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.1, 03-OCT-2021 (NJB)
      !>
      !>        Corrected typos in comments.
      !>
      !>-    SPICELIB Version 1.1.0, 18-JUN-1999 (WLT)
      !>
      !>        Removed an unbalanced call to CHKOUT
      !>
      !>-    Beta Version 1.0.0, 10-OCT-1995 (NJB)
      module subroutine zzekiic1 ( ctx, handle, segdsc, coldsc, ckey, recptr, null )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekcnamsz
      use pepper_inc_ekcoldsc
      use pepper_inc_ekopcd
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      character(*), intent(in) :: ckey  !! Character key.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      logical, intent(in) :: null  !! Null flag.
!
!     Local variables
!
      character(cnamsz) :: column

      integer(ip) :: dtype
      integer(ip) :: itype
      integer(ip) :: prvidx
      integer(ip) :: prvptr
      integer(ip) :: tree

      logical :: indexd

      if ( ctx%failed() ) return

!
!     If the column's not indexed, we have no business being here.
!
      indexd  =  coldsc(ixtidx) /= ifalse

      if ( .not. indexd ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Column # is not indexed.' )
         call ctx%errch  ( '#',  column               )
         call ctx%sigerr ( 'SPICE(NOTINDEXED)'        )
         return

      end if

!
!     Check the column's data type.
!
      dtype  =  coldsc(typidx)

      if ( dtype /= chr ) then

         call zzekcnam ( ctx, handle, coldsc, column )

         call ctx%setmsg ( 'Column # should be CHR but has type #.' )
         call ctx%errch  ( '#',  column                             )
         call ctx%errint ( '#',  dtype                              )
         call ctx%sigerr ( 'SPICE(INVALIDTYPE)'                     )
         return

      end if

      itype  =  coldsc(ixtidx)

      if ( itype == 1 ) then
!
!        Get the tree pointer from the column descriptor.
!
         tree  =  coldsc(ixpidx)

!
!        Locate the predecessor of the input key, record pair.
!
         call zzeklerc ( ctx,  handle,  segdsc,  coldsc,  ckey, &
                          recptr,  null,    prvidx,  prvptr  )

!
!        Insert the new record number right after the item we've found.
!
         call zzektrin ( ctx, handle, tree, prvidx+1, recptr )

      else

         call zzekcnam ( ctx, handle, segdsc, column )

         call ctx%setmsg ( 'Column # has index type #.' )
         call ctx%errch  ( '#',  column                 )
         call ctx%errint ( '#',  itype                  )
         call ctx%sigerr ( 'SPICE(INVALIDTYPE)'         )
         return

      end if

      return
      end subroutine zzekiic1

      !> Insert into a type 1 EK index a record pointer associated with a
