         call zzekad02 ( ctx, handle, segdsc, coldsc, recptr, dval, isnull )

      else
!
!        The data pointer is corrupted.
!
         recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

         call ctx%setmsg ( 'Data pointer is corrupted. SEGNO = #; '  // &
                       'COLIDX =  #; RECNO = #; EK = #'          )
         call ctx%errint ( '#',  segdsc(snoidx)                      )
         call ctx%errint ( '#',  coldsc(ordidx)                      )
         call ctx%errint ( '#',  recno                               )
         call ctx%errhan ( '#',  handle                              )
         call ctx%sigerr ( 'SPICE(BUG)'                              )
         return

      end if

      return
      end subroutine zzekue02

      !> Delete a specified record from a specified E-kernel segment.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is a file handle of an EK open for write access.
      !>
      !>     SEGNO    is the number of the segment from which to
      !>              delete the specified record.
      !>
      !>     RECNO    is the index of the record to delete. RECNO must
      !>              be in the range 1 : NREC, where NREC is the
      !>              number of records in the segment prior to the
      !>              insertion.
      !>
      !>## Detailed Output
      !>
      !>     None. See the $Particulars section for a description of the
      !>     effect of this routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, an error is signaled by a routine in the
      !>         call tree of this routine. The file will not be modified.
      !>
      !>     2)  If SEGNO is out of range, the error SPICE(INVALIDINDEX)
      !>         is signaled. The file will not be modified.
      !>
      !>     3)  If RECNO is out of range, the error SPICE(INVALIDINDEX)
      !>         is signaled. The file will not be modified.
      !>
      !>     4)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error is signaled by a routine in the call tree of
      !>         this routine. The file may be corrupted.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading ek.req for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects: it deletes a record
      !>     from an EK segment. Deleting a record implies:
      !>
      !>        1) All column entries in the record are deleted.
      !>
      !>        2) Link counts are decremented for data pages containing
      !>           column entries in the record to be deleted. Pages whose
      !>           link counts drop to zero are freed.
      !>
      !>        3) All column indexes are updated for the parent segment.
      !>
      !>        4) The link count is decremented for the page containing the
      !>           record pointer structure of the record to be deleted. If
      !>           the link count drops to zero, the page is freed.
      !>
      !>        5) The pointer to the deleted record is deleted from the
      !>           record tree for the parent segment.
      !>
      !>        6) The segment's metadata is updated to reflect the new
      !>           record count.
      !>
      !>## Examples
      !>
      !>     1)  Suppose the second segment of an EK file designated by
      !>         HANDLE contains 5 records:
      !>
      !>            +-----------------+
      !>            |     Record 1    |
      !>            +-----------------+
      !>            |     Record 2    |
      !>            +-----------------+
      !>            |     Record 3    |
      !>            +-----------------+
      !>            |     Record 4    |
      !>            +-----------------+
      !>            |     Record 5    |
      !>            +-----------------+
      !>
      !>         Then the call
      !>
      !>            CALL EKDELR ( HANDLE, 2, 3 )
      !>
      !>         deletes the third record from the segment, leaving the
      !>         segment's contents as follows:
      !>
      !>            +-----------------+
      !>            |     Record 1    |
      !>            +-----------------+
      !>            |     Record 2    |
      !>            +-----------------+
      !>            |     Record 4    |
      !>            +-----------------+
      !>            |     Record 5    |
      !>            +-----------------+
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 26-MAY-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 19-DEC-1995 (NJB)
      module subroutine ekdelr ( ctx, handle, segno, recno )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekcnamsz
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(in) :: segno  !! Segment number.
      integer(ip), intent(inout) :: recno  !! Record number. (PEPPER: changed by the routine, an input in SPICELIB's table)

      character(cnamsz) :: column

      integer(ip) :: base
      integer(ip) :: class
      integer(ip) :: coldsc ( cdscsz )
      integer(ip) :: dscbas
      integer(ip) :: i
      integer(ip) :: mbase
      integer(ip) :: mp
      integer(ip) :: ncols
      integer(ip) :: nlinks
      integer(ip) :: nrec
      integer(ip) :: p
      integer(ip) :: recptr
      integer(ip) :: segdsc ( sdscsz )
      integer(ip) :: unit

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Before trying to actually modify the file, do every error
!     check we can.
!
!     Is this file handle valid--is the file open for paged write
!     access?  Signal an error if not.
!
      call zzekpgch ( ctx, handle, 'WRITE' )

      if ( ctx%failed() ) return

!
!     Look up the integer metadata page and page base for the segment.
!     Given the base address, we can read the pertinent metadata in
!     one shot.
!
      call zzekmloc ( ctx, handle,  segno,  mp,  mbase  )

      if ( ctx%failed() ) return

      call dasrdi ( ctx, handle,  mbase+1,  mbase+sdscsz,  segdsc )

!
!     In case the target EK is shadowed, let the shadow system know
!     about the deletion.  This must be done before the data is
!     deleted.  The argument COLDSC is unused on this call.
!
      call zzekrbck ( ctx, 'DELETE', handle, segdsc, coldsc, recno )

!
!     We'll need to know how many columns the segment has in order to
!     compute the size of the record pointer.  The record pointer
!     contains DPTBAS items plus two elements for each column.
!
      ncols  =  segdsc ( ncidx )

!
!     Check the number of records already present.  RECNO must not
!     exceed this count.
!
      nrec  =  segdsc ( nridx )

      if (  ( recno < 1 ) .or. ( recno > nrec )  ) then

         call ctx%setmsg ( 'Record number = #; valid range is 1:#.' )
         call ctx%errint ( '#',  recno                              )
         call ctx%errint ( '#',  nrec                               )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)'                    )
         return

      end if

!
!     Delete all of the column entries in the record.  The deletion
!     routines handle updating column indexes and freeing unlinked
!     pages.
!
      call zzektrdp ( ctx, handle, segdsc(rtidx), recno, recptr )

      do i =  1, ncols
!
!        Get the descriptor of the Ith column.
!
         dscbas  =  mbase  +  cdoff  +  (i-1)*cdscsz

         call dasrdi ( ctx, handle, dscbas+1, dscbas+cdscsz, coldsc )

         class   =  coldsc(clsidx)

!
!        Delete the entry in the current column.
!
         if ( class == 1 ) then

            call zzekde01 ( ctx, handle, segdsc, coldsc, recptr )

         else if ( class == 2 ) then

            call zzekde02 ( ctx, handle, segdsc, coldsc, recptr )

         else if ( class == 3 ) then

            call zzekde03 ( ctx, handle, segdsc, coldsc, recptr )

         else if ( class == 4 ) then

            call zzekde04 ( ctx, handle, segdsc, coldsc, recptr )

         else if ( class == 5 ) then

            call zzekde05 ( ctx, handle, segdsc, coldsc, recptr )

         else if ( class == 6 ) then

            call zzekde06 ( ctx, handle, segdsc, coldsc, recptr )

         else
!
!           This is an unsupported class.
!
            recno  =  zzekrp2n ( ctx, handle, segdsc(snoidx), recptr )

            call dashlu    ( ctx, handle, unit )
            call zzekcnam  ( ctx, handle, coldsc, column )

            call ctx%setmsg ( 'Class # from input column descriptor '  // &
                          'is not supported.  COLUMN = #; '        // &
                          'RECNO = #; SEGNO = #; EK = #.'           )
            call ctx%errint ( '#',  class                               )
            call ctx%errch  ( '#',  column                              )
            call ctx%errint ( '#',  recno                               )
            call ctx%errint ( '#',  segdsc(snoidx)                      )
            call ctx%errfnm ( '#',  unit                                )
            call ctx%sigerr ( 'SPICE(NOCLASS)'                          )
            return

         end if

      end do

!
!     Find the page containing the record pointer.
!
      call zzekpgpg ( ctx, int, recptr+1, p, base )

!
!     Get the link count for the page.  If we have more
!     than one link to the page, decrement the link count.  If
!     we're down to one link, this deletion will finish off the
!     page:  we'll deallocate it.
!
      call zzekglnk ( ctx, handle, int, p, nlinks )

      if ( nlinks > 1 ) then

         call zzekslnk ( ctx, handle, int, p, nlinks-1 )

      else
!
!        If we removed the last item from the page, we can delete
!        the page.  ZZEKDPS adjusts the segment's metadata
!        to reflect the deallocation.
!
         call zzekdps ( ctx, handle, segdsc, int, p )

      end if

!
!     The entry corresponding to the record is deleted from
!     the data record tree at index RECNO.  The record count gets
!     decremented.
!
      call zzektrdl ( ctx, handle,  segdsc(rtidx),  recno )

      segdsc ( nridx )  =  segdsc ( nridx ) - 1

!
!     Write out the updated segment descriptor.
!
      call dasudi ( ctx, handle,  mbase+1,  mbase+sdscsz,  segdsc )

      return
      end subroutine ekdelr

      !> Update a double precision column entry in a specified EK record.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is a file handle attached to an EK open for
      !>              write access.
      !>
      !>     SEGNO    is the index of the segment containing the column
      !>              entry to be updated.
      !>
      !>     RECNO    is the index of the record containing the column
      !>              entry to be updated. This record number is
      !>              relative to the start of the segment indicated by
      !>              SEGNO; the first record in the segment has index 1.
      !>
      !>     COLUMN   is the name of the column containing the entry to
      !>              be updated.
      !>
      !>     NVALS,
      !>     DVALS    are, respectively, the number of values to add to
      !>              the specified column and the set of values
      !>              themselves. The data values are written in to the
      !>              specified column and record.
      !>
      !>              If the  column has fixed-size entries, then NVALS
      !>              must equal the entry size for the specified column.
      !>
      !>              For columns with variable-sized entries, the size
      !>              of the new entry need not match the size of the
      !>              entry it replaces. In particular, the new entry
      !>              may be larger.
      !>
      !>     ISNULL   is a logical flag indicating whether the entry is
      !>              null. If ISNULL is .FALSE., the column entry
      !>              defined by NVALS and DVALS is added to the
      !>              specified kernel file.
      !>
      !>              If ISNULL is .TRUE., NVALS and DVALS are ignored.
      !>              The contents of the column entry are undefined.
      !>              If the column has fixed-length, variable-size
      !>              entries, the number of entries is considered to
      !>              be 1.
      !>
      !>              The new entry may be null even though it replaces
      !>              a non-null value, and vice versa.
      !>
      !>## Detailed Output
      !>
      !>     None. See $Particulars for a description of the effect of this
      !>     routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     2)  If SEGNO is out of range, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     3)  If COLUMN is not the name of a declared column, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>     4)  If COLUMN specifies a column of whose data type is not DOUBLE
      !>         PRECISION or TIME, the error SPICE(WRONGDATATYPE) is signaled.
      !>
      !>     5)  If RECNO is out of range, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     6)  If the specified column has fixed-size entries and NVALS does
      !>         not match this size, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     7)  If the specified column has variable-size entries and NVALS is
      !>         non-positive, an error is signaled by a routine in the call
      !>         tree of this routine.
      !>
      !>     8)  If an attempt is made to add a null value to a column that
      !>         doesn't take null values, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     9)  If COLUMN specifies a column of whose class is not
      !>         a double precision class known to this routine, the error
      !>         SPICE(NOCLASS) is signaled.
      !>
      !>     10) If an I/O error occurs while reading or writing the indicated
      !>         file, the error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading ek.req for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects: it modifies the named
      !>     EK file by adding data to the specified record in the specified
      !>     column. Data may be added to a segment in random order; it is not
      !>     necessary to fill in columns or rows sequentially. Data may only
      !>     be added one logical element at a time. Partial assignments of
      !>     logical elements are not supported.
      !>
      !>     Since columns of data type TIME are implemented using double
      !>     precision column classes, this routine may be used to update
      !>     columns of type TIME.
      !>
      !>## Examples
      !>
      !>     1)  Replace the value in the third record of the column DCOL in
      !>         the fifth segment of an EK file designated by HANDLE. Set
      !>         the new value to 999.D0.
      !>
      !>            CALL EKUCED ( HANDLE, 5, 3, 'DCOL', 1, 999.D0, .FALSE. )
      !>
      !>     2)  Same as (1), but this time add a null value. The argument
      !>         999.D0 is ignored because the null flag is set to .TRUE.
      !>
      !>            CALL EKUCED ( HANDLE, 5, 3, 'DCOL', 1, 999.D0, .TRUE. )
      !>
      !>     3)  Replace the entry in the third record of the column DARRAY in
      !>         the fifth segment of an EK file designated by HANDLE. Set
      !>         the new value using an array DBUFF of 10 d.p. values.
      !>
      !>            CALL EKUCED ( HANDLE, 5, 3, 'DARRAY', 10, DBUFF, .FALSE. )
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.2.1, 06-AUG-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.2.0, 06-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>-    SPICELIB Version 1.1.0, 20-JUN-1999 (WLT)
      !>
      !>        Removed unbalanced call to CHKOUT.
      !>
      !>-    SPICELIB Version 1.0.0, 26-SEP-1995 (NJB)
      module subroutine ekuced ( ctx, handle, segno, recno, column, nvals, dvals, isnull )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(inout) :: segno  !! Index of segment containing record. (PEPPER: changed by the routine, an input in SPICELIB's table)
      integer(ip), intent(in) :: recno  !! Record in which entry is to be updated.
      character(*), intent(in) :: column  !! Column name.
      integer(ip), intent(in) :: nvals  !! Number of values in new column entry.
      real(wp), intent(in) :: dvals  ( * )  !! Double precision values to add to column.
      logical, intent(in) :: isnull  !! Flag indicating whether column entry is null.

      integer(ip) :: coldsc ( cdscsz )
      integer(ip) :: class
      integer(ip) :: dtype
      integer(ip) :: recptr
      integer(ip) :: segdsc ( sdscsz )

      logical :: isshad

!
!     First step:  find the descriptor for the named segment.  Using
!     this descriptor, get the column descriptor.
!
      call zzeksdsc ( ctx, handle, segno,  segdsc          )
      call zzekcdsc ( ctx, handle, segdsc, column, coldsc  )

      if ( ctx%failed() ) return

!
!     This column had better be of double precision or `time' type.
!
      dtype  =  coldsc(typidx)

      if (  ( dtype /= dp ) .and. ( dtype /= time )  ) then

         call ctx%setmsg ( 'Column # is of type #; EKUCED only works '    // &
                       'with d.p. or TIME columns.  RECNO = #; '      // &
                       'SEGNO = #; EK = #.'                            )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  dtype                                     )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(WRONGDATATYPE)'                          )
         return

      end if

!
!     Look up the record pointer for the target record.
!
      call zzektrdp ( ctx, handle, segdsc(rtidx), recno, recptr )

!
!     Determine whether the EK is shadowed.
!
      call ekshdw ( ctx, handle, isshad )

!
!     If the EK is shadowed, we must back up the current column entry
!     if the entry has not already been backed up.  ZZEKRBCK will
!     handle this task.
!
      if ( isshad ) then
         call zzekrbck ( ctx, 'UPDATE', handle, segdsc, coldsc, recno )
      end if

!
!     Now it's time to carry out the replacement.
!
      class  =  coldsc ( clsidx )

      if ( class == 2 ) then
!
!        Class 2 columns contain scalar d.p. data.
!
         call zzekue02 ( ctx, handle, segdsc, coldsc, recptr, dvals(1), isnull )

      else if ( class == 5 ) then
!
!        Class 5 columns contain array-valued d.p. data.
!
         call zzekue05 ( ctx, handle,  segdsc, coldsc, &
                         recptr,  nvals,  dvals,  isnull )

      else
!
!        This is an unsupported d.p. column class.
!
         segno  =  segdsc ( snoidx )

         call ctx%setmsg ( 'Class # from input column descriptor is not ' // &
                       'a supported d.p. class.  COLUMN = #; '        // &
                       'RECNO = #; SEGNO = #; EK = #.'                 )
         call ctx%errint ( '#',  class                                     )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

      return
      end subroutine ekuced

      !> Update an integer column entry in a specified EK record.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is a file handle attached to an EK open for
      !>              write access.
      !>
      !>     SEGNO    is the index of the segment containing the column
      !>              entry to be updated.
      !>
      !>     RECNO    is the index of the record containing the column
      !>              entry to be updated. This record number is
      !>              relative to the start of the segment indicated by
      !>              SEGNO; the first record in the segment has index 1.
      !>
      !>     COLUMN   is the name of the column containing the entry to
      !>              be updated.
      !>
      !>     NVALS,
      !>     IVALS    are, respectively, the number of values to add to
      !>              the specified column and the set of values
      !>              themselves. The data values are written in to the
      !>              specified column and record.
      !>
      !>              If the  column has fixed-size entries, then NVALS
      !>              must equal the entry size for the specified column.
      !>
      !>              For columns with variable-sized entries, the size
      !>              of the new entry need not match the size of the
      !>              entry it replaces. In particular, the new entry
      !>              may be larger.
      !>
      !>     ISNULL   is a logical flag indicating whether the entry is
      !>              null. If ISNULL is .FALSE., the column entry
      !>              defined by NVALS and IVALS is added to the
      !>              specified kernel file.
      !>
      !>              If ISNULL is .TRUE., NVALS and IVALS are ignored.
      !>              The contents of the column entry are undefined.
      !>              If the column has fixed-length, variable-size
      !>              entries, the number of entries is considered to
      !>              be 1.
      !>
      !>              The new entry may be null even though it replaces
      !>              a non-null value, and vice versa.
      !>
      !>## Detailed Output
      !>
      !>     None. See $Particulars for a description of the effect of this
      !>     routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     2)  If SEGNO is out of range, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     3)  If COLUMN is not the name of a declared column, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>     4)  If COLUMN specifies a column of whose data type is not
      !>         integer, the error SPICE(WRONGDATATYPE) is signaled.
      !>
      !>     5)  If RECNO is out of range, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     6)  If the specified column has fixed-size entries and NVALS does
      !>         not match this size, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     7)  If the specified column has variable-size entries and NVALS is
      !>         non-positive, an error is signaled by a routine in the call
      !>         tree of this routine.
      !>
      !>     8)  If an attempt is made to add a null value to a column that
      !>         doesn't take null values, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     9)  If COLUMN specifies a column of whose class is not
      !>         an integer class known to this routine, the error
      !>         SPICE(NOCLASS) is signaled.
      !>
      !>     10) If an I/O error occurs while reading or writing the indicated
      !>         file, the error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading ek.req for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects: it modifies the named
      !>     EK file by adding data to the specified record in the specified
      !>     column. Data may be added to a segment in random order; it is not
      !>     necessary to fill in columns or rows sequentially. Data may only
      !>     be added one logical element at a time. Partial assignments of
      !>     logical elements are not supported.
      !>
      !>## Examples
      !>
      !>     1)  Replace the value in the third record of the column ICOL in
      !>         the fifth segment of an EK file designated by HANDLE. Set
      !>         the new value to 999.
      !>
      !>            CALL EKUCEI ( HANDLE, 5, 3, 'ICOL', 1, 999, .FALSE. )
      !>
      !>     2)  Same as (1), but this time add a null value. The argument
      !>         999 is ignored because the null flag is set to .TRUE.
      !>
      !>            CALL EKUCEI ( HANDLE, 5, 3, 'ICOL', 1, 999, .TRUE. )
      !>
      !>     3)  Replace the entry in the third record of the column IARRAY in
      !>         the fifth segment of an EK file designated by HANDLE. Set
      !>         the new value using an array IBUFF of 10 values.
      !>
      !>            CALL EKUCEI ( HANDLE, 5, 3, 'IARRAY', 10, IBUFF, .FALSE. )
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.2.1, 06-AUG-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.2.0, 06-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>-    SPICELIB Version 1.1.0, 20-JUN-1999 (WLT)
      !>
      !>        Removed unbalanced call to CHKOUT.
      !>
      !>-    SPICELIB Version 1.0.0, 26-SEP-1995 (NJB)
      module subroutine ekucei ( ctx, handle, segno, recno, column, nvals, ivals, isnull )
      use pepper_kinds, only: ip
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(inout) :: segno  !! Index of segment containing record. (PEPPER: changed by the routine, an input in SPICELIB's table)
      integer(ip), intent(in) :: recno  !! Record in which entry is to be updated.
      character(*), intent(in) :: column  !! Column name.
      integer(ip), intent(in) :: nvals  !! Number of values in new column entry.
      integer(ip), intent(in) :: ivals  ( * )  !! Integer values to add to column.
      logical, intent(in) :: isnull  !! Flag indicating whether column entry is null.

      integer(ip) :: coldsc ( cdscsz )
      integer(ip) :: class
      integer(ip) :: dtype
      integer(ip) :: recptr
      integer(ip) :: segdsc ( sdscsz )

      logical :: isshad

!
!     First step:  find the descriptor for the named segment.  Using
!     this descriptor, get the column descriptor.
!
      call zzeksdsc ( ctx, handle, segno,  segdsc          )
      call zzekcdsc ( ctx, handle, segdsc, column, coldsc  )

      if ( ctx%failed() ) return

!
!     This column had better be of integer type.
!
      dtype  =  coldsc(typidx)

      if ( dtype /= int ) then

         call ctx%setmsg ( 'Column # is of type #; EKUCEI only works '    // &
                       'with integer columns.  RECNO = #; SEGNO = '   // &
                       '#; EK = #.'                                    )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  dtype                                     )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(WRONGDATATYPE)'                          )
         return

      end if

!
!     Look up the record pointer for the target record.
!
      call zzektrdp ( ctx, handle, segdsc(rtidx), recno, recptr )

!
!     Determine whether the EK is shadowed.
!
      call ekshdw ( ctx, handle, isshad )

!
!     If the EK is shadowed, we must back up the current column entry
!     if the entry has not already been backed up.  ZZEKRBCK will
!     handle this task.
!
      if ( isshad ) then
         call zzekrbck ( ctx, 'UPDATE', handle, segdsc, coldsc, recno )
      end if

!
!     Now it's time to carry out the replacement.
!
      class  =  coldsc ( clsidx )

      if ( class == 1 ) then
!
!        Class 1 columns contain scalar integer data.
!
         call zzekue01 ( ctx, handle, segdsc, coldsc, recptr, ivals(1), isnull )

      else if ( class == 4 ) then
!
!        Class 4 columns contain array-valued integer data.
!
         call zzekue04 ( ctx, handle,  segdsc, coldsc, &
                         recptr,   nvals,  ivals,  isnull )

      else
!
!        This is an unsupported integer column class.
!
         segno  =  segdsc ( snoidx )

         call ctx%setmsg ( 'Class # from input column descriptor is not ' // &
                       'a supported integer class.  COLUMN = #; '     // &
                       'RECNO = #; SEGNO = #; EK = #.'                 )
         call ctx%errint ( '#',  class                                     )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

      return
      end subroutine ekucei

      !> Get data for a single star from a SPICE type 1 star catalog.
      !>
      !>## Detailed Input
      !>
      !>     INDEX    is the index of the star in the list of stars
      !>              that satisfy the selection criteria specified in
      !>              the last call to STCF01.
      !>
      !>## Detailed Output
      !>
      !>     RA       is right ascension of the star at the catalog epoch
      !>              in radians relative to the J2000 inertial frame.
      !>
      !>     DEC      is declination of the star at the catalog epoch in
      !>              radians relative to the J2000 inertial frame.
      !>
      !>     RASIG    is the uncertainty in right ascension of the star at
      !>              the catalog epoch in radians.
      !>
      !>     DECSIG   is the uncertainty in declination of the star at
      !>              the catalog epoch in radians.
      !>
      !>     CATNUM   is the star number in the catalog.
      !>
      !>     SPTYPE   is the star's spectral type. See catalog description
      !>              for more information regarding encoding of spectral
      !>              type values.
      !>
      !>     VMAG     is the visual magnitude of the star.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If fetching of any of output values fails, the error
      !>         SPICE(BADSTARINDEX) is signaled.
      !>
      !>     2)  If no star catalog has been loaded, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     3)  If a star catalog type 1 was not queried by calling STCF01
      !>         before calling this routine, an error is signaled by a routine
      !>         in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     This routine reads the data from SPICE type 1 star catalog file
      !>     loaded into the program by a call to STCL01.
      !>
      !>     SPICE type 1 star catalog files MUST contain a single data table.
      !>     It can occupy a single segment or it can spread across multiple
      !>     segments. This table MUST include the following columns:
      !>
      !>        column name                data type          units
      !>        ----------------------------------------------------
      !>        RA                   DOUBLE PRECISION        DEGREES
      !>        DEC                  DOUBLE PRECISION        DEGREES
      !>        RA_SIGMA             DOUBLE PRECISION        DEGREES
      !>        DEC_SIGMA            DOUBLE PRECISION        DEGREES
      !>        CATALOG_NUMBER       INTEGER
      !>        SPECTRAL_TYPE        CHARACTER*(4)
      !>        VISUAL_MAGNITUDE     DOUBLE PRECISION
      !>
      !>     Nulls are not allowed in any of the columns.
      !>     Other columns can also be present in the table but their data
      !>     will NOT be accessible through STCF01 and STCG01 --
      !>     the interface used to access data in the catalog. Note
      !>     that the names and attributes of these additional columns
      !>     must be identical for all segments containing this table.
      !>
      !>## Particulars
      !>
      !>     This routine is intended to be a part of the user interface to
      !>     the SPICE type 1 star catalog. It allows the caller to retrieve
      !>     data for a single star found by STCF01 using the star's
      !>     index within the search result array. This subroutine MUST
      !>     NOT be called before a search by STCF01 was done.
      !>
      !>     Other routines in the SPICE type 1 star catalog access
      !>     family are:
      !>
      !>        STCL01  load the catalog file and make its data
      !>                available for search and retrieval.
      !>
      !>        STCF01  search through the catalog for all stars within
      !>                a specified RA-DEC rectangle.
      !>
      !>## Examples
      !>
      !>     In the following code fragment, STCG01 is used to retrieve
      !>     position and characteristics for every star within an RA - DEC
      !>     rectangle from a particular SPICE type 1 star catalog.
      !>
      !>     C
      !>     C     Load catalog file.
      !>     C
      !>           CALL STCL01 ( CATFN, TABNAM, HANDLE )
      !>     C
      !>     C     Search through the loaded catalog.
      !>     C
      !>           CALL STCF01 ( TABNAM, RAMIN,  RAMAX,
      !>          .              DECMIN, DECMAX, NSTARS )
      !>     C
      !>     C     Retrieve data for every star found.
      !>     C
      !>           DO I = 1, NSTARS
      !>
      !>              CALL STCG01 ( I, RA, DEC, RASIG, DECSIG,
      !>          .                 CATNUM, SPTYPE, VMAG )
      !>
      !>           END DO
      !>
      !>## Restrictions
      !>
      !>     1)  The catalog file STCG01 reads data from MUST be loaded
      !>         by STCL01 and a search through the catalog MUST be done by
      !>         STCF01 before STCG01 is called.
      !>
      !>     2)  No other EK queries can be made between the call to STCF01
      !>         and the call to STCG01.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 16-JUN-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Updated header to comply with NAIF standard. Corrected argument
      !>        names "RASIG" and "DECSIG" in $Brief_I/O.
      !>
      !>        Updated entry #3 in $Exceptions section.
      !>
      !>-    SPICELIB Version 1.0.0, 15-MAY-1996 (BVS)
      module subroutine stcg01 ( ctx, index, ra, dec, rasig, decsig, catnum, sptype, vmag )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: rpd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: index  !! Star index.
      real(wp), intent(out) :: ra  !! Right ascension in radians.
      real(wp), intent(out) :: dec  !! Declination in radians.
      real(wp), intent(out) :: rasig  !! Right ascension uncertainty in radians.
      real(wp), intent(out) :: decsig  !! Declination uncertainty in radians.
      integer(ip), intent(out) :: catnum  !! Catalog number.
      character(*), intent(out) :: sptype  !! Spectral type.
      real(wp), intent(out) :: vmag  !! Visual magnitude.

!
!     Local variables.
!
      logical :: found
      logical :: null

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Fetch data from the catalog in the following order
!     as defined QUERY string template in STCF01 routine
!
!           RA, DEC, RASIG, DECSIG, CATNUM, SPTYPE, VMAG
!
!     Check FOUNDs and report error if any of the parameters
!     is not found.
!
!     Since NULLs are not allowed in any of the star catalog
!     columns, no check for NULLs is performed.
!
      call ekgd ( ctx,  1, index, 1, ra, null, found )
      if ( .not. found ) then
         call ctx%setmsg ( 'RA value for star # not found. '    )
         call ctx%errint ( '#', index                           )
         call ctx%sigerr ( 'SPICE(BADSTARINDEX)'                )
         return
      end if

      call ekgd ( ctx,  2, index, 1, dec, null, found )
      if ( .not. found ) then
         call ctx%setmsg ( 'DEC value for star # not found. '   )
         call ctx%errint ( '#', index                           )
         call ctx%sigerr ( 'SPICE(BADSTARINDEX)'                )
         return
      end if

      call ekgd ( ctx,  3, index, 1, rasig, null, found )
      if ( .not. found ) then
         call ctx%setmsg ( 'RASIG value for star # not found. ' )
         call ctx%errint ( '#', index                           )
         call ctx%sigerr ( 'SPICE(BADSTARINDEX)'                )
         return
      end if

      call ekgd ( ctx,  4, index, 1, decsig, null, found )
      if ( .not. found ) then
         call ctx%setmsg ( 'DECSIG value for star # not found.' )
         call ctx%errint ( '#', index                           )
         call ctx%sigerr ( 'SPICE(BADSTARINDEX)'                )
         return
      end if

      call ekgi ( ctx,  5, index, 1, catnum, null, found )
      if ( .not. found ) then
         call ctx%setmsg ( 'CATNUM value for star # not found.' )
         call ctx%errint ( '#', index                           )
         call ctx%sigerr ( 'SPICE(BADSTARINDEX)'                )
         return
      end if

      call ekgc ( ctx,  6, index, 1, sptype, null, found )
      if ( .not. found ) then
         call ctx%setmsg ( 'SPTYPE value for star # not found.' )
         call ctx%errint ( '#', index                           )
         call ctx%sigerr ( 'SPICE(BADSTARINDEX)'                )
         return
      end if

      call ekgd ( ctx,  7, index, 1, vmag, null, found )
      if ( .not. found ) then
         call ctx%setmsg ( 'VMAG value for star # not found. '  )
         call ctx%errint ( '#', index                           )
         call ctx%sigerr ( 'SPICE(BADSTARINDEX)'                )
         return
      end if

!
!     Convert angles to radians before return.
!
      ra     = ra     * rpd
      dec    = dec    * rpd
      rasig  = rasig  * rpd
      decsig = decsig * rpd

      return
      end subroutine stcg01

      !> Load SPICE type 1 star catalog and return the catalog's
      !> table name.
      !>
      !>## Detailed Input
      !>
      !>     CATFNM   is the name of the catalog file.
      !>
      !>## Detailed Output
      !>
      !>     TABNAM   is the name of the table loaded from the catalog
      !>              file. This name must be provided as an input argument
      !>              to STCF01 catalog search routine. Multiple catalogs
      !>              containing the table TABNAM may be loaded. Sets of
      !>              columns, column names and attributes must be
      !>              identical through all these files.
      !>
      !>     HANDLE   is the integer handle of the catalog file.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the indicated file cannot be opened, an error is signaled
      !>         by a routine in the call tree of this routine.
      !>
      !>     2)  If the indicated file has the wrong architecture version, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     3)  If an I/O error occurs while reading the indicated file, the
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     4)  If the catalog file is not a type 1 star catalog file, the
      !>         error SPICE(BADCATALOGFILE) is signaled.
      !>
      !>## Files
      !>
      !>     This routine loads a SPICE type 1 star catalog file.
      !>
      !>     SPICE type 1 star catalog files MUST contain a single data table.
      !>     It can occupy a single segment or it can spread across multiple
      !>     segments. This table MUST include the following columns:
      !>
      !>        column name                data type          units
      !>        ----------------------------------------------------
      !>        RA                   DOUBLE PRECISION        DEGREES
      !>        DEC                  DOUBLE PRECISION        DEGREES
      !>        RA_SIGMA             DOUBLE PRECISION        DEGREES
      !>        DEC_SIGMA            DOUBLE PRECISION        DEGREES
      !>        CATALOG_NUMBER       INTEGER
      !>        SPECTRAL_TYPE        CHARACTER*(4)
      !>        VISUAL_MAGNITUDE     DOUBLE PRECISION
      !>
      !>     Nulls are not allowed in any of the columns.
      !>     Other columns can also be present in the table but their data
      !>     will NOT be accessible through STCF01 and STCG01 --
      !>     the interface used to access data in the catalog. Note
      !>     that the names and attributes of these additional columns
      !>     must be identical for all segments containing this table.
      !>
      !>## Particulars
      !>
      !>     This STCL01 routine is intended to be part of the user
      !>     interface to the SPICE type 1 star catalog. It loads a
      !>     SPICE type 1 star catalog file and makes its data available
      !>     for searches and retrieval.
      !>
      !>     Other routines in SPICE type 1 star catalog access family are:
      !>
      !>        STCF01  search through the catalog for all stars within
      !>                a specified RA-DEC rectangle.
      !>
      !>        STCG01  retrieve position and characteristics for
      !>                every single star found.
      !>
      !>## Examples
      !>
      !>     In the following code fragment, STCL01 is used to load
      !>     a SPICE type 1 star catalog.
      !>
      !>     C
      !>     C     Load catalog file.
      !>     C
      !>           CALL STCL01 ( CATFN, TABNAM, HANDLE )
      !>     C
      !>     C     Search through the loaded catalog.
      !>     C
      !>           CALL STCF01 ( TABNAM, RAMIN,  RAMAX,
      !>          .              DECMIN, DECMAX, NSTARS )
      !>     C
      !>     C     Retrieve data for every star that matched the
      !>     C     search criteria.
      !>     C
      !>           DO I = 1, NSTARS
      !>
      !>              CALL STCG01 ( I, RA, DEC, RASIG, DECSIG,
      !>          .                 CATNUM, SPTYPE, VMAG )
      !>
      !>           END DO
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.2.0, 20-AUG-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.1.0, 18-JUN-1999 (WLT)
      !>
      !>        Balanced calls to CHKIN/CHKOUT.
      !>
      !>-    SPICELIB Version 1.0.0, 15-MAY-1996 (BVS)
      module subroutine stcl01 ( ctx, catfnm, tabnam, handle )
      use pepper_kinds, only: ip
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: catfnm  !! Catalog file name.
      character(*), intent(out) :: tabnam  !! Catalog table name.
      integer(ip), intent(out) :: handle  !! Catalog file handle.

      logical :: istyp1
      character(256) :: errmsg

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Check whether the file is really a type 1 star catalog file.
!     If not then signal an error.
!
      call stcc01 ( ctx, catfnm, tabnam, istyp1, errmsg )

      if ( .not. istyp1 ) then
         call ctx%setmsg ('File # is not type 1 star catalog ' // &
                         'file.' // errmsg                  )
         call ctx%errch  ( '#', catfnm                          )
         call ctx%sigerr ( 'SPICE(BADCATALOGFILE)'              )
         return
      end if

!
!     Load the catalog file with the high level EK loader.
!
      call eklef  ( ctx, catfnm, handle )

      return
      end subroutine stcl01

      !> Check and resolve a specified column name in an encoded EK query.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines.  Users should not call this routine directly due
      !> to the volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     QUERY          is the original query from which EQRYI and EQRYC
      !>                    were obtained.  QUERY is used only for
      !>                    construction of error messages.
      !>
      !>     EQRYI          is the integer portion of an encoded EK query.
      !>                    The query must have been parsed.
      !>
      !>     EQRYC          is the character portion of an encoded EK query.
      !>
      !>     NTAB           is the number of tables in the FROM clause of
      !>                    the input query.
      !>
      !>     TABLST         is a list of table names present in the FROM
      !>                    clause of the input query.
      !>
      !>     ALSLST         is a list of table aliases present in the FROM
      !>                    clause of the input query.  Absent aliases are
      !>                    represented by blank strings.
      !>
      !>     BASE           is the base address of a pair of descriptors
      !>                    for a qualified column.  The column may appear on
      !>                    either side of a query constraint, or it may
      !>                    appear in an order-by clause.
      !>
      !>## Detailed Output
      !>
      !>     EQRYI          is the integer portion of an encoded EK query.
      !>                    On output, the specified column will have been
      !>                    resolved and checked.  Specifically, the table
      !>                    descriptor will have the ordinal position of the
      !>                    table in the FROM clause filled in, and the
      !>                    index of the column within the virtual table
      !>                    containing it will be filled in.
      !>
      !>     EQRYC          is the character portion of an encoded EK query.
      !>
      !>     ERROR          is a logical flag indicating whether an error was
      !>                    detected.  The error could be a name resolution
      !>                    error or a semantic error.
      !>
      !>     ERRMSG         is an error message describing an error in the
      !>                    input query, if one was detected.  If ERROR is
      !>                    returned .FALSE., then ERRPTR is undefined.
      !>
      !>     ERRPTR         is the character position in the original query
      !>                    at which an error was detected, if an error was
      !>                    found.  This index refers to the offending lexeme's
      !>                    position in the original query represented by the
      !>                    input encoded query.  If ERROR is returned .FALSE.,
      !>                    ERRPTR is undefined.
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input query is not initialized, the error will be
      !>         diagnosed by routines called by this routine.  The outputs
      !>         will not be modified.
      !>
      !>     2)  If the input query has not been parsed, the error
      !>         SPICE(QUERYNOTPARSED) will be signaled.  The outputs
      !>         will not be modified.
      !>
      !>     3)  If any sort of name resolution error or semantic error is
      !>         detected in the input query, the output flag ERROR is set,
      !>         and an error message is returned.  The checks performed by
      !>         this routine are listed below:
      !>
      !>           - No column name may be qualified with a name that is not
      !>             the name or alias of a table in the FROM clause.
      !>
      !>           - Each qualified column must be present in the table
      !>             indicated by its qualifying name.
      !>
      !>           - Each unqualified column name must be the name of a
      !>             column present in exactly one of the tables listed in the
      !>             FROM clause.
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine exists for the sole purpose of centralizing code
      !>     used in multiple places by the name resolver ZZEKNRES.
      !>
      !>     This routine assumes that encoded EK query architecture version
      !>     1 is to be used with the query to be initialized; this routine
      !>     will not work with any other architecture version.
      !>
      !>## Examples
      !>
      !>     See ZZEKNRES.
      !>
      !>## Restrictions
      !>
      !>     1) This routine relies on the internals of the EK encoded query
      !>        structure.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.1, 03-OCT-2021 (NJB)
      !>
      !>        Corrected typos in comments.
      !>
      !>-    SPICELIB Version 1.1.0, 15-OCT-1996 (NJB)
      !>
      !>        Error checking of column string bounds was added.
      !>
      !>-    SPICELIB Version 1.0.0, 26-SEP-1995 (NJB)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.1.0, 15-OCT-1996 (NJB)
      !>
      !>        Error checking of column string bounds was added.  These
      !>        bounds should never be out of range, but if they are, the
      !>        error diagnosis should be more graceful than a memory
      !>        violation.
      module subroutine zzekcchk ( ctx, query, eqryi, eqryc, ntab, tablst, alslst, base, error, errmsg, errptr )
      use pepper_kinds, only: ip
      use pepper_strings, only: repmc_inplace
      use pepper_inc_ekattdsc
      use pepper_inc_ekbool
      use pepper_inc_ekcnamsz
      use pepper_inc_ekqlimit
      use pepper_inc_ekquery
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: query  !! Original query string.
      integer(ip), intent(inout) :: eqryi ( lbcell : * )  !! Integer component of query.
      character(*), intent(inout) :: eqryc  !! Character component of query.
      integer(ip), intent(in) :: ntab  !! Number of tables in FROM clause.
      character(*), intent(in) :: tablst ( * )  !! List of table names.
      character(*), intent(in) :: alslst ( * )  !! List of table aliases.
      integer(ip), intent(in) :: base  !! Base address of table/column descriptor pair.
      logical, intent(out) :: error  !! Error flag.
      character(*), intent(out) :: errmsg  !! Error message.
      integer(ip), intent(out) :: errptr  !! Position in query where error was detected.

      character(cnamsz) :: column
      character(1) :: ctouch

      integer(ip) :: attdsc ( adscsz )
      integer(ip) :: cb
      integer(ip) :: cc
      integer(ip) :: ce
      integer(ip) :: colidx
      integer(ip) :: i
      integer(ip) :: iparse
      integer(ip) :: j
      integer(ip) :: lxb ( 2 )
      integer(ip) :: nmatch
      integer(ip) :: tabidx
      integer(ip) :: tb
      integer(ip) :: te

      logical :: fnd
      logical :: noname

!
!     No error to start with.
!
      error  =  .false.
      errmsg =  ' '
      errptr =  0

      ctouch =  query(1:1)

!
!     The query must have been parsed at this point, or it's no go.
!
      call zzekreqi ( ctx, eqryi, 'PARSED', iparse )

      if ( ctx%failed() ) return

      if ( iparse == ifalse ) then

         call ctx%setmsg ( 'Encoded query has not been parsed.'  )
         call ctx%sigerr ( 'SPICE(QUERYNOTPARSED)'               )
         return

      end if

!
!     Get the name and lexeme pointers for both the table and column.
!     Decide whether a table name was supplied.
!
      tb      =  eqryi ( base + eqbstr )
      te      =  eqryi ( base + eqestr )
      lxb(1)  =  eqryi ( base + eqblex )

      cb      =  eqryi ( base + eqvdsz + eqbstr )
      ce      =  eqryi ( base + eqvdsz + eqestr )
      lxb(2)  =  eqryi ( base + eqvdsz + eqblex )

      if (  ( cb <= 0 )  .or.  ( ce <= 0 )  ) then

         call ctx%setmsg ( 'Invalid string bounds #:# for column.  ' // &
                       'Column name descriptor base is #.'       )
         call ctx%errint ( '#',  cb                                  )
         call ctx%errint ( '#',  ce                                  )
         call ctx%errint ( '#',  base                                )
         call ctx%sigerr ( 'SPICE(BUG)'                              )
         return

      end if

      noname  =  tb == 0

      if ( noname ) then
!
!        If no table name is present, search for the LHS column among
!        the tables in the FROM clause.  If exactly one table
!        contains the column, that table is considered to be the
!        qualifying table.  Otherwise, the qualification is in error.
!
         nmatch = 0

         do i = 1, ntab

            call ekccnt ( ctx, tablst(i), cc  )

            do j = 1, cc

               call ekcii ( ctx, tablst(i),  j,  column,  attdsc )

               if (  eqryc(cb:ce) == column ) then
                  nmatch  =  nmatch + 1
                  colidx  =  j
                  tabidx  =  i
               end if

            end do

         end do

         if ( nmatch == 0 ) then

            error  = .true.
            errmsg = 'Column <#> is not present in any table in FROM '// &
                     'clause.'

            call repmc_inplace ( errmsg, '#', eqryc(cb:ce) )

            errptr = lxb(2)
            return

         else if ( nmatch > 1 ) then

            error  = .true.
            errmsg = 'Column name <#> is ambiguous; a qualifying '// &
                     'table name or alias is required.'

            call repmc_inplace ( errmsg, '#', eqryc(cb:ce) )

            errptr = lxb(2)
            return

         end if

      else

!
!        Find the qualifying name in the FROM table list.  If the
!        name is not there, look in the alias list.
!
         tabidx  =  findloc(tablst(1:ntab), eqryc(tb:te), dim=1)

         if ( tabidx == 0 ) then
            tabidx  =  findloc(alslst(1:ntab), eqryc(tb:te), dim=1)
         end if

!
!        If the table name wasn't in either list, we can't use it.
!
         if ( tabidx == 0 ) then

            error  = .true.
            errmsg = 'Table name <#> is not present in FROM clause.'

            call repmc_inplace ( errmsg, '#', eqryc(tb:te) )

            errptr = lxb(1)
            return

         end if

!
!        Check the column.  This column must be present in the
!        table that qualifies it.
!
         call ekccnt ( ctx, tablst(tabidx), cc  )

         fnd  =  .false.
         i    =   1

         do while (  ( i <= cc )  .and. ( .not. fnd )  )

            call ekcii ( ctx, tablst(tabidx),  i,  column,  attdsc )

            if ( eqryc(cb:ce) == column ) then
               fnd     =  .true.
               colidx  =  i
            else
               i       =  i + 1
            end if

         end do

         if ( .not. fnd ) then

            error  =  .true.
            errmsg =  'Column <#> does not exist in table <#>.'

            call repmc_inplace ( errmsg, '#', eqryc(cb:ce) )
            call repmc_inplace ( errmsg, '#', eqryc(tb:te) )

            errptr = lxb(2)
            return

         end if

      end if

!
!     If we got this far, the table and column check out.  Fill in the
!     table and column indices in their respective descriptors.
!
      eqryi ( base +          eqtord )  =  tabidx
      eqryi ( base + eqvdsz + eqcidx )  =  colidx

      return
      end subroutine zzekcchk

      !> Given an encoded query, parse the name of a column appearing in
      !> that query, returning full particulars concerning the column and
      !> its parent table.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines.  Users should not call this routine directly due
      !> to the volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     QCOL           is a column name from an EK query.  QCOL may be
      !>                    qualified by a table name, in which case it
      !>                    conforms to the sytax
      !>
      !>                       <identifier> . <identifier>
      !>
      !>                    or QCOL may be unqualified, in which case it
      !>                    is simply an <identifier> in the EK query language.
      !>
      !>     EQRYI          is the integer portion of an encoded EK query.
      !>                    The query must have been parsed.
      !>
      !>     EQRYC          is the character portion of an encoded EK query.
      !>
      !>## Detailed Output
      !>
      !>     TABLE          is the name of the table containing the column
      !>                    identified by QCOL.  If QCOL contains a table name
      !>                    to begin with, TABLE is that name, converted to
      !>                    upper case.
      !>
      !>     ALIAS          is the alias of the table containing the column
      !>                    identified by QCOL, if an alias for that table is
      !>                    present in the input query.  If QCOL contains a
      !>                    table alias to begin with, TABLE is that alias,
      !>                    converted to upper case.
      !>
      !>     TABIDX         is the ordinal position in the FROM clause of the
      !>                    input query of the table containing the column
      !>                    designated by QCOL.
      !>
      !>     COLUMN         is the name of the column designated by QCOL,
      !>                    converted to upper case.
      !>
      !>     COLIDX         is the ordinal position column designated by QCOL
      !>                    with respect to the virtual table containing that
      !>                    column.
      !>
      !>     ERROR          is a logical flag indicating whether QCOL was
      !>                    parsed correctly.  The previous list of outputs
      !>                    are undefined if a parse error occurred.  ERROR
      !>                    is returned .TRUE. if a parse error occurred,
      !>                    .FALSE. otherwise.
      !>
      !>     ERRMSG         is a character string describing the cause of a
      !>                    parse error, if such an error occurred.  Otherwise,
      !>                    ERRMSG is returned blank.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input query is not initialized, the error will be
      !>         diagnosed by routines called by this routine.  The outputs
      !>         will not be modified.
      !>
      !>     2)  If the input query has not been semantically checked, the
      !>         error SPICE(NOTSEMCHECKED) will be signaled.  The outputs
      !>         will not be modified.
      !>
      !>     3)  If the input QCOL does not parse as a qualified or
      !>         unqualified column name, the error flag and message will
      !>         indicate that a parse error occurred.  No error will be
      !>         signaled.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine supports parsing of the SELECT clause of EK
      !>     queries by higher-level routines.  This routine is
      !>     superseded by the SPICELIB routine EKPSEL.
      !>
      !>## Examples
      !>
      !>     1)  Suppose that EQRYI and EQRYC have been obtained by
      !>         encoding the query
      !>
      !>            'SELECT T1.COL1, T2.COL2 FROM TABLE1 T1, TABLE2 T2'
      !>
      !>         Suppose also that the table TABLE1 contains two columns
      !>         named COL1 and COL2, and that the columns occur in that
      !>         order in the table.
      !>
      !>         Then the call
      !>
      !>            CALL ZZEKPCOL ( 'T1.COL', EQRYI,  EQRYC,  TABLE, ALIAS,
      !>           .                TABIDX,   COLUMN, COLIDX, ERROR, ERRMSG )
      !>
      !>         will return
      !>
      !>            TABLE  =  'TABLE1'
      !>            ALIAS  =  'T1'
      !>            TABIDX =  1
      !>            COLUMN =  'COL1'
      !>            COLIDX =  1
      !>            ERROR  =  .FALSE.
      !>            ERRMSG =  ' '
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 02-OCT-2021 (NJB)
      !>
      !>        Corrected typos in comments.
      !>
      !>-    Beta Version 1.0.0, 11-OCT-1995 (NJB)
      module subroutine zzekpcol ( ctx, qcol, eqryi, eqryc, table, alias, tabidx, column, colidx, error, errmsg )
      use pepper_kinds, only: ip, wp
      use pepper_strings, only: ucase, repmc_inplace
      use pepper_inc_ekattdsc
      use pepper_inc_ekbool
      use pepper_inc_ekcnamsz
      use pepper_inc_ekqlimit
      use pepper_inc_ekquery
      use pepper_inc_ektnamsz
      use pepper_inc_ektokn
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: qcol  !! Column name, possibly qualified.
      integer(ip), intent(in) :: eqryi ( lbcell : * )  !! Integer component of query.
      character(*), intent(in) :: eqryc  !! Character component of query.
      character(*), intent(out) :: table  !! Name of table qualifying column.
      character(*), intent(out) :: alias  !! Alias of table, if present.
      integer(ip), intent(out) :: tabidx  !! Index of TABLE in FROM clause, if known.
      character(*), intent(out) :: column  !! Name of QCOL, unqualified.
      integer(ip), intent(out) :: colidx  !! Index of QCOL within its parent virtual table.
      logical, intent(out) :: error  !! Error flag.
      character(*), intent(out) :: errmsg  !! Parse error message.

      integer(ip), parameter :: long = 160

      character(tnamsz), allocatable :: alslst ( : )
      character(long) :: chrbuf
      character(tnamsz), allocatable :: tablst ( : )
      character(cnamsz) :: tmpcol
      character(tnamsz) :: tmptab

      real(wp) :: numvls ( 3 )

      integer(ip) :: attdsc ( adscsz )
      integer(ip) :: cc
      integer(ip) :: chbegs ( 3 )
      integer(ip) :: chends ( 3 )
      integer(ip) :: i
      integer(ip) :: icheck
      integer(ip) :: j
      integer(ip) :: lxbegs ( 3 )
      integer(ip) :: lxends ( 3 )
      integer(ip) :: nmatch
      integer(ip) :: ntab
      integer(ip) :: ntoken
      integer(ip) :: tokens ( 3 )
      integer(ip) :: values ( 3 )

      logical :: fnd
      logical :: qual

      error   =  .false.
      errmsg  = ' '

      call zzekreqi ( ctx, eqryi, 'SEM_CHECKED', icheck )

      if ( ctx%failed() ) return

!
!     Make sure the encoded query is in order before proceeding.
!
      if ( icheck == ifalse ) then

         call ctx%setmsg ( 'Encoded query has not yet been semantically '// &
                       'checked.'                                     )
         call ctx%sigerr ( 'SPICE(NOTSEMCHECKED)'                         )
         return

      end if

!
!     Scan the input column name.  There are only two valid token
!     sequences possible:
!
!        <identifier>
!
!        <identifier> . <identifier>
!
!     ZZEKSCAN should therefore return 1 or 3 tokens.
!
      call zzekscan ( ctx, qcol,   3,      0,      ntoken, tokens, &
                      lxbegs, lxends, values, numvls, chrbuf, &
                      chbegs, chends, error,  errmsg          )

      if ( error ) return

      if ( ntoken == 1 ) then

         if ( tokens(1) /= tkid ) then

            error  = .true.
            errmsg = 'Invalid column name; name should consist of ' // &
                     'an identifier.'
            return

         end if

         call ucase ( qcol, column )
         qual   =  .false.

      else if ( ntoken == 3 ) then

         if ( tokens(1) /= tkid  ) then

            error  = .true.
            errmsg = 'Invalid table name; name should consist of ' // &
                     'an identifier.'
            return

         else if ( tokens(2) /= tkdot ) then

            error  = .true.
            errmsg = 'Invalid qualified column name; table name ' // &
                     'should be followed by a period.'
            return

         else if ( tokens(3) /= tkid ) then

            error  = .true.
            errmsg = 'Invalid column name; name should consist of ' // &
                     'an identifier.'
            return

         end if

         i       =  values(1)
         j       =  values(3)
         tmptab  =  chrbuf ( chbegs(i) : chends(i) )
         column  =  chrbuf ( chbegs(j) : chends(j) )
         qual    = .true.

      else

         error  = .true.
         errmsg = 'Invalid tokens present in qualified column name. ' // &
                  'Valid syntax is <column> or <table>.<column>'
         return

      end if

!
!     At this point, COLUMN and QUAL are set.  If a qualifying table
!     or alias was supplied, that string is stored in TMPTAB.  Both
!     COLUMN and TMPTAB are in upper case.
!
!     If we got this far, we'll need to look up the table names and
!     aliases from the query.
!
      call zzekreqi ( ctx, eqryi,  'NUM_TABLES', ntab   )
      allocate ( alslst(max(ntab,1)), tablst(max(ntab,1)) )

      do i = 1, ntab
         call zzekqtab ( ctx, eqryi, eqryc, i, tablst(i), alslst(i) )
      end do

!
!     If QCOL contains a table name, look for that name in the
!     table list, and if necessary, in the alias list.
!
      if ( qual ) then

         tabidx  =  findloc(tablst(1:ntab), tmptab, dim=1)

         if ( tabidx == 0 ) then
            tabidx = findloc(alslst(1:ntab), tmptab, dim=1)
         end if

!
!        If we didn't find the table name in either list, it's just
!        plain wrong.
!
         if ( tabidx == 0 ) then
            error  =  .true.
            errmsg =  'Table name <#> does not match table or alias '// &
                      'from query.'
            call repmc_inplace ( errmsg, '#', tmptab )
            return
         end if

!
!        At this point, TABIDX is valid.  Locate the column within
!        the table.
!
         call ekccnt ( ctx, tablst(tabidx), cc )

         if ( ctx%failed() ) return

         fnd   =  .false.
         j     =   1

         do while (  ( j <= cc ) .and. ( .not. fnd )  )

            call ekcii ( ctx, tablst(tabidx), j, tmpcol, attdsc )

            if ( tmpcol == column ) then
               colidx  =  j
               fnd     =  .true.
            else
               j       = j + 1
            end if

         end do

         if ( .not. fnd ) then

            error  =  .true.
            errmsg =  'Column name <#> does not appear in the '// &
                      'qualifying table <#>.'
            call repmc_inplace ( errmsg, '#', column )
            call repmc_inplace ( errmsg, '#', tmptab )
            return

         end if
!
!        At this point, TABIDX and COLIDX are set correctly.
!

      else
!
!        No qualifying table name was supplied.  COLUMN had better
!        be a unique column name among the set of columns belong to
!        tables in the FROM clause of the input query.  Check the
!        columns for each table in the FROM clause, looking for
!        matches.
!
         nmatch  =  0

         do i  = 1, ntab

            call ekccnt ( ctx, tablst(i), cc )

            if ( ctx%failed() ) return

            do j = 1, cc

               call ekcii ( ctx, tablst(i), j, tmpcol, attdsc )

               if (  tmpcol == column ) then
                  nmatch = nmatch + 1
                  column = tmpcol
                  colidx = j
                  tabidx = i
               end if

            end do

         end do
!
!        Check to see whether we have the unique identification we're
!        hoping for.
!
         if ( nmatch == 0 ) then

            error  =  .true.
            errmsg =  'Column name <#> does not appear in any table '// &
                      'in FROM clause of query.'
            call repmc_inplace ( errmsg, '#', column )
            return

         else if ( nmatch > 1 ) then

            error  =  .true.
            errmsg =  'Column name <#> is ambiguous without '// &
                      'a qualifying table name.'
            call repmc_inplace ( errmsg, '#', column )
            return

         end if
!
!        At this point, COLUMN, TABIDX and COLIDX are set correctly.
!

      end if

!
!     At this point, COLUMN, TABIDX and COLIDX are set correctly,
!     regardless of whether the input name was qualified.  Fill the rest
!     of our output variables.
!
      table  =  tablst ( tabidx )
      alias  =  alslst ( tabidx )

      return
      end subroutine zzekpcol

      !> Semantically check an encoded EK query.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines.  Users should not call this routine directly due
      !> to the volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     QUERY          is the original query from which EQRYI and EQRYC
      !>                    were obtained.  QUERY is used only for
      !>                    construction of error messages.
      !>
      !>     EQRYI          is the integer portion of an encoded EK query.
      !>                    The query must have been parsed and must have
      !>                    its table and column names resolved.  Time values
      !>                    must also have been resolved.
      !>
      !>     EQRYC          is the character portion of an encoded EK query.
      !>
      !>## Detailed Output
      !>
      !>     EQRYI          is the integer portion of an encoded EK query.
      !>                    On output, semantic checking will have been
      !>                    performed.
      !>
      !>     EQRYC          is the character portion of an encoded EK query.
      !>
      !>     ERROR          is a logical flag indicating whether a semantic
      !>                    error was detected.
      !>
      !>     ERRMSG         is an error message describing a semantic error,
      !>                    if such an error was detected.  If ERROR is
      !>                    returned .FALSE., then ERRPTR is undefined.
      !>
      !>     ERRPTR         is the character position in the original query
      !>                    at which a semantic error was detected, if the
      !>                    input query contains a semantic error.  This
      !>                    index refers to the offending lexeme's position in
      !>                    the original query represented by the input encoded
      !>                    query.  If ERROR is returned .FALSE., ERRPTR is
      !>                    undefined.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If no EK files are loaded at the time this routine is called,
      !>         the error will be diagnosed by routines called by this
      !>         routine.
      !>
      !>     2)  If the input query is not initialized, the error will be
      !>         diagnosed by routines called by this routine.  The outputs
      !>         will not be modified.
      !>
      !>     3)  If the input query has not had its names resolved, the error
      !>         SPICE(UNRESOLVEDNAMES) will be signaled.  The outputs
      !>         will not be modified.
      !>
      !>     4)  If the input query contains time values that have not been
      !>         resolved, the error SPICE(UNRESOLVEDTIMES) will be signaled.
      !>         The outputs will not be modified.
      !>
      !>     5)  If any sort of semantic error is detected in the input query,
      !>         the output flag ERROR is set, an error message is returned,
      !>         and LXBEG and LXEND are set to indicate the location of the
      !>         first lexeme at which an error was detected.
      !>
      !>         The checks performed by this routine are listed below:
      !>
      !>           - Constraints comparing values from two columns must
      !>             refer to columns having identical data types, or else
      !>             both types must be numeric.
      !>
      !>           - Constraints comparing values from a column with literal
      !>             values must refer to columns having the data type of the
      !>             literal value.
      !>
      !>           - The LIKE and NOT LIKE operators may be used only with
      !>             string values.
      !>
      !>           - Columns named in constraints must be scalar-valued.
      !>
      !>           - Columns named as order-by columns must be scalar-valued.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     The semantic checking performed by this routine is dependent on
      !>     the kernels loaded at the time this routine is called.
      !>
      !>     This routine assumes that encoded EK query architecture version
      !>     1 is to be used with the query to be initialized; this routine
      !>     will not work with any other architecture version.
      !>
      !>## Examples
      !>
      !>     See EKFIND.
      !>
      !>## Restrictions
      !>
      !>     1) Loading or unloading EK files between name resolution of the
      !>        the input query and passing the query to this routine will
      !>        invalidate the checking done by this routine, and may cause
      !>        the routine to fail.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 03-OCT-2021 (NJB)
      !>
      !>        Corrected typos in comments.
      !>
      !>-    Beta Version 1.0.0, 23-OCT-1995 (NJB)
      module subroutine zzeksemc ( ctx, query, eqryi, eqryc, error, errmsg, errptr )
      use pepper_kinds, only: ip
      use pepper_strings, only: repmc_inplace, repmi_inplace
      use pepper_inc_ekattdsc
      use pepper_inc_ekbool
      use pepper_inc_ekcnamsz
      use pepper_inc_ekopcd
      use pepper_inc_ekquery
      use pepper_inc_ektnamsz
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: query  !! Original query.
      integer(ip), intent(inout) :: eqryi ( lbcell : * )  !! Integer component of query.
      character(*), intent(inout) :: eqryc  !! Character component of query.
      logical, intent(out) :: error  !! Error flag.
      character(*), intent(out) :: errmsg  !! Semantic error message.
      integer(ip), intent(out) :: errptr  !! Position in query where error was detected.
!
!     Local variables
!
      character(tnamsz) :: alias
      character(cnamsz) :: colnam
      character(tnamsz) :: lhstab
      character(tnamsz) :: ordtab
      character(tnamsz) :: rhstab
      integer(ip) :: attdsc ( adscsz )
      integer(ip) :: base
      integer(ip) :: cnstyp
      integer(ip) :: colidx
      integer(ip) :: i
      integer(ip) :: irsolv
      integer(ip) :: lhssiz
      integer(ip) :: lhstyp
      integer(ip) :: lxb    ( 2 )
      integer(ip) :: lxe    ( 2 )
      integer(ip) :: ncnj
      integer(ip) :: ncns
      integer(ip) :: nord
      integer(ip) :: ntab
      integer(ip) :: opcode
      integer(ip) :: rhssiz
      integer(ip) :: rhstyp
      integer(ip) :: tabidx
      integer(ip) :: trsolv
      logical :: likeop
      logical :: nulval
      if ( .not. allocated ( ctx%zzeksemc_state ) ) allocate ( ctx%zzeksemc_state )
      associate ( typstr => ctx%zzeksemc_state%typstr )
      error   =  .false.
      errmsg  = ' '
      errptr  = 0

      call zzekreqi ( ctx, eqryi, 'NAMES_RESOLVED', irsolv )

      if ( ctx%failed() ) return

      if ( irsolv == ifalse ) then

         call ctx%setmsg ( 'Encoded query has not had names resolved.'  )
         call ctx%sigerr ( 'SPICE(UNRESOLVEDNAMES)'                     )
         return

      end if

      call zzekreqi ( ctx, eqryi, 'TIMES_RESOLVED', trsolv )

      if ( ctx%failed() ) return

      if ( trsolv == ifalse ) then

         call ctx%setmsg ( 'Encoded query has not had time values '     // &
                       'resolved.'                                  )
         call ctx%sigerr ( 'SPICE(UNRESOLVEDTIMES)'                     )
         return

      end if

!
!     Get the important counts from the query.
!
      call zzekreqi ( ctx, eqryi, 'NUM_TABLES',        ntab )
      call zzekreqi ( ctx, eqryi, 'NUM_CONSTRAINTS',   ncns )
      call zzekreqi ( ctx, eqryi, 'NUM_CONJUNCTIONS',  ncnj )
      call zzekreqi ( ctx, eqryi, 'NUM_ORDERBY_COLS',  nord )

!
!     Perform semantic checks applicable to constraints.
!
      do i = 1, ncns
!
!        Calculate the base address of the constraint.
!
         base    =  eqvbas + (ntab * 2 * eqvdsz) + (i-1)*eqcdsz

!
!        Obtain the constraint type.
!
         cnstyp  =  eqryi ( base + eqctyp )

!
!        Get the index of the table containing the LHS column, and get
!        the index of this column within that table.  Look up the
!        table name.
!
         tabidx  =  eqryi ( base + eqltab - 1 + eqtord )
         colidx  =  eqryi ( base + eqlcol - 1 + eqcidx )
         lxb(1)  =  eqryi ( base + eqlcol - 1 + eqblex )
         lxe(1)  =  eqryi ( base + eqlcol - 1 + eqelex )

         call zzekqtab ( ctx, eqryi, eqryc, tabidx, lhstab, alias )

!
!        Look up the name and attributes of the column on the LHS of the
!        constraint.
!
         call ekcii ( ctx, lhstab, colidx, colnam, attdsc )

         lhstyp  =  attdsc(atttyp)
         lhssiz  =  attdsc(attsiz)

         if ( lhssiz /= 1 ) then

            error  =  .true.
            errmsg =  'Non-scalar column <#> having size # found '  // &
                      'in query constraint.'
            call repmc_inplace ( errmsg, '#', query(lxb(1):lxe(2)) )
            call repmi_inplace ( errmsg, '#', lhssiz )

            errptr =  lxb(1)
            return

         end if

!
!        Get the operator for the current constraint.
!
         opcode  =  eqryi ( base + eqopcd )

!
!        Decide whether the constraint is an `IS NULL' or `IS NOT NULL'
!        test.
!
         nulval  =  ( opcode == isnull ) .or. ( opcode == notnul )

!
!        Check for use of the LIKE or NOT LIKE operators.  These
!        operators may be used only if the LHS column has character
!        type.
!
         likeop  =  ( opcode == like ) .or. ( opcode == unlike )

         if (  likeop  .and.  ( lhstyp /= chr )  ) then

            error  =  .true.
            errmsg = 'LIKE and NOT LIKE operators may be used only ' // &
                     'with character columns.  Column <#> has type '// &
                     '#.'

            call repmc_inplace ( errmsg, '#', query(lxb(1):lxe(1)) )
            call repmc_inplace ( errmsg, '#', typstr(lhstyp) )

            errptr  =  lxb(1)
            return

         end if

!
!        If the constraint compares two columns, get the same
!        information for the RHS column.
!
         if ( cnstyp == eqcol ) then

            tabidx  =  eqryi ( base + eqrtab - 1 + eqtord )
            colidx  =  eqryi ( base + eqrcol - 1 + eqcidx )
            lxb(2)  =  eqryi ( base + eqrcol - 1 + eqblex )
            lxe(2)  =  eqryi ( base + eqrcol - 1 + eqelex )

            call zzekqtab ( ctx, eqryi, eqryc, tabidx, rhstab, alias )

!
!           Look up the name and attributes of the column on the RHS of
!           the constraint.
!
            call ekcii ( ctx, rhstab, colidx, colnam, attdsc )

            rhstyp  =  attdsc(2)
            rhssiz  =  attdsc(4)

            if ( rhssiz /= 1 ) then

               error  =  .true.
               errmsg =  'Non-scalar column <#> having size # found '// &
                         'in query constraint.'
               call repmc_inplace ( errmsg, '#', query(lxb(1):lxe(2)) )
               call repmi_inplace ( errmsg, '#', rhssiz )

               errptr =  lxb(2)
               return

            end if

!
!           Check for data type mismatch.
!
            if ( rhstyp /= lhstyp ) then
!
!              The only allowed mismatch is between integers and
!              d.p. numbers.
!
               if (      ( lhstyp == time ) &
                    .or. ( lhstyp == chr  ) &
                    .or. ( rhstyp == time ) &
                    .or. ( rhstyp == chr  )  ) then

                  error  =  .true.
                  errmsg = 'Data type mismatch: column <#> has data ' // &
                           'type #; column <#> has data type #.'

                  call repmc_inplace (errmsg, '#', query(lxb(1):lxe(1)))
                  call repmc_inplace (errmsg, '#', typstr(lhstyp))
                  call repmc_inplace (errmsg, '#', query(lxb(2):lxe(2)))
                  call repmc_inplace (errmsg, '#', typstr(rhstyp))

                  errptr = lxb(2)
                  return

               end if

            end if

         else
!
!           The constraint compares a column against a value.  If the
!           operator is `IS NULL' or `IS NOT NULL', there are no
!           further semantic checks to be made.
!
            if ( nulval ) return

!
!           Get the data type of the value on the RHS.
!
            rhstyp  =  eqryi ( base + eqbval - 1 + eqdtyp )
            lxb(2)  =  eqryi ( base + eqbval - 1 + eqblex )
            lxe(2)  =  eqryi ( base + eqbval - 1 + eqelex )

            if ( rhstyp /= lhstyp ) then
!
!              The only allowed mismatch is between integers and
!              d.p. numbers.
!
               if (       ( lhstyp == time ) &
                     .or. ( lhstyp == chr  ) &
                     .or. ( rhstyp == time ) &
                     .or. ( rhstyp == chr  )  ) then

                  error  =  .true.
                  errmsg = 'Data type mismatch: column <#> has data ' // &
                           'type #; value <#> has data type #.'

                  call repmc_inplace (errmsg, '#', query(lxb(1):lxe(1)))
                  call repmc_inplace (errmsg, '#', typstr(lhstyp))
                  call repmc_inplace (errmsg, '#', query(lxb(2):lxe(2)))
                  call repmc_inplace (errmsg, '#', typstr(rhstyp))

                  errptr = lxb(2)
                  return

               end if

            end if

         end if

!
!        We've finished the checks on the current constraint.
!
      end do

!
!     Now check the order-by columns, if any are present.  These
!     columns must have scalar type.
!
      do i = 1, nord
!
!        Get the query column descriptor for the Ith order-by column.
!
         base   =       eqvbas &
                    +   ntab * 2 * eqvdsz &
                    +   ncnj &
                    +   ncns     * eqcdsz &
                    +   (i-1)    * eqodsz
!
!        Look up the attributes of the column.  It's the size we're
!        after.
!
         tabidx  =  eqryi ( base              + eqtord )
         colidx  =  eqryi ( base + eqocol - 1 + eqcidx )
         lxb(1)  =  eqryi ( base + eqocol - 1 + eqblex )
         lxe(1)  =  eqryi ( base + eqocol - 1 + eqelex )

         call zzekqtab ( ctx, eqryi, eqryc, tabidx, ordtab, alias )

         call ekcii ( ctx, ordtab, colidx, colnam, attdsc )

         if ( attdsc(4) /= 1 ) then

            error  =  .true.
            errmsg =  'Non-scalar column <#> having size # found '  // &
                      'in order-by column.'
            call repmc_inplace ( errmsg, '#', query(lxb(1):lxe(2)) )
            call repmi_inplace ( errmsg, '#', attdsc(4) )

            errptr =  lxb(1)
            return

         end if

      end do

!
!     Indicate completion of semantic checking.
!
      call zzekweqi ( ctx,  'SEM_CHECKED',  itrue,  eqryi  )

      return
      end associate
      end subroutine zzeksemc

      !> Resolve time values in an encoded EK query.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines.  Users should not call this routine directly due
      !> to the volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     QUERY          is the original query from which EQRYI and EQRYC
      !>                    were obtained.  QUERY is used only for
      !>                    construction of error messages.
      !>
      !>     EQRYI          is the integer portion of an encoded EK query.
      !>                    The query must have been parsed.
      !>
      !>     EQRYC          is the character portion of an encoded EK query.
      !>
      !>     EQRYD          is the numeric portion of an encoded EK query.
      !>
      !>## Detailed Output
      !>
      !>     EQRYI          is the integer portion of an encoded EK query.
      !>                    On output, all valid time values will have been
      !>                    converted from strings to equivalent numeric
      !>                    values which represent times as ephemeris
      !>                    seconds past J2000 (TDB).
      !>
      !>     EQRYC          is the character portion of an encoded EK query.
      !>
      !>     ERROR          is a logical flag indicating whether an error was
      !>                    detected.  Note that a time string might be
      !>                    syntactically valid, but incapable of being
      !>                    converted to ET if the appropriate time kernels
      !>                    (Leapseconds or SCLK) are not loaded.
      !>
      !>     ERRMSG         is an error message describing an error in the
      !>                    input query, if one was detected.  If ERROR is
      !>                    returned .FALSE., then ERRPTR is undefined.
      !>
      !>     ERRPTR         is the character position in the original query
      !>                    at which an error was detected, if an error was
      !>                    found.  This index refers to the offending lexeme's
      !>                    position in the original query represented by the
      !>                    input encoded query.  If ERROR is returned .FALSE.,
      !>                    ERRPTR is undefined.
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input query is not initialized, the error will be
      !>         diagnosed by routines called by this routine.  The outputs
      !>         will not be modified.
      !>
      !>     2)  If names have not been resolved in the input query, the error
      !>         SPICE(NAMESNOTRESOLVED) will be signaled.  The outputs
      !>         will not be modified.
      !>
      !>     3)  If any sort of time conversion error occurs, the output flag
      !>         ERROR is set, and an error message is returned.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     Strings representing time values are interpreted as follows:
      !>
      !>        1)  The string is first examined to see whether it's an
      !>            SCLK string for a recognized clock; if it is, the
      !>            string is converted to the equivalent ET.
      !>
      !>        2)  If the string is not a SCLK string, it is expected
      !>            to be some sort of UTC representation.  The string is
      !>            checked to see whether it's an ISO format UTC time that
      !>            ISO2UTC can handle.
      !>
      !>        3)  If the string does not conform to an ISO format, the
      !>            last chance is to try to get the string through
      !>            TPARSE.  If TPARSE can't deal with it, it's considered
      !>            to be invalid.
      !>
      !>     This routine assumes that encoded EK query architecture version
      !>     1 is to be used with the query to be initialized; this routine
      !>     will not work with any other architecture version.
      !>
      !>## Examples
      !>
      !>     See EKFIND.
      !>
      !>## Restrictions
      !>
      !>     1) A leapseconds kernel must be loaded at the time this routine
      !>        is called.
      !>
      !>     2) In order to convert SCLK strings, an appropriate SCLK kernel
      !>        must be loaded at the time this routine is called.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 03-OCT-2021 (NJB)
      !>
      !>        Corrected typos in comments.
      !>
      !>-    Beta Version 1.0.0, 11-OCT-1995 (NJB)
      module subroutine zzektres ( ctx, query, eqryi, eqryc, eqryd, error, errmsg, errptr )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekattdsc
      use pepper_inc_ekbool
      use pepper_inc_ekcnamsz
      use pepper_inc_ekopcd
      use pepper_inc_ekqlimit
      use pepper_inc_ekquery
      use pepper_inc_ektnamsz
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: query  !! Original query string.
      integer(ip), intent(inout) :: eqryi  ( lbcell : * )  !! Integer component of query.
      character(*), intent(inout) :: eqryc  !! Character component of query.
      real(wp), intent(inout) :: eqryd  ( * )  !! Numeric component of query.
      logical, intent(out) :: error  !! Error flag.
      character(*), intent(out) :: errmsg  !! Error message.
      integer(ip), intent(out) :: errptr  !! Position in query where error was detected.

      integer(ip), parameter :: short = 32

      character(tnamsz) :: alias  ( 1 )
      character(cnamsz) :: colnam
      character(tnamsz) :: table  ( 1 )
      character(short) :: timstr
      character(1) :: touchc

      real(wp) :: et

      integer(ip) :: attdsc ( adscsz )
      integer(ip) :: base
      integer(ip) :: cnstyp
      integer(ip) :: colidx
      integer(ip) :: descr  ( eqvdsz )
      integer(ip) :: dtype
      integer(ip) :: i
      integer(ip) :: irsolv
      integer(ip) :: lxb
      integer(ip) :: lxe
      integer(ip) :: ncns
      integer(ip) :: ntab
      integer(ip) :: opcode
      integer(ip) :: sb
      integer(ip) :: se
      integer(ip) :: tabidx

!
!     No error to start with.
!
      error  =  .false.
      errmsg =  ' '
      errptr =  0

      touchc =  query(1:1)

!
!     The query must have had names resolved at this point, or it's no
!     go.
!
      call zzekreqi ( ctx, eqryi, 'NAMES_RESOLVED', irsolv )

      if ( ctx%failed() ) return

      if ( irsolv == ifalse ) then

         call ctx%setmsg ( 'Names are not resolved in encoded query.'  )
         call ctx%sigerr ( 'SPICE(NAMESNOTRESOLVED)'                   )
         return

      end if

!
!     Time strings occur only on the right sides of constraints.
!     Examine each constraint that compares a column and a value.
!
      call zzekreqi ( ctx, eqryi, 'NUM_TABLES',      ntab )
      call zzekreqi ( ctx, eqryi, 'NUM_CONSTRAINTS', ncns )

      do i = 1, ncns
!
!        Calculate the base address of the constraint.
!
         base    =  eqvbas + (ntab * 2 * eqvdsz) + (i-1)*eqcdsz

!
!        Obtain the constraint type.  If the RHS is not a value or if
!        the RHS is null (as indicated by the opcode), we can skip it.
!
         cnstyp  =  eqryi ( base + eqctyp )
         opcode  =  eqryi ( base + eqopcd )

         if (        ( cnstyp == eqval  ) &
              .and.  ( opcode /= isnull ) &
              .and.  ( opcode /= notnul )  ) then
!
!           Get the index of the table containing the LHS column, and
!           get the index of this column within that table.  Get the
!           table name, then get the column's attributes.
!
            tabidx  =  eqryi ( base + eqltab - 1 + eqtord )
            colidx  =  eqryi ( base + eqlcol - 1 + eqcidx )

            call zzekqtab ( ctx, eqryi, eqryc, tabidx, table(1), alias(1) )

            call ekcii ( ctx, table(1), colidx, colnam, attdsc )

            dtype  =  attdsc(2)

            if ( dtype == time ) then
!
!              The RHS points to a string representing a time
!              value.
!
               lxb    =  eqryi ( base + eqbval - 1 + eqblex )
               lxe    =  eqryi ( base + eqbval - 1 + eqblex )
               sb     =  eqryi ( base + eqbval - 1 + eqbstr )
               se     =  eqryi ( base + eqbval - 1 + eqestr )
               timstr =  eqryc ( sb:se )

!
!              Convert the time to ET, if possible.
!
               call zzektcnv ( ctx, timstr, et, error, errmsg )

               if ( error ) then

                  errptr = sb
                  return

               end if
!
!              Insert the ET value into the query, and replace the
!              value descriptor for the time string.
!
               call zzekinqn ( ctx, et, time, lxb, lxe, eqryi, eqryd, descr )

               eqryi(base+eqbval:base+eqbval+eqvdsz-1) = descr

            end if
!
!           We've parsed a time string, if the current column's type
!           was TIME.
!

         end if
!
!        We've examined the current constraint, if it compares a
!        column with a value.
!

      end do

!
!     Indicate completion of time resolution.
!
      call zzekweqi ( ctx,  'TIMES_RESOLVED',  itrue,  eqryi  )

      return
      end subroutine zzektres

      !> Update a specified class 3 column entry in an EK record.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE         is a file handle of an EK open for write access.
      !>
      !>     SEGDSC         is the descriptor of the segment containing
      !>                    the specified column entry.
      !>
      !>     COLDSC         is the descriptor of the column containing
      !>                    the specified column entry.
      !>
      !>     RECPTR         is a pointer to the record containing the column
      !>                    entry to update.
      !>
      !>     CVAL           is the character string value with which to update
      !>                    the specified column entry.
      !>
      !>     ISNULL         is a logical flag indicating whether the value
      !>                    of the specified column entry is to be set to NULL.
      !>                    If so, the input CVAL is ignored.
      !>
      !>## Detailed Output
      !>
      !>     None.  See the $Particulars section for a description of the
      !>     effect of this routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, the error will be diagnosed by routines
      !>         called by this routine.  The file will not be modified.
      !>
      !>     2)  If RECNO is out of range, the error SPICE(INVALIDINDEX)
      !>         will be signaled.  The file will not be modified.
      !>
      !>     3)  If an I/O error occurs while reading or writing the indicated
      !>         file, the error will be diagnosed by routines called by this
      !>         routine.  The file may be corrupted.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects:  it updates a column entry
      !>     in an EK segment.  This routine does not participate in shadowing
      !>     functions.  If the target EK is shadowed, the caller is
      !>     responsible for performing necessary backup operations.  If the
      !>     target EK is not shadowed, the target record's status is not
      !>     modified.
      !>
      !>     If the column containing the entry is indexed, the corresponding
      !>     index is updated.
      !>
      !>     The changes made by this routine to the target EK file become
      !>     permanent when the file is closed.  Failure to close the file
      !>     properly will leave it in an indeterminate state.
      !>
      !>## Examples
      !>
      !>     See EKUCEC.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 03-OCT-2021 (NJB)
      !>
      !>        Corrected typos in comments.
      !>
      !>-    Beta Version 1.0.0, 27-SEP-1995 (NJB)
      module subroutine zzekue03 ( ctx, handle, segdsc, coldsc, recptr, cval, isnull )
      use pepper_kinds, only: ip
      use pepper_inc_ekbool
      use pepper_inc_ekcoldsc
      use pepper_inc_ekdatpag
      use pepper_inc_ekrecptr
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! File handle.
      integer(ip), intent(inout) :: segdsc ( sdscsz )  !! Segment descriptor. (PEPPER: changed by the routine, an input in SPICELIB's table)
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Record pointer.
      character(*), intent(in) :: cval  !! Character string value.
      logical, intent(in) :: isnull  !! Null flag.
!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Get rid of the old column entry first.
!
      call zzekde03 ( ctx, handle, segdsc, coldsc, recptr )

      if ( ctx%failed() ) return

!
!     We've reduced the problem to a solved one:  that of adding
!     a column entry.
!
      call zzekad03 ( ctx, handle, segdsc, coldsc, recptr, cval, isnull )

      return
      end subroutine zzekue03

      !> Update a character column entry in a specified EK record.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is a file handle attached to an EK open for
      !>              write access.
      !>
      !>     SEGNO    is the index of the segment containing the column
      !>              entry to be updated.
      !>
      !>     RECNO    is the index of the record containing the column
      !>              entry to be updated. This record number is
      !>              relative to the start of the segment indicated by
      !>              SEGNO; the first record in the segment has index 1.
      !>
      !>     COLUMN   is the name of the column containing the entry to
      !>              be updated.
      !>
      !>     NVALS,
      !>     CVALS    are, respectively, the number of values to add to
      !>              the specified column and the set of values
      !>              themselves. The data values are written in to the
      !>              specified column and record.
      !>
      !>              If the  column has fixed-size entries, then NVALS
      !>              must equal the entry size for the specified column.
      !>
      !>              For columns with variable-sized entries, the size
      !>              of the new entry need not match the size of the
      !>              entry it replaces. In particular, the new entry
      !>              may be larger.
      !>
      !>     ISNULL   is a logical flag indicating whether the entry is
      !>              null. If ISNULL is .FALSE., the column entry
      !>              defined by NVALS and CVALS is added to the
      !>              specified kernel file.
      !>
      !>              If ISNULL is .TRUE., NVALS and CVALS are ignored.
      !>              The contents of the column entry are undefined.
      !>              If the column has fixed-length, variable-size
      !>              entries, the number of entries is considered to
      !>              be 1.
      !>
      !>              The new entry may be null even though it replaces
      !>              a non-null value, and vice versa.
      !>
      !>## Detailed Output
      !>
      !>     None. See $Particulars for a description of the effect of this
      !>     routine.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If HANDLE is invalid, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     2)  If SEGNO is out of range, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     3)  If COLUMN is not the name of a declared column, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>     4)  If COLUMN specifies a column of whose data type is not
      !>         CHARACTER, the error SPICE(WRONGDATATYPE) is signaled.
      !>
      !>     5)  If RECNO is out of range, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     6)  If the specified column has fixed-size entries and NVALS does
      !>         not match this size, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     7)  If the specified column has variable-size entries and NVALS is
      !>         non-positive, an error is signaled by a routine in the call
      !>         tree of this routine.
      !>
      !>     8)  If an attempt is made to add a null value to a column that
      !>         doesn't take null values, an error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>     9)  If COLUMN specifies a column of whose class is not
      !>         a character class known to this routine, the error
      !>         SPICE(NOCLASS) is signaled.
      !>
      !>     10) If an I/O error occurs while reading or writing the indicated
      !>         file, the error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>## Files
      !>
      !>     See the EK Required Reading ek.req for a discussion of the EK file
      !>     format.
      !>
      !>## Particulars
      !>
      !>     This routine operates by side effects: it modifies the named
      !>     EK file by adding data to the specified record in the specified
      !>     column. Data may be added to a segment in random order; it is not
      !>     necessary to fill in columns or rows sequentially. Data may only
      !>     be added one logical element at a time. Partial assignments of
      !>     logical elements are not supported.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) The following program demonstrates how to create a new EK and
      !>        add data to a character column in a given record within the
      !>        file, how to update the data in this record, and how to read
      !>        the data from it.
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM EKUCEC_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Include the EK Column Name Size (CNAMSZ)
      !>C
      !>      INCLUDE 'ekcnamsz.inc'
      !>
      !>C
      !>C     Local constants.
      !>C
      !>      CHARACTER*(*)         EKNAME
      !>      PARAMETER           ( EKNAME = 'ekucec_ex1.bdb' )
      !>
      !>      CHARACTER*(*)         IFNAME
      !>      PARAMETER           ( IFNAME = 'Test EK'  )
      !>
      !>      CHARACTER*(*)         TABLE
      !>      PARAMETER           ( TABLE  = 'CHR_DATA' )
      !>
      !>      INTEGER               CVLEN
      !>      PARAMETER           ( CVLEN  = 9  )
      !>
      !>      INTEGER               DECLEN
      !>      PARAMETER           ( DECLEN = 200 )
      !>
      !>      INTEGER               MAXVAL
      !>      PARAMETER           ( MAXVAL = 4  )
      !>
      !>      INTEGER               NCOLS
      !>      PARAMETER           ( NCOLS  = 2  )
      !>
      !>      INTEGER               NROWS
      !>      PARAMETER           ( NROWS  = 6  )
      !>
      !>      INTEGER               NRESVC
      !>      PARAMETER           ( NRESVC = 0  )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(DECLEN)    CDECLS ( NCOLS  )
      !>      CHARACTER*(CNAMSZ)    CNAMES ( NCOLS  )
      !>      CHARACTER*(CVLEN)     CVALS  ( MAXVAL )
      !>
      !>      INTEGER               HANDLE
      !>      INTEGER               I
      !>      INTEGER               J
      !>      INTEGER               NVALS
      !>      INTEGER               RECNO
      !>      INTEGER               SEGNO
      !>
      !>      LOGICAL               ISNULL
      !>
      !>C
      !>C     Open a new EK file.  For simplicity, we won't
      !>C     reserve space for the comment area, so the
      !>C     number of reserved comment characters is zero.
      !>C     The constant IFNAME is the internal file name.
      !>C
      !>      CALL EKOPN ( EKNAME, IFNAME, NRESVC, HANDLE )
      !>
      !>C
      !>C     Set up the table and column names and declarations
      !>C     for the CHR_DATA segment.  We'll index all of
      !>C     the columns.
      !>C
      !>      CNAMES(1) =  'CHR_COL_1'
      !>      CDECLS(1) =  'DATATYPE = CHARACTER*(*), '
      !>     .       //    'INDEXED = TRUE, NULLS_OK = TRUE'
      !>
      !>      CNAMES(2) =  'CHR_COL_2'
      !>      CDECLS(2) =  'DATATYPE = CHARACTER*(9), '
      !>     .       //    'SIZE = VARIABLE, NULLS_OK = TRUE'
      !>
      !>C
      !>C     Start the segment.
      !>C
      !>      CALL EKBSEG ( HANDLE, TABLE,  NCOLS,
      !>     .              CNAMES, CDECLS, SEGNO )
      !>
      !>      DO I = 0, NROWS-1
      !>
      !>         CALL EKAPPR ( HANDLE, SEGNO, RECNO )
      !>
      !>         ISNULL = ( I .EQ. 1 )
      !>
      !>         CALL INTSTR ( I, CVALS(1) )
      !>         CALL EKACEC ( HANDLE, SEGNO, RECNO, CNAMES(1),
      !>     .                 1,      CVALS, ISNULL           )
      !>
      !>C
      !>C        Array-valued columns follow.
      !>C
      !>         CALL INTSTR ( 10*I,     CVALS(1) )
      !>         CALL INTSTR ( 10*I + 1, CVALS(2) )
      !>         CALL INTSTR ( 10*I + 2, CVALS(3) )
      !>         CALL INTSTR ( 10*I + 3, CVALS(4) )
      !>         CALL EKACEC ( HANDLE, SEGNO, RECNO, CNAMES(2),
      !>     .                 4,      CVALS, ISNULL           )
      !>
      !>      END DO
      !>
      !>C
      !>C     End the file.
      !>C
      !>      CALL EKCLS ( HANDLE )
      !>
      !>C
      !>C     Open the EK for write access.
      !>C
      !>      CALL EKOPW ( EKNAME, HANDLE )
      !>
      !>C
      !>C     Negate the values in the odd-numbered records
      !>C     using the update routines.
      !>C
      !>      DO I = 1, NROWS, 2
      !>
      !>         RECNO  = I+1
      !>
      !>         ISNULL = ( I .EQ. 1 )
      !>
      !>         CALL INTSTR ( -I, CVALS(1) )
      !>         CALL EKUCEC ( HANDLE, SEGNO, RECNO, CNAMES(1),
      !>     .                 1,      CVALS, ISNULL           )
      !>
      !>C
      !>C        Array-valued columns follow.
      !>C
      !>         CALL INTSTR ( -10*I,       CVALS(1) )
      !>         CALL INTSTR ( -(10*I + 1), CVALS(2) )
      !>         CALL INTSTR ( -(10*I + 2), CVALS(3) )
      !>         CALL INTSTR ( -(10*I + 3), CVALS(4) )
      !>         CALL EKUCEC ( HANDLE, SEGNO, RECNO, CNAMES(2),
      !>     .                 4,      CVALS, ISNULL           )
      !>
      !>      END DO
      !>
      !>C
      !>C     Close the file.
      !>C
      !>      CALL EKCLS ( HANDLE )
      !>
      !>C
      !>C     Open the created file. Show the values added.
      !>C
      !>      CALL EKOPR ( EKNAME, HANDLE )
      !>
      !>      DO I = 1, NROWS
      !>
      !>         CALL EKRCEC ( HANDLE, SEGNO, I,     CNAMES(1),
      !>     .                 NVALS,  CVALS, ISNULL           )
      !>
      !>         IF ( .NOT. ISNULL ) THEN
      !>
      !>            WRITE(*,*) 'Data from column: ', CNAMES(1)
      !>            WRITE(*,*) '   record number: ', I
      !>            WRITE(*,*) '   values       : ',
      !>     .                                ( CVALS(J), J=1,NVALS )
      !>            WRITE(*,*) ' '
      !>
      !>         ELSE
      !>
      !>            WRITE(*,*) 'Record ', I, 'flag is NULL.'
      !>            WRITE(*,*) ' '
      !>
      !>         END IF
      !>
      !>C
      !>C        Array-valued columns follow.
      !>C
      !>         CALL EKRCEC ( HANDLE, SEGNO, I,     CNAMES(2),
      !>     .                 NVALS,  CVALS, ISNULL           )
      !>
      !>         IF ( .NOT. ISNULL ) THEN
      !>
      !>            WRITE(*,*) 'Data from column: ', CNAMES(2)
      !>            WRITE(*,*) '   record number: ', I
      !>            WRITE(*,*) '   values       : ',
      !>     .                                ( CVALS(J), J=1,NVALS )
      !>            WRITE(*,*) ' '
      !>
      !>         END IF
      !>
      !>      END DO
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Data from column: CHR_COL_1
      !>            record number:            1
      !>            values       : 0
      !>
      !>         Data from column: CHR_COL_2
      !>            record number:            1
      !>            values       : 0        1        2        3
      !>
      !>         Record            2 flag is NULL.
      !>
      !>         Data from column: CHR_COL_1
      !>            record number:            3
      !>            values       : 2
      !>
      !>         Data from column: CHR_COL_2
      !>            record number:            3
      !>            values       : 20       21       22       23
      !>
      !>         Data from column: CHR_COL_1
      !>            record number:            4
      !>            values       : -3
      !>
      !>         Data from column: CHR_COL_2
      !>            record number:            4
      !>            values       : -30      -31      -32      -33
      !>
      !>         Data from column: CHR_COL_1
      !>            record number:            5
      !>            values       : 4
      !>
      !>         Data from column: CHR_COL_2
      !>            record number:            5
      !>            values       : 40       41       42       43
      !>
      !>         Data from column: CHR_COL_1
      !>            record number:            6
      !>            values       : -5
      !>
      !>         Data from column: CHR_COL_2
      !>            record number:            6
      !>            values       : -50      -51      -52      -53
      !>
      !>        Note that the second record does not appear due to setting the
      !>        ISNULL flag to true for that record. The odd value record
      !>        numbers have negative values as a result of the update calls.
      !>
      !>        After run completion, a new EK exists in the output directory.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.2.1, 06-AUG-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>        Added complete code example.
      !>
      !>-    SPICELIB Version 1.2.0, 06-FEB-2015 (NJB)
      !>
      !>        Now uses ERRHAN to insert DAS file name into
      !>        long error messages.
      !>
      !>        Corrected some header comment errors (cut-and-paste
      !>        errors referring to double precision or time data).
      !>
      !>-    SPICELIB Version 1.1.0, 20-JUN-1999 (WLT)
      !>
      !>        Removed unbalanced call to CHKOUT.
      !>
      !>-    SPICELIB Version 1.0.0, 26-SEP-1995 (NJB)
      module subroutine ekucec ( ctx, handle, segno, recno, column, nvals, cvals, isnull )
      use pepper_kinds, only: ip
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(inout) :: segno  !! Index of segment containing record. (PEPPER: changed by the routine, an input in SPICELIB's table)
      integer(ip), intent(in) :: recno  !! Record in which entry is to be updated.
      character(*), intent(in) :: column  !! Column name.
      integer(ip), intent(in) :: nvals  !! Number of values in new column entry.
      character(*), intent(in) :: cvals  ( * )  !! Character string values to add to column.
      logical, intent(in) :: isnull  !! Flag indicating whether column entry is null.

      integer(ip) :: coldsc ( cdscsz )
      integer(ip) :: class
      integer(ip) :: dtype
      integer(ip) :: recptr
      integer(ip) :: segdsc ( sdscsz )

      logical :: isshad

!
!     First step:  find the descriptor for the named segment.  Using
!     this descriptor, get the column descriptor.
!
      call zzeksdsc ( ctx, handle, segno,  segdsc          )
      call zzekcdsc ( ctx, handle, segdsc, column, coldsc  )

      if ( ctx%failed() ) return

!
!     This column had better be of character type.
!
      dtype  =  coldsc(typidx)

      if ( dtype /= chr ) then

         call ctx%setmsg ( 'Column # is of type #; EKUCEC only works '    // &
                       'with character columns.  RECNO = #; '      // &
                       'SEGNO = #; EK = #.'                            )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  dtype                                     )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(WRONGDATATYPE)'                          )
         return

      end if

!
!     Look up the record pointer for the target record.
!
      call zzektrdp ( ctx, handle, segdsc(rtidx), recno, recptr )

!
!     Determine whether the EK is shadowed.
!
      call ekshdw ( ctx, handle, isshad )

!
!     If the EK is shadowed, we must back up the current column entry
!     if the entry has not already been backed up.  ZZEKRBCK will
!     handle this task.
!
      if ( isshad ) then
         call zzekrbck ( ctx, 'UPDATE', handle, segdsc, coldsc, recno )
      end if

!
!     Now it's time to carry out the replacement.
!
      class  =  coldsc ( clsidx )

      if ( class == 3 ) then
!
!        Class 3 columns contain scalar character data.
!
         call zzekue03 ( ctx, handle, segdsc, coldsc, recptr, cvals(1), isnull )

      else if ( class == 6 ) then
!
!        Class 6 columns contain array-valued character data.
!
         call zzekue06 ( ctx, handle,  segdsc, coldsc, &
                         recptr,  nvals,  cvals,  isnull )

      else
!
!        This is an unsupported character column class.
!
         segno  =  segdsc ( snoidx )

         call ctx%setmsg ( 'Class # from input column descriptor is not ' // &
                       'a supported character class.  COLUMN = #; '   // &
                       'RECNO = #; SEGNO = #; EK = #.'                 )
         call ctx%errint ( '#',  class                                     )
         call ctx%errch  ( '#',  column                                    )
         call ctx%errint ( '#',  recno                                     )
         call ctx%errint ( '#',  segno                                     )
         call ctx%errhan ( '#',  handle                                    )
         call ctx%sigerr ( 'SPICE(NOCLASS)'                                )
         return

      end if

      return
      end subroutine ekucec

      !> Resolve and semantically check table names, aliases, and column
      !> names in an encoded EK query.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines.  Users should not call this routine directly due
      !> to the volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     QUERY          is the original query from which EQRYI and EQRYC
      !>                    were obtained.  QUERY is used only for
      !>                    construction of error messages.
      !>
      !>     EQRYI          is the integer portion of an encoded EK query.
      !>                    The query must have been parsed.
      !>
      !>     EQRYC          is the character portion of an encoded EK query.
      !>
      !>## Detailed Output
      !>
      !>     EQRYI          is the integer portion of an encoded EK query.
      !>                    On output, all names have been resolved, and
      !>                    table names, aliases, and column names have
      !>                    been semantically checked.
      !>
      !>     EQRYC          is the character portion of an encoded EK query.
      !>
      !>     ERROR          is a logical flag indicating whether an error was
      !>                    detected.  The error could be a name resolution
      !>                    error or a semantic error.
      !>
      !>     ERRMSG         is an error message describing an error in the
      !>                    input query, if one was detected.  If ERROR is
      !>                    returned .FALSE., then ERRPTR is undefined.
      !>
      !>     ERRPTR         is the character position in the original query
      !>                    at which an error was detected, if an error was
      !>                    found.  This index refers to the offending lexeme's
      !>                    position in the original query represented by the
      !>                    input encoded query.  If ERROR is returned .FALSE.,
      !>                    ERRPTR is undefined.
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input query is not initialized, the error will be
      !>         diagnosed by routines called by this routine.  The outputs
      !>         will not be modified.
      !>
      !>     2)  If the input query has not been parsed, the error
      !>         SPICE(QUERYNOTPARSED) will be signaled.  The outputs
      !>         will not be modified.
      !>
      !>     3)  If any sort of name resolution error or semantic error is
      !>         detected in the input query, the output flag ERROR is set,
      !>         and an error message is returned.  The checks performed by
      !>         this routine are listed below:
      !>
      !>           - All tables named in the FROM clause must be loaded
      !>             in the EK system.
      !>
      !>           - All aliases in the FROM clause must be distinct.
      !>
      !>           - No alias may be the name of a table in the FROM clause,
      !>             unless it is identical to the name of the table it is
      !>             associated with.
      !>
      !>           - No column name may be qualified with a name that is not
      !>             the name or alias of a table in the FROM clause.
      !>
      !>           - Each qualified column must be present in the table
      !>             indicated by its qualifying name.
      !>
      !>           - Each unqualified column name must be the name of a
      !>             column present in exactly one of the tables listed in the
      !>             FROM clause.
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     Resolution of table names involves finding each table's ordinal
      !>     position in the FROM clause, and setting the table's descriptor
      !>     to record that position.  The same is done for column descriptors.
      !>
      !>## Examples
      !>
      !>     See EKFIND.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 03-OCT-2021 (NJB)
      !>
      !>        Corrected typos in comments.
      !>
      !>-    Beta Version 1.0.0, 17-OCT-1995 (NJB)
      module subroutine zzeknres ( ctx, query, eqryi, eqryc, error, errmsg, errptr )
      use pepper_kinds, only: ip
      use pepper_strings, only: repmc_inplace
      use pepper_inc_ekbool
      use pepper_inc_ekqlimit
      use pepper_inc_ekquery
      use pepper_inc_ektnamsz
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: query  !! Original query string.
      integer(ip), intent(inout) :: eqryi ( lbcell : * )  !! Integer component of query.
      character(*), intent(inout) :: eqryc  !! Character component of query.
      logical, intent(out) :: error  !! Error flag.
      character(*), intent(out) :: errmsg  !! Error message.
      integer(ip), intent(out) :: errptr  !! Position in query where error was detected.


      character(tnamsz), allocatable :: alias ( : )
      character(tnamsz) :: ltable
      character(tnamsz), allocatable :: table ( : )

      integer(ip) :: base
      integer(ip), allocatable :: cc ( : )
      integer(ip) :: cnstyp
      integer(ip) :: i
      integer(ip) :: iparse
      integer(ip) :: j
      integer(ip) :: lxb
      integer(ip) :: lxe
      integer(ip) :: ncnj
      integer(ip) :: ncns
      integer(ip) :: nload
      integer(ip) :: nord
      integer(ip) :: nsel
      integer(ip) :: ntab

      logical :: fnd

!
!     No error to start with.
!
      error  =  .false.
      errmsg =  ' '
      errptr =  0

!
!     The query must have been parsed at this point, or it's no go.
!
      call zzekreqi ( ctx, eqryi, 'PARSED', iparse )

      if ( ctx%failed() ) return

      if ( iparse == ifalse ) then

         call ctx%setmsg ( 'Encoded query has not been parsed.'  )
         call ctx%sigerr ( 'SPICE(QUERYNOTPARSED)'               )
         return

      end if

!
!     Get the important counts from the query.
!
      call zzekreqi ( ctx, eqryi, 'NUM_TABLES',       ntab )
      allocate ( alias(max(ntab,1)), table(max(ntab,1)), cc(max(ntab,1)) )
      call zzekreqi ( ctx, eqryi, 'NUM_CONSTRAINTS',  ncns )
      call zzekreqi ( ctx, eqryi, 'NUM_CONJUNCTIONS', ncnj )
      call zzekreqi ( ctx, eqryi, 'NUM_ORDERBY_COLS', nord )
      call zzekreqi ( ctx, eqryi, 'NUM_SELECT_COLS',  nsel )

!
!     Start out by fetching the table names and their aliases.
!
      do i = 1, ntab
         call zzekqtab ( ctx, eqryi, eqryc, i, table(i), alias(i) )
      end do

!
!     Make sure that the aliases are distinct.  Rather than sorting
!     them, we'll check them in left-to-right order.
!
      do i = 1, ntab - 1

         do j = i+1, ntab

            if (      (  alias(i) == alias(j)  ) &
                .and. (  alias(i) /= ' '       )  ) then

               error  =  .true.
               errmsg =  'Non-distinct alias <#> was found.'

               base   =  eqvbas  +  ( (j-1)*2 + 1 ) * eqvdsz
               lxb    =  eqryi ( base + eqblex )
               lxe    =  eqryi ( base + eqelex )

               call repmc_inplace ( errmsg, '#', query(lxb:lxe) )

               errptr = lxb

               return

            end if
!
!           We've checked the Jth alias for a match.
!
         end do

      end do

!
!     Make sure that no alias matches a table name other than that of
!     the table it corresponds to.
!
      do i = 1, ntab

         j  =  findloc(table(1:ntab), alias(i), dim=1)

         if ( j /= 0 ) then

            if ( j /= i ) then

               error  =  .true.
               errmsg =  'Alias <#> conflicts with table name.'

               base   =  eqvbas  +  ( (i-1)*2 + 1 ) * eqvdsz
               lxb    =  eqryi ( base + eqblex )
               lxe    =  eqryi ( base + eqelex )

               call repmc_inplace ( errmsg, '#', query(lxb:lxe) )

               errptr = lxb

               return

            end if

         end if

      end do

!
!     Make sure that all of the tables are loaded in the EK system.
!
      call ekntab ( ctx, nload )

      do i = 1, ntab

         fnd  =  .false.
         j    =   1

         do while (  ( j <= nload ) .and. ( .not. fnd )  )

            call ektnam ( ctx, j, ltable )

            if (  table(i) == ltable  ) then
!
!              When we find a loaded table, save the column count for
!              that table.
!
               fnd  =  .true.
               call ekccnt ( ctx, table(1), cc(i) )
            else
               j    =   j + 1
            end if

         end do

         if ( .not. fnd ) then

            error  = .true.
            errmsg =  'Table <#> is not currently loaded.'
!
!           In order to set the error pointer, we'll need the
!           lexeme begin value for the offending table.
!
            base   =  eqvbas  +   (i-1)* 2 * eqvdsz

            lxb    =  eqryi ( base + eqblex )
            lxe    =  eqryi ( base + eqelex )

            call repmc_inplace ( errmsg, '#', query(lxb:lxe) )

            errptr = lxb

            return

         end if

      end do

!
!     At this point, the tables and aliases are deemed correct.  For
!     safety, fill in each table and alias descriptor with its
!     ordinal position.
!
      do i = 1, ntab

         base  =  eqvbas + (i-1)*2*eqvdsz

         eqryi( base          + eqtord ) = i
         eqryi( base + eqvdsz + eqtord ) = i

      end do

!
!     Check the column names used in the constraints.
!
      do i = 1, ncns
!
!        Calculate the base address of the constraint.
!
         base    =  eqvbas + (ntab * 2 * eqvdsz) + (i-1)*eqcdsz

!
!        Obtain the constraint type.
!
         cnstyp  =  eqryi ( base + eqctyp )

!
!        Check the column and table on the LHS of the constraint.
!
         call zzekcchk ( ctx, query,  eqryi,   eqryc, &
                         ntab,   table,   alias,  base+eqltab-1, &
                         error,  errmsg,  errptr                )

         if ( error ) return

         if ( cnstyp == eqcol ) then
!
!           Check the column and table on the RHS of the constraint.
!
            call zzekcchk ( ctx, query,  eqryi,   eqryc, &
                            ntab,   table,   alias,  base+eqrtab-1, &
                            error,  errmsg,  errptr                )

            if ( error ) return

         end if

      end do

!
!     Do the same checks and assignments for the SELECT columns.
!
      do i = 1, nsel
!
!        Calculate the base address of the SELECT column descriptor.
!
         base   =       eqvbas &
                    +   ntab * 2 * eqvdsz &
                    +   ncnj &
                    +   ncns     * eqcdsz &
                    +   nord     * eqodsz &
                    +   (i-1)    * eqsdsz

         call zzekcchk ( ctx, query,  eqryi,   eqryc, &
                         ntab,   table,   alias,  base, &
                         error,  errmsg,  errptr        )

         if ( error ) return

      end do

!
!     Do the same checks and assignments for the order-by columns.
!
      do i = 1, nord
!
!        Calculate the base address of the order-by column descriptor.
!
         base   =       eqvbas &
                    +   ntab * 2 * eqvdsz &
                    +   ncnj &
                    +   ncns     * eqcdsz &
                    +   (i-1)    * eqodsz

         call zzekcchk ( ctx, query,  eqryi,   eqryc, &
                         ntab,   table,   alias,  base, &
                         error,  errmsg,  errptr        )

         if ( error ) return

      end do

!
!     Indicate completion of name resolution.
!
      call zzekweqi ( ctx, 'NAMES_RESOLVED',  itrue,  eqryi  )

      end subroutine zzeknres

      !> Find E-kernel data that satisfy a set of constraints.
      !>
      !>## Detailed Input
      !>
      !>     QUERY    is a character string that specifies a set of EK
      !>              data to select from those present in currently
      !>              loaded EK files. The selected data will be
      !>              retrievable via the EK fetch routines EKGC, EKGD,
      !>              and EKGI.
      !>
      !>              The query consists of four clauses, the third and
      !>              fourth of which are optional. The general form
      !>              of a query is
      !>
      !>                 SELECT <column list>
      !>                 FROM <table list>
      !>                 [WHERE <constraint list>]
      !>                 [ORDER BY <ORDER BY column list>]
      !>
      !>              where brackets indicate optional items. The
      !>              elements of the query shown above are called,
      !>              respectively, the `SELECT clause', the
      !>              `FROM clause', the `WHERE clause', and the
      !>              `ORDER BY clause'. The result of a query may be
      !>              thought of as a new table, whose columns are those
      !>              specified in the SELECT clause, whose rows are
      !>              those satisfying the constraints of the WHERE
      !>              clause, and whose rows are ordered according to
      !>              the ORDER BY clause.
      !>
      !>              The SELECT clause specifies a list of columns
      !>              from which data are to be selected. In a simple
      !>              (non-join) query, these columns must belong to
      !>              the single table specified in the FROM clause.
      !>
      !>              The form of a SELECT clause is
      !>
      !>                 SELECT <column name> [ ,<column name>...]
      !>
      !>              In queries having multiple tables in the FROM
      !>              clause, column names are ambiguous if they occur
      !>              in more than one table in the FROM clause. Such
      !>              column names must be qualified with table
      !>              identifiers. These identifiers may be the names of
      !>              the tables to which the columns belong, or table
      !>              `aliases', names (usually short ones) associated
      !>              with tables in the FROM clause. Table aliases have
      !>              duration limited to the execution of the query to
      !>              which they belong.
      !>
      !>              The form of a qualified column name is
      !>
      !>                 <table name>.<column name>
      !>
      !>              or
      !>
      !>                 <table alias>.<column name>
      !>
      !>              The FROM clause specifies the tables from which
      !>              data are to be selected. In simple queries, only
      !>              one table is listed. In this case the form of
      !>              the FROM clause is
      !>
      !>                 FROM <table name>
      !>
      !>              In queries involving multiple tables, the form of
      !>              the FROM clause becomes
      !>
      !>                 FROM <table name> [<table alias>]
      !>                      [ , <table name> [<table alias>] ... ]
      !>
      !>              The aliases associated with the table names must
      !>              be distinct and must not be the actual names of
      !>              loaded EK tables.
      !>
      !>              Queries involving multiple tables are called
      !>              `joins'.
      !>
      !>              The meaning of a FROM clause containing multiple
      !>              tables is that the output is to be a subset of
      !>              the rows of the Cartesian product of the listed
      !>              tables. Normally, WHERE clause constraints are
      !>              supplied to reduce the selected rows to a set of
      !>              interest.
      !>
      !>              The most common example of a join is a query with
      !>              two tables listed in the FROM clause, and a WHERE
      !>              clause constraint enforcing equality of members
      !>              of a column in the first table with members of
      !>              column in the second table. Such a query is
      !>              called an `equi-join'. A join in which columns
      !>              of different tables are related by an inequality
      !>              is called a `non-equi-join'. Any type of join
      !>              other than an equi-join may be very slow to
      !>              evaluate, due to the large number of elements that
      !>              may be contained in the Cartesian
      !>              product of the listed tables.
      !>
      !>              The WHERE clause lists constraints that must
      !>              be met by each row satisfying the query. The
      !>              constraints are specified as a logical combination
      !>              of relational expressions. The form of the
      !>              constraint list is
      !>
      !>                 WHERE <constraint expression>
      !>
      !>              where each <constraint expression> consists of one
      !>              or more simple relational expressions of the form
      !>
      !>                 <column name> <operator> <RHS symbol>
      !>
      !>              where
      !>
      !>                 <RHS symbol>
      !>
      !>              is a column name, a literal value, or the special
      !>              symbol
      !>
      !>                 NULL
      !>
      !>              and
      !>
      !>                 <operator>
      !>
      !>              is any of
      !>
      !>                 EQ, GE, GT, LE, LIKE, LT, NE, NOT LIKE, <, <=,
      !>                 =, >, >=, !=, <>
      !>
      !>              For comparison with null values, the special
      !>              syntaxes
      !>
      !>                 <column name> IS NULL
      !>                 <column name> IS NOT NULL
      !>
      !>              are allowed, in addition to the standard
      !>              comparison syntaxes using the equality or
      !>              inequality operators.
      !>
      !>              The LIKE operator allows comparison of a string
      !>              value against a template. The template syntax
      !>              is that allowed by the SPICELIB routine MATCHI.
      !>              Templates may include literal characters, the
      !>              wild string marker '*', and the wild character
      !>              marker '%'. Case is significant in templates.
      !>
      !>              Templates are bracketed by quote characters, just
      !>              as are literal strings.
      !>
      !>              The query language also supports the BETWEEN and
      !>              NOT BETWEEN constructs
      !>
      !>                 <column> BETWEEN <symbol 1> AND <symbol 2>
      !>
      !>                 <column> NOT BETWEEN <symbol 1> AND <symbol 2>
      !>
      !>              The tokens
      !>
      !>                 <symbol 1>
      !>                 <symbol 2>
      !>
      !>              may be literal values or column names.
      !>
      !>              The BETWEEN operator considers values that match
      !>              the bounds to satisfy the condition: the BETWEEN
      !>              operator tests for inclusion in the closed interval
      !>              defined by the bounds.
      !>
      !>              In the WHERE clause, simple relational expressions
      !>              may be combined using the logical operators AND,
      !>              OR, and NOT, as in the Fortran programming
      !>              language. Parentheses may be used to enforce a
      !>              desired order of evaluation of logical expressions.
      !>
      !>              The expression syntax is NOT symmetric: literal
      !>              values must not appear on the left hand side of the
      !>              operators that apply to them.
      !>
      !>              The columns named in a constraint clause must
      !>              belong to the tables listed in the FROM clause.
      !>              If the query is a join, qualifying table names or
      !>              aliases are required wherever their omission would
      !>              result in ambiguity.
      !>
      !>              Data types of the columns or constants used on the
      !>              right-hand-sides of operators must match the data
      !>              types of the corresponding columns on the
      !>              left-hand-sides, except that comparison of integer
      !>              and double precision quantities is permitted.
      !>
      !>              Literal strings used in constraints are always
      !>              bracketed by quotes. Either single  quotes (')
      !>              or double quotes (") may be used, but the same
      !>              quote character must be used to start and end any
      !>              literal string. Within character string values,
      !>              quote characters must be doubled in order to be
      !>              recognized. Case is significant in character
      !>              except in comparisons using the LIKE and NOT LIKE
      !>              operators, which ignore case: the expression
      !>
      !>                 ANIMAL LIKE "*A*"
      !>
      !>              would be considered true when ANIMAL takes the
      !>              value
      !>
      !>                 "cat"
      !>
      !>              Time values are considered to be strings and
      !>              require bracketing quotes. Currently, the
      !>              only time values allowed are UTC times in ISO
      !>              format, UTC times represented in forms accepted by
      !>              the SPICELIB routine TPARSE, and SCLK strings in
      !>              NAIF format.
      !>
      !>              The ORDER BY clause indicates which columns to
      !>              use to order the output generated by the query.
      !>              The columns in the ORDER BY clause define a
      !>              dictionary ordering, with the first listed column
      !>              acting as a primary key, the second column acting
      !>              as a secondary key, and so on.
      !>
      !>              For each ORDER BY column, the keywords ASC or DESC
      !>              may be supplied to indicate whether the items in
      !>              that column are to be listed in ascending or
      !>              descending order. Ascending order is the default.
      !>              The direction in which data items increase is
      !>              referred to as the `order sense'.
      !>
      !>              The ORDER BY clause, if present, must appear
      !>              last in the query.
      !>
      !>              The form of the ORDER BY clause is
      !>
      !>                 ORDER BY <column name> [<order sense>]
      !>                          [ ,<column name> [<order sense>]...]
      !>
      !>              Rows satisfying the query constraints will be
      !>              returned so that the entries of the first column
      !>              specified in the ORDER BY clause will be appear in
      !>              the order specified by the order sense keyword,
      !>              which is assumed to be ASC if absent. When entries
      !>              in the first through Nth ORDER BY column are equal,
      !>              the entries in the (N+1)st ORDER BY column
      !>              determine the order of the rows, and so on.
      !>
      !>              As in the WHERE clause, column names must be
      !>              qualified by table names or table aliases where
      !>              they would otherwise be ambiguous.
      !>
      !>              The query language is word-oriented, and some
      !>              indicate whether the words are reserved. Reserved
      !>              words must be separated from other words by white
      !>              space. It is not necessary to use white space
      !>              to separate words and punctuation characters.
      !>              The list of reserved words is
      !>
      !>                 AND
      !>                 BETWEEN
      !>                 BY
      !>                 COLUMN
      !>                 EQ
      !>                 FROM
      !>                 GE
      !>                 GT
      !>                 IS
      !>                 LE
      !>                 LT
      !>                 LIKE
      !>                 NE
      !>                 NOT
      !>                 NULL
      !>                 OR
      !>                 ORDER
      !>                 SELECT
      !>                 WHERE
      !>
      !>              The left and right parenthesis characters are also
      !>              reserved; they may not be used in queries outside
      !>              of quoted strings.
      !>
      !>              Case is not significant in queries, except within
      !>              literal strings.
      !>
      !>## Detailed Output
      !>
      !>     NMROWS   is the number of rows that match the query
      !>              criteria. NMROWS is defined if and only if
      !>              ERROR is returned .FALSE.
      !>
      !>     ERROR    is a logical flag indicating whether the query
      !>              failed to parse correctly.
      !>
      !>     ERRMSG   is a character string that describes EKFIND's
      !>              diagnosis of a parse error, should one occur.
      !>              Otherwise, ERRMSG will be returned blank.
      !>
      !>## Parameters
      !>
      !>     See the include files.
      !>
      !>## Exceptions
      !>
      !>     1)  Most of the exceptions that can occur on a call to
      !>         EKFIND are caused by errors in the input query. EKFIND
      !>         attempts to diagnose these via the output error flag and
      !>         error message, instead of signaling errors. The following
      !>         classes of errors are detected:
      !>
      !>            Scanning errors---these result from badly formed query
      !>            in which EKFIND could not identify all of the tokens.
      !>            When these errors occur, EKFIND may be too confused to
      !>            give a helpful diagnostic message.
      !>
      !>            Parsing errors---these result from a badly formed
      !>            query that EKFIND was able to separate into tokens
      !>            but that EKFIND determined to be syntactically invalid:
      !>
      !>            Name resolution errors---these result from referencing
      !>            invalid or ambiguous column or table names in a query.
      !>
      !>            Time resolution errors---these result from use of time
      !>            strings that cannot be parsed.
      !>
      !>            Semantic errors---these result from a syntactically
      !>            valid query that violates a limit or a restriction on
      !>            values used in a query.
      !>
      !>     Some problems with queries are not trapped by EKFIND but
      !>     instead cause errors to be signaled. These are listed below.
      !>
      !>     2)  If no E-kernels are loaded at the time this routine is called,
      !>         an error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     3)  If a leapseconds kernel is is not loaded before this routine
      !>         is called, UTC time values may not be used in queries. If they
      !>         are, an error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>     4)  If an SCLK kernel for the appropriate spacecraft clock has not
      !>         been loaded before this routine is called, SCLK values for
      !>         that clock may not be used in queries. If they are, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine operates almost entirely by side effects: it
      !>     prepares the EK fetch routines to return event data that
      !>     satisfy the input query. See the EK Required Reading for
      !>     examples of use of this routine in conjunction with the EK
      !>     fetch routines.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for these examples may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Perform a query on an EK file that contains a database with
      !>        the different commands of the Deep Impact spacecraft
      !>        subsystem, and a table with the subsystem id, the parameter
      !>        name, and the description of that parameters, ordered by
      !>        subsystem name. Print the number of records of that table.
      !>
      !>        Use the EK kernel below to load the Deep Impact spacecraft
      !>        subsystem commands dictionary.
      !>
      !>           dif_cmdict_128_20050620.bdb
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM EKFIND_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Include the EK Maximum length of an input query,
      !>C     MAXQRY, and the maximum length of literal string
      !>C     values, MAXSTR, from eklimit.inc.
      !>C
      !>      INCLUDE 'ekqlimit.inc'
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      CHARACTER*(*)         EKNAME
      !>      PARAMETER           ( EKNAME =
      !>     .                         'dif_cmdict_128_20050620.bdb' )
      !>
      !>      INTEGER               ERRLEN
      !>      PARAMETER           ( ERRLEN = 1840 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(ERRLEN)    ERRMSG
      !>      CHARACTER*(MAXQRY)    QUERY
      !>
      !>      INTEGER               NMROWS
      !>
      !>      LOGICAL               ERROR
      !>
      !>C
      !>C     Open an EK file.
      !>C
      !>      CALL FURNSH ( EKNAME )
      !>
      !>C
      !>C     The EK file contains the table 'DIF_COMMANDS',
      !>C     and that 'DIF_COMMANDS' contains columns named:
      !>C
      !>C       SUBSYSTEM, COMMAND, PARAMETER_NAME, DESCRIPTION
      !>C
      !>C     Define a set of constraints to perform a query on all
      !>C     loaded EK files (the SELECT clause).
      !>C
      !>      QUERY = 'Select SUBSYSTEM, COMMAND, PARAMETER_NAME, '
      !>     .   //   'DESCRIPTION from DIF_COMMANDS '
      !>     .   //   'order by SUBSYSTEM'
      !>
      !>C
      !>C     Query the EK system for data rows matching the
      !>C     SELECT constraints.
      !>C
      !>      CALL EKFIND ( QUERY, NMROWS, ERROR, ERRMSG )
      !>
      !>C
      !>C     Check whether an error occurred while processing the
      !>C     SELECT clause. If so, output the error message.
      !>C
      !>      IF ( ERROR ) THEN
      !>
      !>         WRITE(*,*) 'SELECT clause error: ', ERRMSG
      !>
      !>      ELSE
      !>
      !>C
      !>C        If no error, NMROWS contains the number of rows
      !>C        matching the constraints specified in the query
      !>C        string.
      !>C
      !>         WRITE(*,*) 'Number of matching rows: ', NMROWS
      !>
      !>      END IF
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Number of matching rows:         5798
      !>
      !>     2) Examples of strings containing syntactically valid queries:
      !>
      !>            SELECT COL1 FROM TAB1
      !>
      !>            select col1 from tab1 where col1 gt 5
      !>
      !>            SELECT COL2 FROM TAB1 WHERE COL2 > 5.7D0 ORDER BY COL2
      !>
      !>            SELECT COL2 FROM TAB1 WHERE COL1 != 5
      !>
      !>            SELECT COL2 FROM TAB1 WHERE COL1 GE COL2
      !>
      !>            SELECT COL1, COL2, COL3 FROM TAB1 ORDER BY COL1
      !>
      !>            SELECT COL3 FROM TAB1 WHERE COL5 EQ "ABC"
      !>
      !>            SELECT COL3 FROM TAB1 WHERE COL5 = 'ABC'
      !>
      !>            SELECT COL3 FROM TAB1 WHERE COL5 LIKE 'A*'
      !>
      !>            SELECT COL3 FROM TAB1 WHERE COL5 LIKE 'A%%'
      !>
      !>            SELECT COL4 FROM TAB1 WHERE COL4 = '1995 JAN 1 12:38:09.7'
      !>
      !>            SELECT COL4 FROM TAB1 WHERE COL4 = "1995 JAN 1 12:38:09.7"
      !>
      !>            SELECT COL4 FROM TAB1 WHERE
      !>            COL4 NE 'GLL SCLK 02724646:67:7:2'
      !>
      !>            SELECT COL1 FROM TAB1 WHERE COL1 != NULL
      !>
      !>            SELECT COL1 FROM TAB1 WHERE COL1 IS NULL
      !>
      !>            SELECT COL1 FROM TAB1 WHERE COL1 IS NOT NULL
      !>
      !>            SELECT COL1, COL2, COL3 FROM TAB1
      !>            WHERE (COL1 BETWEEN 4 AND 6) AND (COL3 NOT LIKE "A%%")
      !>            ORDER BY COL1, COL3
      !>
      !>            SELECT COL4 FROM TAB1
      !>            WHERE COL4 BETWEEN "1995 JAN 1 12:38" AND
      !>            "October 23, 1995"
      !>
      !>            SELECT COL1, COL2 FROM TAB1 WHERE
      !>            NOT (    ( ( COL1 <  COL2 ) AND ( COL1 > 5   ) )  OR
      !>                     ( ( COL1 >= COL2 ) AND ( COL2 <= 10 ) )      )
      !>
      !>            SELECT T1.COL1, T1.COL2, T2.COL2, T2.COL3
      !>            FROM TABLE1 T1, TABLE2 T2
      !>            WHERE T1.COL1 = T2.COL1
      !>            AND T1.COL2 > 5
      !>            ORDER BY T1.COL1, T2.COL2
      !>
      !>     3) Examples of syntactically invalid queries:
      !>
      !>            SELECT TIME WHERE TIME
      !>            LT 1991 JAN 1                      {FROM clause is absent}
      !>
      !>            select time from table1 where
      !>            time lt 1991 jan 1                 {time string is not
      !>                                                quoted}
      !>
      !>            select time from table1
      !>            where time .lt. '1991 jan 1'       {operator should be lt}
      !>
      !>            select cmd from table1
      !>            where "cmd,6tmchg" != cmd          {value is on left side
      !>                                                of operator}
      !>
      !>            select event_type from table1
      !>            where event_type eq ""             {quoted string is empty
      !>                                                ---use " " to indicate
      !>                                                a blank string}
      !>
      !>            select event_type from table1
      !>            where event_type = "COMMENT"
      !>            order TIME                         {ORDER BY phrase is
      !>                                                lacking BY keyword}
      !>
      !>            select COL1 from table where
      !>            where COL1 eq MOC_EVENT            {literal string on
      !>                                                right-hand-side of
      !>                                                operator is not quoted}
      !>
      !>         In the following examples, we'll assume that the program
      !>         calling EKFIND has loaded an EK containing two segments
      !>         having columns having the following names and attributes:
      !>
      !>          TABLE1:
      !>          ==========
      !>
      !>            Column name        Data type         Size       Indexed?
      !>            -----------        ---------         ----       --------
      !>            EVENT_TYPE         CHARACTER*32      1          YES
      !>            EVENT_PARAMETERS   CHARACTER*(*)     1          NO
      !>            COMMENT            CHARACTER*80      VARIABLE   NO
      !>
      !>          TABLE2:
      !>          ==========
      !>
      !>            Column name        Data type         Size       Indexed?
      !>            -----------        ---------         ----       --------
      !>            EVENT_TYPE         CHARACTER*32      1          YES
      !>            EVENT_PARAMETERS   CHARACTER*80      1          NO
      !>            COMMENT            CHARACTER*80      VARIABLE   NO
      !>            COMMAND            CHARACTER*80      1          YES
      !>
      !>         Then the following queries are semantically invalid:
      !>
      !>            SELECT EVENT_PARAMETERS
      !>            FROM TABLE1
      !>            WHERE EVENT_DURATION = 7.0         {No column called
      !>                                                EVENT_DURATION
      !>                                                is present in a loaded
      !>                                                EK}
      !>
      !>            SELECT COMMENT FROM TABLE2
      !>            WHERE COMMENT EQ "N/A"             {The COMMENT column does
      !>                                                not have size 1 and
      !>                                                therefore cannot be
      !>                                                referenced in a query}
      !>
      !>## Restrictions
      !>
      !>     1)  A leapseconds kernel must be loaded before this routine may
      !>         be called, if UTC time values are used in input queries.
      !>
      !>     2)  An appropriate SCLK kernel must be loaded before this routine
      !>         may be called, if SCLK values are used in input queries.
      !>
      !>     3)  Data found in response to a query become unavailable
      !>         when a fast load is initiated via EKIFLD. Any desired
      !>         fetches of the data must be performed before a fast
      !>         load or any other operation that modifies the EK scratch
      !>         area is initiated.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 13-AUG-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>        Added complete code example.
      !>
      !>-    SPICELIB Version 1.0.4, 18-MAY-2010 (BVS)
      !>
      !>        Removed "C$" marker from text in the header.
      !>
      !>-    SPICELIB Version 1.0.3, 19-DEC-2001 (NJB)
      !>
      !>        $Restrictions section was updated.
      !>
      !>-    SPICELIB Version 1.0.2, 14-JAN-1997 (NJB)
      !>
      !>        Syntax descriptions for comparisons using null values have been
      !>        added. The $Examples section was augmented with sample queries
      !>        demonstrating use of the IS NULL and IS NOT NULL comparison
      !>        operators.
      !>
      !>-    SPICELIB Version 1.0.1, 16-AUG-1996 (NJB)
      !>
      !>        $Exceptions section of header was updated to indicate that
      !>        calling this routine while no E-kernels are loaded will cause
      !>        an error to be signaled. Previous version line was changed
      !>        from "Beta" to "SPICELIB," and the previous version was
      !>        corrected to 1.0.0.
      !>
      !>-    SPICELIB Version 1.0.0, 24-OCT-1995 (NJB)
      module subroutine ekfind ( ctx, query, nmrows, error, errmsg )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekquery
      use pepper_inc_ekqlimit
      use pepper_inc_ektype
      use pepper_inc_ekopcd
      use pepper_inc_ekcnamsz
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: query  !! Query specifying data to be found.
      integer(ip), intent(out) :: nmrows  !! Number of matching rows.
      logical, intent(out) :: error  !! Flag indicating whether query parsed correctly.
      character(*), intent(out) :: errmsg  !! Parse error description.

      integer(ip) :: room

      character(:), allocatable :: chrbuf
      character(:), allocatable :: eqryc

      real(wp), allocatable :: eqryd ( : )
      real(wp), allocatable :: numvls ( : )

      integer(ip), allocatable :: chbegs ( : )
      integer(ip), allocatable :: chends ( : )
      integer(ip), allocatable :: eqryi ( : )
      integer(ip) :: errptr
      integer(ip), allocatable :: lxbegs ( : )
      integer(ip), allocatable :: lxends ( : )
      integer(ip) :: ntoken
      integer(ip), allocatable :: tokens ( : )
      integer(ip), allocatable :: values ( : )

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Initialize the encoded query each time, for safety.
!
!     PEPPER: the buffers are sized from the query: it has at most one
!     token, and one number, per character, and its strings and names fit
!     in its length; the integer part of the encoded query grows as it is
!     written (SPICELIB: MAXQRY = 2000 characters, MAXTOK = 500 tokens,
!     MAXQNM = 100 numbers, and EQIMIN elements, sized for the largest
!     query).
!
      room = max ( len_trim ( query ), 1 )
      allocate ( character(room) :: chrbuf, eqryc )
      allocate ( eqryd(room), numvls(room), source = 0.0_wp )
      allocate ( chbegs(room), chends(room), lxbegs(room), lxends(room), &
                 tokens(room), values(room), source = 0_ip )
      allocate ( eqryi(lbcell:eqvbas + 64), source = 0_ip )
      call zzekqini ( ctx, ubound ( eqryi, 1, kind=ip ), room, eqryi, eqryc, eqryd )

!
!     Find the tokens in the input query.
!
      call zzekscan ( ctx, query,  room, room, ntoken, tokens, &
                      lxbegs, lxends, values, numvls, chrbuf, &
                      chbegs, chends, error,  errmsg         )

      if ( error ) return

!
!     Now parse the query.
!
      call zzekpars ( ctx,  query,   ntoken,  lxbegs,  lxends, &
                       tokens,  values,  numvls,  chrbuf, &
                       chbegs,  chends,  eqryi,   eqryc, &
                       eqryd,   error,   errmsg          )

      if ( error ) return

!
!     Resolve names.
!
      call zzeknres ( ctx, query, eqryi, eqryc, &
                             error, errmsg, errptr )

      if ( error ) return

!
!     Resolve time values, if necessary.
!
      call zzektres ( ctx, query, eqryi,  eqryc,  eqryd, &
                             error,  errmsg, errptr  )

      if ( error ) return

!
!     Perform semantic checks.
!
      call zzeksemc ( ctx, query, eqryi, eqryc, &
                             error, errmsg, errptr )

      if ( error ) return

!
!     If we arrived here, the encoded query is ready for execution.
!     Find the data satisfying the constraints.
!
      call eksrch ( ctx, eqryi, eqryc, eqryd, nmrows, error, errmsg )

      return
      end subroutine ekfind

      !> Convert an EK query to encoded form.
      !>
      !>## Detailed Input
      !>
      !>     QUERY          is an EK query, starting after the FROM keyword.
      !>
      !>## Detailed Output
      !>
      !>     EQRYI          is the integer portion of an encoded EK query.
      !>                    Semantic checking will have been performed.
      !>
      !>     EQRYC          is the character portion of an encoded EK query.
      !>
      !>     EQRYD          is the numeric portion of an encoded EK query.
      !>
      !>     ERROR          is a logical flag indicating whether the query
      !>                    was syntactically correct and, as far as this
      !>                    routine could determine, semantically correct.
      !>
      !>     ERRMSG         is a character string that describes ZZEKENCD's
      !>                    diagnosis of a parse error, should one occur.
      !>                    Otherwise, ERRMSG will be returned blank.
      !>
      !>     ERRPTR         is the index, within the input query, of the
      !>                    first character at which an error was detected
      !>                    ERRPTR is valid only if ERROR is returned .TRUE.
      !>
      !>## Parameters
      !>
      !>     See the include files.
      !>
      !>## Exceptions
      !>
      !>     If a parse error occurs, either the outputs ERROR, ERRMSG, and
      !>     ERRPTR will be set by routines called by this routine, or an
      !>     error will be signaled by routines called by this routine.
      !>     Under normal circumstances, no errors will be signaled.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine assumes that encoded EK query architecture version
      !>     1 is to be used with the query to be initialized; this routine
      !>     will not work with any other architecture version.
      !>
      !>## Examples
      !>
      !>     See EKPSEL.
      !>
      !>## Restrictions
      !>
      !>     1)  Uses EK encoded query architecture version 1.
      !>
      !>     2)  A leapseconds kernel must be loaded before this routine may
      !>         be called, if UTC time values are used in input queries.
      !>
      !>     3)  An appropriate SCLK kernel must be loaded before this routine
      !>         may be called, if SCLK values are used in input queries.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 4.0.1, 03-OCT-2021 (NJB)
      !>
      !>        Corrected typos in comments.
      !>
      !>-    Beta Version 4.0.0, 10-OCT-1995 (NJB)
      module subroutine zzekencd ( ctx, query, eqryi, eqryc, eqryd, error, errmsg, errptr )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekopcd
      use pepper_inc_ekqlimit
      use pepper_inc_ekquery
      use pepper_inc_ektype
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: query  !! Query specifying events to be found.
      integer(ip), allocatable, intent(inout) :: eqryi ( : )  !! Integer component of encoded query. PEPPER: allocatable, lower bound LBCELL; grows as the query is encoded.
      character(*), intent(out) :: eqryc  !! Character component of encoded query.
      real(wp), intent(out) :: eqryd  ( * )  !! Numeric component of encoded query.
      logical, intent(out) :: error  !! Flag indicating whether query parsed correctly.
      character(*), intent(out) :: errmsg  !! Parse error description.
      integer(ip), intent(out) :: errptr  !! Error pointer.
      integer(ip) :: room
      integer(ip) :: dsize

      character(:), allocatable :: chrbuf

      real(wp), allocatable :: numvls ( : )

      integer(ip), allocatable :: chbegs ( : )
      integer(ip), allocatable :: chends ( : )
      integer(ip), allocatable :: lxbegs ( : )
      integer(ip), allocatable :: lxends ( : )
      integer(ip) :: ntoken
      integer(ip), allocatable :: tokens ( : )
      integer(ip), allocatable :: values ( : )

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Initialize the encoded query each time, for safety.
!
!     PEPPER: the scanner's buffers are sized from the query (at most one
!     token per character); the encoded query keeps the sizes its caller
!     initialized it with (ZZEKQINI; its integer part grows), and the
!     numbers scanned are limited to its numeric part (SPICELIB: MAXQRY,
!     MAXTOK, MAXQNM, EQIMIN).
!
      room  = max ( len_trim ( query ), 1 )
      dsize = eqryi(eqnsiz)
      allocate ( character(room) :: chrbuf )
      allocate ( numvls(room), source = 0.0_wp )
      allocate ( chbegs(room), chends(room), lxbegs(room), lxends(room), &
                 tokens(room), values(room), source = 0_ip )
      call zzekqini ( ctx, sizei ( ctx, eqryi ), dsize, eqryi, eqryc, eqryd )

!
!     Find the tokens in the input query.
!
      call zzekscan ( ctx, query,  room, min ( room, dsize ), ntoken, tokens, &
                      lxbegs, lxends, values, numvls, chrbuf, &
                      chbegs, chends, error,  errmsg         )

      if ( error ) then
         errptr  = 1
         return
      end if

!
!     Now parse the query.
!
      call zzekpars ( ctx,  query,   ntoken,  lxbegs,  lxends, &
                       tokens,  values,  numvls,  chrbuf, &
                       chbegs,  chends,  eqryi,   eqryc, &
                       eqryd,   error,   errmsg          )

      if ( error ) then
         errptr = 1
         return
      end if

!
!     Resolve names.
!
      call zzeknres ( ctx, query, eqryi, eqryc, &
                             error, errmsg, errptr )

      if ( error ) return

!
!     Resolve time values, if necessary.
!
      call zzektres ( ctx, query, eqryi,  eqryc,  eqryd, &
                             error,  errmsg, errptr  )

      if ( error ) return

!
!     Perform semantic checks.
!
      call zzeksemc ( ctx, query, eqryi, eqryc, &
                             error, errmsg, errptr )

      if ( error ) return

      return
      end subroutine zzekencd

      !> Parse the SELECT clause of an EK query, returning full particulars
      !> concerning each selected item.
      !>
      !>## Detailed Input
      !>
      !>     QUERY    is a character string containing an EK query.
      !>              EK queries have the general form
      !>
      !>                 SELECT <select expr>, <select expr>, ...
      !>                 FROM <table spec>, <table spec>, ...
      !>                 [WHERE <constraint list>]
      !>                 [ORDER BY <order-by column list>]
      !>
      !>              Here the symbol <select expr> indicates any
      !>              expression representing an entity that can be
      !>              selected. Commonly, the selected items are
      !>              columns, with or without qualifying table names,
      !>              having the form
      !>
      !>                 <column name>
      !>                 <table name>.<column name>
      !>                 <table alias>.<column name>
      !>
      !>              but more general expressions may also be selected.
      !>              Examples are functions, such as
      !>
      !>                 COUNT(*)
      !>                 COUNT( <table name>.<column name> )
      !>                 MAX  ( <table name>.<column name> )
      !>
      !>              or expressions involving constants, such as
      !>
      !>                 2 * <column name>
      !>
      !>## Detailed Output
      !>
      !>     N        is the number of items specified in the
      !>              SELECT clause of the input query.
      !>
      !>     XBEGS,
      !>     XENDS    are, respectively, arrays of begin and end
      !>              positions of expressions designating items in the
      !>              SELECT clause of the input query. The Ith
      !>              expression is located in the substring
      !>
      !>                 QUERY ( XBEGS(I) : XENDS(I) )
      !>
      !>     XTYPES   is an array of short strings indicating the data
      !>              types of the expressions in the SELECT clause.
      !>              Values and meanings of XTYPES are:
      !>
      !>                 'CHR'        Character type
      !>                 'DP'         Double precision type
      !>                 'INT'        Integer type
      !>                 'TIME'       Time type
      !>
      !>              The Ith element of XTYPES refers to the Ith
      !>              selected item.
      !>
      !>              The data type of an expression indicates which
      !>              fetch routine to use to obtain values of the
      !>              selected expression. The mapping of data types
      !>              to fetch routines is shown below:
      !>
      !>                 'CHR'        EKGC
      !>                 'DP'         EKGD
      !>                 'INT'        EKGI
      !>                 'TIME'       EKGD
      !>
      !>              Note that time values are stored as d.p. numbers.
      !>
      !>     XCLASS   is an array of short strings giving the classes
      !>              of the expressions occurring in the SELECT clause
      !>              of the input query. Values and meanings of
      !>              XCLASS are:
      !>
      !>                 'COL'        Selected item was a column. The
      !>                              column may qualified.
      !>
      !>                 'FUNC'       Selected item was a simple
      !>                              function invocation of the form
      !>
      !>                                 F ( <column> )
      !>
      !>                              or else was
      !>
      !>                                 COUNT(*)
      !>
      !>                 'EXPR'       Selected item was a more general
      !>                              expression than those shown above.
      !>
      !>              The Ith element of XCLASS refers to the Ith
      !>              selected item.
      !>
      !>              When a selected item is a column, the values of
      !>              the arguments TABS and COLS (discussed below) are
      !>              defined.
      !>
      !>     TABS     is an array of names of tables corresponding to
      !>              the columns in the SELECT clause. The Ith element
      !>              of TABS corresponds to the table containing the
      !>              Ith SELECT column. Table names returned in TABS
      !>              are the actual names of tables in loaded EK, not
      !>              aliases supplied in the input query. Table names
      !>              are supplied even if the corresponding column was
      !>              unqualified in the input query, as long as the
      !>              column name was unambiguous.
      !>
      !>              The contents of TABS(I) are defined if and only if
      !>              the returned value of XCLASS(I) is 'COL'.
      !>
      !>     COLS     is an array containing the columns of the SELECT
      !>              clause. The contents of COLS(I) are defined if and
      !>              only if the returned value of XCLASS(I) is 'COL'.
      !>
      !>     ERROR    is a logical flag indicating whether the input
      !>              QUERY parsed correctly. The other outputs of this
      !>              routine, except for ERRMSG, are undefined if a
      !>              parse error occurred. ERROR is returned .TRUE. if
      !>              a parse error occurred, .FALSE. otherwise.
      !>
      !>     ERRMSG   is a character string describing the cause of a
      !>              parse error, if such an error occurred. Otherwise,
      !>              ERRMSG is returned blank.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  Parse failures do not cause this routine to signal errors;
      !>         instead, the ERROR and ERRMSG outputs indicate invalid
      !>         QUERY.
      !>
      !>     2)  Queries cannot be parsed correctly unless at least one EK
      !>         is loaded.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine allows callers of the EK fetch routines to determine
      !>     at run time the attributes of the columns from which data is to be
      !>     fetched.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Query the EK system and fetch data matching that query.
      !>
      !>        The program shown here does not rely on advance
      !>        knowledge of the input query or the contents of any loaded EK
      !>        files.
      !>
      !>        To simplify the example, we assume that all data are scalar.
      !>        This assumption relieves us of the need to test the size of
      !>        column entries before fetching them. In the event that a
      !>        column contains variable-size array entries, the entry point
      !>        EKNELT may be called to obtain the size of column entries to
      !>        be fetched. See EKNELT for an example.
      !>
      !>        Use the EK kernel below to load the information from the
      !>        original Supplementary Engineering Data Record (SEDR) data
      !>        set generated by the Viking Project.
      !>
      !>           vo_sedr.bdb
      !>
      !>        Use the LSK kernel below to load the leap seconds and time
      !>        constants required for the conversions.
      !>
      !>           naif0012.tls
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM EKPSEL_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Include EK Query Limit Parameters
      !>C
      !>      INCLUDE 'ekqlimit.inc'
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      INTEGER               RTRIM
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      CHARACTER*(*)         EKNAME
      !>      PARAMETER           ( EKNAME = 'vo_sedr.bdb' )
      !>
      !>      CHARACTER*(*)         LSKNAM
      !>      PARAMETER           ( LSKNAM = 'naif0012.tls' )
      !>
      !>      INTEGER               DESCSZ
      !>      PARAMETER           ( DESCSZ = 31   )
      !>
      !>      INTEGER               ERRLEN
      !>      PARAMETER           ( ERRLEN = 1840 )
      !>
      !>      INTEGER               ITEMSZ
      !>      PARAMETER           ( ITEMSZ = DESCSZ + 4 )
      !>
      !>      INTEGER               TIMLEN
      !>      PARAMETER           ( TIMLEN = 27   )
      !>
      !>      INTEGER               TYPLEN
      !>      PARAMETER           ( TYPLEN = 4    )
      !>
      !>      INTEGER               XCLSLN
      !>      PARAMETER           ( XCLSLN = 4    )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(MAXSTR)    CDATA
      !>      CHARACTER*(MAXCLN)    COLS   ( MAXSEL )
      !>      CHARACTER*(ERRLEN)    ERRMSG
      !>      CHARACTER*(ITEMSZ)    ITEM
      !>      CHARACTER*(DESCSZ)    OUTSTR
      !>      CHARACTER*(MAXQRY)    QUERY
      !>      CHARACTER*(TIMLEN)    UTCSTR
      !>      CHARACTER*(MAXCLN)    TABS   ( MAXTAB )
      !>      CHARACTER*(XCLSLN)    XCLASS ( MAXSEL )
      !>      CHARACTER*(TYPLEN)    XTYPES ( MAXSEL )
      !>
      !>      DOUBLE PRECISION      DDATA
      !>      DOUBLE PRECISION      TDATA
      !>
      !>      INTEGER               B
      !>      INTEGER               COLNO
      !>      INTEGER               E
      !>      INTEGER               HANDLE
      !>      INTEGER               IDATA
      !>      INTEGER               N
      !>      INTEGER               NMROWS
      !>      INTEGER               ROW
      !>      INTEGER               XBEGS  ( MAXSEL )
      !>      INTEGER               XENDS  ( MAXSEL )
      !>
      !>      LOGICAL               ERROR
      !>      LOGICAL               FOUND
      !>      LOGICAL               NULL
      !>
      !>C
      !>C     Load leapseconds file for time conversion.
      !>C
      !>      CALL FURNSH ( LSKNAM )
      !>
      !>C
      !>C     Load EK.
      !>C
      !>      CALL EKLEF  ( EKNAME, HANDLE )
      !>
      !>C
      !>C     Setup the query.  Parse the SELECT clause using
      !>C     EKPSEL.
      !>C
      !>      QUERY = 'Select IMAGE_NUMBER, IMAGE_ID, '
      !>     .   //          'PLATFORM_CLOCK, IMAGE_TIME '
      !>     .   //   'from VIKING_SEDR_DATA '
      !>     .   //   'where IMAGE_NUMBER < 25850000 '
      !>     .   //   'order by IMAGE_NUMBER'
      !>
      !>      CALL EKPSEL ( QUERY,  N,    XBEGS, XENDS, XTYPES,
      !>     .              XCLASS, TABS, COLS,  ERROR, ERRMSG )
      !>
      !>      IF ( ERROR ) THEN
      !>
      !>         WRITE(*,*) ERRMSG
      !>
      !>      ELSE
      !>
      !>C
      !>C        Submit query to the EK query system.
      !>C
      !>         CALL EKFIND ( QUERY, NMROWS, ERROR, ERRMSG )
      !>
      !>         IF ( ERROR ) THEN
      !>
      !>            WRITE(*,*) ERRMSG
      !>
      !>         ELSE
      !>
      !>C
      !>C           Fetch the rows that matched the query.
      !>C
      !>            DO ROW = 1, NMROWS
      !>
      !>C
      !>C              Fetch data from the Ith row.
      !>C
      !>               WRITE (*,*) ' '
      !>               WRITE (*,*) 'ROW = ', ROW
      !>
      !>               DO COLNO = 1, N
      !>
      !>C
      !>C                 Fetch the data from the Jth selected
      !>C                 column.
      !>C
      !>                  IF ( XCLASS(COLNO) .EQ. 'COL' ) THEN
      !>
      !>                     OUTSTR  =  COLS(COLNO)
      !>                     CALL PREFIX ( '.',         0, OUTSTR )
      !>                     CALL PREFIX ( TABS(COLNO), 0, OUTSTR )
      !>                     ITEM = '  ' // OUTSTR // ':'
      !>
      !>                  ELSE
      !>
      !>                     B  =  XBEGS(COLNO)
      !>                     E  =  XENDS(COLNO)
      !>                     ITEM = '  ITEM = ' // QUERY(B:E)
      !>
      !>                  END IF
      !>
      !>                  IF ( XTYPES(COLNO) .EQ. 'CHR' ) THEN
      !>
      !>                     CALL EKGC ( COLNO,  ROW,  1,
      !>     .                           CDATA, NULL, FOUND )
      !>
      !>                     IF ( NULL ) THEN
      !>                        WRITE(*,*) ITEM, '<Null>'
      !>                     ELSE
      !>                        WRITE(*,*) ITEM, CDATA(:RTRIM(CDATA))
      !>                     END IF
      !>
      !>                  ELSE IF ( XTYPES(COLNO) .EQ. 'DP' ) THEN
      !>
      !>                     CALL EKGD ( COLNO,  ROW,  1,
      !>     .                           DDATA, NULL, FOUND )
      !>
      !>                     IF ( NULL ) THEN
      !>                        WRITE(*,*) ITEM, '<Null>'
      !>                     ELSE
      !>                        WRITE(*,*) ITEM, DDATA
      !>                     END IF
      !>
      !>                  ELSE IF ( XTYPES(COLNO) .EQ. 'INT' ) THEN
      !>
      !>                     CALL EKGI ( COLNO,  ROW,  1,
      !>     .                           IDATA, NULL, FOUND )
      !>
      !>                     IF ( NULL ) THEN
      !>                        WRITE(*,*) ITEM, '<Null>'
      !>                     ELSE
      !>                        WRITE(*,*) ITEM, IDATA
      !>                     END IF
      !>
      !>                  ELSE
      !>C
      !>C                    The item is a time value.  Convert it
      !>C                    to UTC for output.
      !>C
      !>                     CALL EKGD ( COLNO,  ROW,  1,
      !>     .                           TDATA, NULL, FOUND )
      !>
      !>                     IF ( NULL ) THEN
      !>                        WRITE(*,*) ITEM, '<Null>'
      !>                     ELSE
      !>                        CALL ET2UTC ( TDATA, 'C', 3, UTCSTR )
      !>                        WRITE(*,*) ITEM, UTCSTR
      !>                     END IF
      !>
      !>                  END IF
      !>
      !>C
      !>C              We're done with the column having index COLNO.
      !>C
      !>               END DO
      !>
      !>C
      !>C           We're done with the row having index ROW.
      !>C
      !>            END DO
      !>
      !>C
      !>C        We either processed the query or had an error.
      !>C
      !>         END IF
      !>
      !>C
      !>C     We either parsed the SELECT clause or had an error.
      !>C
      !>      END IF
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         ROW =            1
      !>           VIKING_SEDR_DATA.IMAGE_NUMBER  :     25837050
      !>           VIKING_SEDR_DATA.IMAGE_ID      : 168C09
      !>           VIKING_SEDR_DATA.PLATFORM_CLOCK:    119.88000000000000
      !>           VIKING_SEDR_DATA.IMAGE_TIME    : 1976 JUN 16 16:50:55.925
      !>
      !>         ROW =            2
      !>           VIKING_SEDR_DATA.IMAGE_NUMBER  :     25837051
      !>           VIKING_SEDR_DATA.IMAGE_ID      : 168C10
      !>           VIKING_SEDR_DATA.PLATFORM_CLOCK:    119.27000000000000
      !>           VIKING_SEDR_DATA.IMAGE_TIME    : 1976 JUN 16 16:51:00.269
      !>
      !>         ROW =            3
      !>           VIKING_SEDR_DATA.IMAGE_NUMBER  :     25840344
      !>           VIKING_SEDR_DATA.IMAGE_ID      : 168C11
      !>           VIKING_SEDR_DATA.PLATFORM_CLOCK:    119.88000000000000
      !>           VIKING_SEDR_DATA.IMAGE_TIME    : 1976 JUN 16 20:56:53.051
      !>
      !>         ROW =            4
      !>           VIKING_SEDR_DATA.IMAGE_NUMBER  :     25840345
      !>           VIKING_SEDR_DATA.IMAGE_ID      : 168C12
      !>           VIKING_SEDR_DATA.PLATFORM_CLOCK:    119.27000000000000
      !>           VIKING_SEDR_DATA.IMAGE_TIME    : 1976 JUN 16 20:56:57.395
      !>
      !>         ROW =            5
      !>           VIKING_SEDR_DATA.IMAGE_NUMBER  :     25843638
      !>           VIKING_SEDR_DATA.IMAGE_ID      : 169C01
      !>           VIKING_SEDR_DATA.PLATFORM_CLOCK:    119.88000000000000
      !>           VIKING_SEDR_DATA.IMAGE_TIME    : 1976 JUN 17 01:02:50.177
      !>
      !>         ROW =            6
      !>           VIKING_SEDR_DATA.IMAGE_NUMBER  :     25843639
      !>           VIKING_SEDR_DATA.IMAGE_ID      : 169C02
      !>           VIKING_SEDR_DATA.PLATFORM_CLOCK:    119.27000000000000
      !>           VIKING_SEDR_DATA.IMAGE_TIME    : 1976 JUN 17 01:02:54.521
      !>
      !>         ROW =            7
      !>           VIKING_SEDR_DATA.IMAGE_NUMBER  :     25846934
      !>           VIKING_SEDR_DATA.IMAGE_ID      : 169C03
      !>           VIKING_SEDR_DATA.PLATFORM_CLOCK:    120.14000000000000
      !>           VIKING_SEDR_DATA.IMAGE_TIME    : 1976 JUN 17 05:08:56.263
      !>
      !>         ROW =            8
      !>           VIKING_SEDR_DATA.IMAGE_NUMBER  :     25846935
      !>           VIKING_SEDR_DATA.IMAGE_ID      : 169C04
      !>           VIKING_SEDR_DATA.PLATFORM_CLOCK:    119.52000000000000
      !>           VIKING_SEDR_DATA.IMAGE_TIME    : 1976 JUN 17 05:09:00.607
      !>
      !>         ROW =            9
      !>           VIKING_SEDR_DATA.IMAGE_NUMBER  :     25848026
      !>           VIKING_SEDR_DATA.IMAGE_ID      : 169C05
      !>           VIKING_SEDR_DATA.PLATFORM_CLOCK:    120.14000000000000
      !>           VIKING_SEDR_DATA.IMAGE_TIME    : 1976 JUN 17 06:30:28.424
      !>
      !>         ROW =           10
      !>           VIKING_SEDR_DATA.IMAGE_NUMBER  :     25848030
      !>           VIKING_SEDR_DATA.IMAGE_ID      : 169C09
      !>           VIKING_SEDR_DATA.PLATFORM_CLOCK:    120.14000000000000
      !>           VIKING_SEDR_DATA.IMAGE_TIME    : 1976 JUN 17 06:30:46.174
      !>
      !>         ROW =           11
      !>           VIKING_SEDR_DATA.IMAGE_NUMBER  :     25848032
      !>           VIKING_SEDR_DATA.IMAGE_ID      : 169C11
      !>           VIKING_SEDR_DATA.PLATFORM_CLOCK:    120.14000000000000
      !>           VIKING_SEDR_DATA.IMAGE_TIME    : 1976 JUN 17 06:30:55.168
      !>
      !>## Restrictions
      !>
      !>     1)  Currently, column names are the only supported expressions.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 06-JUL-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard. Added complete
      !>        code example based on existing fragment.
      !>
      !>-    SPICELIB Version 1.0.0, 19-DEC-1995 (NJB)
      module subroutine ekpsel ( ctx, query, n, xbegs, xends, xtypes, xclass, tabs, cols, error, errmsg )
      use pepper_kinds, only: ip, wp
      use pepper_inc_ekattdsc
      use pepper_inc_ekcnamsz
      use pepper_inc_ekqlimit
      use pepper_inc_ekquery
      use pepper_inc_ektnamsz
      use pepper_inc_ektype
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: query  !! EK query.
      integer(ip), intent(out) :: n  !! Number of items in SELECT clause of QUERY.
      integer(ip), intent(out) :: xbegs  ( * )  !! Begin positions of expressions in SELECT clause.
      integer(ip), intent(out) :: xends  ( * )  !! End positions of expressions in SELECT clause.
      character(*), intent(out) :: xtypes ( * )  !! Data types of expressions.
      character(*), intent(out) :: xclass ( * )  !! Classes of expressions.
      character(*), intent(out) :: tabs   ( * )  !! Names of tables qualifying SELECT columns.
      character(*), intent(out) :: cols   ( * )  !! Names of columns in SELECT clause of QUERY.
      logical, intent(out) :: error  !! Error flag.
      character(*), intent(out) :: errmsg  !! Parse error message.

      integer(ip) :: room


      integer(ip), parameter :: short = 4

      character(tnamsz) :: aka
      character(short), parameter :: chrtyp ( ntypes ) = &
         [ character(short) :: 'CHR', 'DP', 'INT', 'TIME' ]
      character(cnamsz) :: column
      character(:), allocatable :: eqryc
      character(tnamsz) :: qtab

      real(wp), allocatable :: eqryd ( : )

      integer(ip) :: attdsc ( adscsz )
      integer(ip) :: colidx
      integer(ip), allocatable :: eqryi ( : )
      integer(ip) :: errptr
      integer(ip) :: i
      integer(ip) :: tabidx

!
!     Saved values
!

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Initialize the encoded query each time, for safety.
!
!     PEPPER: the encoded query is sized from the query (see EKFIND).
!
      room = max ( len_trim ( query ), 1 )
      allocate ( character(room) :: eqryc )
      allocate ( eqryd(room), source = 0.0_wp )
      allocate ( eqryi(lbcell:eqvbas + 64), source = 0_ip )
      call zzekqini ( ctx, ubound ( eqryi, 1, kind=ip ), room, eqryi, eqryc, eqryd )

!
!     Encode the input query.
!
      call zzekencd ( ctx,  query, &
                       eqryi,  eqryc,   eqryd, &
                       error,  errmsg,  errptr  )

      if ( error ) return

!
!     Look up the number of SELECT columns.  For each column, look up
!     the parent table, the alias, and the column's name.
!
      call zzekreqi ( ctx,  eqryi,  'NUM_SELECT_COLS',  n   )

      do i = 1, n

         call zzekqsel ( ctx, eqryi,  eqryc,   i,        xbegs(i),  xends(i), &
                         qtab,   tabidx,  cols(i),  colidx             )

!
!        Make the table index to the table name.
!
         call zzekqtab ( ctx, eqryi, eqryc, tabidx, tabs(i), aka )

!
!        Currently, every expression is a column.
!
         xclass(i)  =  'COL'

!
!        Look up the data type of the column.
!
         call ekcii ( ctx, tabs(i), colidx, column, attdsc )

         xtypes(i)  =  chrtyp (  attdsc(atttyp)  )

      end do

      return
      end subroutine ekpsel

      !> Search through a type 1 star catalog and return the number of
      !> stars within a specified RA - DEC rectangle.
      !>
      !>## Detailed Input
      !>
      !>     CATNAM   is name of the catalog data table. This name is
      !>              returned by the catalog loader routine STCL01.
      !>
      !>     WESTRA   are right ascension and declination constraints
      !>     EASTRA   giving the western, eastern, southern and northern
      !>     STHDEC   boundaries of a search rectangle as follows:
      !>     NTHDEC
      !>                    RA  BETWEEN WESTRA  AND EASTRA  and
      !>                    DEC BETWEEN STHDEC AND NTHDEC
      !>
      !>              where RA and DEC are the right ascension and
      !>              declination of a star. WESTRA always represents
      !>              "west" side of this rectangle and EASTRA -- the
      !>              "east" side. STHDEC represents the "south" side
      !>              of the rectangle, NTHDEC represents the "north"
      !>              side of the rectangle.
      !>
      !>              For an observer standing on the surface
      !>              of the earth at the equator, the west side of the
      !>              rectangle ( the side associated with WESTRA) rises
      !>              first. The east side (the side associated with
      !>              EASTRA) rises last. All meridians that rise between
      !>              the rising of the west and east edges of the
      !>              rectangle  cross through the RA-DEC rectangle.
      !>
      !>              To specify the 6 degrees wide RA-DEC
      !>              square centered on the celestial equator that
      !>              has western most right ascension of 357 degrees,
      !>              use the following values for WESTRA, EASTRA, STHDEC,
      !>              and NTHDEC (we multiply the angles by the SPICELIB
      !>              function RPD to convert degrees to radians).
      !>
      !>                   WESTRA  = 357.0D0 * RPD()
      !>                   EASTRA  =   3.0D0 * RPD()
      !>                   STHDEC  =  -3.0D0 * RPD()
      !>                   DEXMAX  =   3.0D0 * RPD()
      !>
      !>              To specify a 5 degree wide RA-DEC square that has
      !>              western most right ascension 10 degrees and
      !>              eastern most right ascension 15 degrees and southern
      !>              most declination of 45 degrees, assign the following
      !>              values to WESTRA, EASTRA, STHDEC and NTHDEC.
      !>
      !>                   WESTRA  =  10.0D0 * RPD()
      !>                   EASTRA  =  15.0D0 * RPD()
      !>                   STHDEC  =  45.0D0 * RPD()
      !>                   DEXMAX  =  50.0D0 * RPD()
      !>
      !>              All RA and DECS should be in radians and relative
      !>              to the J2000 inertial frame.
      !>
      !>              All Right Ascension values should be in the
      !>              interval [0, 2*pi ).  This routine does
      !>              not "fold" Right Ascension values into the this
      !>              interval. For example if you request stars in
      !>              whose right ascensions lie between 3*pi and 4*pi
      !>              no stars will be found.
      !>
      !>              All Declination values should be in the interval
      !>              [-pi,pi].
      !>
      !>## Detailed Output
      !>
      !>     NSTARS   is number of catalog stars found within the
      !>              specified RA - DEC rectangle.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If no star catalog has been loaded, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     2)  If the catalog query fails for any reason, the error
      !>         SPICE(QUERYFAILURE) is signaled.
      !>
      !>## Files
      !>
      !>     This routine searches for stars within SPICE type 1 star catalog
      !>     files that have been loaded by calls to the STCL01 routine and
      !>     that contain that catalog data table named CATNAM.
      !>
      !>     SPICE type 1 star catalog files MUST contain a single data table.
      !>     It can occupy a single segment or it can spread across multiple
      !>     segments. This table MUST include the following columns:
      !>
      !>        column name                data type          units
      !>     -------------------------------------------------------
      !>        RA                   DOUBLE PRECISION        DEGREES
      !>        DEC                  DOUBLE PRECISION        DEGREES
      !>        RA_SIGMA             DOUBLE PRECISION        DEGREES
      !>        DEC_SIGMA            DOUBLE PRECISION        DEGREES
      !>        CATALOG_NUMBER       INTEGER
      !>        SPECTRAL_TYPE        CHARACTER*(4)
      !>        VISUAL_MAGNITUDE     DOUBLE PRECISION
      !>
      !>     Nulls are not allowed in any of the columns.
      !>     Other columns can also be present in the table but their data
      !>     will NOT be accessible through STCF01 and STCG01 --
      !>     the interface used to access data in the catalog. Note
      !>     that the names and attributes of these additional columns
      !>     must be identical for all segments containing this table.
      !>
      !>## Particulars
      !>
      !>     This routine is intended to be a part of the user interface to
      !>     the SPICE type 1 star catalog. It allows the caller to find all
      !>     stars within a specified RA - DEC rectangle in the SPICE
      !>     EK type 1 star catalog files loaded by STCL01. This
      !>     subroutine MUST NOT be called before a catalog file has
      !>     been loaded.
      !>
      !>     Other routines in the SPICE type 1 star catalog access
      !>     family are:
      !>
      !>        STCL01  load the catalog file and make its data
      !>                available for search and retrieval.
      !>
      !>        STCG01  retrieve position and characteristics for
      !>                a specified star in the set found by this
      !>                routine.
      !>
      !>## Examples
      !>
      !>     In the following code fragment, STCF01 is used to find
      !>     all stars within a specified RA - DEC rectangle in a SPICE
      !>     EK type 1 star catalog.
      !>
      !>     C
      !>     C     Load catalog file.
      !>     C
      !>           CALL STCL01 ( CATFN, TABNAM, HANDLE )
      !>     C
      !>     C     Search through the loaded catalog.
      !>     C
      !>           CALL STCF01 ( TABNAM, WESTRA,  EASTRA,
      !>          .              STHDEC, NTHDEC, NSTARS )
      !>     C
      !>     C     Retrieve data for every star found.
      !>     C
      !>           DO I = 1, NSTARS
      !>
      !>              CALL STCG01 ( I, RA, DEC, RASIG, DECSIG,
      !>          .                 CATNUM, SPTYPE, VMAG )
      !>
      !>           END DO
      !>
      !>## Restrictions
      !>
      !>     1)  The catalog file STCF01 searches through MUST be loaded
      !>         by STCL01 before STCF01 is called.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 20-AUG-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 15-MAY-1996 (BVS)
      module subroutine stcf01 ( ctx, catnam, westra, eastra, sthdec, nthdec, nstars )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: dpr
      use pepper_strings, only: repmc_inplace, repmd_inplace
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: catnam  !! Catalog table name.
      real(wp), intent(in) :: westra  !! Western most right ascension in radians.
      real(wp), intent(in) :: eastra  !! Eastern most right ascension in radians.
      real(wp), intent(in) :: sthdec  !! Southern most declination in radians.
      real(wp), intent(in) :: nthdec  !! Northern most declination in radians.
      integer(ip), intent(out) :: nstars  !! Number of stars found.

!
!     Local parameters.
!
      integer(ip), parameter :: errlen = 512

      integer(ip), parameter :: qrylen = 512

      character(errlen) :: errmsg
      character(qrylen) :: query
      character(qrylen) :: qrytm1
      character(qrylen) :: qrytm2

      real(wp) :: ramin
      real(wp) :: ramax
      real(wp) :: decmin
      real(wp) :: decmax

      logical :: error

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Query templates.
!
      qrytm1 = &
       'SELECT '                                            // &
       'RA, DEC, RA_SIGMA, DEC_SIGMA,'                      // &
       'CATALOG_NUMBER, SPECTRAL_TYPE, VISUAL_MAGNITUDE '   // &
       'FROM # '                                            // &
       'WHERE '                                             // &
       '( RA  BETWEEN # AND # ) AND '                       // &
       '( DEC BETWEEN # AND # ) '

      qrytm2 = &
       'SELECT '                                            // &
       'RA, DEC, RA_SIGMA, DEC_SIGMA,'                      // &
       'CATALOG_NUMBER, SPECTRAL_TYPE, VISUAL_MAGNITUDE '   // &
       'FROM # '                                            // &
       'WHERE '                                             // &
       '( ( RA BETWEEN # AND 360 ) OR '                     // &
       '  ( RA BETWEEN 0 AND #   )      ) AND '             // &
       '  ( DEC BETWEEN # AND # ) '

!
!     Choose query template to be used.
!
      if ( westra <= eastra ) then
         query = qrytm1
      else
         query = qrytm2
      end if

!
!     Convert angles in radians to angles in degrees.
!
      ramin   = westra * dpr
      ramax   = eastra * dpr
      decmin  = sthdec * dpr
      decmax  = nthdec * dpr

!
!     Construct query using inputs and chosen template.
!
      call repmc_inplace ( query, '#', catnam )
      call repmd_inplace ( query, '#', ramin,  15 )
      call repmd_inplace ( query, '#', ramax,  15 )
      call repmd_inplace ( query, '#', decmin, 15 )
      call repmd_inplace ( query, '#', decmax, 15 )

!
!     Submit query and get number of stars. Check for
!     errors in QUERY.
!
      call ekfind( ctx, query, nstars, error, errmsg )

      if ( error ) then
         call ctx%setmsg ( 'Error querying type 1 star catalog. '// &
                       'Error message: # '                  )
         call ctx%errch  ( '#', errmsg                          )
         call ctx%sigerr ( 'SPICE(QUERYFAILURE)'                )
         return
      end if

      return
      end subroutine stcf01

   !> PEPPER: initialize EKQMGR's five linked list pools (the file table,
   !> segment table, column descriptor table, column attribute table and
   !> table list) at their current sizes: SPICELIB's block of five [[lnkini]]
   !> calls with the fixed sizes, in every entry point.
   subroutine ekqmgr_lnkini ( ctx )
      class(pepper_context), intent(inout) :: ctx  !! the context
      associate ( q => ctx%spice%ekqmgr )
      call lnkini ( ctx, ubound ( q%ftpool, 2, kind=ip ), q%ftpool )
      call lnkini ( ctx, ubound ( q%stpool, 2, kind=ip ), q%stpool )
      call lnkini ( ctx, ubound ( q%dtpool, 2, kind=ip ), q%dtpool )
      call lnkini ( ctx, ubound ( q%ctpool, 2, kind=ip ), q%ctpool )
      call lnkini ( ctx, ubound ( q%tbpool, 2, kind=ip ), q%tbpool )
      end associate
   end subroutine ekqmgr_lnkini

   !> PEPPER: make room in EKQMGR's tables for loading the EK file HANDLE
   !> with NSEG segments: a file table entry, NSEG segment table and
   !> table list entries, and as many column attribute and column
   !> descriptor entries as the segments have columns. Each pool grows
   !> (keeping its nodes and lists) with its parallel arrays.
   subroutine ekqmgr_room ( ctx, handle, nseg )
      use pepper_containers, only: grow, lnkgrow, grown_capacity
      use pepper_inc_eksegdsc, only: sdscsz, ncidx
      use pepper_inc_ekcoldsc, only: cdscsz
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! handle of the EK file being loaded
      integer(ip), intent(in) :: nseg  !! number of segments in the file
      integer(ip) :: segdsc ( sdscsz ), ncol, seg, n
      ncol = 0
      do seg = 1, nseg
         call zzeksdsc ( ctx, handle, seg, segdsc )
         if ( ctx%failed() ) return
         ncol = ncol + segdsc(ncidx)
      end do
      associate ( q => ctx%spice%ekqmgr )
      n = needed ( q%ftpool, 1_ip )
      if ( n > 0 ) then
         call lnkgrow ( q%ftpool, n )
         call grow ( q%fthan, n )
      end if
      n = needed ( q%stpool, nseg )
      if ( n > 0 ) then
         call lnkgrow ( q%stpool, n )
         call grow ( q%sthan, n )
         call grow ( q%stsidx, n )
         call grow ( q%stnrow, n )
         call grow ( q%stncol, n )
         call grow ( q%stdtpt, n )
         call grow ( q%stdscs, n, sdscsz )
      end if
      n = needed ( q%tbpool, nseg )
      if ( n > 0 ) then
         call lnkgrow ( q%tbpool, n )
         call grow ( q%tbstpt, n )
         call grow ( q%tbncol, n )
         call grow ( q%tbctpt, n )
         call grow ( q%tbnams, n )
      end if
      n = needed ( q%ctpool, ncol )
      if ( n > 0 ) then
         call lnkgrow ( q%ctpool, n )
         call grow ( q%ctnams, n )
         call grow ( q%ctclas, n )
         call grow ( q%cttyps, n )
         call grow ( q%ctlens, n )
         call grow ( q%ctsizs, n )
         call grow ( q%ctfixd, n )
         call grow ( q%ctindx, n )
         call grow ( q%ctnull, n )
      end if
      n = needed ( q%dtpool, ncol )
      if ( n > 0 ) then
         call lnkgrow ( q%dtpool, n )
         call grow ( q%dtdscs, n, cdscsz )
      end if
      end associate
   contains
      !> The size a pool must grow to (at least doubling) for EXTRA more
      !> nodes, or 0 if it has room.
      integer(ip) function needed ( pool, extra ) result ( n )
         integer(ip), intent(in) :: pool ( :, -5: )  !! the pool, pool(2, lbpool:size)
         integer(ip), intent(in) :: extra  !! the number of nodes to add
         integer(ip) :: size, free
         size = ubound ( pool, 2, kind=ip )
         free = lnknfn ( ctx, pool )
         n = 0
         if ( free < extra ) n = grown_capacity ( size, size - free + extra )
      end function needed
   end subroutine ekqmgr_room

   !> PEPPER: size the per-query arrays of EKQMGR's context state for the
   !> query EQRYI: its FROM tables, SELECT and ORDER BY columns, the
   !> constraints of a conjunction (at most all of them) and its
   !> conjunctions (SPICELIB: MAXTAB, MAXSEL, MAXORD, MAXCON, MXJOIN,
   !> MXJRS). The element index arrays are all 1, as SPICELIB set them.
   subroutine ekqmgr_query_room ( ctx, eqryi )
      use pepper_containers, only: grow, grow_cell
      use pepper_inc_ektnamsz, only: tnamsz
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: eqryi ( lbcell : * )  !! the encoded query
      integer(ip) :: ntab, nsel, nord, ncns, ncnj
      call zzekreqi ( ctx, eqryi, 'NUM_TABLES',       ntab )
      call zzekreqi ( ctx, eqryi, 'NUM_SELECT_COLS',  nsel )
      call zzekreqi ( ctx, eqryi, 'NUM_ORDERBY_COLS', nord )
      call zzekreqi ( ctx, eqryi, 'NUM_CONSTRAINTS',  ncns )
      call zzekreqi ( ctx, eqryi, 'NUM_CONJUNCTIONS', ncnj )
      ntab = max ( ntab, 1_ip )
      nsel = max ( nsel, 1_ip )
      nord = max ( nord, 1_ip )
      ncns = max ( ncns, 1_ip )
      ncnj = max ( ncnj, 1_ip )
      associate ( q => ctx%ekqmgr_query )
      call grow ( q%frmals, ntab )
      call grow ( q%frmtab, ntab )
      call grow ( q%rbas, ntab )
      call grow ( q%rsize, ntab )
      call grow_cell ( q%tptvec, ntab )
      if ( allocated ( q%tabvec ) ) then
         if ( ubound ( q%tabvec, 1, kind=ip ) < ntab ) deallocate ( q%tabvec )
      end if
      if ( .not. allocated ( q%tabvec ) ) allocate ( q%tabvec(lbcell:ntab), source = repeat ( ' ', tnamsz ) )
      call grow ( q%selcol, nsel )
      call grow ( q%selctp, nsel )
      call grow ( q%seltab, nsel )
      call grow ( q%ocols, nord )
      call grow ( q%oelts, nord )
      call grow ( q%otabs, nord )
      call grow ( q%sense, nord )
      call grow ( q%dvals, ncns )
      call grow ( q%cbegs, ncns )
      call grow ( q%cends, ncns )
      call grow ( q%cnstyp, ncns )
      call grow ( q%dtype, ncns )
      call grow ( q%ivals, ncns )
      call grow ( q%lcidx, ncns )
      call grow ( q%lelts, ncns )
      call grow ( q%ltbidx, ncns )
      call grow ( q%ops, ncns )
      call grow ( q%rcidx, ncns )
      call grow ( q%relts, ncns )
      call grow ( q%rtbidx, ncns )
      call grow ( q%activc, ncns )
      call grow ( q%activv, ncns )
      call grow ( q%ubase, ncnj )
      q%lelts = 1
      q%oelts = 1
      q%relts = 1
      end associate
   end subroutine ekqmgr_query_room

   !> PEPPER: read an element of a character column entry, as [[zzekrsc]]
   !> does, into a buffer that holds the whole string. The buffer has the
   !> declared length of a column of fixed-length strings (whose readers
   !> signal SPICE(STRINGTRUNCATED) on a shorter one); a variable-length
   !> string longer than the buffer is read again into a buffer of its
   !> length. SPICELIB read into a CHARACTER*(MAXSTR) buffer and compared
   !> at most MAXSTR (1024) characters.
   subroutine zzekrsc_whole ( ctx, handle, segdsc, coldsc, recptr, eltidx, cvlen, cval, isnull, found )
      use pepper_inc_ekcoldsc
      use pepper_inc_eksegdsc
      !> length of the first buffer for a variable-length string
      integer(ip), parameter :: inilen = 1024
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle attached to EK file.
      integer(ip), intent(in) :: segdsc ( sdscsz )  !! Segment descriptor.
      integer(ip), intent(in) :: coldsc ( cdscsz )  !! Column descriptor.
      integer(ip), intent(in) :: recptr  !! Pointer to record from which data is to be read.
      integer(ip), intent(in) :: eltidx  !! Index of column entry element to be read.
      integer(ip), intent(out) :: cvlen  !! Length of stored string.
      character(:), allocatable, intent(inout) :: cval  !! Character value in column entry (at least CVLEN characters long, when found and not null).
      logical, intent(out) :: isnull  !! Flag indicating whether column entry is null.
      logical, intent(out) :: found  !! Flag indicating whether entry element was found.
      integer(ip) :: n
      n = coldsc ( lenidx )
      if ( n < 1 ) n = inilen
      call room ( n )
      call zzekrsc ( ctx, handle, segdsc, coldsc, recptr, eltidx, cvlen, cval, isnull, found )
      if ( ctx%failed() ) return
      if ( found .and. ( .not. isnull ) .and. ( cvlen > len ( cval ) ) ) then
         call room ( cvlen )
         call zzekrsc ( ctx, handle, segdsc, coldsc, recptr, eltidx, cvlen, cval, isnull, found )
      end if
   contains
      !> make CVAL at least N characters long
      subroutine room ( n )
         integer(ip), intent(in) :: n  !! the length needed
         if ( allocated ( cval ) ) then
            if ( len ( cval ) >= n ) return
            deallocate ( cval )
         end if
         allocate ( character(n) :: cval )
      end subroutine room
   end subroutine zzekrsc_whole

end submodule pepper_ek
